globalThis.ANDE_CHUNKS["0102193c4d3d627c6c708701db62e306d7ce58f432fa85d1ce9a466eaf25701a"] = [{"id":"bytedance:7622996922623297797","sourceKey":"bytedance","company":"字节跳动","title":"音频多模态算法工程师-Seed大模型人才校招","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622996922623297797/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、参与研发多模态大模型等下一代人工智能核心技术，挑战最具颠覆性的AI前沿工作，参与构建全球领先的Seed音频多模态基座大模型，探索下一代AI；\n2、关注和推进技术在业务场景中的广泛应用，包括但不限于语言、音乐、语音、音频的生成与理解等；\n3、深入调研和关注音频/LLM/VLM等方向的前沿技术。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、自动化、数学相关专业优先；\n2、怀有科技改变世界的远大抱负，有志于投身机器学习、人工智能、大模型、多模态理解和生成等技术领域；\n3、有自然语言处理、语音合成与识别、音乐生成等研究或者技术背景优先；在ACL/EMNLP/NAACL/NeurIPS/ICML/ICLR/Icassp/Interspeech等顶级会议上发表论文者优先；\n4、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n5、在大模型领域或者RL领域，主导过大影响力的项目或论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680032733219850501","sourceKey":"bytedance","company":"字节跳动","title":"电机驱动器硬件实习生 - Seed Model","city":"北京","category":"硬件","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680032733219850501/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\n\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责无框电机控制系统的方案设计和硬件实现（器件选型，原理图与PCB设计）；\n2、负责无框电机调试，梳理测试用例，完成电机性能测试与分析优化；\n3、解决产品研发过程中出现的可靠性问题、质量问题、EMC问题、功能以及性能等问题。","requirements":"1、本科及以上学历在读，自动化、电力电子、控制理论与控制工程、电气工程、自动控制等相关专业优先；\n2、对无框电机的工作原理、控制方式、性能指标和测试方法等有了解；\n3、熟练使用Altium Designer，Cadence等电路设计软件，有硬件设计经验者优先；\n4、熟悉电机驱动器设计，熟悉MOSFET、栅极驱动和保护设计，可完成开发和调试；\n5、熟悉电机控制中常用的传感器检测技术和应用，具备力传感器结构设计和制作经验者优先；\n6、RoboMaster、飞思卡尔智能车、大学生方程式、Robocon等比赛获奖经历者优先考虑。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678185468568029493","sourceKey":"bytedance","company":"字节跳动","title":"招聘实习生 - 生活服务","city":"上海","category":"人力","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678185468568029493/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持字节跳动抖音生活服务团队，满足业务团队日常招聘需求；\n2、深刻理解业务，把握招聘需求，为快速发展的团队搭建优秀的人才梯队；\n3、参与团队内人才寻访，以及面试等流程管理；\n4、协助管理招聘渠道，如猎头、招聘网站等资源管理；\n5、协助招聘相关项目（如校园招聘、人才地图绘制、高端人才招聘等）及分析招聘数据及漏斗，提升招聘有效性。","requirements":"1、本科及以上学历在读，人力资源、工商管理、心理学专业优先；\n2、有HR相关实习经验，对人力工作有热情，希望在HR方向上持续发展；\n3、优秀的沟通能力、学习能力，逻辑性强，具有良好的合作性和责任心；\n4、性格积极主动，为人坦诚正直，做事认真务实，自驱、有上进心；\n5、具备良好的数据分析能力、口头和文字表达能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676433354120038661","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（治理策略方向） - 抖音电商","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676433354120038661/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商治理策略产品相关工作，通过对治理业务的抽象总结或更新策略与规则，并推进治理侧的全链路策略落地，以及相关的机制搭建和产品改造；\n2、了解并掌握当前大模型的能力边界，并将不断更新的策略融入到治理模型的建设中，搭建自动化的防控链路；\n3、充分调用公司内的AI产品能力提升整体策略产出的效率与质量；\n4、推进内部交流，协同业务团队、算法、研发团队，保证团队合作的顺畅，及跨横向团队间的协作等。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、数据、人工智能等相关专业优先；\n2、拥有AI产品/B端/平台产品工作经验，具备出色的学习能力和逻辑思维，跨团队协同能力强，能够深入业务，理解业务，有自驱力目标导向；\n3、熟悉产品与运营机制，能够高效的与业务、算法团队沟通，并转化成可行的解决方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675242123075225909","sourceKey":"bytedance","company":"字节跳动","title":"兴趣推荐策略产品实习生-TikTok","city":"上海","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675242123075225909/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、参与TikTok双列兴趣信号定义、收集与清洗，提升用户兴趣识别的准确性；\n2、参与兴趣分发策略建设，优化推荐效果与用户体验；\n3、完善负反馈、投放问卷等能力，收集用户体验反馈并推进策略迭代；\n4、通过数据分析、案例研究等方式发现兴趣分发的问题和机会，产出方案并推动落地。","requirements":"1、本科及以上学历在读，专业不限；\n2、每周可实习5天，可连续实习；\n3、具备优秀的逻辑分析和数据分析能力，对数据敏感；\n4、对推荐系统、用户兴趣及内容社区有较强兴趣和思考，具备内容意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670031907660319029","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈产品研发工程师（国际化内容社区） - TikTok研发","city":"上海/北京","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670031907660319029/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与TikTok、Lemon8等国际化内容社区产品研发，在导师指导下以AI Coding为核心工作方式，完成前端、客户端、服务端等方向的开发；\n2、参与需求讨论、方案设计、编码实现、测试验证与上线迭代，建立完整的端到端工程交付意识；\n3、岗位亮点：\n1）面向全球用户的真实业务场景，你的代码和产品判断有机会影响海量用户；\n2）以AI原生方式工作，强调端到端交付和下一代软件工程范式，而非单一技术栈的执行；\n3）业务节奏快、技术挑战丰富，团队重视工程质量、技术成长和跨角色协作；\n4）把AI工具用于日常开发——实践代码理解、生成、问题定位、测试补全和重构建议，并学会审查、验证和修正AI的输出；\n5）学习跨栈与跨职能协作，理解页面、端侧、服务端接口、数据与发布验证之间的链路关系；\n6）在真实业务项目中快速成长，逐步具备独立负责模块设计与开发的能力。","requirements":"1、2027届获得本科及以上学历，计算机及相关专业优先；\n2、扎实的基础功：熟悉数据结构、算法、操作系统、网络、数据库等基础，至少熟练一种主流编程语言，能编写清晰、可维护的代码；\n3、真实的AI使用经历与验证意识：在个人项目、课程、实习或开源中真正用过AI工具，能说明如何验证和修正AI的输出，而不只停留在工具名或概念层面；\n4、快速学习与跨栈潜力：能在不熟悉的语言或环境里借助AI快速上手，至少一个方向有可展示的实践；产品好奇心与自驱力：对真实业务问题和用户体验有好奇心，能主动发现、拆解并推动解决问题；逻辑思维、沟通能力和团队合作意识良好；\n5、加分项：有实习经历，参与过完整的业务项目或工程项目；有前端、客户端、服务端、多端协同或全栈项目经验；能展示用AI辅助完成的代码、测试、重构或问题定位成果（熟悉Cursor、TRAE、Copilot、Claude Code、Codex等工具）；有ACM/ICPC、蓝桥杯、CCPC、LeetCode、Kaggle等竞赛经历或优秀成绩；有开源贡献、技术博客、App、小程序、网站或工具类作品。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669768445164996869","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（搜索方向） - 抖音搜索","city":"上海/北京/杭州","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669768445164996869/detail","duty":"团队介绍：抖音搜索是抖音的核心产品能力之一，满足用户找内容、找商品、找服务、找经验、找人等多元需求，基于海量的内容和商品供给、领先的意图识别和产品能力，用户搜索规模保持高速增长，快速成为中国第一梯队的移动搜索平台。抖音搜索业务体系完善，涵盖内容、电商、生活服务、推荐、交互、数据分析等多个方向。AI大模型和抖音内容生态的结合，会给抖音搜索带来的新的增长动力！\n\n1、参与抖音电商搜索、智能导购、种草转化、决策下单等场景的用户需求分析与问题拆解，结合大模型和生成式AI能力，协助推进AI电商搜索产品方案设计与体验优化；\n2、参与AI智能导购核心场景建设，包括搜索意图理解、智能问答导购、商品推荐、多轮对话决策、场景化种草等方向，帮助提升用户搜索体验和交易转化效率；\n3、参与大模型在电商交易搜索场景中的产品落地，协助完成策略拆解、规则设计、效果评估和迭代优化，并与算法、研发团队共同推动模型能力在业务中的应用；\n4、参与AI产品从需求分析、方案设计、PRD撰写、上线跟进到数据复盘的完整流程，在实际业务中不断打磨产品体验，沉淀对AI产品设计与落地的理解。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、数据科学、电子信息、数学、统计学、信息管理、工业工程、设计、心理学等相关专业优先；\n2、对AI产品、大模型应用、搜索产品或电商产品方向有浓厚兴趣，了解大模型、生成式AI的基本原理和常见应用方式，对Prompt、检索增强、多轮对话、Agent等方向有一定认知者优先；\n3、具备较强的逻辑分析能力和结构化思考能力，具备基础的数据分析能力，能够从用户需求、业务目标和数据反馈中发现问题并提出解决思路；\n4、具备良好的沟通协作能力和执行力，能够与产品、算法、研发、设计等多角色同学高效配合，共同推进项目落地；\n5、对新技术保持好奇心和学习热情，愿意拥抱AI原生工作方式，具备快速学习和持续迭代的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667841819807746357","sourceKey":"bytedance","company":"字节跳动","title":"广告后端开发工程师 - Pangle","city":"北京/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667841819807746357/detail","duty":"团队介绍：Pangle 是国际化业务旗下独家广告联盟网络，目前已覆盖近 50 个市场。该平台通过值得信赖、智能且注重实效的广告解决方案，助力广告主对接优质本地发布渠道，将营销触角延伸至整个国际化业务生态。Pangle 已在 20 多个新兴市场构建行业领先的广告网络，于亚太、中东及拉丁美洲地区拥有经市场验证的成功经验。与此同时，Pangle 为开发者打造广告变现与用户获取的闭环增长，助力开发者获取更高收益、更优质用户，全面释放成长潜能。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验，参与设计系统技术方案、核心代码开发和系统调优；\n2、参与制定代码规范、测试规范，建立起开发质量控制方法；\n3、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n4、参与各专项技术调研、新技术引入等前瞻项目，以及机器学习与异构计算系统研发。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：C++、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665314139103267125","sourceKey":"bytedance","company":"字节跳动","title":"大数据AI工程师 - 抖音用户增长","city":"北京/上海","category":"大数据","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665314139103267125/detail","duty":"团队介绍：抖音用户增长（User Growth）负责抖音、今日头条、番茄小说等多个产品的用户增长业务，建立行业领先的增长和营销技术，打造极致的用户体验。加入我们，有机会参与亿级用户场景的开发与架构工作，也有机会从数据出发，利用策略和模型为业务带来更大的助力。\n\n1、参与字节跳动用户行为的理解和建模，帮助业务洞察用户需求，促进业务增长；\n2、基于用户数据和业务数据，深度参与各业务线增长的离线、实时数据仓库建设工作；\n3、面向PB级超大规模数据问题，处理亿级增量的用户行为数据，对数据质量和赋能业务的效率负责；\n4、体验前沿的AI开发模式，协助构建面向AI应用（如智能分析、智能问答）的数据底座与工具，降低数据使用门槛；\n5、参与构建设计良好的数据流、数据仓库、数据服务，构建流程规范和数据工具、产品，保证系统稳定高效运行，以实现数据的最大价值。","requirements":"1、2027届获得本科及以上学历，计算机、数据等相关专业优先；\n2、扎实的计算机编程能力，会使用SQL，掌握C/C++、Java、Python、Scala中任意一门编程语言；\n3、熟悉数据仓库实施方法论、了解数据仓库体系优先；\n4、熟悉大数据集、分布式计算工具（Map/Reduce、Hadoop、Hive、Spark、Flink等）的应用和基本原理优先；\n5、对AI大模型应用充满热情，有基于大模型完成相关开发经验的优先；\n6、有过数据治理，数据挖掘，BI，算法等大数据相关项目/实习经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7634137444192405813","sourceKey":"bytedance","company":"字节跳动","title":"数据分析实习生-TikTok直播","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7634137444192405813/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播是全球领先的直播业务，以实时互动为核心，提供多元化的商业化模式和创作工具。我们为用户提供独特的内容和消费体验；为创作者找到合适的观众，提供最好的工具和一系列盈利模式，帮助创作者创造更多机会、改变他们的生活；通过直播，平台也能从中获得健康、客观的商业化收益，持续发展。我们一直听到这样的故事 —— “LIVE changes my life” —— 他们更好，我们才会更好。\n\n加入我们，一起探索 “不可能的事”—— 我们是行业的先行者，在一步步改变行业。我们持续让行业了解直播是一种新的内容形式，是创作者可以依赖的商业模式。\n\n1、主要支持国际化直播业务的风险评估与合规分析工作，协同跨团队开展风险评估，覆盖产品及业务流程；识别潜在合规风险，并提供可落地的解决方案与建议；\n2、数据驱动的风险识别与效率提升：通过数据分析、测试验证等方式主动识别并校验业务风险；分析合规问题的重复性模式，提升分析效率，推动优化方案；\n3、风险案例分析与判断：对风险案例进行事实还原与结构化分析，基于分析结果输出合理的判断与处理建议；\n4、风险治理能力建设：将风险发现转化为前置的治理机制，包括识别、监控及控制能力；支持构建数据驱动的风险管理体系，推动风险治理能力的体系化建设。","requirements":"1、本科及以上学历在读，专业不限，数学、计算机、会计或相关专业优先；\n2、具备较强的数据分析能力，熟练掌握SQL；\n3、严谨细致，具备风险意识：分析逻辑清晰，具备深入挖掘问题的能力；具备良好的保密意识与职业操守；\n4、相关经验优先：有直播、审计、内控或合规相关经验者优先；\n5、沟通与业务理解能力：具备良好的沟通能力和业务理解能力；中文、英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622899895045392645","sourceKey":"bytedance","company":"字节跳动","title":"AI搜索算法实习生-Seed大模型人才实习","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622899895045392645/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、基于AI建设下一代搜索引擎，并服务于AI Agents，包括全网搜索、视频搜索、商品搜索、本地搜索、图片搜索、视觉搜索、结构化检索等；\n2、基于LLM/VLM大幅突破搜索排序、召回、内容理解、个性化等任务，解决多语言、难语义、长文本等核心挑战。","requirements":"1、2028届及以后本科及以上学历在读，计算机、人工智能等相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握C++或Python；\n3、熟悉深度学习算法，有一定的算法应用经验和出色的技术判断能力；\n4、出色的数据和问题分析能力，对新问题能够独立探索解决方案；\n5、加分项：有ACM/ICPC等比赛获奖、在顶会发表相关论文、有顶级开源项目经验等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669673936569878837","sourceKey":"bytedance","company":"字节跳动","title":"商业化产品经理 - 今日头条","city":"深圳","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669673936569878837/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n1、负责今日头条/番茄小说/番茄畅听APP内电商的推荐策略，通过优化电商广告、直播、短视频的推荐算法策略，提升各信息流内容场、搜索、商城货架场的变现效率，为电商业务目标负责；\n2、深入推荐算法链路，分析广告模型、电商模型的链路、原理差异，挖掘结合提效的方案和空间；\n3、对电商分发体验优化，深入分析各场景的电商触达位置、频次、间隔、转化概率，做到用户体验和电商收入的平衡；\n4、关注行业最新增长模式，结合今日头条电商及生态业务特点，不断推陈出新。","requirements":"1、2027届获得本科及以上学历；\n2、电商行业/广告策略/推荐策略/ROI优化/UG投放策略等实习相关经验加分；有扎实的逻辑分析能力和数据理解能力，对发现和拆解问题有热情，通过大胆的业务假设，谨慎的数据求证，严谨的逻辑思考来分析和解决问题；\n3、拥有强烈的责任心和团队合作精神，出色的学习能力，具备强烈的好奇心和自我驱动力，喜欢接受挑战，追求卓越，同时具有良好表达和跨团队沟通能力；\n4、对新技术有热情，能够不断对新技术保持关注和学习。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668524950284421381","sourceKey":"bytedance","company":"字节跳动","title":"推荐大模型算法工程师 - 抖音","city":"北京/上海/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668524950284421381/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、增长算法、广告自动化投放、智能对话等算法工作，对接全链路各体裁（短视频，图文）各业务（内容消费，互动，UGC，双列，社交，生态，垂类，创作，消息，汽水音乐，精选，随变，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、多业务复杂约束下的优化问题、多模态内容理解、LLM基础技术研究、业务Agent化和创新AI落地应用、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型技术支持抖音的AI分身、业务智能化、智能客服等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音APP产品的算法工作，共同搭建业界领先的推荐系统、内容理解系统，为用户提供一流的产品体验；\n2、深入理解业务和机器学习技术，优化模型和策略，持续提升推荐效果；\n3、深入理解用户行为，结合数据挖掘等技术，优化用户创作和浏览等体验；\n4、在抖音各个业务场景应用内容算法，改进内容社区的运行效率，支持下游的算法和产品需求；\n5、和产品、运营团队紧密合作，通过对产品和用户的深入理解和分析，制定算法策略促进抖音生态的长期繁荣发展。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备编码能力，扎实的数据结构和算法功底；\n3、对推荐算法和机器学习有热情、乐于学习、思考和创新；\n4、分析问题和解决问题的能力，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎、CV、NLP、语音、LLM、AIGC等相关领域有经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680818474939812101","sourceKey":"bytedance","company":"字节跳动","title":"主播/公会运营实习生（俄语方向） - TikTok直播","city":"深圳/北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680818474939812101/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播是全球领先的直播业务，以实时互动为核心，提供多元化的商业化模式和创作工具。我们为用户提供独特的内容和消费体验；为创作者找到合适的观众，提供最好的工具和一系列盈利模式，帮助创作者创造更多机会、改变他们的生活；通过直播，平台也能从中获得健康、客观的商业化收益，持续发展。我们一直听到这样的故事 —— “LIVE changes my life” —— 他们更好，我们才会更好。\n\n加入我们，一起探索 “不可能的事”—— 我们是行业的先行者，在一步步改变行业。我们持续让行业了解直播是一种新的内容形式，是创作者可以依赖的商业模式。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、能够结合业务分析发现问题，提出解决方案，利用活动落地；学习和研究其他产品的优秀活动案例，优化活动环节，并提出新的玩法和方案；\n2、引导主播产生优质内容，协助策划和落地本地活动，提升泛娱乐板块的内容丰富度；熟悉主播、用户心理，协助了解当地用户特征，提出建设性和探索性建议，并且推进问题的解决，优化用户体验。","requirements":"1、本科及以上学历在读，俄语专业优先；\n2、熟悉直播或者内容平台，了解TikTok直播的主播生态，具备基础数据分析能力（SQL），可支持业务决策，能快速适应动态变化的环境，应对实时挑战；\n3、具备优秀的分析思维与问题解决能力及沟通团队协作能力，能解读数据并产出可落地洞察；\n4、有产品运营相关实习或项目经验优先；俄语需要作为工作语言进行使用，英语及六级以上者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678960581828872453","sourceKey":"bytedance","company":"字节跳动","title":"用户增长策略运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678960581828872453/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、补贴策略：参与新人券、包邮券、广告等策略的设计和执行，包括但不限于补贴、产品和实验配置；\n2、数据分析：关键数据分析、AB实验测试，追踪业务关键指标，发现数据背后的问题和机会点；\n3、产品追踪：了解并追踪产品整体策略，记录并帮助团队制定对应打法；\n4、支持跨部门沟通、项目管理、信息收集等工作。","requirements":"1、本科及以上学历在读；\n2、可长期实习优先；\n3、熟练使用SQL，具备一定的数据分析能力；\n4、英语表达及书写流利，可作为工作语言，有国际化留学或经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675357908361775365","sourceKey":"bytedance","company":"字节跳动","title":"校招COE实习生 - 管理研究院","city":"上海","category":"人力","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675357908361775365/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助全球校招中台团队，共同完成校园招聘相关工作；\n2、参与校招人才策略与招聘系统、机制设计，协助将策略洞察转化为可落地的流程、规则与工具优化，支持招聘链路的数字化与效率提升；\n3、参与全球人才策略研究，协助完成各类分析调研，定向进行全球人才地图绘制和分析；\n4、运用数据分析工具，对招聘数据进行可视化处理，为招聘策略的优化提供数据支持，并协助从招聘报告中挖掘潜在问题；\n5、协助完成校园招聘相关项目的达成。","requirements":"1、本科及以上学历在读，专业不限；\n2、有HR相关实习经历，具备招聘、数据分析能力者优先；\n3、熟练使用Excel办公软件，具备较强的数据处理与分析能力，对数字敏感，具备良好的逻辑思维能力，能够从数据中发现问题并提出合理建议；\n4、工作认真负责，踏实细心，具有快速、持续的学习能力；\n5、一周可实习4-5天，能连续实习4个月以上优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670896417674201349","sourceKey":"bytedance","company":"字节跳动","title":"作者策略 - 抖音电商","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670896417674201349/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、具备体系化运营思维：从数据反馈中洞察作者问题，制定策略并联合作者运营、巨量百应产品、AI产品、推荐策略等团队落地，提升作者供给产能与生态健康度；\n2、作者经营与成长策略：根据作者生命周期和经营类型，设计分层作者成长策略，洞察垂类作者大盘的问题与潜在机会，通过任务赛、社群运营，RPA等手段，提升作者规模；\n3、引入与中小作者孵化策略：制定新作者引入策略，识别高潜达人供给，设计引入路径与机制，扩充达人供给池；负责长尾潜力达人的孵化成长策略，基于内容生态、流量机制与产品功能设计孵化路径，推动腰部向升级。","requirements":"1、2027届获得本科及以上学历，理工科背景优先；\n2、有直播、视频电商行业策略或作者运营实习经验者优先，有聪明敏捷的思维，数据敏感，有清晰的逻辑分析能力，能够快速梳理复杂业务逻辑并找到关键突破口；\n3、具备良好的沟通协调能力，能有效联动产品、运营等多方资源，推动运营工作顺利开展；\n4、拥有持续创业的激情，具备在动态环境中解决问题的能力，以结果为导向，具备一定的结果交付能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668357351300385077","sourceKey":"bytedance","company":"字节跳动","title":"视觉搜索算法工程师 - TikTok算法","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668357351300385077/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、多模态Query理解：研究图片、视频、截图、观看上下文等多模态Query的意图理解与语义表示，建模用户从“看到什么”到“想找什么、想知道什么、想决策什么”的需求转化；\n2、视觉搜索Ranking：研究多模态Query与视频内容之间的相关性建模，融合视觉语义、用户意图和行为反馈，优化召回、排序和结果组织；\n3、多模态AI Search：研究基于全模态输入的AI Search：从图片、视频、截图和观看上下文中理解用户问题，融合视觉细节、内容语境、搜索结果和用户意图，完成基于视觉内容的问答、解释、比较、推荐和决策支持；\n4、大规模视觉搜索系统：面向全球视频生态，研究数据构建、模型训练、评测体系、在线推理和系统效率，让多模态搜索能力稳定服务真实产品体验。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、电子信息、数学、统计等相关专业优先；\n2、机器学习、深度学习、计算机视觉或自然语言处理基础扎实，具备优秀的代码实现和实验分析能力；\n3、在视频理解、VLM、多模态检索、搜索推荐、大模型或Ranking中至少一个方向有深入积累；\n4、能从搜索系统视角理解视觉问题，不只关注模型指标，也关注Query理解、相关性、排序、结果组织和用户满意度；\n5、能把真实用户需求抽象成可建模、可训练、可评估的问题，并在复杂数据和系统约束下验证方案价值；\n6、对多模态Query和AI Search如何重构视觉搜索体验有强烈兴趣。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667606195475089669","sourceKey":"bytedance","company":"字节跳动","title":"AI搜索算法工程师 - TikTok Shop","city":"上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667606195475089669/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、以Search Agent为核心主线，围绕用户历史上下文进行深度个性化理解、推理与决策，让搜索从被动的关键词匹配，升级为「懂用户、能推理、会决策」的AI搜索；\n2、建设AI搜索全链路Harness能力，提升Agent在复杂链路下的稳定性和资源能效；\n3、Post-training Optimization，搭建基于Rubrics的自动化评估体系，实现模型迭代与效果评估的闭环提升；\n4、构建个性化能力，融合用户长期兴趣、实时意图与图文/视频等多模态信号，提供千人千面的搜索体验；\n5、打造面向Agent的智能搜索引擎，攻克复杂Query下的搜索相关性问题，持续提升召回与排序质量。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、电子、自动化、软件工程、数学等相关专业优先；\n2、具备扎实的编码能力、数据结构和基础算法功底，熟练运用各种算法框架与工程框架，熟练使用C/C++和Python语言；\n3、在搜索、推荐、广告、自然语言处理NLP、自然语言理解NLU、多模态、机器学习、深度学习等一个或多个领域有较深入研究优先；\n4、在人工智能领域、机器学习领域国际会议或期刊发表论文者优先；\n5、具有良好的问题分析解决能力与沟通协作能力。\n\n加分项：\n1、具有优秀的基础算法、扎实的机器学习/深度学习基础，熟悉NLP、RL、ML等领域的技术，在KDD、SIGIR、ICML、ACL、COML、EMNLP、CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等会议/期刊上发表论文者优先；\n2、ACM/ICPC、NOI/IOl、Top Coder、Kaggle等比赛获奖者优先；\n3、在Agent、多模态、世界模型、RL等领域，主导过大影响力项目者优先；\n4、有AI搜索、Coding Agent相关实习经历并参与项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667158023316654389","sourceKey":"bytedance","company":"字节跳动","title":"Camera软件开发工程师 - 移动OS","city":"深圳/北京","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667158023316654389/detail","duty":"团队介绍：我们隶属于产品研发与工程架构部，是字节跳动在智能硬件领域的软件技术攻坚力量—— 聚焦 AI 与智能硬件的深度融合，如豆包手机助手等；以 “让人与设备的交互更自然、更便捷” 为目标，探索前沿 AI 技术的落地场景，打造行业领先的智能硬件综合解决方案。\n在这里，你将与一支顶尖技术团队并肩：\n- 直击 AI 与硬件结合的核心技术难题，参与从 “技术探索” 到 “场景落地” 的全链路研发；\n- 主导或深度参与关键技术突破，用创新定义智能硬件的交互未来；\n- 站在行业前沿，将技术理想转化为千万用户可感知的产品体验。\n如果你心怀对技术的热忱，渴望在 AI 与智能硬件的赛道上突破自我、创造价值，我们期待你的加入，与我们一起解锁更多技术可能，共筑智能交互的新生态！\n\n1、负责影像软件架构设计与代码开发；\n2、负责开发AI与智能硬件结合的功能，提升影像竞争力；\n3、负责软件算法集成与新硬件需求的开发，提升影像竞争力；\n4、负责影像各个场景的稳定性优化，与用户体验优化。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟练掌握计算机基础，包括但不限于操作系统原理，计算机组成原理；\n3、熟练掌握一门计算机编程语言，C/C++优先，MATLAB/Python等也可以；\n4、有图像处理相关项目经验或者实习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665318354483792133","sourceKey":"bytedance","company":"字节跳动","title":"数据科学 - 抖音用户增长","city":"北京/上海","category":"大数据","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665318354483792133/detail","duty":"团队介绍：抖音用户增长（User Growth）负责抖音、今日头条、番茄小说等多个产品的用户增长业务，建立行业领先的增长和营销技术，打造极致的用户体验。加入我们，有机会参与亿级用户场景的开发与架构工作，也有机会从数据出发，利用策略和模型为业务带来更大的助力。\n\n1、负责字节跳动用户行为的理解和建模，帮助业务满足用户需求，促进业务增长；\n2、基于用户数据和业务数据，进行商业智能分析，探索业务增长机会；\n3、基于用户数据和业务数据，进行数据挖掘，探索对内容、用户、场景的认识。","requirements":"1、2027届获得本科及以上学历，计算机、统计学相关专业优先；\n2、扎实的计算机编程能力，C/C++、Java、Python、SQL/HQL均可；\n3、有较强的业务和数据理解能力；\n4、有过数据治理、数据挖掘、商业智能、算法等大数据相关项目/实习经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7644128620855789877","sourceKey":"bytedance","company":"字节跳动","title":"数据分析实习生-抖音电商","city":"上海","category":"数据分析","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7644128620855789877/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：抖音电商致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、协助数据团队完成日常数据收集、整理、清洗工作，确保数据的准确性、完整性和时效性，处理基础数据异常问题；\n2、协助进行数据统计与分析，根据业务需求整理数据报表、绘制基础数据图表（如折线图、柱状图等），辅助输出数据分析初步结论；\n3、配合完成数据相关文档的整理与归档，包括数据字典、操作手册等，协助维护数据管理规范；\n4、协助对接业务部门，了解基础数据需求，配合完成简单的数据查询、提取工作，反馈数据使用过程中的问题；\n5、参与团队日常数据相关工作，学习数据处理、分析工具的使用，配合完成其他临时性数据相关任务。","requirements":"1、本科及以上学历在读，统计学、应用数学、计算机等理工科专业背景优先；\n2、对数据敏感，对数据类工作有高度热情；\n3、对数据应用场景有一定认识，有数据仓库、BI、数据挖掘、用户画像等方面的经验者优先；\n4、熟悉SQL/Hive，可熟练使用一种数据可视化分析工具；\n5、沟通表达能力优、协调推动能力好。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622244847551203589","sourceKey":"bytedance","company":"字节跳动","title":"视觉多模态大模型应用算法工程师-Seed大模型人才校招","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622244847551203589/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、负责多模态大模型的研发和应用，探索超大规模模型，进行极致系统优化；研究相关技术在豆包、智能助手、智能硬件等领域的全新应用和解决方案，包括而不限于多模态理解生成，视觉Agent等能力；\n2、数据建设、指令微调、偏好对齐、模型优化；\n3、相关应用落地，包括看图对话、问答、搜索、生成创作、逻辑推理、代码生成等；\n4、在未来生活中的更多使用场景的深入研究和探索，研发以人工智能技术为核心的新技术、新产品，满足用户不断增长的智能交互需求，全面提升用户在未来世界的生活和交流方式。","requirements":"1、2027届获得本科及以上学历，计算机/数学等相关专业的优先；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、具有扎实的计算机视觉、机器学习基础，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议上发表论文者优先；\n4、熟悉NLP、CV相关的算法和技术，熟悉大模型训练、RL算法者优先；\n5、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；\n6、具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7601816755878758709","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型Agent算法实习生-火山方舟","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7601816755878758709/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、验证探索LLM应用领域前沿的架构设计和模型优化（AgenticRL，Self-Evolving Agent，上下文工程，Multi-Agent System，模型路由）。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、了解LLM技术栈（如Prompt Engineering、SFT、RLHF、AgenticRL、RLVR等），有较强的问题分析和算法、数据优化能力；\n3、了解AI Agent技术栈（如 ToolUse、Skills、ReAct、Multi-Agent），具备扎实的代码能力，有想法且能动手；\n4、在ACL/EMNLP/NeurIPS等顶会发表LLM/Agent相关论文加分；开源模型、AI应用、Agent项目贡献者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7596680595154946357","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent研发质量效能工程实习生-飞书","city":"杭州","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7596680595154946357/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：飞书是AI时代先进生产力平台，提供一站式工作协同、组织管理、业务提效工具和深入企业场景的AI能力，助力企业能增长，有巧降。\n从互联网、高科技、消费零售，到制造、金融、医疗健康等，各行各业先进企业都在选择飞书，与飞书共创行业最佳实践。先进团队，先用飞书。\n\n1、参与飞书AI Harness质量系统的构建与演进，围绕服务端、Web端、移动端及AI相关能力，建设面向真实业务场景的自动化验证、评测执行、结果分析与质量闭环能力；\n2、参与团队AI质量体系与工程体系建设，包括但不限于：自动化评测、流程验证、持续集成、上线准入与质量门禁等；\n3、面向AI场景设计质量方案，覆盖结果质量、过程质量与系统稳定性，提升问题发现效率与质量反馈速度；\n4、参与线上问题追踪、归因分析与质量数据建设，推动问题从发现、定位到修复验证的闭环提效；\n5、参与通用质量工具、评测脚本与效率平台建设，提升团队在复杂业务和AI场景下的验证效率。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程、人工智能、自动化等相关专业优先；\n2、熟练使用至少一种AI编程工具，能够将AI能力应用于自动化验证、评测脚本开发、问题分析与质量效率优化等场景；\n3、具备基础的编程能力，至少熟悉一门常用开发语言；\n4、具备扎实的计算机基础知识，了解网络通信基础，包括TCP/IP、HTTP等常见协议；\n5、对AI产品质量、自动化验证、评测体系或工程效率方向有兴趣，理解除“结果是否正确”之外，还需要关注“过程是否可控、系统是否稳定、反馈是否高效”；\n6、有脚本开发、工具开发或工程实践经验者优先；了解常见的自动化方法、数据驱动验证思路或持续集成流程，有质量工具、评测平台、自动化流程或工程效率建设经验者优先；了解常见算法评测方法与客观评估指标，有大模型、搜索、NLP、语音、多模态等相关评测经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7595096815294695685","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发实习生-质量技术","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7595096815294695685/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动质量技术团队，我们聚焦质量领域前沿创新，打造稳定、高效、领先的质量技术，深度赋能抖音、今日头条、豆包、电商等亿级用户产品。\n当前，我们通过AI来检测代码、架构、产品的缺陷、风险和效果，用AI重构质量保障模式，提升研发效能。聚焦智能缺陷检测、GUI agent、AI评测等前沿方向，希望通过质量技术的突破，用AI改变测试行业。欢迎加入，与我们一起，定义和构建下一代质量技术，推动行业前进。\n\n1、负责AI智能平台的后端研发工作，包括产品需求分析，架构设计、技术攻坚，产品开发与优化工作；\n2、与前端，产品，UI一起提升产品的用户体验，打造卓越的智能化产品（GUI/LUI）；\n3、关注质量智能领域前沿AI技术发展，能够将新知识传递给团队，并且转化到潜在项目中。","requirements":"1、2027届本科及以上学历在读，计算机、通信等相关专业优先；\n2、扎实的计算机基础知识，熟悉常用的数据结构与算法，并能在日常研发中灵活使用；\n3、有较强的学习能力，有强烈的求知欲、好奇心和进取心，能及时关注和学习业界最新技术；\n4、深入了解大语言模型相关技术及应用，有AI工程落地经验者优先；有大规模系统架构经验优先；\n5、能够独立完成一个复杂模块或项目的研发工作；\n6、具备较强的责任感、团队合作精神、逻辑思维能力和表达能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7350236714797730086","sourceKey":"bytedance","company":"字节跳动","title":"政策研究实习生 - 隐私和数据保护办公室","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7350236714797730086/detail","duty":"团队介绍：我们是字节跳动隐私与数据保护核心团队，联动法律、安全、研发等多方力量，为全球数亿用户构建第一道数据安全防线。聚焦隐私合规落地、数据风险防控，在超150个国家/地区的复杂隐私、数据合规场景中，构建全生命周期数据安全方案，以“隐私+数据”双通道驱动保护创新。\n为什么加入我们？\n1、全球化核心战场：加入支撑字节跳动国际化生态的关键团队，主导服务数亿用户的隐私安全体系，同字节跳动系产品一起定义行业标准；\n2、硬核能力历练：攻克数亿级数据防护，横跨美洲、欧盟、东南亚等法律差异等难题，沉淀覆盖多区域的合规技术视野；\n3、多元成长生态：融入跨多国家多城市的协作团队，参与行业隐私标杆项目，在文化碰撞中解锁国际化合规实战经验。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深度了解产品和服务的特性，协助团队从法律合规、产业论证、技术实现、设计理念等不同角度分析优劣、盲点、优化重心与发展趋势；\n2、密切追踪和理解国际政策和立法动态，协助团队将立法和政策等规制或规范思路与产品服务逻辑对接和交互；\n3、支持研究流程各环节，包括信息收集整合、问题框架搭建、项目协调设计、论点和论据支撑、学术会议主旨发言和讨论、学术论文写作、研究成果落地等；\n4、有跨学科交流能力，能与业务、法务团队及不同背景的同事交流，协助团队提供有价值的输出的同时能够获取所需的研究思路、方向；\n5、支持集团内部隐私和数据保护培训和相关活动，协助团队设计培训材料、活动和流程。","requirements":"1、本科及以上学历在读，法律、公共政策、计算科学（偏社会和隐私安全方向）、隐私工程等相关专业优先；\n2、具备良好的英语听说读写能力，能够进行专业交流和撰写专业文本；\n3、对隐私和数据保护相关的法律、技术和社会问题有基础理解，熟悉欧盟数据保护法（GDPR、EUDPR、ePrivacy、LED等），并对其他国家和地区相关立法有基础性了解；\n4、对数字治理相关议题有研究兴趣，对2018年以来欧盟（以及其他国家和地区）在数字治理领域的若干立法有基础性了解优先；\n5、具备持续学习能力，对新知识和技能保持开放态度，并能迅速适应变化；能够在多元文化背景中工作，尊重和理解不同文化和观点。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7330161472447809842","sourceKey":"bytedance","company":"字节跳动","title":"电商多模态大模型算法实习生-电商业务","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7330161472447809842/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：Data-电商团队，负责电商创新项目的算法和大数据工作。依托于字节跳动产品，帮助用户发现并获得好物，享受美好生活。在这个团队，我们不仅要通过推荐和搜索算法帮助用户买到感兴趣的好东西，也要通过风控算法和智能平台治理算法去甄别违规行为，保护用户的购物体验；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户体验；另外我们还会用人工智能来帮助商家提升经营能力。我们的使命：没有难卖的优价好物，让美好生活触手可得。\n\n1、大模型算法研发：构建电商领域的大模型LLM底座，融合电商的知识，快速落地电商业务，例如：沉淀电商大模型预训练链路，研发电商NLP大模型，或者研发电商图文或者视频多模态大模型；\n2、基础算法研发：持续建设和深耕NLP/CV/多模态基础预训练算法（BERT类算法），例如：沉淀&优化电商场景的预训练模型，包括超长文本/口语文本预训练，电商图片/视频自监督，适配电商商品的多模态表征学习等；\n3、梳理&沉淀算法库，抽象算法接口，最大化提高算法/预训练模型的复用率，同时优化数据采集&模型训练&部署&推理的流程，提升研发效率；\n4、技术输出：定期分享SOTA模型，赋能电商甚至公司级别的业务BU，沉淀专利和论文。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、扎实的深度学习技术基础，有CV/NLP/多模态相关的项目经验，发表过高水平学术会议论文或者有竞赛经验者优先；\n3、熟练掌握Python/C++等至少一门编程语言；熟练Pytorch训练框架；熟悉Hunggingface-Transformers框架；\n4、熟悉常用的大语言模型架构优先；\n5、了解模型压缩&推理加速的研究和技术进展，包括但不限于模型量化、剪枝、蒸馏、TensorRT推理优化等；\n6、了解业界常用的大语言模型推理加速框架，如VLLM，TensorRT-LLM；了解混合精度训练、分布式训练等训练加速方法优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7275279986729519419","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生 - 中国交易与广告","city":"上海/杭州/成都/北京","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7275279986729519419/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与生活服务平台治理相关的前端研发工作，完整参与整个产品的设计与研发，包括：需求评审、UI/UE评审、编码、前后端协作等各个环节，保证系统质量；\n2、持续迭代和优化系统，提升交互体验，系统性能，可用性，扩展性以及监控能力；\n3、进行前端基础组件建设，探索新技术并推动落地，提升开发效率和系统稳定性。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、精通HTML、CSS、JS，熟悉页面架构和布局，熟悉HTML5/CSS3等常用技术，熟悉常用UI框架（如Bootstrap/Pure/Kendo等)；\n3、精通JavaScript、Ajax、DOM、jQuery等技术，熟悉NodeJS，熟练使用Grunt、gulp、Webpack等构建工具；\n4、具备MVVM框架开发经验，如React、VueJS、AngularJS等；\n5、良好的沟通和团队协作能力、热爱技术、责任心强、能推动技术框架的落地使用。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676425531558889733","sourceKey":"bytedance","company":"字节跳动","title":"UK商城供给孵化运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676425531558889733/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责研究并优化UK商城的货盘供给策略，提升供给效率；协助联动场域搜推、UG、行业团队，输出针对不同场景的有效供给，如高搜货盘、潜力货盘，拉动商城GMV增长的供给货盘；\n2、结合重点货盘和有效供给特征，与各资源团队合作，联动商城新品补贴、频道等资源以及与搜推团队联动，优化商品分发，研究场域与货盘的匹配逻辑，对比钱效和重点货盘GMV持续贡献；\n3、强数据分析和决策能力，具备SQL和风神取数、有复杂数据分析工作经验，具备独立完成供给分析与诊断能力；基于数据工具，不断完善监控体系和分析效率。","requirements":"1、本科及以上学历在读；\n2、实习期不低于5个月，每周到岗不低于4天；\n3、具备良好的数据分析意识，熟练掌握相关数据分析工具的使用（SQL取数优先）；\n4、有过数据分析或ds实习经历优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675929837876037893","sourceKey":"bytedance","company":"字节跳动","title":"达人策略（直播方向）实习生 - TikTok生活服务","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675929837876037893/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间,让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok生活服务(TikTok GO) 是一站式商业解决方案，创造性地通过TikTok POI、短视频、直播和搜索等，连接全球用户与本地服务，提供有价值的真实世界生活体验，激发用户探索周围的世界。以“发现好去处，助力本地商家”为使命，致力于成为最值得信赖的发现好去处和连接本地商家的平台，让社区更轻松地与餐厅、酒店和景点互动，为商家提供全新方式来连接客户并促进交易，结合创新的营销和运营工具，带来可持续增长。团队分布多国，目前积极扩张中。大航海时代，我们欢迎大家一起加入国际化征程，共同打造TikTok生活服务业务!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助策略团队展开本地生活直播数据分析和策略制定工作，包括但不限于：行业趋势分析、主播成长路径、商家达人撮合等；\n2、负责异动指标分析和归因，并能在过程中找到业务机会点并进行下钻研究分析；\n3、协同行业、商家、产品等团队，推动重点项目落地并交付结果。","requirements":"1、本科及以上学历在读；\n2、英语听说读写流利，可作为工作语言；\n3、能够每周至少工作4天，且持续工作至少6个月；\n4、有战略分析、数据/策略分析、行业研究等实习经验，了解TikTok平台特性及餐饮行业内容趋势者优先；\n5、较好的数据意识和分析能力，能自主完成数据清洗、整理、分析，能使用SQL优先；\n6、较强的逻辑思维能力和跨团队沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675675169187219717","sourceKey":"bytedance","company":"字节跳动","title":"营销工具产品经理（AI方向） - TikTok Shop","city":"上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675675169187219717/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责TikTok Shop营销工具营销增长方向的产品规划与落地，围绕商家分层与多种营销工具特点，提升工具渗透率与采纳率，驱动大盘GMV增长；\n2、主导营销工具策略的产品设计，推动C端到、商品能力同步等关键链路建设，协同上下游打通可凑单商品的覆盖率与转化闭环；\n3、基于数据分析驱动产品迭代，关注各工具GMV占比、AOV撬动、ROAS等核心指标，量化产品收益并为目标拆解提供数据支撑；\n4、理解电商平台在生态中发挥的作用，产品规划能够支撑平台健壮、规模化发展。","requirements":"1、2027届获得本科及以上学历，计算机等理工类相关专业优先；\n2、有电商B端产品相关经验优先；\n3、跨团队协作能力强，具备优秀的沟通表达能力；\n4、具备良好的逻辑思维与抽象能力；\n5、有英文语言能力优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669731505744234757","sourceKey":"bytedance","company":"字节跳动","title":"多模态算法工程师 - TikTok内容安全算法","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669731505744234757/detail","duty":"团队介绍：国际化内容安全算法研究团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，团队同时负责产品基座大模型的研发，我们在研发过程中需要解决数据合规、模型推理能力、多语种性能优化等方面的问题，从而为平台上的内容审核、搜索、推荐等多项业务提供安全合规，性能优越的基座模型。\n\n1、负责多模态大模型在TikTok内容安全场景中的算法研发与落地，包括视频理解、跨模态检索、复杂语义推理等方向；\n2、探索大模型预训练、后训练及对齐技术，包括但不限于SFT、RL、Reward Model、模型蒸馏等，提升模型在复杂任务中的理解、推理、对齐和泛化能力；\n3、探索Agent、GUI-Agent、Agentic RL、Self-Evolving、Loop Engineering等技术在创新业务场景中的应用，包括短剧、小游戏等内容形态，推动前沿技术的业务落地；\n4、与产品、策略、工程、数据、评估等团队紧密协作，推动数据构建、模型训练、评测体系、线上部署到业务反馈闭环的完整算法迭代。","requirements":"1、2027届获得硕士及以上学位，计算机、人工智能等相关专业背景；\n2、具备扎实的算法基础，熟悉大语言模型、多模态大模型或视觉语言模型相关技术，对LLM、VLM、Agent、视频理解、多模态检索、RL、Agentic RL等一个或多个方向有深入理解；\n3、具备扎实的算法工程实现能力，熟悉常见的大模型训练与推理框架，能够独立完成模型训练、调优、评估和性能优化；\n4、具备较强的问题抽象能力和业务理解能力，能够在复杂、不确定的真实场景中提出有效技术方案，并推动落地；\n5、具备良好的沟通协作能力，能够与跨职能团队共同推进高影响力项目；\n6、具备大模型、计算机视觉、多模态、NLP、推荐/搜索或内容理解相关研发经验，有模型训练、后训练或线上落地经验，或在NeurIPS、ICML、ICLR、CVPR、ICCV、ECCV、ACL、EMNLP等顶级会议或期刊发表论文，或在高水平竞赛中取得优秀成绩者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669691023216199941","sourceKey":"bytedance","company":"字节跳动","title":"智能AI产品运营 - 商业化","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669691023216199941/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、了解并充分评估商业化业务进展，与产品研发团队紧密合作，确保智能服务产品的稳定运行以及相关需求落地，并协同算法进行知识挖掘和模型效果改善；\n2、挖掘商业化营销合作及品牌投放链路中的流程痛点，运用AI思维诊断业务风险，并提出可行性分析和优化方案，输出智能化资源组合推荐、售卖流程优化、效率提升及服务改进方案；\n3、协同战略、销售、产品、法财税等团队，通过AI赋能、系统迭代、智能工具搭建，推动业务合规落地，打造更智能、高效的商业化服务体验。","requirements":"1、2027届获得本科及以上学历；\n2、对AI工具或大模型有一定基础了解，愿意长期在AI相关领域发展；\n3、具备良好的沟通能力和团队合作精神，自驱力强，能够与不同部门的人员合作完成项目；\n4、具备较强的学习能力和创新能力，能够不断提升自己的技术水平和业务能力；\n5、对客户需求和用户体验有深刻的理解，能够从客户角度出发设计和优化系统。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667590063169341701","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 抖音电商","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667590063169341701/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商平台客服AI产品建设，围绕咨询、售前售后、投诉等服务场景，设计并推动智能客服Agent落地，对产品效果负责；\n2、参与平台客服Agent建设，负责Query理解、方案召回、智能决策、工具调用、方案生成和用户交互等全链路产品设计与优化；\n3、建设智能客服评估和优化体系，通过业务案例、效果评测、问题分析和线上实验，持续提升AI服务能力，推动客服从“回答问题”向“解决问题”升级。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程、数据科学等相关专业优先；\n2、具备大模型应用能力，了解AI Agent构建与优化方法，熟悉Agent Harness、RAG、Prompt Engineering、Tool Calling、Agent Loop等核心技术，能够结合业务场景推动Agent效果优化；\n3、对电商、客服和用户体验方向有兴趣，具备业务理解能力，能够洞察用户需求并推动产品落地；\n4、具备较强的数据分析和问题解决能力，能够通过数据、实验和用户反馈持续优化AI产品效果；\n5、学习能力强，逻辑清晰，自驱力强，能够在快速发展的AI产品领域持续探索。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667144702417750277","sourceKey":"bytedance","company":"字节跳动","title":"代码智能大模型算法研究员 - TRAE","city":"北京/上海/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667144702417750277/detail","duty":"团队介绍：TRAE是字节跳动旗下AI办公工具，产品已上线国际版与中国版，拥有TRAE IDE和TRAE Work两种产品；既可以用TRAE IDE写代码、读项目、改Bug，也可以用TRAE Work写方案、做分析、做应用、推进协作。TRAE当前支持PC、手机、Web多端使用，让用户随时随地高效产出！ Let TRAE Work For You！同时我们正在寻找充满热情、富有创造力的人才。期待你的加入！\n\n1、负责代码领域的模型效果优化，深入研究LLM后训练等相关技术，提升训练效果和效率；\n2、分析业务场景，设计并实现适用于不同场景的算法解决方案，支持产品效果方面的需求；\n3、持续跟进LLM前沿技术，聚焦LLM在软件工程领域中的应用。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、数学、软件工程等相关专业优先；\n2、具备优秀的代码能力、数据结构和基础算法功底，熟练掌握C/C++、Python等一个或多个编程语言；熟悉大模型相关的算法和技术，有自然语言处理（NLP）和大模型训练和强化学习（RL）算法经验者优先；\n3、在软件工程或者人工智能领域有出色的科研经历，在NeurlPS/ICRL/ICML/ISSTA/ACL/EMNLP/ICSE/ASE/FSE等国际顶级期刊会议上发表论文者优先；\n4、具备出色的问题分析和解决能力，有自主探索解决方案的能力；良好的沟通协作能力，能和团队一起探索新技术，推进技术进步；\n5、出色的心理素质与应变能力，面对困难勇于迎接挑战；面对复杂局面沉着、冷静、灵活。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628896431759231285","sourceKey":"bytedance","company":"字节跳动","title":"抖音多业务场景的大模型训练与应用-抖音AI","city":"杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628896431759231285/detail","duty":"团队介绍：抖音AI团队主要负责抖音项目以及团队内的AI落地相关基础建设工作。我们的职责是用前沿的AI技术去赋能抖音应用以及抖音团队。我们希望在AI技术的加持下，能够更好的给抖音用户带来更好的信息消费体验，也能够让抖音这个大型组织能够更加高效的运转，从而更加及时的满足用户的各项诉求。团队主要负责抖音AI基础建设，包括但不限于模型训练、Agent相关的工程链路开发、通用Agent工具抽象以及AI Native的各类产品开发工作。AGI信仰强，以发展成为AI Native组织为目标，努力拓展传统协作模式的职责边界，充分给同学们提供自身探索的空间。\n\n课题介绍：\n抖音研发团队，负责抖音短视频、直播、中长视频、搜索、图文、音乐、社交通讯、医疗等业务技术开发，以及字节跳动旗下产品的客服平台、业务安全、用户增长、用户体验、抖音账号、AI技术研究与赋能等中台团队的研发工作。本次课题共涉及5个方向：\n1、用户体验：抖音场景下的端侧大模型架构与推理加速体系研究；\n2、抖音直播：迭代3D生成大模型，优化数据、编码和模型架构，提升3D资产生成效率和品质；\n3、汽水音乐：聚焦音乐生成大模型的核心算法研究与优化，旨在攻克上述技术瓶颈，提升AI音乐创作的质量、可控性与创新性，赋能短视频配乐、虚拟偶像等多元应用场景；\n4、AI技术研究与赋能：随着大模型在代码生成与软件开发中的应用不断深化，构建端到端AI Coding模型已成为提升研发效率的关键方向。本课题聚焦从数据构建、模型训练（SFT/RL）、到推理部署的全链路优化，探索从需求理解，代码生成与修复，与功能上线的一体化建模方法。重点解决领域知识注入、大规模SFT训练、Agentic RL等问题，推动AI在抖音等真实业务研发场景中的规模化落地；\n5、小荷健康：围绕问诊、工具调用、科普与病例分析，提升医疗大模型任务规划与推理能力，保证结果准确稳定可用。\n\n课题挑战：\n1、资源约束极强，需兼顾算力、内存与功耗；通用性要求高，需支撑多业务场景高精度处理；面向差异化设备，实现任务复杂度的弹性适配；\n2、高质量3D数据严重稀缺，3D几何与纹理表征复杂，生成质量与美术水准比仍有差距，当前链路冗长效率偏低；\n3、音乐审美偏好的量化建模问题、长序列高品质音乐生成问题、多风格泛化与创新生成问题、推理增强方法的迁移应用问题；\n4、抖音研发大模型需高效的业务知识注入，复杂且超长的上下文管理，解决高质量训练数据稀缺，Agentic RL的持续训练；\n5、小荷健康围绕医疗场景基座模型 ，Agent Foundation构建与评测体系，强化模型复杂知识检索、任务分解及长链路执行能力。通过优化 SFT、RL、OPD等后训练方法的组合策略，兼顾模型效果、稳定性与泛化性。同时探究线上用户体验与基座模型训练间的关联，实现医疗大模型能力与实际应用效果的协同提升。\n\n课题价值：\n1、技术价值：等参数量级下，可大规模落地的业界领先模型；业务价值：提升抖音用户和业务接入的覆盖面，获得用户和营收价值；\n2、技术上提升3D表征与生成能力，迭代3D生成大模型；业务上支撑直播和社交应用，产出丰富3D资产，满足海量用户的个性化需求；\n3、技术上突破音乐生成在审美建模、长序列连贯性等核心瓶颈，引领AI音乐生成技术前沿；业务上提升抖音/汽水音乐的AI创作能力，降低音乐创作门槛，丰富内容生态，提供音乐内容供给；\n4、技术上探索前沿模型训练策略，构建字节内部真实环境下的数据飞轮，提高业务研发效率，提升代码质量与性能；\n5、技术上提升医疗大模型Agent与Post-Training方向的关键技术突破，提升问诊、科普、病例分析等核心场景业务效果，沉淀可复用的数据、训练与评测方法，支撑长期模型演进。","requirements":"1、2027届毕业，获得博士学位，计算机、软件工程、人工智能等相关专业；\n2、优秀的问题分析与解决能力，能够深入解决大模型训练及应用中的复杂问题；\n3、具备数据构建、指令微调及模型开发经验；\n4、熟悉大模型相关技术，掌握相关训练推理框架，对大模型预训练、指令微调、Agent训练、RL等方向有深入研究和实践。\n\n加分项\n1、熟悉代码领域，熟悉Agent训练和Agentic RL训练，熟悉MoE模型训练者优先；\n2、以第一作者在ICML、ICLR、NeurIPS、ACL、ICSE、FSE等顶级学术会议发表过有影响力的研究成果者优先；\n3、在ACM/ICPC、NOI/IOI、Kaggle等编程或AI竞赛中获奖者优先；\n4、主导或参与过具有影响力的AI开源或闭源项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7472981470840146183","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-TikTok社交","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7472981470840146183/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok社交团队业务覆盖国际化短视频产品内所有社交场景,包括评论、点赞、通知,以及多种创新社交场景，对增加用户活跃度和用户粘性有着至关重要的作用。\n在这里，有大牛带队与大家一同不断探索前沿,突破想象空间。\n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队人专业且纯粹,合作氛围平等且轻松。\n\n1、参与大规模分布式系统的架构设计与开发，支撑亿级用户的社交互动；\n2、参与系统技术方案设计、性能优化与稳定性建设；\n3、参与AI能力在社交场景中的落地（如AI ChatBot、智能回复、多模态互动等）；\n4、参与构建工程质量体系（代码规范、测试规范、自动化能力等）；\n5、协助解决高并发、数据一致性、系统解耦等技术挑战；\n6、参与AI前沿技术调研与新技术落地。","requirements":"1、2027届本科及以上学历在读，计算机、软件、电子信息等相关专业； \n2、掌握Golang或C++语言，有扎实的数据结构和算法功底；\n3、理解计算机原理、计算机网络，熟悉业内常用的基础组件；\n4、对技术有热情，既有高远目标，也能脚踏实地，责任心强、积极主动；\n5、熟练使用AI Coding工具，对大模型/AI ChatBot/Agent有兴趣或实践经验者优先；\n6、喜欢研究开源新技术，开源贡献者、GitHub源码者、技术博客者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680886482614339893","sourceKey":"bytedance","company":"字节跳动","title":"墨西哥大促策略运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680886482614339893/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持墨西哥TikTok Shop核心项目，推动平台增长并实现业务目标，包括但不限于平台大促、联盟和内容、商城运营等；\n2、能够在适度指导下进行细致的资源管理、市场调研及其他运营工作；\n3、协调相关跨职能团队的资源，确保项目正常有序地开展和实施；\n4、与后端支持团队沟通，持续优化基础设施建设；\n5、根据需要持续跟踪项目绩效指标；能够识别并制定负责项目的改进计划。","requirements":"1、本科及以上学历在读；\n2、具有逻辑性思考、多视角思考（商家视角/平台视角/各职能视角），思维敏捷活络，愿意协调解决复杂问题，沟通表达清楚；\n3、具有较强的数据敏感度和分析能力；\n4、英语可以作为日常工作沟通语言；\n5、可实习时间不少于6个月，每周不低于4天，期间工作投入度高。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667869640871627013","sourceKey":"bytedance","company":"字节跳动","title":"3D生成算法工程师 - 抖音直播","city":"深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667869640871627013/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、负责抖音直播及相关产品的AIGC算法研发，如数字人、动作驱动、3D生成等相关工作；\n2、负责关键场景AIGC算法优化，提升业务效果；\n3、跟踪AIGC前沿技术进展，并推动前沿技术的产品化落地。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、软件工程等相关专业；\n2、具有优秀的编程能力，熟练使用Python/C++等至少一种编程语言，熟练使用TensorFlow/PyTorch等至少一种深度学习框架；\n3、熟悉扩散模型、VAE等模型结构，有3D生成、数字人、Unity/Unreal引擎等相关项目经验者优先考虑；\n4、在图形学、AIGC等相关方向发表过高质量论文者优先考虑；\n5、优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情，良好的沟通和团队合作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665614487081601285","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发工程师 - 抖音AI","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665614487081601285/detail","duty":"团队介绍：抖音AI团队主要负责抖音项目以及团队内的AI落地相关基础建设工作。我们的职责是用前沿的AI技术去赋能抖音应用以及抖音团队。我们希望在AI技术的加持下，能够更好的给抖音用户带来更好的信息消费体验，也能够让抖音这个大型组织能够更加高效的运转，从而更加及时的满足用户的各项诉求。团队主要负责抖音AI基础建设，包括但不限于模型训练、Agent相关的工程链路开发、通用Agent工具抽象以及AI Native的各类产品开发工作。AGI信仰强，以发展成为AI Native组织为目标，努力拓展传统协作模式的职责边界，充分给同学们提供自身探索的空间。\n\n1、聚焦抖音内研发提效场景，参与AI-Native研发流程中的Agent设计、效果调优和评测设计；\n2、围绕抖音内研发建设Agent基建，探索Agent最佳实践和Agent交互范式，推动产品体验优化；\n3、持续跟踪AI Coding领域的最新技术动态，并将其应用于实际业务场景中，推动技术落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、具备扎实的软件开发基础，熟悉C/C++/Golang/Java/Python/Android/iOS中至少一门编程语言或技术栈；\n3、优秀的问题分析与解决能力，学习能力强，具备技术好奇心，乐于探索并实践新技术、新方向；了解Agent开发、RAG、编排调优、上下文工程开发等至少一项开发经验；\n4、深度使用Copilot、Cursor、Claude Code等AI编程工具者优先。\n\n加分项\n1、持续关注Agentic AI领域的前沿技术，拥有Agent System相关的研发实践经验者优先；或熟悉大模型相关技术，对大模型预训练、指令微调、RL等方向有了解和实践；\n2、有Pretrain研究或应用经验者优先，熟悉代码领域的预训练与微调方法者优先；\n3、以第一作者在ICML、ICLR、NeurIPS、ACL等顶级学术会议发表过高影响力研究成果者优先；\n4、在ACM/ICPC、NOI/IOI、Kaggle等编程或AI竞赛中获奖者优先；\n5、主导或参与过具有广泛影响力的AI开源或闭源项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664629827266857221","sourceKey":"bytedance","company":"字节跳动","title":"传输智能算法工程师 - 音视频技术","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664629827266857221/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、打造业界领先的多模态数据处理、多媒体AI计算平台，支持Seed生成、视觉、语言等大模型的预训练数据处理、豆包AI实时通话计算平台等重点业务；2、负责平台的架构设计和研发，包括高性能数据处理框架、任务调度、资源管理、模型、算子管理、自动伸缩服务等；3、基于K8s体系构建大规模任务处理系统，并负责GPU、CPU等多种异构资源的编排调度优化；4、负责云平台与字节跳动火山引擎基础设施如计算、存储、AI模型等上下游生态的集成。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、学习能力强，有独立解决问题的能力；\n3、熟悉面向对象编程，掌握Java/C++/Python/Go中的至少一门语言，Go背景优先；\n4、有良好的沟通能力和业务理解能力；\n5、对技术有好奇心，持续关注熟悉前沿技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664532550576965941","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发实习生 - TikTok直播","city":"深圳/广州","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664532550576965941/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播研发团队，旨在实现TikTok直播业务的研发工作，搭建及维护业界领先的产品。\n加入我们，你能接触到包括：社交互动、营收活动、主播生态、消费订阅、游戏直播、公会&运营平台等核心业务场景，支持产品在全球赛道上高速发展；\n也能接触到包括服务架构、大模型算法、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 \n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队专业且纯粹，合作氛围平等且轻松。\n目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与TikTok业务产品研发，深度参与产品需求讨论，ToC和ToB的功能构建等；\n2、参与设计基于前端和全栈的解决方案，代码开发、组件抽象以及系统调优等；\n3、参与系统工程效率和性能优化，提升研发效率以及用户体验；\n4、调研和学习前端新技术，进行技术分享并在项目内落地，参与部门前端和全栈技术建设。","requirements":"1、本科及以上学历在读，计算机、软件工程、电子信息等相关专业优先；\n2、具备良好的计算机和Web开发基础，有JavaScript/TypeScript及React等前端开发经验；了解Node.js、Go、Python、Java等至少一种服务端技术，有全栈项目实践者优先；\n3、对AI Coding工具有较强的使用兴趣和意愿，乐于探索AI在编码、测试和问题排查等研发环节中的应用；\n4、具备良好的编程习惯和代码管理意识，了解基本的软件设计原则，能够在指导下完成业务开发，并主动排查和解决问题；\n5、认可AI辅助研发方式，愿意长期向全栈方向发展，具备较强的学习和适应能力；主动负责，具备良好的沟通与团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677571671927212341","sourceKey":"bytedance","company":"字节跳动","title":"数据分析实习生 - TikTok Shop","city":"北京/上海","category":"数据分析","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677571671927212341/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与国际电商数据体系建设，结合全域数据生态，为国际电商大促业务发展提供数据能力支撑；\n2、参与数据模型的规划与设计、业务数据报表需求分析、设计、落地，为业务及管理层提供决策支持；\n3、挖掘国际电商业务中的各项数据需求，探索AI Agent等创新型数据产品，驱动模型和策略的优化。","requirements":"1、本科及以上学历在读；\n2、对数据敏感，有缜密的逻辑思维能力、数据洞察能力和沟通协调能力，熟练掌握AI、SQL、BI产品使用；结果导向，责任心强，能够独立负责某个小型数据项目的沟通、开发、落地；\n3、有电商行业数据岗位实习经历者优先；\n4、且同理心强，擅长跨文化/跨行业背景沟通，英语可作为日常工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667109941203159301","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（用户增长） - TikTok研发","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667109941203159301/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责TikTok用户增长业务的服务端研发工作；\n2、深入发掘和分析业务需求，设计合理的技术方案并实现；\n3、持续对系统进行架构改造和优化，提升系统的稳定性与可扩展性。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、熟练使用基本的数据结构与算法，具备良好的编码习惯；\n3、有分布式系统的设计和开发经验，能独立完成系统的设计及开发；\n4、熟练掌握Golang/Java/Python常用框架，深入了解框架提供的特性及其实现原理细节；\n5、熟悉分布式系统，熟练掌握关系型、非关系型数据库，熟练掌握一种以上服务框架和消息中间件，了解各自的实现原理及使用场景；\n6、有较强的责任心、自驱力和成长型思维。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664849986345568565","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师（广告业务） - 中国交易与广告","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664849986345568565/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、依托各类AI Coding工具，独立完成广告业务相关项目的前后端全栈开发、功能迭代与接口联调，负责前/后端技术选型和开发工作，参与方案设计，保障业务需求高质量落地；\n2、主导或参与前后端基础设施建设，包括组件库沉淀、工程化工具链优化、CI/CD流程改进，提升团队研发效率；\n3、与产品、算法等团队紧密协作，推动跨团队技术方案对齐，保障项目按时交付；\n4、参与Agent在广告业务场景中的落地探索（如Agent产品交互开发、工作流编排等），利用AI Coding工具提升个人及团队开发效率，跟进前沿Agent开源方案，沉淀可复用的调度模板与工程最佳实践。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程等相关专业；\n2、掌握Python/Go/Java/JavaScript任意2门开发语言，熟悉Node.js/Go，具备前后端一体化开发能力；\n3、理解LLM基础原理，熟悉AI Agent核心模块（Prompt、记忆机制、工具调用、RAG、多智能体），能区分不同层级模型的业务适用场景；\n4、熟练掌握主流AI编码工具（TRAE、Claude Code、Codex等），能够利用AI完成需求拆解、代码编写、复杂逻辑重构、Bug定位修复、单测编写、代码评审，具备AI协同研发思维；\n5、熟悉Git基础操作，具备良好的沟通能力与团队合作精神；对技术保持好奇心，善于独立思考并反思总结；\n6、有相关岗位实习及项目开发经历优先。\n\n加分项：\n1、有AI辅助前后端全栈开发、Agent项目部署与二次开发实战经验；\n2、实操过Agent任务拆分、多智能体并行调度、模型自动择优等核心功能；\n3、熟悉MCP协议、LLM工具调用、AI自动化工作流搭建；\n4、有对话应用、智能编排、知识库平台等相关项目开发经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628565963559389445","sourceKey":"bytedance","company":"字节跳动","title":"AI芯片的架构/物理实现和系统设计（芯片物理）-芯片研发（上海）","city":"上海","category":"硬件","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628565963559389445/detail","duty":"团队介绍：字节芯片研发团队目前工作主要集中在芯片设计环节，主要围绕字节自身业务展开芯片探索，为字节多项业务的专用场景定制硬件优化，设计多款基于先进半导体工艺的云端复杂芯片，以期提升性能、降低成本。早期若干芯片项目已经进入到量产部署阶段，有多次一版成功的投片经历，所用工艺包含多个主流的先进工艺节点。与基础设施各团队之间工作的整体协同，能更容易和更好地发挥芯片研发的价值。\n\n课题介绍：\n研究方向：集成电路设计、计算机体系结构、半导体、存储系统、机器学习系统、计算机网络。\n \n芯片设计\n1、负责AI芯片架构/微架构探索与方案设计，包括AI推理/训练系统软硬件协同优化、AI模型与算子特性分析、硬件实现方案制定与性能优化、数据中心ASIC芯片微架构探索、RTL设计与集成、业内先进AI芯片微架构跟踪调研、benchmark总结与搭建、芯片互联网络协议与架构演进；\n2、重点投入到AI芯片架构、微架构、AI工具链、Scale up/Scale out/Switch等方向。\n \n芯片物理层设计\n1、负责ASIC/CPU芯片的物理层研发，具体包括逻辑综合、可测性设计、后端设计、定制IP设计、封装仿真、硅后研发等环节；\n2、重点投入到高级封装、高性能IP设计、高性能设计方法学、物理前沿技术（AI for EDA、DTCO）等方向。\n\n课题挑战：\n1、探索AI计算、高速互联、存储、先进封装一体化协同架构；\n2、负责创新架构与系统设计；\n3、与软硬件团队协同，落地AI训练/推理芯片与数据中心系统。\n\n课题价值：\n不断探索芯片前沿架构，支持字节火山引擎、抖音、豆包等业务，持续扩展应用领域，赋能LLM、视频/图片生成、视觉理解等大模型方向。以高性能、高精度、高可用性、低成本为目标，提供端云全场景覆盖、软硬件协同的AI芯片和系统解决方案。","requirements":"1、2027届毕业，获得博士学位，计算机/电子/微电子/通信等相关专业优先；\n2、熟悉芯片设计的中后端和封测流程，有相关项目经验者优先；\n3、良好的团队合作精神，认真负责的工作态度；\n4、良好的沟通能力，英语读写顺畅。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592501882166249733","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-数据库","city":"上海","category":"基础架构","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592501882166249733/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027届8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动基础设施数据库团队，致力于构建认知型数据基础设施，持续定义数据技术的未来边界。团队基于全栈自研技术，打造了涵盖关系型数据库、NoSQL 数据库、大规模图平台、多模态搜索、云原生中间件等十余项产品的数据库矩阵，用独创的技术架构实现事务处理、混合查询、智能检索等全场景覆盖。面向 AI 时代，我们正在突破传统架构边界：一方面深化 AI 原生驱动内核、AI 算子优化等创新方向，推动数据库向智能 Copilot 演进；另一方面聚焦超大规模图计算、分布式跨模态数据联邦查询等前沿领域，构建支持跨模态数据管理的下一代设施。我们践行“务实浪漫”的极客文化，既在 VLDB 、SIGMOD 等顶级会议持续输出突破性成果，又以商业落地为导向打造全场景的产品矩阵。\n\n1、参与AI时代的数据库产品研发与架构设计：涵盖支持AI/ML工作负载的新型数据库系统架构，优化AI模型训练与推理的数据访问效率；构建支持向量搜索、图计算、时序分析等AI场景的混合型数据库解决方案，探索LLM大模型与数据库系统的深度集成方案，如自然语言SQL生成、智能查询优化；\n2、参与数据库智能策略研发：研发基于AI的数据库性能调优系统，包括自动索引推荐、查询计划优化、资源分配策略等；构建智能监控系统，实现异常检测、根因分析、容量预测等AIOps能力；\n3、参与AI数据基础设施的构建：构建AI数据基础设施，如支持特征工程、模型训练、推理服务的全流程数据管道架构，实现数据库与机器学习框架（TensorFlow/PyTorch）的高效对接；\n4、参与AI与数据库结合的实践方案探索与落地：探索AI技术和数据库各产品结合的最佳实践方案并落地，服务超大规模的集团内部业务及火山引擎业务。","requirements":"1、2027届本科及以上学历在读，计算机、通信等相关专业；\n2、掌握算法、数据结构等基础知识，至少熟练使用一门编程语言（C/C++/Python/Go等）；\n3、积极乐观，责任心强，工作认真细致，具有良好的团队沟通与协作能力；\n4、热爱编程，有较强的学习能力，有强烈的求知欲、好奇心和进取心，能及时关注和学习业界最新技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7441892751312095496","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-TikTok智能创作","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7441892751312095496/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok智能创作团队是为TikTok业务提供AI，特效，音视频创作技术能力，涵盖了计算机视觉、图形学、拍摄编辑、特效、客户端、服务端工程等技术领域,并以多种形式向抖音提提供业界前沿的内容理解、内容创作、互动体验与消费的能力和行业解决方案。\n\n1、参与TikTok智能创作服务端需求设计及开发；\n2、参与产品的完整生命周期，和国际化团队一起推进产品的迭代，在技术、产品、运营效率、用户体验等方面创造价值；\n3、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n4、负责业务需求调研，撰写技术方案和系统设计；持续改善已有服务，优化系统薄弱点，提升系统性能和稳定性。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、掌握Golang或C++语言，有扎实的数据结构和算法功底；\n3、理解计算机原理、计算机网络，熟悉业内常用的基础组件；\n4、对技术有热情，既有高远目标，也能脚踏实地，责任心强、积极主动；\n5、喜欢研究开源新技术，开源贡献者、GitHub源码者、技术博客者优先；\n6、每周可以实习4天及以上，连续实习3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7679025100775328053","sourceKey":"bytedance","company":"字节跳动","title":"变现产品实习生 - 抖音短剧","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7679025100775328053/detail","duty":"团队介绍：抖音短剧团队，负责抖音短剧的分发-消费-变现全链路环节，致力于为内容创作者拓展多元高效的商业模式，为用户提供更优质、更丰富的短剧内容，引领短剧行业的健康发展。加入抖音短剧团队，你将有机会加入行业领先平台，参与打造服务亿级用户的产品，共同推动短剧的创新与发展，创造更大的商业价值和社会价值。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与抖音短剧变现产品的设计、迭代与推进，围绕用户体验、广告效率和营收增长，持续优化短剧变现能力；\n2、参与内流变现模式优化，围绕个性化内流交互、广告流量策略、广告创意样式等方向，提升变现效率与广告体验；\n3、基于数据分析和用户洞察，理解短剧用户的消费路径与变现漏斗，发现关键问题并提出可落地的产品或策略方案；\n4、协同工程、算法等团队推进需求落地、实验验证和效果评估；关注短剧行业趋势、用户需求和商业化创新机会，探索新的产品模式和变现场景，推动业务持续增长。","requirements":"1、本科及以上学历在读，计算机、统计学、数据科学、等相关专业或学科背景优先；\n2、有商业化产品或策略产品实习经验优先；\n3、有AI创作、数据分析和工作提效等方向应用经验优先；\n4、具备较强的数据分析能力和逻辑思维，能够基于数据发现问题、拆解问题并推动解决；\n5、沟通协作能力强，工作耐心细致，有高度的责任心和热情，能够在跨职能协作中主动推进项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677444792511482165","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（模型训练策略方向） - AI数据与安全","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677444792511482165/detail","duty":"团队介绍：AI 数据与安全团队为 Seed 基座模型及 AI 原生应用提供跨模态数据服务，覆盖数据生产全流程，包含模型评估标准的制定、数据规模化生产、数据飞轮搭建，不断提升数据质量，支持模型快速迭代。\n团队由产品经理、数据工程、数据运营等跨职能人才组成，并通过与 Seed 研究员、行业专家、全球顶尖数据供应商紧密合作，从真实场景中收集反馈并分析模型表现数据，解决 AI 前沿突破过程中的复杂数据问题，推动模型性能与用户体验的双重提升。我们既是帮助模型技术迭代的一线贡献者，也是模型和 AI 产品的一手用户。\n\n1、参与自研基座模型训练的数据策略工作，覆盖LLM/VLM、Code&Agent、世界模型（视频生成/游戏引擎/3D)、具身智能等前沿方向，从优化方向定义、数据策略制定、数据管线搭建、评测集构建、小范围数据验证、及应用产品设计，全程参与大模型能力迭代；\n2、围绕预训练和后训练，从评测和用户反馈中挖掘模型优化需求，和Seed算法团队设计数据生产和回流路径；\n3、协同数据工程团队落实规模化清洗与合成数据的管线，并联动标注运营、专家社区和供应商开拓人工评估和标注资源，为模型优化与产品迭代提供高质量的数据保障。","requirements":"1、2027届获得本科及以上学历，计算机科学与技术、人工智能、软件工程、数学、统计学等理工科专业优先；\n2、具有优秀的科研能力、Coding实现能力和端到端管理意识；\n3、对AI行业有强烈好奇心，熟练使用各类AI工具，主动追踪前沿技术与产品动态；\n4、具备系统思维与数据驱动思维，能够设计数据生产、评估与处理链路，通过分析发现和解决问题；\n5、具有较强的跨团队协作与项目推进能力，兼具责任心与大局观。\n\n加分项\n1、活跃的AI创作者或开源社区贡献者，有Hackathon等参赛经历；\n2、有编程经验或算法/研发背景；\n3、熟练使用扣子、Dify、Claude Code等工具，有Workflow/Agent搭建经验；\n4、熟悉视频生成架构（DiT等）或游戏引擎（UE/Unity）、物理仿真、渲染管线。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675704557938788661","sourceKey":"bytedance","company":"字节跳动","title":"搜索大模型算法工程师 - 番茄小说/红果短剧/番茄畅听","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675704557938788661/detail","duty":"团队介绍：番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、参与基于大语言模型的搜索算法研发，包括Query理解与改写、语义检索、文档排序、生成式摘要与回答等方向，持续提升搜索效果指标；\n2、负责小说/短剧场景下的多模态内容检索，优化向量检索、混合检索（稀疏+稠密）、重排序等链路，提升召回质量与排序精度；\n3、推动大模型在搜索场景的工程化落地，包括模型训练/微调、推理加速、在线服务架构设计，平衡效果、延迟与成本；\n4、探索对话式搜索、多轮Query理解、个性化搜索等前沿方向，构建更智能的内容发现体验；\n5、建设搜索效果评估体系，设计离线/在线评测指标，通过A/B实验驱动算法迭代，用数据说话。","requirements":"1、2027届获得硕士及以上学位，计算机科学、人工智能、软件工程、数学、统计学等相关专业；\n2、扎实的机器学习、深度学习基础，熟悉常见模型架构（Transformer、BERT、GPT等），理解注意力机制、预训练与微调范式；\n3、对搜索/推荐系统有一定了解，熟悉信息检索基本原理（倒排索引、BM25、向量检索、Learning to Rank等），有搜索/推荐相关项目或实习经验者优先；\n4、有大语言模型相关实践经验，包括但不限于Prompt Engineering、SFT/RLHF微调、RAG（检索增强生成）、大模型推理优化等；\n5、熟练掌握Python/C++，具备良好的工程编码习惯，熟悉PyTorch/TensorFlow等深度学习框架，有分布式训练或高性能推理优化经验者优先；\n6、具备优秀的逻辑思维和问题拆解能力，能够从业务问题出发，设计算法方案并推动落地，对数据敏感，有较强的结果导向意识，具备良好的沟通能力和团队协作精神，能够跨团队推动项目，乐于分享与学习。\n\n加分项\n1、有搜索/推荐/NLP方向顶会论文发表（SIGIR、WWW、KDD、ACL、EMNLP、NeurIPS等）；\n2、有大模型预训练、指令微调、RLHF等完整流程实践经验；\n3、熟悉向量数据库（FAISS、Milvus、Weaviate等）、混合检索技术与多模态检索（文本+图片+视频）相关技术；\n4、有LLM推理加速经验（vLLM、TensorRT-LLM、量化、蒸馏等）；\n5、有小说/短剧/内容平台相关实习或项目经验；\n6、有开源项目贡献或Kaggle/算法竞赛获奖经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670812949539883317","sourceKey":"bytedance","company":"字节跳动","title":"机器学习平台研发工程师 - Data AML","city":"北京/上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670812949539883317/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、负责AML机器学习平台的开发与优化，打造聚焦AI开发者体验的机器学习平台；\n2、理解算法工程师的业务需求，围绕模型的开发、调试、训练、评估和推理等全生命周期设计解决方案，持续提升算法工程师的迭代效率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟练掌握Linux环境下的Golang/C++/Python语言；\n3、有机器学习算法或大规模分布式系统相关实习经验优先；\n4、对PyTorch、DeepSpeed等机器学习框架，以及推荐、搜索、LLM等领域的前沿算法感兴趣，愿意深入研究和探索。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669708613165812021","sourceKey":"bytedance","company":"字节跳动","title":"机器学习数据系统工程师 - Data AML","city":"北京/上海/杭州","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669708613165812021/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、负责超大规模机器学习系统中数据链路的构建，解决系统高并发、高可靠性、高可扩展性等技术难关；\n2、面向深度学习模型的数据存储引擎：针对深度学习模型特性，突破传统行存/列存格式限制，设计并实现适配深度学习场景的专用存储结构，追求性能与成本的极致优势；\n3、面向深度学习模型的数据读取和缓存体系：针对深度学习模型的数据访问IO Pattern，构建多层的缓存体系，在CPU和GPU侧构建近计算的缓存和数据预读取方案，显著提高数据访问吞吐，降低延迟；\n4、高效的数据预处理引擎：通过解耦数据预处理与模型计算，设计兼容多数据格式的高效预处理引擎，集成算子下推能力，大幅提升预处理效率；\n5、前瞻技术探索落地：跟踪机器学习数据链路前沿技术（如新型存储结构、异构计算系统、硬件创新、编译优化技术等），推动技术调研与工程落地；\n6、算法-系统联合优化：与算法团队深度协同，推进算法与系统的联合优化，持续提升系统对业务的支撑能力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟练掌握Linux环境下的C/C++、Python语言；\n3、具备扎实的计算机科学功底和编程能力，熟悉常见算法和数据结构，具有良好的编程习惯；\n4、掌握分布式系统原理，参与过分布式系统的设计、开发和维护；\n5、熟悉分布式存储的一致性、可靠性、高性能、成本优化等方向；\n6、有强烈的工作责任心，较好的学习能力、沟通能力和自驱力，能够快速的响应和行动。\n\n加分项\n1、熟悉至少一种主流的机器学习框架（PyTorch/TensorFlow）；\n2、有以下某一方向领域的经验：AI Infrastructure，HW/SW Co-Design，High Performance Computing，ML Hardware Architecture（GPU，Accelerators，Networking）；\n3、在大模型或推荐模型领域，参与过大影响力的项目或论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668297090290387205","sourceKey":"bytedance","company":"字节跳动","title":"AI算法工程架构与模型服务开发后端实习生 - TikTok内容安全平台","city":"北京/上海","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668297090290387205/detail","duty":"团队介绍：国际化内容安全平台团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，以人工智能技术支持业务发展，力求更高效、更敏捷、更全能地维护站内生态安全。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、大模型在线服务架构开发：参与千万级吞吐量模型在线服务的架构设计与开发，负责模型应用管理、复杂模型编排、流量调度与服务稳定性保障，持续优化服务的延迟、吞吐与资源利用率；\n2、离线批量推理系统建设：参与千卡级离线批量推理服务的研发，负责任务调度、数据分片与并行执行、失败重试与断点续跑等核心能力，在大规模数据场景下提升整体吞吐与算力性价比；\n3、技术难题攻坚：与团队一起直面高并发、高可靠、高可扩展的技术挑战，解决在线服务的多租户隔离与故障容错、离线任务的资源争抢与长尾拖尾等核心架构难题；\n4、效能与场景落地：协同算法与业务团队，打通从模型部署、批量评估到线上推理的完整链路，优化接入与集成方案，缩短模型交付周期并推动AI能力在多元业务中规模化应用；\n5、前沿技术探索：跟进推理加速、动态批处理、异构算力调度等方向的业界进展，参与专项技术调研与新技术引入，并推动其在在线与离线推理链路中落地验证。","requirements":"1、本科及以上学历在读，计算机、通信、电子信息科学等相关专业优先；\n2、对AI工程领域充满热情，具备强烈的求知欲、自驱力和钻研精神；\n3、扎实的编程基础与AI使用能力，熟悉常见后端技术栈（如数据库、缓存、消息队列等）；\n4、对分布式系统架构和并行计算原理有一定理解，有高并发系统、平台型产品或开源项目的实践经历优先；\n5、了解主流模型推理框架（Triton、vLLM、TensorRT等）或有推理性能优化经验优先；\n6、能够保证充足的实习时间，每周到岗4天及以上，连续实习6个月及以上者优先考虑。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667922736900475141","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（生活服务营销） - 中国交易与广告","city":"上海/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667922736900475141/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、负责生活服务营销架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、热爱计算机科学，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。\n\n加分项\n1、有生活服务、广告等相关业务的项目或实习经验优先；\n2、有基于LLM/Agent等实践经验优先，能讲清设计取舍、评测方式与工程边界；\n3、有开源项目贡献、专利、技术博客、竞赛获奖或专业前10%等技术沉淀；\n4、有较复杂项目设计或重构经验优先，如领域模型设计、组件化设计、渲染性能或包体积优化等专项能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667868656646654261","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师（社交互动方向） - 抖音直播","city":"北京/深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667868656646654261/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、负责抖音社交互动方向的大语言模型/多模态大模型的算法研发，利用AI赋能社交，提升聊天活跃度、促进社交关系、沉淀社交资产，重构用户社交链路与互动体验，包括但不局限于消息会话、合养精灵、群聊等场景；\n2、负责社交大模型的后训练，通过强化学习、生成式奖励模型、用户反馈系统等技术突破大模型交互共情能力的天花板；\n3、负责社交智能体的搭建，提供多模态的感知、互动能力及长期记忆系统，为用户提供极致的个性化体验；\n4、跟踪AI前沿技术进展，推动前沿技术的产品化落地。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、软件工程等相关专业优先；\n2、熟悉Linux系统和常用的数据结构，熟练使用Python/C++等至少一种编程语言，熟练使用TensorFlow/PyTorch等至少一种深度学习框架；\n3、熟悉Attention、Transformer、BERT、GPT等常用模型结构，熟悉Llama、ChatGLM等开源大模型原理与实现；\n4、在代码生成、大模型训练、Agent、RLHF等方面有积累者优先考虑；\n5、优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情，良好的沟通和团队合作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667570226889345285","sourceKey":"bytedance","company":"字节跳动","title":"广告算法工程师 - 抖音电商&直播","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667570226889345285/detail","duty":"团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n抖音直播算法团队，负责抖音、抖音极速版、抖音火山版等App的直播推荐算法优化，业务包括直播体裁基建和直播营收。直播体裁基建从用户侧的召回/粗排/精排/混排等模型和策略和主播侧的冷启动算法，结合多模态内容技术动态理解切片和用户兴趣，建立短视频域到直播域的兴趣迁移，在全场景分发直播体裁，满足用户看播需求并服务于营收、电商、生活服务、游戏等多业务。直播营收致力于为歌唱/舞蹈/弹奏/朗读/情感/户外等广泛的具有一技之长的普通人通过直播这个舞台被更多人看到获得收入，并满足用户多层次的精神消费和情感表达诉求，让优质内容供给持续增长反哺整个直播生态。在推荐技术方面，我们持续验证并落地全链路模型的高效scaling up方案，积极探索生成式推荐和LLM4Rec路线，提升模型系统的整体智能。\n\n1、负责巨量千川全域投放策略，围绕ROI2框架，提升客户投广带来的自然协同能力；\n2、负责巨量千川竞价机制策略，比如ROI1/长效ROI1/佣金ROI1等出价产品策略优化，通过满足广告主多场景下的预算表达诉求，长期提升平台收入；\n3、负责巨量千川商家分客群策略，对不同客群做定制化优化，例如达人客群或者中小客群成长；\n4、负责巨量千川商家投放体验优化，降低商家广告投放操作成本，提升商家投放生态体验；\n5、负责巨量千川商家场景化营销建设，通过优化货品/大促等方向，赋能商家营销能力。","requirements":"1、2027届获得本科及以上学历，计算机、自动化、电子信息、数学、统计学等相关专业；\n2、深入理解和掌握人工智能领域前沿技术，对以下至少一个领域有深入理解并有应用解决有挑战性问题的能力：互联网搜索、推荐、广告算法；深度学习和统计机器学习、计算经济学、博弈论、运筹学；\n3、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n4、较好的主动性和求知欲，良好的沟通表达能力和团队精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665990798262356229","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师 - 抖音平台产品","city":"杭州/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665990798262356229/detail","duty":"团队介绍：\n平台产品基础：作为抖音平台支撑团队，以 AI为核心抓手，打造高效能平台底座，为全业务线筑牢坚实底层支撑\n生态与运营：聚焦创作者成长与商业化，激活生态活力，夯实内容根基\n营销搭建：全链路营销体系，助力业务推广，实现品效增长\n文娱业务：深耕短剧赛道，打通内容 - 营收 - 宣发全链路，构建健康文娱生态\n变现与资金平台：筑牢交易结算核心底盘，提供全链路支付与清结算能力，保障平台资金安全与高效流转\n治理・体验・客服：三位一体守护平台安全、用户体验 以及 高效响应解决用户诉求\n开放业务：有序开放平台能力与数据，链接外部资源，拓展生态边界\n全体团队以业务增长与用户价值为核心，持续深耕、协同共进，推动抖音生态持续繁荣。\n\n1、负责前端技术开发工作，包括移动端产品以及PC端产品；\n2、完成用户功能设计和开发，确保浏览器或其他终端设备兼容性；\n3、通过技术手段，优化前端性能，提升用户体验；\n4、设计研发通用组件、工具和类库，提升开发质量和效率。","requirements":"1、2027届获得本科及以上学历，计算机、通信和电子信息科学、数学等相关专业；\n2、具备良好的计算机基础，熟悉常用的数据结构和算法，并熟练使用至少一门编程语言完成代码编写；\n3、有兴趣深入学习前端技术开发和了解用户交互体验；\n4、熟练使用HTML5/CSS3/JS等前端技术完成页面布局和交互开发；\n5、熟悉使用Vue/React等前端框架或者具备Web项目开发经验的同学优先；\n6、积极乐观，责任心强，具备良好的沟通协作能力、逻辑思维能力以及服务意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665626194213341445","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法研究员 - 小荷健康","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665626194213341445/detail","duty":"团队介绍：小荷健康是字节跳动旗下的医疗健康品牌，我们致力于利用大模型技术，探索医疗健康服务的新范式，孵化了“小荷AI医生”app，为用户提供专业的健康咨询服务。小荷健康拥有专业的医学和互联网产研团队，认真探索AI医疗。\n\n1、参与医疗基座模型训练与优化，涵盖数据构建、MidTrain、SFT、RL、偏好优化等关键环节；结合AI Infra、Harness/Loop/Graph Engineering，完善训练、推理、评测与自动化实验体系，提升研发效率与训练效果；\n2、围绕医疗复杂任务开展算法研究，重点突破Long-Horizon场景下的规划、推理、执行、恢复与自我修正能力；\n3、参与医疗Agent任务模式建设，优化任务编排、工具调用、状态跟踪、记忆管理、反思纠错等核心机制；\n4、面向生物信息、EHR仿真、临床对话、医疗问答等任务设计实验、构建评测体系、分析误差并迭代模型能力；\n5、跨团队协作推动模型能力在真实业务场景落地，对最终效果负责。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、数学、生物信息学、统计等相关专业优先；\n2、具备良好的AI-Native/Vibe coding能力，能够高效借助AI工具完成实验实现、问题调试和迭代验证；有ICML、NeurIPS、ICLR、ACL、EMNLP、CVPR、MICCAI等顶会相关论文者优先；\n3、对大模型训练、对齐与推理有系统理解，了解预训练、SFT、RL、偏好优化中的一种或多种；有大模型预训练、SFT、RLHF/DPO/PPO、Reward Modeling经验者优先；\n4、对医疗AI、长程任务、Agent、模型训练与优化有强烈兴趣，愿意深入难题并持续做高质量研究；有医疗大模型、临床NLP、生物信息建模、EHR任务、医疗知识建模经验者优先；有Agent训练经验者优先，尤其是在Long-Horizon Task、Workflow Graph、Memory/Retrieval、自反思、自进化等方向有实践经验；\n5、具备较强的实验设计、问题分析、论文阅读和结果归因能力，能够从数据和现象中定位本质问题；有业界通用基模后训练经验者优先，尤其是在Reasoning、Tool-Use、Deep Research、Agent能力提升等方向有训练或优化经验，或具备多模态感知、推理、偏好优化等相关实践；\n6、具备良好的协作意识和自驱力，能够独立推进课题并持续产出；有高质量开源项目、工业界实习或医疗AI项目落地经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664446595187083525","sourceKey":"bytedance","company":"字节跳动","title":"数据科学 - 中国交易与广告","city":"北京/上海","category":"数据分析","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664446595187083525/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、负责字节跳动系产品广告与营收核心数据监控，针对异常情况协调资源进行深入分析；\n2、通过对数据的敏锐洞察以及定性和定量分析，定位内部问题以及发现行业机会；\n3、负责重点专题进行专项设计实验、评估以及下钻分析，制定指标、目标，同时支持业务决策；\n4、通过宏观、微观数据结合，判断业务发展趋势，产出量化预估并制定中长期业务发展规划以及关键路径。","requirements":"1、2027届获得本科及以上学历，统计学、数学、经济学等相关专业；\n2、至少熟练使用R、SQL、SAS、MATLAB、Python中的一种；\n3、熟悉至少一种AI相关工具，在分析项目中有过实操应用；\n4、熟悉常用数据统计和分析方法，具有相关应用经验和机器学习建模能力；\n5、良好的逻辑思维、业务解读能力和快速学习能力；\n6、良好的沟通能力、团队合作精神和主动意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615513191099074869","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent服务端研发实习生-开发者服务","city":"杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615513191099074869/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、围绕研发高可用治理，质量保障AI化，研发环境管理等方向进行Agent应用开发工作，推动AI技术在相关场景的落地与突破；\n2、参与大模型应用开发全流程，包括但不限于模型接入、AI Agent开发、RAG优化、MCP及工具开发、数据工程等；\n3、跟踪AI领域的发展动态，推动Agent应用的持续优化。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、自动化、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握至少一门编程语言，包括但不限于Python、Java、Go等；\n3、了解AI Agent相关技术与设计思想，了解主流AI模型及其应用场景；\n4、有从0-1搭建AI Agent应用经验，能够独立完成Agent应用的设计开发者优先；\n5、在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7563699449831983365","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-Flow","city":"杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7563699449831983365/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动Flow产品研发团队，专注研究AI智能化相关业务落地，目前落地豆包、Cici 等 APP，以及对应的Bot 开发平台等AI智能化创新产品，业务和团队均处于快速发展期，成长空间大，欢迎各位同学加入！\n\n1、参与和指导公司平台级技术组件和平台（AGW/Janus/ByteSync/BAM）的研发工作；\n2、分析和深入发掘现有系统的不足，定位系统瓶颈，提高系统性能和稳定性；\n3、主要实现语言为Golang/Python。","requirements":"1、本科及以上学历在读，计算机、通信等相关专业优先；\n2、深刻理解计算机原理，有良好的数据结构和算法基础；\n3、熟悉MySQL、Redis、消息队列等常用WEB组件，并有能力进行定制化改进；\n4、有较好的产品意识优先；\n5、积极乐观，责任心强，工作认真细致，具有良好的团队沟通与协作能力；\n6、热爱编程，至少掌握一门编程语言，有较强的学习能力，有强烈的求知欲、好奇心和进取心，能及时关注和学习业界最新技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7272655474210163005","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法实习生 - TikTok Shop","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7272655474210163005/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与电商场景下文本、多模态相关模型能力建设，包括但不限于：基于Llama/LLaVA等模型的多模态、关键信息抽取、实体识别、文本分类、知识图谱构建等；\n2、参与构建业内领先的内容安全、内容生态识别方法，探索前沿技术（如NLP前沿、多模态前沿的训练和运用相关），并应用落地到电商业务场景中；\n3、参与分析模型落地对电商生态的正面影响。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、熟悉常用的机器学习和深度学习算法，熟悉基本的网络模型结构（DNN/LSTM/CNN/Transformer等）、生成式模型（Llama/GLM/GPT/BERT/BLOOM等）、PEFT技巧；熟悉常见多模态模型，并有一定实践经验；\n3、具备较强的编码能力，熟悉Python，熟悉PyTorch/TensorFlow等至少一种主流深度学习框架；\n4、具备优秀的学习能力和良好的沟通合作精神。\n\n加分项：\n1、在自然语言处理、机器学习领域（SIGIR、ACL、EMNLP、AAAI等）有论文发表；\n2、国际知名竞赛获得前三名次。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675720914621876533","sourceKey":"bytedance","company":"字节跳动","title":"东南亚电商运营管培生计划（越南） - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675720914621876533/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n岗位介绍\nTikTok Shop毕业生发展管培项目是专为高潜力本科应届生打造的定制化管理培训生计划，面向有志于搭建东南亚电商未来的人才。本项目为职场新人提供快速成长通道，助力大家在快速迭代的数字电商生态中，培养商业判断力、数据分析能力、精细化运营能力与跨部门统筹领导力。\n入职起，你将深度承接业务工作，在电商团队轮岗。每段轮岗都会让你实操全链路业务：商家孵化成长、达人运营、大型营销活动落地、平台运营优化、复杂商业难题攻坚。\n顺利完成全部轮岗后，你将胜任关键岗位，拥有持续成长空间，未来可成长为业务、运营或战略方向负责人。\n\n轮岗方向\n1、商家招募与孵化：通过商家拉新、入驻引导、培训扶持、成长孵化全流程助力新店起步。依托数据洞察、标准化运营手册、可规模化运营机制，帮助商家在平台实现业绩增长。\n2、品类与达人增长：对接达人、网红、商家及品类团队，深化多方合作，优化商品内容曝光，驱动内容电商业绩增长。\n3、营销活动管理：统筹全域营销活动，提升平台曝光、用户互动与商品交易总额（GMV）；负责活动策略制定、落地执行、数据复盘及活动后增长分析。\n4、平台运营与商业分析：借助数据分析、流程优化、项目落地解决平台层面业务痛点，提升整体运营效率，助力业务达成增长目标。\n\n项目期间你将轮换3-4个业务团队，轮岗时长根据业务需求调整。我们会结合你的个人偏好、优势与成长目标，打造沉浸式、针对性学习成长路径。\n\n岗位职责\n1、在TikTok Shop团队轮岗，建立完整的东南亚数字电商生态全局认知；\n2、全链路支持商家招募孵化、达人合作、营销活动、平台运营、商业分析等增长项目；\n3、拆解业务经营数据，挖掘增长洞察，输出可落地优化方案同步各业务负责人；\n4、主导重点项目，提升商家经营成效、达人活跃度、用户体验、运营效率与整体商业收益；\n5、联动产品、运营、品类、市场、达人、数据、战略等跨部门团队，协同解决各类业务难题；搭建标准化运营手册、落地长效运营机制、完善数据追踪体系，支撑业务可持续增长；\n6、向直属领导、导师及业务高管清晰汇报分析结论、优化方案与项目推进进度；每段轮岗全程主动担责、保持求知欲、快速适应变化，具备较强落地执行意识。","requirements":"1、2027届获得本科及以上学历，商科相关专业优先；\n2、对电商、科技平台、消费品、达人经济、业务运营抱有浓厚兴趣；\n3、具备用数据解决商业问题实操经验，熟练使用Excel、SQL、数据可视化看板、各类分析工具，或独立完成行业深度调研；梳理模糊业务问题、输出可行解决方案；\n4、沟通表达清晰高效，可跨团队、跨市场协同多方对接人；\n5、具备求知探索精神、快速学习能力、工作责任心；适应不确定性环境、学习速度快，擅长跨部门、多元文化团队协作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672270818409957637","sourceKey":"bytedance","company":"字节跳动","title":"EMG算法工程师 - PICO","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672270818409957637/detail","duty":"团队介绍：作为一家拥有自主创新和研发创造能力的科技品牌，PICO致力于成为领先的世界级XR平台，成就开发者与创作者，共同为全球消费者创造更美好的生活体验。我们开创性地将虚拟现实扩展到了多个领域，为运动、视频、娱乐等消费级场景带来了全新体验；并广泛应用在教育、医疗和企业培训等商用场景，给全球企业级用户提供了多元化的VR解决方案。\n\n1、参与EMG、EEG、视觉、语音、文本等多模态数据处理、建模与实验验证；\n2、参与用户意图理解、状态识别、场景理解、多模态融合等方向算法研发；\n3、协助完成数据分析、效果评估、论文复现、技术报告与原型验证。","requirements":"1、2027届获得硕士及以上学位，计算机、自动化、电子、生物医学工程、机器人、AI等相关专业；\n2、熟悉Python，具备良好的算法、数据结构和工程实现能力；\n3、在生理信号、CV、语音、NLP、多模态学习等至少一个方向有项目或研究经验；\n4、熟悉PyTorch等深度学习框架，有实验设计与结果分析能力。\n\n加分项\n1、有EMG/EEG/BCI/XR/可穿戴/多模态大模型/Agent相关经验；\n2、有论文、竞赛、开源或完整项目经历；\n3、有真实设备、传感器、实验平台联调经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668252664955717893","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师 - 业务中台","city":"北京/深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668252664955717893/detail","duty":"团队介绍：团队负责公司多个跨产品业务方向，提供可复用的平台能力及技术解决方案。我们为公司多业务提供如地理位置、行业数据等多类型的中台能力与技术解决方案，积极利用AI等技术做中台能力提效与升级。\n加入我们，你将有机会从中台的多视角参与业务建设，感受不同类型/阶段的业务特点；通过用户场景的开发&架构工作，学习和解决极富挑战的技术问题；你也可以从数据出发，积极利用策略和模型，为业务提供有价值的助力。\n\n1、参与地理位置中台核心能力建设，覆盖POI、路网数据生产、地理编码、融合定位、时空知识图谱、路线规划、ETA预估、路况预测、地图应用等方向；\n2、面向文本、图像、轨迹等多源数据，构建多模态理解和时空建模能力，推动POI、路网数据生产、关系理解、场景识别等能力建设；\n3、关注AI与时空预测结合的前沿方向，如大模型、多模态、Agent技术，探索其在下一代地图与地理位置智能能力中的应用机会；\n4、深入理解业务目标，建立算法效果评估体系，协同产品、工程、数据等团队推动算法方案落地并持续迭代。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、数学、地理信息、自动化、电子工程等相关专业优先；\n2、具备扎实的编程基础与算法功底，熟悉Python、C++、Java等至少一种主流编程语言，具备良好的工程实现能力；\n3、熟悉机器学习、深度学习、数据挖掘、自然语言处理、计算机视觉、图算法、定位算法、LLM/VLM中的一项或多项，并有相关实践经验；\n4、具备良好的问题分析能力、学习能力、沟通表达能力和团队协作精神，对技术创新和业务落地有热情；\n5、熟练使用PyTorch，熟悉TensorRT/ONNX等模型量化与加速工具。\n\n加分项：\n1、在AI会议/期刊发表高质量论文，或有高水平算法竞赛、科研项目、开源项目经验者优先；\n2、有地理位置相关项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667770208559909125","sourceKey":"bytedance","company":"字节跳动","title":"IP创新业务AI产品经理（抖音AI产品人才校招） - 抖音运营","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667770208559909125/detail","duty":"团队介绍：负责抖音知识，兴趣，消费，生活，娱乐等垂类的创作者运营，主要目标为提升抖音内容供给，探索多元化的作者变现和商业模式，促进多领域的创作者更好地在平台经营和成长。同时也包括抖音中长视频、演出相关业务。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责Agent知识问答，包括知识组织、检索、回答、溯源及效果优化；\n2、负责创作辅助MCP产品设计，沉淀标准化的资源、工具和接口能力，推动MCP接入各类创作工具，完善权限、版本、监控、文档及开发者体验；\n3、协同算法、研发、内容和创作团队，推动产品从方案设计到规模化落地；\n4、协同评测运营建立相关评测体系，持续提升准确率、设定一致性、可解释性及响应效率。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、大数据等相关专业优先；\n2、熟悉RAG、Agent、Function Calling及MCP，能够理解API、JSON等技术方案；\n3、具备较强的产品抽象、数据分析和复杂项目推进能力；\n4、对IP、世界观设定及内容创作有兴趣，能够理解创作者需求；\n5、有较强的自驱力、沟通能力和结果意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667449963626072373","sourceKey":"bytedance","company":"字节跳动","title":"AI多模态产品经理 - 音视频技术","city":"北京/上海/杭州","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667449963626072373/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、定义AI Native的音视频产品体验：负责AI音视频产品的功能设计，不局限于传统后台，探索「多模态处理」「多模态传输与实时交互」「人与Agent协同创作」的媲美豆包同款体验的全新产品形态；\n2、构建多模态「超级工场」：参与搭建面向未来的AI Media Platform；将复杂的算法算子、工作流、批处理封装为优雅的、Agent友好的产品能力，支持Seed、豆包等大模型与各类Agent在具体业务场景中的高效落地；\n3、调研「模型与Agent生态」演进趋势：跟踪全球AI音视频模型与Agent产品生态的前沿动向，洞察AI在用户场景与需求上的演进，与算法、工程技术合作，将技术转化为用户可感知的极致体验；\n4、建立评测与产品迭代闭环：围绕意图理解、任务完成率、音视频效果等建立产品评测方法，分析真实使用中的负面案例，驱动产品体验与能力可靠性的持续优化。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、信息工程、语言学或相关交叉学科专业优先；\n2、作为AIGC与Agent产品的深度用户，包括但不限于CHATGPT/CLAUDE/豆包/即梦/剪映等产品；了解AI原理，能从「用户体验」与「Agent体验」双视角拆解产品的优缺点；\n3、对视频理解、视频生成模型（如Seedance、SORA、可灵等）的能力与边界有基本认知和产品判断；\n4、具备良好的逻辑能力和学习能力，能够从用户需求出发，结合技术可行性，设计创新的产品功能和体验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667125843387156789","sourceKey":"bytedance","company":"字节跳动","title":"云基础资源运营 - 火山引擎","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667125843387156789/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责火山引擎计算/存储/网络/AI产品的运营工作，参与数据中心资源运营，做好需求和容量管理，保障业务需求交付；\n2、协助完成集团内部的经营结算工作，参与产品的营收和成本管理，为产品优化提供方向和数据支撑，提升产品综合竞争力；\n3、深度了解产品经营体系运作逻辑与流程，配合产品线开展资源预算、预测与预实分析等工作；\n4、参与产品的运营平台建设，建设业务规范和标准化业务流程，提升产品运营效率。","requirements":"1、2027届获得本科及以上学历，计算机类、通信工程类、经济管理类等专业背景；\n2、有数据中心运营管理或AI产品运营经验者优先；\n3、具有较强的沟通协调能力、学习能力、及多任务处理能力，具备一定的项目管理能力；逻辑思维能力强，思考框架性强，性格开朗、工作积极主动。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7614003210621864197","sourceKey":"bytedance","company":"字节跳动","title":"大语言模型算法实习生（智能对话）-国际电商","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7614003210621864197/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：国际电商是以TikTok为载体的电商业务（也称为TikTok Shop），致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商、货架电商等多场景下，国际电商希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，致力于新奇好物畅销全球，美好生活触手可得的使命。\nData-电商团队是国际电商的核心算法技术力量，专注于电商领域的算法创新，帮助用户高效发现感兴趣的商品，保障用户的购物安全，提升交易各环节的智能化水平。在这里，你将与一流的产品和技术团队合作、钻研，一起应对技术和业务上的挑战，推动技术在电商场景的深度落地。\n\n1、负责AI智能客服系统的设计与开发，包括基于大语言模型（LLM，支持文本及多模态）的对话助手，实现对电商咨询、投诉、退款、争议解决及物流等场景的自动化处理，提升客户服务效率；\n2、针对电商客服场景，开展模型后训练（如Fine-tuning、Instruction Tuning、RLHF等），持续优化大模型在理解、生成及多轮对话中的表现；\n3、研究并实现多模态技术（如文本、图片）在客服场景中的应用，提升客服机器人的用户体验与自动化解决率；\n4、关注并引入业界前沿LLM相关技术，推动智能客服领域的创新及能力迭代落地；\n5、制定并推动数据采集、清洗、标注、增强和评测的全流程，确保模型在客服领域的高准确性与安全性。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具有扎实的编程功底，至少精通一门主流编程语言（C++/Java/Go/Python等），具备良好的工程实践能力；\n3、在大模型训练、智能体、提示词工程、信息检索、数据集构建、大模型评测等领域有实际的开发和从业经验者优先，有复杂智能体系统落地经验者优先；\n4、有高水平论文发表经历者优先，包括但不限于ACL、EMNLP、COLING、WWW、AAAI等；\n5、实践动手能力强，有ACM、ICPC、NOI/IOI、Top Coder、Kaggle等高水平比赛获奖经历者优先；\n6、有好奇心，对新技术有热情，善于团队协作，具备创新精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683448753924163893","sourceKey":"bytedance","company":"字节跳动","title":"商业安全产品实习生 - 广告业务","city":"北京/上海/深圳","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683448753924163893/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责商业化内容安全方向的策略能力设计与优化，结合业务风险目标、数据分析和大模型/多模态模型能力，设计更高效、可迭代的风险识别、处置与评估机制；\n2、负责大模型平台的产品能力建设，围绕策略生产、人机协同等场景，抽象平台化能力，提升策略建设效率和业务支撑能力；\n3、结合业务目标与一线问题，分析风险数据、业务反馈和平台使用情况，持续优化产品功能、策略配置能力和协作体验，支撑业务快速发展；\n4、对接业务方、研发、运营等多方，完成需求调研、方案设计、PRD输出与项目推进，协调资源推动能力落地，并对最终效果负责。","requirements":"1、本科及以上学历在读；\n2、有大模型、B端平台或风控策略相关经验优先，具备优秀的产品思维、策略思维和解决方案能力，逻辑清晰，能够从复杂业务问题中抽象出可落地的平台能力和策略机制；\n3、具备较强的数据分析能力，能够基于数据发现问题、评估效果，并推动策略与产品持续迭代；\n4、具备良好的沟通协作和项目推进能力，能在多业务、多角色协作环境中推动需求落地；\n5、有较强的自我驱动力、责任心，对AI技术在业务场景中的落地有持续兴趣。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683125162023864629","sourceKey":"bytedance","company":"字节跳动","title":"策略产品（内容质量方向）实习生 - 今日头条","city":"北京","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683125162023864629/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责今日头条App内容质量工作，结合用户反馈，通过开放问题研判，发现消费体验问题与机会点，提出可落地的质量优化方案，并独立完成需求产出到落地的全过程；\n2、针对质量治理目标，完成需求分析、识别策略制定，协调资源跟进项目落地，对治理目标负责；\n3、独立完成相关产品需求文档的撰写，推动需求落地，持续关注指标变化，善于通过数据发现问题及论证假设。","requirements":"1、本科及以上学历在读；\n2、对社区、内容型产品兴趣浓厚，有内容质量相关产品实习经验优先；\n3、对数据敏感，能透过数据分析业务现状，持续优化用户消费体验；\n4、对视频、小说、短剧等各类内容产品有深入思考，日常有较高频的内容消费习惯，能够从用户视角发现体验问题，有内容产品、社区、社交、作者等相关经验的优先；\n5、跨团队协作能力强，具备优秀的沟通表达能力，乐观积极。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678270608639134005","sourceKey":"bytedance","company":"字节跳动","title":"内容策略运营（内容生产方向）实习生 - 今日头条","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678270608639134005/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、分析刻画今日头条作者内容流量结构及供需关系，从数据角度理解和解释今日头条内容生态和供需变化；\n2、负责今日头条APP内容质量工作，制定并执行内容及账号的管控规则，为平台安全、内容质量和用户体验负责；\n3、负责今日头条垂类内容运营，结合平台用户特征，策划端内专题、话题活动等传播方案；\n4、与技术、产品协同，通过数据分析洞察，完善搜索场景推荐策略与推动持续迭代，提升搜索渗透。","requirements":"1、本科及以上学历在读，社会学、统计学等相关专业优先；\n2、对内容型产品感兴趣，对作者与内容有自己的理解，有产品运营等相关实习经验的优先；\n3、具备严谨的逻辑思维能力，对数据敏感、善于从数据中发现问题，自驱力；\n4、解决问题注重过程和结果，关注细节。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677438105138219317","sourceKey":"bytedance","company":"字节跳动","title":"菲律宾大促运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677438105138219317/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与平台大促项目的运营落地，协助大促PM进行项目进度统筹、关键节点跟进、跨团队信息同步等工作；支持促中数据走查与问题排查，跟进核心指标表现，及时发现异常并协助推动相关团队定位和解决问题；\n2、负责大促期间营销资源位配置与上线跟进，包括活动页面、资源位、权益玩法、商品/商家信息等内容的整理、配置和检查；\n3、协助专项活动的招商、活动复盘，协助整理商家/商品/资源位/玩法效果数据，输出阶段性总结和优化建议；\n4、支持产品运营相关对接，与产品、行业运营、数据分析、设计及本地团队协作，推动重点项目落地。","requirements":"1、本科及以上学历在读；\n2、每周可实习4-5天，需保证至少3个月实习时间；良好的逻辑思维能力与数据分析能力，熟练使用办公软件，英文读写能力强；\n3、对电商行业有基本了解，熟悉东南亚电商及TikTok Shop更优；\n4、耐心负责，具备良好的团队协作能力，自我驱动，期待在赛道中发展成长；\n5、英语听说读写流利。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669716946866538805","sourceKey":"bytedance","company":"字节跳动","title":"机器学习系统调度编排工程师 - Data AML","city":"杭州/北京/上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669716946866538805/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、ML PaaS方向--编排调度基础设施；\n1）建设机器学习平台基础编排能力，包括Kubernetes交互层、控制面抽象、CRD/Operator，以及任务和服务生命周期管理；\n2）建设多租户资源与Quota系统，支持优先级、抢占、公平共享、弹性资源和跨集群资源调度；\n3）建设容器运行时和有状态服务编排能力，持续优化镜像、存储、网络、资源隔离、故障恢复、容灾与系统SLA；\n2、训练编排方向--训练编排与可靠性；\n1）对接预训练、SFT、RL等训练和后训练场景，建设任务、Workflow及多角色服务编排能力；\n2）优化训练可靠性和ETTR，建设故障检测、慢节点诊断、Checkpoint、Failover和弹性恢复能力；\n3）提升训练工程效能，并支持训练、Rollout、推理、Reward等角色间的资源协同、参数同步和训推共池；\n3、MaaS方向--GPU在线Serving编排；\n1）建设大模型在线推理服务的全生命周期编排，支持部署、升级、回滚、弹性伸缩、多集群和容灾；\n2）建设Prefill/Decode分离、多角色推理、拓扑感知、KV Cache亲和性、QoS/SLA和流量调度能力；\n3）优化模型权重、镜像和KV Cache的分发与加载，并通过资源池化、多租户、弹性和FinOps提升GPU利用率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能及相关专业优先；\n2、熟练掌握Go、C++、Python中至少一种语言，具备扎实的数据结构、算法基础和良好的工程编码习惯；\n3、熟悉Linux，理解操作系统、计算机网络、并发编程和分布式系统的基本原理；\n4、具备较强的动手能力和探索精神，愿意深入代码和系统现场分析问题，而不止停留在框架使用或方案设计层面；\n5、具备系统化和定量分析意识，能够通过指标、日志、Profiling、实验或模型定位问题并验证优化效果；\n6、具备责任心、自驱力和良好的协作能力，愿意持续负责复杂系统从设计、开发到上线和稳定运行的完整过程。\n\n加分项\n1、满足以下任意一项即可；\n2、ML PaaS方向\n1）有资源调度、Quota、基于容器的多租户系统或FinOps项目经验；\n2）参与过Kubernetes、Volcano、Koordinator、Kruise等开源项目；\n3、训练编排方向\n1）有PyTorch Distributed、Megatron、DeepSpeed、Ray、Volcano等分布式训练实践，有对应训练框架的可靠性以及性能优化经验更好；\n2）有训练平台、MLOps、RLHF/PPO/GRPO等强化学习或后训练系统实践；\n3）有训练系统以及AI集群管理相关科研经历或开源贡献；\n4、MaaS方向\n1）有vLLM、SGLang、Triton、KServe、Ray Serve等推理系统实践；\n2）了解大模型推理中的KV Cache、Continuous Batching、Prefill/Decode分离、并行策略等概念；\n3）有在线服务、网关、流量调度、弹性伸缩、性能优化或大规模高可用系统经验；\n4）有GPU/NPU Serving、异构资源调度、模型分发或推理性能分析经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669706036090505525","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法工程师 - TikTok算法","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669706036090505525/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、建设面向TikTok内容理解与推荐场景的多模态大模型（VLM）基模能力，开展VLM全流程训练，包括Pre-training、SFT、RL等环节；探索原生多模态建模、推荐行为Co-training等前沿方向；\n2、为推荐业务提供高质量的视频内容表征，支持推荐下游应用；探索Promotable Embedding、Reasoning Embedding、End-to-End Tokenizer等方向，提升内容表征的语义表达、可泛化性和业务可用性；\n3、与推荐算法团队深度协作，推动内容理解能力在推荐链路中的规模化落地，并探索下一代推荐系统范式，包括Agentic Recommendation、生成式推荐、Vision-Language-Recommendation统一建模等方向。","requirements":"1、2027届获得硕士及以上学位，计算机等相关专业优先；\n2、计算机科学基础扎实，具备优秀的工程实现能力；熟悉大模型训练&推理框架；\n3、具备出色的实验设计、分析和问题解决能力，能够定位并解决模型训练、数据构建、效果评估和业务落地中的复杂问题；\n4、具备良好的沟通协作能力和负责人意识，能够与推荐算法&工程团队协作，推动技术方案从探索走向线上应用；\n5、在多模态、大模型、推荐系统等方向主导过有影响力项目，或发表过高水平论文者优先；\n6、有搜索、广告、推荐等大规模工业场景中的内容理解、表征学习或大模型应用经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668572015601256709","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发/测试开发工程师（泛架构） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668572015601256709/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、我们希望寻找具备扎实工程基础、全栈潜力和AI原生能力的应届毕业生，加入TikTok各业务质量工程团队，区别于传统意义上的“测试执行”岗位，这是一个以质量场景为切入点，面向复杂系统和智能工程建设的研发岗位；\n2、参与业务质量平台、研发效能工具和自动化基础设施的设计与开发，覆盖前端、后端、数据链路和平台能力建设；\n3、深入客户端、服务端及上下游协同链路，建设功能、接口、稳定性、性能、安全等多维质量保障能力；通过代码分析、链路分析、日志分析、压测、故障演练等方式发现复杂系统中的深层问题，并推动问题闭环；\n4、探索并落地AI在质量工程中的应用，包括测试生成、智能缺陷分析、质量评测、测试智能体、自主探索式测试等方向；\n5、沉淀可复用的工程能力，包括测试框架、诊断工具、自动化脚本、质量方法论与平台化能力；与研发、产品、算法、数据等团队协作，共同推动质量内建、研发提效和工程规范升级。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化、数学等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构与算法的核心思想，能够将抽象问题转化为可实现、可优化的工程方案；熟悉至少一门编程语言，如Go、Java、Python、TypeScript/C++等，具备独立完成中型工程项目或核心模块开发的能力；\n3、理解操作系统、计算机网络、数据库、并发编程、常见系统架构等基础知识；对软件工程有基本理解，熟悉从需求分析、设计实现到测试验证、上线迭代的研发流程；\n4、具备良好的问题拆解能力、系统性思维和学习能力，能够面对复杂问题持续追问本质并推动解决；具备良好的沟通协作能力和责任心，能够在跨团队、多角色合作中推动目标达成；\n5、能熟练使用AI工具辅助编码、排障、文档理解和方案设计，具备对AI输出进行判断、校验和二次加工的能力；对AI在测试与质量场景中的应用有兴趣，对大语言模型、Agent、RAG、模型评测、自动化工作流等AI工程方向有认知或实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668527854284343605","sourceKey":"bytedance","company":"字节跳动","title":"广告产品经理 - 广告度量信号与隐私保护","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668527854284343605/detail","duty":"团队介绍：国际化广告度量信号与隐私保护团队致力于构建覆盖广告系统全链路的安全治理基础设施与流程体系，在确保平台海量多元信号数据持续符合全球各地区监管要求的同时，积极探索前沿隐私增强技术的落地应用。团队将肩负双重使命：既要守护用户数据安全，又要维护TikTok自由创新的社区生态。作为核心成员，您将主导数据隐私保护与安全体系建设，并通过跨职能项目推动流程持续优化。\n\n1、负责构建稳健、高效的用户身份图谱，持续提升用户识别、连接与理解的能力，为下游的模型数据利用、广告效果度量等场景提供坚实基础；\n2、负责建立并持续完善产品核心指标体系，通过数据驱动的方式进行优先级排序、产品决策和效果评估，推动产品迭代优化；\n3、与算法、工程、法务、隐私、运营等跨职能团队紧密协作，共同制定并实现产品目标，最大化身份能力在个性化推荐、效果衡量等场景的价值。","requirements":"1、2027届获得本科及以上学历，计算机科学、数学、统计学等相关专业者优先；\n2、具备优秀的数据分析能力和指标体系搭建经验，能够从复杂数据中发现问题、定位机会并驱动决策；\n3、出色的沟通、组织和分析能力，能够清晰地阐述产品理念、协调跨职能团队高效合作，并具备优秀的文档撰写能力；\n4、英语可作为工作语言者优先，英语六级及以上，具备跨文化沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668518017689995573","sourceKey":"bytedance","company":"字节跳动","title":"用户体验运营 - 抖音生活服务","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668518017689995573/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、参与抖音生活服务消费者体验相关问题的洞察、分析与改善推动，围绕用户反馈、业务数据、调研信息等，识别平台消费链路中的体验痛点与优化机会；\n2、结合生活服务本地履约场景，协助拆解复杂体验问题，提炼关键原因，推动产品、运营、服务、算法等相关团队形成解决方案并落地；\n3、参与体验问题的发现、流转、解决和效果评估机制建设，帮助提升问题识别效率和改善闭环质量，推动体验优化更加系统化、标准化；\n4、关注AI、大模型及智能化工具在体验洞察、问题诊断、策略分发等场景中的应用，探索如何用新技术提升体验运营效率和业务价值；\n5、跟进重点体验项目的推进节奏，协同多方对齐目标、标准和进展，确保项目高质量落地，并沉淀可复用的方法和经验。","requirements":"1、2027届获得本科及以上学历，统计学、商业分析、数据分析、经济学、数学、管理科学、心理学、社会学等相关专业优先；\n2、对消费者体验、平台治理、服务运营或本地生活、电商业务有兴趣，愿意深入理解用户在真实消费场景中的需求、痛点和行为，对AI、大模型或智能产品方向有浓厚兴趣，有用户研究、体验洞察、策略运营、AI产品相关项目、实习、课程研究或实践经验者优先；\n3、具备较强的逻辑分析能力和结构化思考能力，能够从复杂信息中提炼关键问题，形成清晰判断，并思考如何评估优化效果，有一定的数据敏感度；\n4、责任心强，目标感清晰，具备良好的沟通表达和协同推进能力，能够与不同角色高效合作，推动多方对齐问题、标准和解决方案；\n5、保持好奇心和主动探索精神，不满足于简单执行，愿意持续学习新业务、新技术和新方法，在真实业务场景中创造影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668253978782779701","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（国际化广告方向） - 销售运营管理平台","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668253978782779701/detail","duty":"团队介绍：国际化销售运营管理平台团队成立于2022年1月，作为国际商业化产品与技术组织的一部分，整合了之前全球CRM（又名3M平台）团队的几个子支柱。我们的团队旨在赋能全球业务解决方案（GBS）团队，通过3M平台和生态系统中的工具和解决方案，通过高效的销售流程和可信的数据洞察，推动业务增长。\n\n1、洞察用户需求，理解业务场景，结合大模型技术能力做出创新AI产品体验；\n2、负责理想用户体验定义，体验衡量体系设计，产品和策略方案设计；\n3、深入策略迭代过程，牵引策略效果提升，组织协同各方达成业务目标。","requirements":"1、2027届获得本科及以上学历；\n2、对AI的能力边界和发展有判断力，有设计策略方案和产品实现的能力，有复杂项目实施运作的经历；\n3、具备敏锐的需求洞察力、良好的逻辑分析能力、产品策略判断能力以及跨团队协作能力；有自驱力、有责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667869209695242501","sourceKey":"bytedance","company":"字节跳动","title":"AI应用全栈工程师 - 抖音平台产品","city":"深圳/北京","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667869209695242501/detail","duty":"团队介绍：\n平台产品基础：作为抖音平台支撑团队，以 AI为核心抓手，打造高效能平台底座，为全业务线筑牢坚实底层支撑\n生态与运营：聚焦创作者成长与商业化，激活生态活力，夯实内容根基\n营销搭建：全链路营销体系，助力业务推广，实现品效增长\n文娱业务：深耕短剧赛道，打通内容 - 营收 - 宣发全链路，构建健康文娱生态\n变现与资金平台：筑牢交易结算核心底盘，提供全链路支付与清结算能力，保障平台资金安全与高效流转\n治理・体验・客服：三位一体守护平台安全、用户体验 以及 高效响应解决用户诉求\n开放业务：有序开放平台能力与数据，链接外部资源，拓展生态边界\n全体团队以业务增长与用户价值为核心，持续深耕、协同共进，推动抖音生态持续繁荣。\n\n1、负责抖音开放平台，包含小程序、抖音开放平台SDK等千万级DAU产品研发，与产品团队合作推动业务落地，保障用户体验与产品性能，积极探索AI大模型结合小程序在多场景落地，包括但不限于：端侧AI大模型、AI智能小程序、AI内容理解等；\n2、负责AI应用平台研发工作，包含AI智能体等产品研发，与产品团队合作推动AI创新产品以及AI业务落地；\n3、调研和跟踪AI行业的前沿技术趋势，持续吸收并推进最新AI行业技术在实际应用场景中落地。","requirements":"1、2027届获得本科及以上学历，计算机软件或相关专业；\n2、具备良好的编程功底，至少熟练掌握一种主流语言（如Kotlin，Swift，JavaScript，TypeScript，Python，Go，C++等）；\n3、具备AI相关经验背景，熟悉AI业界主流前沿技术、对于Agent，MCP，Skills、Prompt Engineering、微调对齐等技术有基本的认知和理解；\n4、对客户端前端后端技术均有广泛的好奇心，具备AI全栈的发展潜力，乐于学习和实践新知识。\n\n加分项\n1、有实际的大模型/AI Agent使用、微调或推理优化经验；\n2、了解小程序技术栈，开发过小程序；\n3、为开源项目贡献过代码，或在技术社区活跃、有自己的技术博客。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667849712639101189","sourceKey":"bytedance","company":"字节跳动","title":"AI跨端开发工程师 - 剪映CapCut","city":"广州/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667849712639101189/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、负责剪映Capcut前端和跨端开发工作，包括工具、生态、主框架等业务方向，服务全球用户，业务前景好；\n2、负责挑战较大的技术架构演进和性能稳定性建设工作，通过技术手段为业务赋能；\n3、探索AI技术在业务和技术场景的应用，如AI Coding、AI Agent等。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、过硬的编码能力，掌握各种前端技术，包括HTML/CSS/JavaScript/Node.js等；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、对AIGC相关技术感兴趣，有AI Agent建设经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667088263216105781","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师 - 国际化内容与服务广告","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667088263216105781/detail","duty":"团队介绍：内容与服务广告团队是全球变现产品组织的一部分，负责为应用下载、游戏、短剧、线索等行业客户构建广告产品。我们的愿景是通过构建支持独特垂直需求、新的变现模式和应用生命周期不同阶段的产品，使我们的产品成为营销人员获取、保留和变现用户的领先平台。\n\n1、利用机器学习技术，改进业务的推荐、广告系统，优化数亿用户的阅读体验；\n2、分析基础数据，挖掘用户兴趣、文章价值，增强推荐、广告系统的预测能力；\n3、分析用户商业意图，挖掘流量潜在商业价值，提升流量变现；\n4、研究计算机视觉算法，给用户提供更多更酷炫的功能；\n5、研发机器翻译与对话技术，促进跨语言内容理解与交流。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业；\n2、热爱计算机科学和技术，对人工智能类产品有浓厚兴趣；\n3、具备优秀的编码能力，熟悉Linux开发环境，熟悉C++和Python语言优先；\n4、有扎实的数据结构和算法功底，熟悉机器学习、自然语言处理、数据挖掘、分布式计算、计算机视觉、计算机图形、语音识别与合成中一项或多项；\n5、对推荐系统、计算广告、搜索引擎、对话问答、图像和视频分析处理相关技术有经验者优先；\n6、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666353809203530037","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（创意经营） - 商业化","city":"北京/杭州/广州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666353809203530037/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、负责巨量引擎渠道生态建设，结合公司产品优势，通过内容生态和精准营销，助力代理商合作伙伴生意增长；\n2、根据公司渠道战略方向，帮助代理商合作伙伴进行生意的诊断与分析，为代理商提供专业的数字营销解决方案，促进目标的达成和生意的长效发展；\n3、研究广告主需求及行业数据，提炼、沉淀、优化方法论，深入理解广告产品营销体系，进行定期培训和指导，参与产品或策略规划与执行，加强业务合作伙伴的服务能力；\n4、深入洞察并掌握市场、行业、政策动态，敏锐分析，不断提升和迭代业务合作的模式和机制，提升效率的同时把控风险，保障生意健康可持续发展。","requirements":"1、2027届获得本科及以上学历；\n2、热爱广告行业，对市场、行业、营销产品具有敏锐洞察力，具有逻辑化与多元化的思维；\n3、具有强大的自驱动力、执行力，以及强烈的好奇心与求知欲，具有出色的沟通能力和协调能力；\n4、性格开朗，为人正直，责任心强，擅长多任务、跨部门的协同与推进。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665316926683515141","sourceKey":"bytedance","company":"字节跳动","title":"Agent研发工程师 - 抖音用户增长","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665316926683515141/detail","duty":"团队介绍：抖音用户增长（User Growth）负责抖音、今日头条、番茄小说等多个产品的用户增长业务，建立行业领先的增长和营销技术，打造极致的用户体验。加入我们，有机会参与亿级用户场景的开发与架构工作，也有机会从数据出发，利用策略和模型为业务带来更大的助力。\n\n1、参与用户增长营销相关产品建设，围绕实时计算、数据服务、策略工程及智能化能力建设落地平台应用，支撑字节跳动抖音系、今日头条系、番茄系、AI系等业务；\n2、基于数据和业务理解，参与整合离线、实时多类型数据源，构建高性能、高可用、可扩展的数据存储与服务体系，与算法、分析师、产品经理等紧密协作，支持精细化运营、智能归因分析、智能触达、用户分层、实验评估等业务场景；\n3、参与优化实时计算和在线服务链路，解决高并发、低延时、高吞吐场景下的稳定性、性能和资源效率问题，推动系统持续演进；\n4、关注实时计算、实时数仓、云原生数据平台及AI Engineering等前沿技术，参与新技术在增长业务中的落地，参与建设AI Coding工程能力，提升工程效率，完成研发开发流程自动化。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、数据等相关专业优先；\n2、熟练掌握至少一种编程语言，包括但不限于Golang、Java、Python、C++；\n3、具备扎实的计算机基础，理解数据结构、算法、操作系统、网络和数据库等核心知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力；\n6、熟悉大数据和实时计算技术栈，有Spark、Flink、Kafka、ClickHouse、Iceberg/Hudi等技术实践经验，具备分布式系统、实时数据处理、在线服务经验，有增长、营销、推荐、广告、画像标签、策略平台等领域经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628643614005184821","sourceKey":"bytedance","company":"字节跳动","title":"Agentic AI算法实习生-风控","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628643614005184821/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：风控算法团队深耕于抖音（短视频、直播、电商、本地生活等）、今日头条等多个字节系业务，涵盖内容、交易、流量、账号等多个场景的底线风险治理、黑灰产对抗及复杂反作弊等关键任务。风控场景具有对抗性极强、逻辑推理链路长及海量多模态数据等挑战。目前，团队正积极推进大语言模型（LLM/MLLM）与 Agentic AI 技术的深入研究与工业化落地。通过探索前沿的模型训练范式、自主规划的 Agent 架构以及严谨的 Harness Engineering 体系，我们致力于打造下一代智能风控基础设施，为十亿级用户的社区生态保驾护航。\n\n1、参与风控垂域大模型基座优化：打造业内领先的风控垂域基座，深入研究CPT、SFT、RL及训练与推理加速等技术；重点攻克强对抗环境下的多模态理解难题，提升模型在超长上下文、复杂逻辑推理和指令遵循等方面的表现；\n2、参与Agentic AI架构研究与演进：参考行业标杆，推进风控Agent的架构升级与工业化落地，打磨领域Skill/Tool框架，优化复杂工具调用、长短期记忆管理、长链路任务编排和多Agent协同等，打造具备自演进能力的下一代智能风控架构；\n3、参与构建科学评估与Harness Engineering体系：构建高质量的领域数据集，设计科学严谨的Benchmark评测体系，构建工业级Harness Engineering系统，持续驱动模型能力边界的突破。","requirements":"1、2027届本科及以上学历在读，计算机、机器学习和模式识别相关专业优先；\n2、扎实的算法与数据结构基础，熟练掌握Python/Go/C++等至少一门编程语言，具备优秀的工程落地能力；\n3、熟悉主流大模型的训练与微调原理，了解RAG、长上下文处理等技术；\n4、在LLM/MLLM/Agent领域有扎实积累；在NeurIPS/ICML/ICLR/ACL/CVPR等顶会发表过相关高质量论文者优先；\n5、具备系统的研究思维与独立思考能力，对风控领域的复杂性、对抗性有浓厚兴趣，敢于挑战现有技术范式。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628143430628919557","sourceKey":"bytedance","company":"字节跳动","title":"面向大模型与AI Agent的AI云原生基础设施关键技术研究-SRE（北京/杭州）","city":"北京","category":"运维","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628143430628919557/detail","duty":"团队介绍：字节跳动基础架构SRE团队，主要负责构建字节跳动私有云的组件服务和稳定性保障，支撑今日头条、西瓜视频、火山小视频、抖音等字节跳动旗下全产品线。Site reliability engineering (SRE) 致力于打造高扩展、高可用系统，并将其贯彻为原则的软件工程师。\n\n课题介绍：\n随着大语言模型与AI Agent规模化落地，传统云原生基础设施已难以适配AI负载的极致性能与弹性需求。本课题围绕AI基础设施全栈展开系统性研究：\n1、网络与可观测：研究大规模AI集群故障智能定位与根因分析，结合时序数据库智能调优，提升集群稳定性；\n2、存储系统：研发AI场景专属的Serverless高性能弹性文件系统与存储加速架构，探索DPU软硬件协同优化，突破AI存储性能瓶颈；\n3、算力调度：研究GPU/CPU/MEM异构协同调度技术，面向AI Agent构建Serverless异构算力编排系统，解决负载异构、状态依赖等调度难题；\n4、向量检索：优化面向大模型应用的向量检索核心技术，打造云原生分布式向量索引引擎，满足超大规模向量检索的低延迟、低成本需求；\n5、智能化与Agent架构：探索基于AI Agent工作流的基础设施自动寻优，构建可自主进化的业务Agent框架，通过AI for Infra赋能全栈智能优化；\n本课题旨在构建支撑大模型与AI Agent落地的下一代AI原生基础设施，提升资源利用率、降低成本、支撑弹性扩展，推动AI基础设施技术演进。\n\n课题挑战：\n1、全栈协同挑战：覆盖多技术领域，需要从端到端视角实现系统性优化，避免单点优化收益不足；\n2、性能成本平衡：AI场景对性能提出极致要求，需要在吞吐、延迟、规模与成本之间找到最优平衡点；\n3、云原生适配：需要将传统单机技术方案重构为适配云原生分布式架构，解决扩缩容、容错、调度等新问题；\n4、AI系统融合：既需要用AI赋能基础设施优化，又需要基础设施原生适配AI负载，深度融合对技术整合要求高；\n5、Agent稳定性：自主进化Agent框架需要解决经验学习、知识一致性、持续安全进化等基础问题，工程化难度大；\n6、研发生态平衡：需要平衡前沿理论创新与工程落地，兼顾技术突破与现有业务生态适配。\n\n课题价值：\n1、构建大模型/RAG 场景的高性能基础设施底座，支撑大规模向量数据高效检索；\n2、优化AI业务存储成本结构与运维复杂度；\n3、提升异构算力资源配置效率与技术复用性。","requirements":"1、2027届毕业，获得博士学位，优先考虑人工智能、计算机科学、数学相关专业；\n2、拥有扎实的信息检索、数据挖掘、机器学习、计算机网络等相关领域理论基础，精通计算机网络和网络编程，熟练掌握至少一门编程语言，如C/C++、Python、Go等，具备优秀的代码能力、数据结构和基础算法功底；\n3、针对不同研究方向，需具备相应能力，如能够独立完成复杂搜索任务的设计与开发；有LLM和基础架构相关研究背景；能完成研究点的设计文档、独立交付件、演示Demo；熟悉当前高性能网络和系统领域的最新进展，包括RDMA，拥塞控制、AI网络优化等技术；\n4、具备高效的学习能力，拥有较强的自我驱动意识；具有良好的团队合作精神，善于与团队成员协作交流，共同攻克难题；出色的问题分析和解决能力，有自主探索解决方案的能力；出色的心理素质与应变能力，面对困难勇于迎接挑战，面对复杂局面沉着、冷静、灵活；\n5、在SIGIR、VLDB、ICDE、NeurIPS、SIGCOMM、NSDI等顶级学术会议或期刊上发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622246696440924469","sourceKey":"bytedance","company":"字节跳动","title":"AIGC模型应用算法工程师-Seed大模型人才校招","city":"杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622246696440924469/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、负责AIGC基础模型相关技术的研究和开发，优化豆包AI创作效果，包括图像模型、Agent模型等；\n2、向字节跳动内部产品提供基础模型及相关应用的支持；\n3、探索以大模型能力为核心的AI创作新产品。","requirements":"1、2027届获得本科及以上学历，计算机/数学等相关专业的优先；\n2、计算机视觉一个或多个领域的研究和实践经验，包括但不限于以下方向：\n1）图像生成/编辑、视频生成/编辑；\n2）生成、理解模型的大规模训练；\n3）VLM的Post-Training（SFT、RM & RL）；\n4）多模态数据生产或多模态模型评测；\n5）生成模型的蒸馏等；\n3、动手能力强，熟练的编程能力，熟悉C++和Python编程；\n4、对AI技术的实际落地和突破性应用充满热情，追求技术创新与现实价值的结合；\n5、良好的自驱力，思维敏捷，追求本质，敢于挑战未知问题，乐于在技术攻关中探索技术前沿，能主动学习并快速成长；\n6、在CVPR/NeurIPS/ICCV/ICLR等顶级会议上发表论文者优先；有数学、编程竞赛经验者有加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7545410474285795592","sourceKey":"bytedance","company":"字节跳动","title":"招聘实习生 - 产品研发","city":"广州","category":"人力","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7545410474285795592/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、根据进行简历的筛选、搜索并进行简历的推荐以及候选人意向沟通；\n2、负责跟进面试安排、面试反馈等招聘流程；\n3、负责招聘渠道开拓及维护，更新招聘信息，负责人才市场的盘点和研究；\n4、协助进行人力资源相关的数据统计工作，协助探索招聘的最佳实践。","requirements":"1、本科及以上学历在读；\n2、有相关的招聘实习经验者优先；\n3、为人正直、亲和力好、耐心、细致认真、负责任；\n4、善于与人沟通、逻辑思维能力及应变能力较好，有团队协作精神；\n5、能够连续实习4个月及以上，每周出勤4天及以上者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668225975628466437","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发工程师（服务体验与治理） - 中国交易与广告","city":"杭州/北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668225975628466437/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与业务系统的设计、开发、测试及持续优化（包括但不限于交互体验、系统性能、可用性等）；\n2、与运营、产品、算法、数据等团队紧密协作，保障项目按时完成，达成业务目标；\n3、使用AI编程工具和智能Agent辅助需求分析、编码、测试与问题排查，提升研发效率；\n4、持续关注大模型、Agent等新技术，探索其在业务和研发流程中的应用。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构、算法、数据库、计算机网络等基础知识；掌握Python/Go/Java/JavaScript中任意一门开发语言，具备基本的软件开发和工程实践能力，熟悉工程开发框架或具备全栈项目经验者优先；\n3、具备良好的业务理解、问题分析、学习能力和团队协作意识；\n4、能够使用主流AI编码工具（TRAE、Claude Code、Codex等）辅助编码、测试和调试，并能够判断、验证和修正AI生成结果；\n5、理解大模型基础原理、熟悉AI Agent模块（Prompt、记忆机制、工具调用、RAG等）者优先；\n6、有完整项目、实习、开源贡献或AI应用开发经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7584334377705801989","sourceKey":"bytedance","company":"字节跳动","title":"国际化咨询实习生 - 飞书项目","city":"北京","category":"销售支持","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7584334377705801989/detail","duty":"团队介绍：飞书项目是专为复杂业务场景打造的专业项目管理平台，通过可视化AI 工作流引擎，帮助企业规范协作流程、提升执行效率。目前，飞书项目已服务多家先进企业，覆盖软件研发、硬件开发、企业经营管理等复杂协同场景，领跑研发项目管理数字化工具赛道。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、与渠道经理团队配合，负责国际化渠道伙伴拓展、赋能及支持工作，输出标准化解决方案工具包，提升伙伴独立对客能力，推动规模化复制；\n2、负责国际化客户的售前沟通及实施交付工作，基于SaaS项目管理平台，围绕流程平台化需求，辅助伙伴完成打单及客户交付服务，协助产出流程解决方案和配置方案；\n3、批量运营及市场活动支持。","requirements":"1、本科及以上学历在读；\n2、英语可作为工作语言，熟悉商务英语；\n3、对企业级软件市场有热情，熟悉项目管理工具、SaaS、ERP数据工具产品、B端产品交付者优先；具备咨询行业相关工作经历优先；\n4、具备较强的业务沟通能力和快速学习能力，具备负责人意识，始终保持创业心态。\n\n加分项：\n1、具备泰语、印尼语等小语种能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7577601298805311797","sourceKey":"bytedance","company":"字节跳动","title":"搜索产品设计实习生 - TikTok设计","city":"北京","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7577601298805311797/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok设计团队的目标是为全球数亿用户提供一流的用户体验，从而帮助用户更好的创作与表达，发现世界的多元与美好，不断打破隔阂，建立起人与人的连接。我们是一个国际化的设计团队，遍布中国、美国、新加坡等国家，世界各地的产品设计师、创意设计师、效果设计师、内容文案专家与本地化经理通力合作，把一个个不可能变成可能。\n\n加入我们，你就有机会理解世界不同地域的文化差异，分析并解决复杂的体验问题，进行前沿的设计探索，更能亲身主导如何把一个想法转化成服务亿级数量用户的产品体验。 如果你积极自驱，对世界充满好奇心和想象力，有希望通过设计打造一流的产品，同时又脚踏实地，欢迎成为我们的一员！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责国际化APP搜索场景体验设计，承担C端方向的设计工作；\n2、参与产品设计迭代，与产品、研发、用户研究、数据等团队合作，主动构思创意，提供最优解决方案；\n3、拥有用户视角与洞察能力，结合实际体验与用户反馈，提出并推动产品机会点落地；\n4、关注主流产品与设计趋势，研究用户体验诉求，结合产品目标，推动产品创新；\n5、将复杂的需求转化为清晰、有吸引力、信息高效的搜索结果呈现方案，并跟踪数据结论。","requirements":"1、本科及以上学历在读，美术、设计等相关专业；\n2、实操能力强：拥有展示UI/UX设计能力的作品集；熟练掌握Figma等设计工具，能高效产出设计稿和原型；\n3、充满好奇心与学习意愿：富有好奇心，乐于主动探索和深入了解用户需求，能力强，对设计细节有追求；\n4、逻辑分析能力好：能将模糊复杂的问题，拆解为结构化的解决方案；\n5、具备良好的沟通能力和团队协作精神；\n6、保证平均每周4.5-5天到岗。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686017568532941061","sourceKey":"bytedance","company":"字节跳动","title":"AI大模型优化工程师 - 音视频技术","city":"杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686017568532941061/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、深度参与对字节跳动VnE自研模型及开源LLM/VLM多模态模型在多种异构芯片上的推理优化，充分发挥出数十万卡的超大规模算力，支撑集团在点播、直播、图片及其它离线大规模数据处理场景中的大模型相关推理业务；\n2、负责完善不同芯片的推理适配和优化技术体系，提升大模型芯片矩阵的适配与优化效率；\n3、负责新型异构芯片在多种大模型上的分析评估工作，引入业界更先进或更高性价比的芯片算力；\n4、负责前沿技术的调研评估和引进落地，例如前沿论文中的推理加速技术、软硬协同优化、新异构硬件特性等。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程或相关专业优先；\n2、熟练掌握Linux环境下的C/C++、Python编程语言；\n3、具备扎实的计算机体系结构技术基础和并行计算优化能力，熟悉常见算法和数据结构，具有良好的编程习惯；\n4、熟悉GPU或NPU的硬件架构，熟练掌握推理优化软件栈（CUDA、CUTLASS、AscendC、BangC等）中的一种或多种，擅长至少一种异构芯片上的AI模型性能分析和算子优化；\n5、了解主流LLM、多模态模型结构特点，了解主流推理框架如vLLM、SGLang，了解常见大模型并行策略；了解常见大模型量化算法及算子优化方案可加分；\n6、具备优秀的问题分析与解决能力，能够自主探索并设计创新性解决方案；具备良好的沟通与协作能力，能够与团队成员共同探索新技术，推动研究进展与项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675268196536535301","sourceKey":"bytedance","company":"字节跳动","title":"广告产品运营实习生 - 国际化电商广告","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675268196536535301/detail","duty":"团队介绍：国际化电商广告团队始终以广告主为核心，追求技术卓越。我们与电商、零售、旅游等各行业广告主紧密合作，致力于将国际化产品打造为各类企业不可或缺的增长平台，同时成为消费者发现并购买产品、内容及服务的首选目的地。团队肩负着实现国际化广告营收的重要使命，正在全力构建新一代网络广告解决方案。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、在全新产品测试阶段辅助对接测试用户，收集客户原声反馈；\n2、整理典型案例，辅助完成数据统计工作；\n3、同步配合产品GTM优化沟通。","requirements":"1、本科及以上学历在读；\n2、英语听说读写流利，能适应跨团队协作交流；\n3、有互联网广告或商业化产品实习经历优先；\n4、有国际化学习经历优先；\n5、每周出勤4天及以上，连续实习4个月及以上者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672328869482875189","sourceKey":"bytedance","company":"字节跳动","title":"大模型训练实习生 - 内容质量与数据服务平台","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672328869482875189/detail","duty":"团队介绍：抖音内容质量与数据服务平台（简称CQC）归属于抖音集团，负责今日头条、抖音等产品内容和抖音集团商业内容的安全质量与体验。平台下设内容质量中心、商业生态与安全、生态治理与增长支持等业务，在全国20余个城市均有分布。\n自成立以来，CQC持续守护抖音集团旗下包括抖音、今日头条、番茄小说、飞书、红果短剧等产品在内的安全、质量与体验，优化产品内创作与交流环境，且在各产品运营增长方面开展支持工作。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、支持今日头条业务安全策略模型结构设计、模型数据建设、模型训练迭代、模型效果评估等全链路工作，保证业务需求稳定交付；\n2、深入了解业务需求及流程链路，与团队成员、业务团队密切协作，根据业务指标、用户反馈等信息持续挖掘模型能力及策略优化空间，设计模型方案并保证高效高质落地；\n3、熟练掌握模型训练方式和应用场景，从解决业务痛点出发灵活运用大模型方法，不断提升模型训练及业务应用效果；\n4、制定、更新和维护大模型服务质量监控标准，促进技术变更和更新，不断迭代大模型应用形式和链路升级。","requirements":"1、2027届本科及以上学历在读，人工智能、计算机科学、数学相关专业优先；\n2、有编程/数模竞赛获奖经历优先；具备出色的编程能力，熟悉大模型训练RM、RL、NLP、CV相关的算法和技术，可使用Python/Java/Go/JavaScript/C/C++二种以上主流语言，熟悉主流数据库的操作，有自然语言处理（NLP）、计算机视觉（CV）或多模态生成模型（如CLIP、Diffusion Models）项目经验；熟悉大模型理论知识和应用，熟悉常见大模型架构，有实际大模型预训练、微调或推理优化经验者优先；\n3、Prompt流程设计创作：深入理解大模型在审核领域应用需求，结合业务与平台治理相关的规则、政策，设计业务流程并转化为Prompt；对Prompt线上效果负责；\n4、RAG应用探索：基于不同业务场景实际落地需求，设计符合其特性的RAG应用方式和训练模式，对RAG召回效果负责；\n5、善于思考、探索，有研究精神，具备很强的逻辑思维能力和解决问题的能力、能理解和抽象业务逻辑；\n6、密切协作产品研发等团队，积极探索大模型等先进的工作方式。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672272924247804165","sourceKey":"bytedance","company":"字节跳动","title":"多传感器融合算法工程师 - PICO","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672272924247804165/detail","duty":"团队介绍：作为一家拥有自主创新和研发创造能力的科技品牌，PICO致力于成为领先的世界级XR平台，成就开发者与创作者，共同为全球消费者创造更美好的生活体验。我们开创性地将虚拟现实扩展到了多个领域，为运动、视频、娱乐等消费级场景带来了全新体验；并广泛应用在教育、医疗和企业培训等商用场景，给全球企业级用户提供了多元化的VR解决方案。\n\n1、负责多传感器（视觉、IMU等）融合方面的空间定位算法的研发工作；\n2、负责算法在实际基于移动平台的产品中的优化和落地；\n3、针对具身数采、XR控制器等需求，提升空间定位精度。","requirements":"1、2027届获得硕士及以上学位，计算机、电子、自动化等相关专业；\n2、熟练掌握C/C++及Python语言，具备优秀的算法和编程能力；\n3、精通状态估计算法（如Kalman Filter,EKF,UKF,Particle Filter等）；\n4、熟悉惯性导航原理，有IMU数据处理及解算经验；\n5、熟悉视觉SLAM算法原理（VSLAM、VIO、RGB-D SLAM等），至少精通一种主流的SLAM开源系统，有相关项目经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667038612056197381","sourceKey":"bytedance","company":"字节跳动","title":"后端研发工程师 - 番茄小说/红果短剧/番茄畅听","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667038612056197381/detail","duty":"团队介绍：\n番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、负责字节跳动番茄小说等多业务方向的服务端开发工作；\n2、负责架构设计和开发，参与系统技术方案设计、代码开发及系统调优，为亿级用户提供优质顺畅的信息服务和极致体验；\n3、参与制定代码规范、测试规范，建立开发质量控制方法，协助团队攻克高并发、数据隔离、系统解耦等技术难关；\n4、参与各专项技术调研、新技术引入等前瞻项目，以及机器学习与异构计算系统研发。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665565323860969781","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师 - 中国交易与广告","city":"上海","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665565323860969781/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与字节跳动系平台（抖音、抖音火山版、今日头条、西瓜视频等）电商消费端以及商家达人端前端架构设计、系统开发与优化工作；\n2、工作范围涉及前端基础架构、跨端应用、全栈开发、数据可视化、前端智能化等多个方向；\n3、深入参与业务解决方案设计，承担业务重点技术攻坚，通过高质量的编码设计支持业务的快速发展；\n4、与产品经理、设计师、后端工程师一起，提升产品的用户体验，打造卓越的互联网产品；\n5、关注前端前沿技术发展，能够将新知识传递给团队，并且转化到潜在项目中。","requirements":"1、2027届获得本科及以上学历，计算机、通信工程等相关专业；\n2、计算机基础扎实，熟练掌握JavaScript、CSS、HTML等前端技术及相关标准规范；\n3、熟悉一种主流前端框架以及相关技术栈，包括但不限于React、Vue等，有实际项目研发经验；\n4、具备良好的编码能力、较好的抽象设计能力，关注国内外各大开源社区和技术论坛；\n5、具备较强的责任感、团队合作精神、逻辑思维能力和表达能力；\n6、熟悉数据结构与算法，能够对具体的日常业务做基础的抽象建模。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7623005989311826181","sourceKey":"bytedance","company":"字节跳动","title":"音频多模态训练实习生-Seed大模型人才实习","city":"上海","category":"基础架构","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7623005989311826181/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、负责音视频多模态场景大模型训练性能优化，负责开发和优化语音相关场景的大模型训练框架，保证训练效率达到业界领先水平；\n2、与算法同学深度合作，进行算法和训推系统的联合深度优化，支撑部门前沿技术探索以及落地；\n3、负责机器学习系统前瞻技术的调研和引入，持续加强提升部门关键技术竞争力。","requirements":"1、2028届及以后本科及以上学历在读，人工智能、计算机、自动化、数学相关专业优先；\n2、熟悉PyTorch深度学习框架，熟练使用Python语言，有C++开发经验者优先；\n3、熟练高性能计算优化技术，深入理解计算机体系结构，熟悉并行计算优化、访存优化，模型压缩，低比特计算等；\n4、熟悉常用深度学习算法优先，例如NLP，CV，语音；\n5、熟悉DeepSpeed/Megatron等大规模训练框架，熟悉数据并行/模型并行/流水并行等常用分布式训练方案优先；\n6、熟悉CUDA生态，有CUDA/NCCL/CUTLASS开发经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622206477847038213","sourceKey":"bytedance","company":"字节跳动","title":"多模态Agent算法研究员-Seed大模型人才校招","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622206477847038213/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、探索构建GUI、Code、游戏等虚拟世界的通用多模态Agent；\n2、探索研究多模态理解、生成式、机器学习、强化学习、AIGC、计算机视觉、人工智能等前沿技术；\n3、探索大规模/超大规模多模态理解与生成交织的基础模型，并进行极致系统优化；数据建设、指令微调、偏好对齐、模型优化；提升数据合成、Scalable oversight、模型推理、规划能力，构建全面客观准确的评测体系，探索提升大模型能力；\n4、利用预训练、仿真等技术对虚拟/现实世界的各类环境进行建模，提供多模态交互探索的基本能力，推动应用落地，研发以人工智能技术为核心的新技术、新产品。","requirements":"1、2027届获得本科及以上学历，计算机、数学等相关专业优先；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、具有扎实的计算机视觉、机器学习基础，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议上发表论文者优先；\n4、在大模型领域或者RL领域，主导过大影响力的项目者优先；\n5、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；\n6、具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7616306853192763653","sourceKey":"bytedance","company":"字节跳动","title":"AI应用开发实习生-Cross Platform","city":"上海","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7616306853192763653/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动Cross Platform致力于开发Lynx等业界前沿的应用框架，构建LLM驱动的前沿系统和基础设施，提升开发者和用户体验。\n\n1、参与AI应用框架和底层能力建设，支撑豆包等字节跳动AI产品的需求；\n2、参与大模型应用开发全流程工作，包括但不限于多模态大模型接入、AI Agent开发、RAG优化、流程编排、MCP及工具开发、AI可观测性和调优等；\n3、持续跟踪AI领域技术演进，探索并推动相关能力在业务落地。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、拥有扎实的计算机基础知识，优秀的编码与代码控制能力；\n3、良好的学习能力、自驱力、问题分析与解决能力、英文阅读能力、与团队合作精神；\n4、至少熟练掌握Android/iOS/Web一种技术栈，熟悉跨端开发或者小程序框架者优先；\n5、熟悉Agent，MCP、RAG，模型SFT，Context Engineering等相关技术，有相关实践经验者优先；\n6、每周保证至少4天的实习时间，可实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668203989573404981","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 番茄小说/红果短剧/番茄畅听","city":"北京/深圳/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668203989573404981/detail","duty":"团队介绍：\n番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、负责字节跳动番茄小说等多业务方向的服务端开发、架构设计与系统技术方案设计，进行代码开发、系统调优，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与制定代码规范、测试规范，建立开发质量控制方法；\n3、协助团队攻克高并发、数据隔离、系统解耦等技术难关；\n4、参与专项技术调研、新技术引入及机器学习与异构计算系统研发等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667935738067962165","sourceKey":"bytedance","company":"字节跳动","title":"配送履约产品经理 - 抖音电商","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667935738067962165/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、参与抖音电商物流服务及解决方案设计，基于供给与商业诉求，设计适配业务场景的物流解决方案；\n2、负责抖音电商发货履约工具产品设计工作，涵盖订单管理、电子面单、包裹中心、发货中心等模块的能力迭代与体系建设；\n3、基于抖音电商商家经营场景，与行业运营、平台治理、商家成长等业务团队深度协同，持续提升商家经营效率；深入洞察电商商家、快递网点、仓储物流等多方角色痛点，结合行业趋势与技术能力，制定并落地产品策略；\n4、深入洞察和理解用户诉求，参与发掘不同业务特点与模式下的物流服务机会点，为平台带来增量价值；\n5、围绕抖音电商履约配送体验，通过数据分析洞察履约体验问题与风险，支持风险识别策略与AI研判等能力建设，驱动履约问题有效解决；\n6、结合业务重心和目标，定期输出产品迭代规划，驱动业务目标达成。","requirements":"1、2027届获得本科及以上学历，物流、计算机、统计学等相关专业背景优先；\n2、具有良好的结构化思维，数据敏感度高；具有敏锐的需求洞察和抽象能力，能从复杂业务逻辑中发现问题本质，找到解决方案并推动落地；\n3、沟通及团队协作能力强，责任心与执行力强；\n4、自驱力强，有目标感，为了目标坚持不懈，敢于承担和挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664484071741606149","sourceKey":"bytedance","company":"字节跳动","title":"多媒体算法工程师 - TikTok研发","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664484071741606149/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、设计智能决策引擎，负责直播/RTC场景中客户端的AI驱动自适应策略研发；\n2、运用强化学习（RL）、时间序列预测等轻量级模型，重构传统的ABR、网络带宽预测、性能降级与播控、缓冲策略，打造端侧感知与自适应联动的“智能大脑”；\n3、负责服务端转码与调度策略的智能演进，探索基于ML、大模型的动态转码资源调度与画质增强策略，实现体验与成本的全局最优（帕累托最优）；\n4、开展数据驱动的个性化QoE建模，突破传统QoS/QoE映射规则局限，依托海量流媒体数据，运用因果推断与大模型（LLM）技术深度分析用户意图与复杂网络环境，构建“千人千面”的个性化体验评价模型，让策略系统具备自我进化能力。","requirements":"1、2027届获得硕士及以上学位，计算机科学、人工智能、数据科学或相关专业优先；\n2、扎实的编码基础，熟练掌握C++/Python，熟悉PyTorch或TensorFlow等主流深度学习框架；\n3、对机器学习、强化学习、因果推断有扎实的理论基础；在大模型（LLM/VLM）、生成式AI等领域有探索热情，有相关顶会Paper或实际工程落地经验者优先；\n4、对直播/RTC系统的基本架构（如推拉流链路、编码器原理）有一定了解者优先考虑；\n5、具备较强的技术好奇心与破局思维，对“用AI重塑传统流媒体基础设施”充满热情，能够在复杂的音视频工程链路中准确界定模型能力边界并推动落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685692551579535621","sourceKey":"bytedance","company":"字节跳动","title":"财务平台运营实习生 - 抖音","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685692551579535621/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责UG用户增长一站式结算平台的运营工作，日常跟进数据产出、核对与结果验收，保障结算数据准确、结算流程稳定；\n2、辅助建设并完善结算监控和自动化对账机制，持续维护校验规则，及时发现数据差异与链路异常，提升风险识别和预警能力；\n3、跟进异常结算数据的处理，完成问题收集、分析与归因，协同相关团队定位并推动修复，追踪处理结果并沉淀典型案例；\n4、深入了解用户增长全业务链路及相关工作流，持续识别流程中的痛点和风险，提出合理的优化方案并推动落地；\n5、与产品、风控、财务、研发等团队协同，做好需求沟通、进度跟进和结果反馈，保障结算运营事项按计划推进。","requirements":"1、本科及以上学历在读，信息管理、会计、统计、计算机或相关专业优先；\n2、对数据敏感，具备基础的数据整理和分析能力；有平台运营、数据运营、财务结算或相关实习经历者优先；\n3、能够快速理解业务流程和工作流，善于发现问题、分析原因，并提出清晰、可执行的解决方案；\n4、沟通协作和执行能力强，做事细致、有耐心，具备较强的自驱力和责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677483899098220853","sourceKey":"bytedance","company":"字节跳动","title":"标准与质量运营实习生 - 内容质量与数据服务平台","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677483899098220853/detail","duty":"团队介绍：抖音内容质量与数据服务平台（简称CQC）归属于抖音集团，负责今日头条、抖音等产品内容和抖音集团商业内容的安全质量与体验。平台下设内容质量中心、商业生态与安全、生态治理与增长支持等业务，在全国20余个城市均有分布。\n自成立以来，CQC持续守护抖音集团旗下包括抖音、今日头条、番茄小说、飞书、红果短剧等产品在内的安全、质量与体验，优化产品内创作与交流环境，且在各产品运营增长方面开展支持工作。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、基于平台生态及用户体验，完善社区标准，并能根据政策要求、舆情变化、用户反馈等因素，不断完善标准体系；\n2、定期对安全治理标准体系的适用性、有效性进行评估和数据分析，根据团队执行情况和平台生态情况设计优化方案，推动规则、策略、产品、流程等优化；\n3、支持机审大模型建设，进行风险域标准知识库改写及协助PE调优流程；\n4、根据质量难点输出对标准和手册的解读、尺度拉齐、培训和规则细则优化，帮助人审对齐规则理解，提升交付质量。","requirements":"1、2027届本科及以上学历在读，优先新闻学、传播学、中文学等专业；\n2、熟悉网络舆论环境及管理尺度，对热点风险、风险有敏锐的洞察力，有良好的内容判断力和风险预见能力；具备优秀的产品思维和解决方案能力，逻辑清晰、数据分析能力强；\n3、文字功底强、具有敏锐的洞察力，能够快速提炼核心信息、下钻深入分析；\n4、自驱力、责任心强，有良好的表达能力、跨部门沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669619179831052549","sourceKey":"bytedance","company":"字节跳动","title":"直播电商C端用户产品经理（欧美市场） - TikTok Shop","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669619179831052549/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、建设TikTok Shop欧美直播电商用户侧产品能力，围绕直播内容发现、导购体验、交易转化和营销增长玩法，持续优化用户从观看、互动到购买的完整链路体验，推动直播电商用户规模与商业效率增长；\n2、深入理解直播电商场景下的用户需求、内容消费偏好和购买决策路径，结合不同用户分层与消费场景，设计更高效的内容承接、导购转化和增长机制，提升用户参与度、转化效率和复购表现；\n3、探索AI/大模型等智能化能力在用户侧直播电商场景中的应用，围绕用户理解、内容推荐、导购决策和营销触达等方向，提升用户触达效率、决策效率和产品体验，推动直播电商用户增长模式持续创新；\n4、深入理解国际化市场、直播电商生态和用户真实需求，通过用户调研、数据分析和业务洞察识别关键问题，协同增长、营销、交易、推荐、TikTok LIVE等团队推动产品方案落地，并持续评估和优化业务结果。","requirements":"1、2027届获得本科及以上学历，数据科学、计算机、AI等相关专业优先；\n2、对国际化电商、直播内容生态、用户增长或用户产品方向有浓厚兴趣；目标&结果导向，具备较强的业务理解、产品判断能力、数据意识、逻辑分析和学习能力，能够结合数据、调研和行业观察持续推动产品迭代；\n3、关注AI/大模型在用户理解、内容推荐和导购决策中的应用，有相关实践经验者优先优先；\n4、具备优秀的沟通协作能力、自驱力和责任心，能够适应国际化业务环境，英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667835102218684725","sourceKey":"bytedance","company":"字节跳动","title":"创意产品经理-「星璨全球」培养计划 - 国际化广告创意与品牌","city":"深圳/北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667835102218684725/detail","duty":"团队介绍：字节跳动国际商业化创意与品牌广告团队致力于通过创意内容（如创意解决方案平台、内容套装及ACA创意工具）与AI技术的结合，为品牌提供从认知到种草转化为购买的全链路营销解决方案。无论是广告投放还是自然流量，我们都能通过智能ROI优化和GMV增长技术，最大化品牌的营销效果。\n我们将创意、社区与商业无缝融合，AI技术贯穿始终，帮助品牌高效触达目标用户，实现可持续增长。我们的使命是激发创意，驱动增长。我们愿景是打造以创意为核心、AI驱动的增长引擎，让每一次内容探索都能带来可衡量的商业价值。\n\n为培养兼具全球视野与互联网商业思维的复合型人才，国际化广告创意与品牌团队面向2027届校招同学持续推出「星璨全球」培养计划：\n-两年全球化业务方向轮岗，拓展国际视野\n-资深导师带教辅导，加速能力提升\n-承担重要岗位挑战，在实战中成长\n\n我们相信年轻的力量，期待携手创造无限可能！\n\n1、负责国际化商业化广告及达人相关产品建设；通过产品和策略设计，帮助广告主在平台高效高质完成创意制作及达人匹配，同时帮助达人更好地实现变现；\n2、负责优化达人和创意相关产品的客户旅程，让广告主、达人与其服务机构合作流程更畅通，体验更好；\n3、负责与各区域运营沟通合作，明确梳理不同区域的差异化需求，设计通用解决方案；\n4、理解创意和达人相关的业务逻辑，抽象过程中遇到的核心问题，并通过调研完成产品设计；\n5、通过数据分析，明确当前业务增长的问题及痛点，与运营协同完成增长策略的设计。","requirements":"1、2027届获得本科及以上学历；\n2、有平台、商业化、To B或合作伙伴生态产品实习经验优先；英语口语、写作能力流畅，可适应多语言工作环境；\n3、积极主动，愿意深入理解业务，对业务及用户需求敏感并擅长沟通；\n4、有同理心、责任感、自驱力，具备优秀的项目管理及推动能力；\n5、有良好的逻辑思维能力，数据敏感，擅长通过数据分析问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667152708928194869","sourceKey":"bytedance","company":"字节跳动","title":"嵌入式开发工程师 - 移动OS","city":"深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667152708928194869/detail","duty":"团队介绍：我们隶属于产品研发与工程架构部，是字节跳动在智能硬件领域的软件技术攻坚力量—— 聚焦 AI 与智能硬件的深度融合，如豆包手机助手等；以 “让人与设备的交互更自然、更便捷” 为目标，探索前沿 AI 技术的落地场景，打造行业领先的智能硬件综合解决方案。\n在这里，你将与一支顶尖技术团队并肩：\n- 直击 AI 与硬件结合的核心技术难题，参与从 “技术探索” 到 “场景落地” 的全链路研发；\n- 主导或深度参与关键技术突破，用创新定义智能硬件的交互未来；\n- 站在行业前沿，将技术理想转化为千万用户可感知的产品体验。\n如果你心怀对技术的热忱，渴望在 AI 与智能硬件的赛道上突破自我、创造价值，我们期待你的加入，与我们一起解锁更多技术可能，共筑智能交互的新生态！\n\n1、负责Camera软件架构设计与开发；\n2、负责集成Camera软、硬件算法，与APP/算法合作提升影像竞争力；\n3、负责Camera各个场景中性能、稳定性、系统资源优化工作。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、自动化、通信工程等相关专业优先；\n2、熟练掌握计算机基础，包括但不限于操作系统原理，计算机组成原理；\n3、熟练掌握一门计算机编程语言，C/C++优先，或MATLAB/Python；\n4、有实时性操作系统(Zephry和Nuttx)经验优先；\n5、有图像处理/算法部署相关项目经验或者实习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667140684885838133","sourceKey":"bytedance","company":"字节跳动","title":"游戏引擎技术工程师 - 抖音研发","city":"杭州/深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667140684885838133/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、参与字节跳动内部自研引擎的设计与开发，将AI Native融入引擎架构；\n2、构建AI Agent驱动的游戏开发工具链，建设AI友好的研发工作流；\n3、探索移动端最佳实践，跟进AI+Graphics前沿方向的移动端落地。","requirements":"1、2027届获得本科及以上学历；\n2、具备良好的抽象能力和编码能力，学习能力强，有主动探索并应用新技术的意愿；\n3、熟练掌握C++/JS、数据结构、多线程，了解计算机图形学或游戏引擎（Unity/UE/自研引擎），熟悉WebGL/Vulkan/Metal等图形API，使用过GitHub Copilot/Cursor/OpenAI Codex等AI编程工具；\n4、对AI（AIGC/Agent/Tool-use）有强兴趣，并有实际项目经验，有深入使用AI编程工具完成实际开发的经验，对AI改变游戏开发有独立判断，有图形学/渲染/引擎相关项目经验，有开源项目或技术博客。\n\n加分项：\n1、有图形学/渲染/引擎相关项目经验；\n2、熟悉WebGL/Vulkan/Metal等图形API；\n3、使用过GitHub Copilot/Cursor/OpenAI Codex等AI编程工具；\n4、有开源项目或技术博客。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665994813989292293","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - 抖音平台产品","city":"杭州/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665994813989292293/detail","duty":"团队介绍：\n平台产品基础：作为抖音平台支撑团队，以 AI为核心抓手，打造高效能平台底座，为全业务线筑牢坚实底层支撑\n生态与运营：聚焦创作者成长与商业化，激活生态活力，夯实内容根基\n营销搭建：全链路营销体系，助力业务推广，实现品效增长\n文娱业务：深耕短剧赛道，打通内容 - 营收 - 宣发全链路，构建健康文娱生态\n变现与资金平台：筑牢交易结算核心底盘，提供全链路支付与清结算能力，保障平台资金安全与高效流转\n治理・体验・客服：三位一体守护平台安全、用户体验 以及 高效响应解决用户诉求\n开放业务：有序开放平台能力与数据，链接外部资源，拓展生态边界\n全体团队以业务增长与用户价值为核心，持续深耕、协同共进，推动抖音生态持续繁荣。\n\n1、构建高效、可靠的AI Agent，精准理解产品的复杂需求，实现自规划、任务拆解及执行；\n2、设计高效的Multi-Agent系统，确保多Agent间任务流转高效，上下文管理准确；\n3、实现AI支撑企业级、大用户规模C端产品的需求端到端生成；\n4、负责研发基于LLM的AI Agent系统，负责构建工程研发不同阶段的Agent；\n5、参与探索Multi-Agent协作机制，推动Multi-Agent系统对复杂任务的规划和拆解，对已有人类经验的学习和引用，不断优化Agent解决实际问题的路径和效果。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的计算机、编程基础，熟悉主流大语言模型的原理及方法；\n3、理解Multi-Agent系统、任务分解、自动化规划、Prompt Engineering等技术领域之一或多个，有AI Agent相关实践项目者优先；\n4、出色的结构化表达能力，较强的技术敏感度与前瞻性，独立的思考和判断力；\n5、热爱AI相关技术，对应用和落地工程感兴趣，富有钻研创新精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7662965849647089925","sourceKey":"bytedance","company":"字节跳动","title":"系统软件工程师 - AI算力基础设施","city":"上海/北京/深圳/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7662965849647089925/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、系统软件开发：参与BIOS、BMC固件、Linux内核及操作系统相关模块的开发，解决底层硬件兼容性以及功能扩展问题，实现软硬件一体化集成；\n2、系统优化与维护：对BIOS、BMC固件、Linux内核及操作系统进行性能测试、分析、优化，定位并解决系统运行过程中的各类问题，保障系统高效稳定运行；\n3、系统监控诊断：设计与实现系统监控诊断相关功能，开发监控工具或模块，实时监测BIOS、BMC固件、Linux内核及操作系统的运行状态，及时发现并预警潜在故障，协助排查和解决系统故障；\n4、新技术探索与应用：关注系统软件领域最新技术动态，如人工智能在系统诊断中的应用、系统技术在AI基础设施中的应用等，结合公司业务需求，探索新技术在项目中的可行性，提出创新方案并实践验证。","requirements":"1、2027届获得本科及以上学历，计算机科学、电子工程、软件工程等相关专业；\n2、掌握C/C++/Golang等编程语言，了解汇编语言基础，具备良好的代码风格；\n3、了解X86/ARM/RISC-V架构基础知识，对BIOS/BMC、Linux内核及操作系统有一定了解或浓厚兴趣；\n4、具备一定的Linux系统使用经验，熟悉Shell、Makefile、GDB、perf等工具；\n5、对底层系统技术有浓厚兴趣，乐于钻研复杂技术问题，具备较强的学习能力、问题分析能力和团队协作精神；\n6、有相关领域开源项目贡献、科研项目或实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7660773799478102325","sourceKey":"bytedance","company":"字节跳动","title":"数据科学实习生-抖音电商","city":"北京","category":"数据分析","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7660773799478102325/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：抖音电商以\"总能发现好东西\"为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、业务数据分析与洞察：参与业务问题拆解，理解业务目标、指标和分析口径；使用SQL/Python完成数据提取、清洗、统计分析和可视化；输出结构化分析结论，支持产品、运营或业务决策；\n2、数据建模与实验评估：协助完成用户行为分析、特征构建、模型训练和效果评估；参与A/B实验、策略评估、预测建模等数据科学相关工作；对模型或实验结果进行解释，分析效果波动原因和优化方向；\n3、AI工具与大模型应用探索：探索大模型、Agent、RAG、自动化数据分析等技术在DS工作流中的应用；将AI工具用于SQL/Python辅助、数据理解、分析报告生成等场景；搭建轻量Demo或自动化脚本，验证AI对分析效率和质量的提升。","requirements":"1、本科及以上学历在读，统计、数学、计算机、AI等相关专业优先；\n2、熟练SQL+Python，具备数据分析与建模基础；\n3、理解常见统计方法、机器学习基础和实验评估；\n4、对AI/大模型有强兴趣，有实际探索项目经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628114831572273461","sourceKey":"bytedance","company":"字节跳动","title":"【实习】抖音多业务场景的大模型训练与应用-抖音用户体验（北京/深圳）","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628114831572273461/detail","duty":"团队介绍：抖音用户体验团队成立于2018年，致力于发展业界独特技术栈，通过技术手段提升抖音等字节跳动旗下应用的用户体验与营收。我们在AI与各类基础技术领域的融合上具备远见与决心，曾开创个性化视频体验、个性化应用体验等多个业界全新的技术子领域和相关技术，在抖音等产品中得到充分验证。团队交叉融合推荐类系统、因果推断、生成式AI、端智能、音视频、网络、编译器等多种不同的技术领域，并能够直接、快速地推动新技术落地，带来显著业务价值。\n\n课题介绍：\n抖音研发团队，负责抖音短视频、直播、中长视频、搜索、图文、音乐、社交通讯、医疗等业务技术开发，以及字节跳动旗下产品的客服平台、业务安全、用户增长、用户体验、抖音账号、AI技术研究与赋能等中台团队的研发工作。本次课题共涉及5个方向：\n1、用户体验：抖音场景下的端侧大模型架构与推理加速体系研究；\n2、抖音直播：迭代3D生成大模型，优化数据、编码和模型架构，提升3D资产生成效率和品质；\n3、汽水音乐：聚焦音乐生成大模型的核心算法研究与优化，旨在攻克上述技术瓶颈，提升AI音乐创作的质量、可控性与创新性，赋能短视频配乐、虚拟偶像等多元应用场景；\n4、AI技术研究与赋能：随着大模型在代码生成与软件开发中的应用不断深化，构建端到端AI Coding模型已成为提升研发效率的关键方向。本课题聚焦从数据构建、模型训练（SFT/RL）、到推理部署的全链路优化，探索从需求理解，代码生成与修复，与功能上线的一体化建模方法。重点解决领域知识注入、大规模SFT训练、Agentic RL等问题，推动AI在抖音等真实业务研发场景中的规模化落地；\n5、小荷健康：围绕问诊、工具调用、科普与病例分析，提升医疗大模型任务规划与推理能力，保证结果准确稳定可用。\n\n课题挑战：\n1、资源约束极强，需兼顾算力、内存与功耗；通用性要求高，需支撑多业务场景高精度处理；面向差异化设备，实现任务复杂度的弹性适配；\n2、高质量3D数据严重稀缺，3D几何与纹理表征复杂，生成质量与美术水准比仍有差距，当前链路冗长效率偏低；\n3、音乐审美偏好的量化建模问题、长序列高品质音乐生成问题、多风格泛化与创新生成问题、推理增强方法的迁移应用问题；\n4、抖音研发大模型需高效的业务知识注入，复杂且超长的上下文管理，解决高质量训练数据稀缺，Agentic RL的持续训练；\n5、小荷健康围绕医疗场景基座模型 ，Agent Foundation构建与评测体系，强化模型复杂知识检索、任务分解及长链路执行能力。通过优化 SFT、RL、OPD等后训练方法的组合策略，兼顾模型效果、稳定性与泛化性。同时探究线上用户体验与基座模型训练间的关联，实现医疗大模型能力与实际应用效果的协同提升。\n\n课题价值：\n1、技术价值：等参数量级下，可大规模落地的业界领先模型；业务价值：提升抖音用户和业务接入的覆盖面，获得用户和营收价值；\n2、技术上提升3D表征与生成能力，迭代3D生成大模型；业务上支撑直播和社交应用，产出丰富3D资产，满足海量用户的个性化需求；\n3、技术上突破音乐生成在审美建模、长序列连贯性等核心瓶颈，引领AI音乐生成技术前沿；业务上提升抖音/汽水音乐的AI创作能力，降低音乐创作门槛，丰富内容生态，提供音乐内容供给；\n4、技术上探索前沿模型训练策略，构建字节内部真实环境下的数据飞轮，提高业务研发效率，提升代码质量与性能；\n5、技术上提升医疗大模型Agent与Post-Training方向的关键技术突破，提升问诊、科普、病例分析等核心场景业务效果，沉淀可复用的数据、训练与评测方法，支撑长期模型演进。","requirements":"1、2027届及以后毕业，博士在读，人工智能、计算机、自动化、数学相关专业优先；\n2、扎实的机器学习基础，熟悉NLP、AIGC领域的技术，在各相关领域顶级会议上发表论文者优先；\n3、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，熟悉各种算法研究所需工具；\n4、在LLM/AIGC领域，主导过大影响力的项目或论文者优先；\n5、在因果推断、优化理论、数据挖掘、运筹学等领域之一达到前沿水平者优先；\n6、出色的问题分析和解决能力，能快速理解并灵活运用跨领域知识，有自主探索解决方案的能力；良好的沟通协作能力，能构建合理的研究与落地规划。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7597379551752128821","sourceKey":"bytedance","company":"字节跳动","title":"推荐大模型算法实习生-抖音电商","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7597379551752128821/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n1、负责大模型驱动的电商个性化推荐算法优化，覆盖商品、直播、短视频等多场景，联动推荐与广告系统，提升数亿用户使用体验；\n2、融合大模型、表征学习、图模型、多任务学习等技术，优化信息匹配效率与预估效果，自动挖掘优质、高口碑商品及主播，助力用户便捷触达好货；\n3、基于大模型挖掘与分析用户行为数据，构建用户长短期兴趣模型，精准预测潜在需求与购买意图，持续提升推荐精准性；\n4、深入内容电商业务场景，设计大模型与算法、策略一体化的技术方案，构建良性电商生态，驱动业务快速增长；\n5、在超大规模在线深度学习框架下，结合大模型研究前沿技术，探索下一代预估建模与推荐方案，推进算法与模型创新。","requirements":"1、2027届硕士及以上学位在读，计算机相关专业；\n2、拥有扎实的算法和数据结构基础，优秀的编码能力，熟练掌握C++和Python语言，熟悉Linux开发环境；\n3、机器学习基础扎实，熟悉常用算法模型，了解大模型在推荐、广告领域的应用者优先；\n4、熟悉XGBoost、TensorFlow、PyTorch中至少一种开源工具，具备优秀的学习、分析及问题解决能力，对技术挑战充满热情；\n5、热爱技术工作，具备良好的沟通表达能力与团队合作精神，能高效推进技术方案落地。\n\n加分项\n1、有个性化推荐、广告、信息检索、自然语言处理、大模型应用及机器学习相关领域的研究或项目实践经验；\n2、在KDD、NeurIPS、WWW、SIGIR、WSDM、ICML、IJCAI、AAAI、RecSys等国际会议发表过论文，或有数据挖掘/机器学习相关竞赛经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680937803145726213","sourceKey":"bytedance","company":"字节跳动","title":"内容质量与评估（阿拉伯语方向） - TikTok","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680937803145726213/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、负责内容安全核心评测集（Golden Set）的构建与持续迭代，通过挖掘长尾、高危及复杂边缘样本，为平台安全策略、AI模型评估与全球执行团队提供高准确度的数据标准（Ground Truth）；\n2、深入剖析高风险与争议性安全案例，准确洞察误判模式与风险演变趋势；主导复杂规则的降维与抽象，将宏观政策转化为逻辑严密、可执行度高的标准化运营指南（SOP）；\n3、推动内容安全数据闭环建设，跨部门协同运营、算法、产品及全球团队，基于评测集指标识别漏洞，实现人工质量与Agent拦截效能的双向提升；\n4、负责内容质量管理体系的通用方法论沉淀，建立并完善日常质量把控机制；通过核心数据指标的追踪与归因，提升整体数据准确率与运营效率。","requirements":"1、2027届获得本科及以上学历；\n2、具备内容安全、质量保证（QA）、AI数据评测、策略运营相关工作经验者优先；具备优秀的逻辑推理与归纳提炼能力，能够穿透复杂、模糊的业务表象洞察底层问题，并独立输出结构化的解决方案；\n3、英语和阿拉伯语可作为核心工作语言（听、说、读、写精通），注重细节与标准的一致性，具备出色的跨文化沟通与书面表达能力；\n4、具备较强的自驱力与负责人意识，能够在快速变化与多地跨国协同的业务环境中适应动态变化，高效推进多线任务并达成业务目标；\n5、熟悉机器学习逻辑、数据标注框架者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669705892888365365","sourceKey":"bytedance","company":"字节跳动","title":"AI异构计算优化工程师 - Data AML","city":"杭州/上海/北京","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669705892888365365/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、负责评估符合业务要求的异构计算芯片，建立并完善评估体系与负载模型，预估业务收益；\n2、负责异构计算芯片在实际推理业务中的落地，适配芯片特性以降低推理时延、提高推理吞吐；\n3、负责异构计算芯片在实际训练业务中的落地，结合芯片计算与通信特性优化显存占用、提升训练吞吐；\n4、负责开发异构计算芯片的高性能算子，依据芯片特性优化算。","requirements":"1、2027届获得本科及以上学历；\n2、熟练掌握Linux环境下的C/C++、Python语言；能够熟练使用至少一种主流的机器学习框架（TensorFlow/PyTorch等），熟悉框架内部实现；\n3、具备扎实的计算机科学功底和编程能力，熟悉常见算法和数据结构，具有良好的编程习惯；熟悉至少一种经典深度学习模型及其应用场景，如GPT、SD、DiT、W&D等；\n4、有良好的工作文档习惯，及时按要求撰写更新工作流程及技术文档；了解推理/训练/通信相关优化，有高性能算子、大规模训练、通算融合领域经验者优先；\n5、了解SIMD/SIMT外其他并行计算模型及算法，了解其并行编程模型及其优、缺点者优先；了解模型剪枝、量化、LLM投机采样等优化方法原理，具备相关模型优化经验者优先；\n6、了解常见AI编译器方案及其优、缺点（如XLA、TVM、MLIR），有实际开发经验者优先；了解GPU硬件架构，了解GPU软件栈（CUDA、cuBLAS、CUTLASS），具备GPU性能分析的能力者优先；了解AI Compiler技术栈（MLIR等），熟悉PyTorch2.0+编译栈、Triton者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668636414620141877","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型Agent Harness算法工程师 - 火山方舟","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668636414620141877/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、参与火山方舟Managed-Agent相关的算法研发工作，参与方舟自有Harness的技术架构选型、设计、优化；\n2、优化方舟自有Harness，包括但不限于Harness的运行模式、Buildin-Tools、Context机制、Multi-Agent协作调度、智能的辅助能力（模型选择、Advisor、Grader、Rlaphloop等等）；\n3、和评测团队一起构建面向Harness迭代的Agent评测，构建全面、有效的Agent Harness端到端评测；\n4、定义和实现Harness领域的前沿创新，与模型团队深度合作，参与实现模型与Harness的共同进化，从Harness的角度实现Harness与模型的深度适配。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对Agent Harness有技术热情，对大模型和Agent有较深入的理解，有Agent Harness的优化经验；有使用AI Agent工具进行软件开发的经验；在软件开发领域具有良好的学习能力；能够在AI辅助下，进行有质量保证的编程工作；\n3、了解模型和Agent Harness的基本机制及其技术原理（如LLM API、Reasoning、KV Cache、ToolUse、Skills、ReAct、Multi-Agent、MCP、A2A、FunctionCalling）；\n4、了解和Agent评估方法、Agent构建、RAG检索技术等；\n5、了解流行的各类Agent应用的原理和实现细节，如：OpenClaw、HermesAgent、Codex、ClaudeCode、Managed-Agents。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668317078402828597","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发工程师 - 豆包","city":"杭州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668317078402828597/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、负责APP的全栈开发（Android/iOS/Harmony/服务端）；\n2、负责APP性能和品质体系建设；\n3、负责AI在移动端的应用场景研发；\n4、参与AI Coding体系搭建，系统性提效。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的数据结构和算法基础；精通至少一门编程语言，包括但不限于：Java、Kotlin、Objective-C、Swift、ArkTs、Rust、C++；\n3、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n4、对AI技术有浓厚兴趣，持续提升AI认知，有AI Coding/Agent实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667871586088732933","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法工程师 - 国际化商业安全","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667871586088732933/detail","duty":"团队介绍：国际化商业安全团队致力于在国际化用户、企业和产品之间建立安全可靠的连接。我们通过一系列完善的系统和能力，审核广告内容、预测政策违规行为，并执行广告审核通过或拒绝的措施。\n作为国际商业化团队的业务合作伙伴，我们提供的业务诚信解决方案不仅确保国际化业务始终是一个安全、积极、友好的用户环境，同时也推动业务增长。\n\n1、提升文本、音频、图像、视频和直播等多模态的细粒度理解能力，实现高准确率的自主决策和可解释性的CoT生成；\n2、探索多语言、长时序和少样本问题，增强Few-Shot和Zero-Shot能力，针对多变的业务规则具备复杂指令和Auto-Prompt生成能力；\n3、研究AIGC图像视频的判别，增强审核大模型对隐晦、抽象的生成式内容的攻防对抗能力；\n4、具备调用RAG模块，使用Tools，和Auto-Planning能力；提升大模型的动态推理和反思能力。","requirements":"1、2027届本科及以上学历，人工智能、计算机、数学相关专业者优先；\n2、具备扎实的编码能力、数据结构和基础算法功底，熟练运用各种算法框架与工程框架；\n3、在国际会议或期刊发表论文者（包括但不限于ACL、EMNLP、NeurIPS、ICML、ICLR、CVPR等）优先；\n4、拥有扎实的机器学习基础，在深度学习、强化学习、NLP、多模态方向有深入的理解与研究经历；\n5、具备良好的沟通协作能力，能够与团队共同探索新技术，推动技术发展。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667505098385901877","sourceKey":"bytedance","company":"字节跳动","title":"增长营销（活动方向）实习生 - TikTok生活服务","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667505098385901877/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间,让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok生活服务(TikTok GO) 是一站式商业解决方案，创造性地通过TikTok POI、短视频、直播和搜索等，连接全球用户与本地服务，提供有价值的真实世界生活体验，激发用户探索周围的世界。以“发现好去处，助力本地商家”为使命，致力于成为最值得信赖的发现好去处和连接本地商家的平台，让社区更轻松地与餐厅、酒店和景点互动，为商家提供全新方式来连接客户并促进交易，结合创新的营销和运营工具，带来可持续增长。团队分布多国，目前积极扩张中。大航海时代，我们欢迎大家一起加入国际化征程，共同打造TikTok生活服务业务!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、品牌活动策划与执行：深度参与线下品牌活动（如快闪店、官方峰会、行业展会等）的全流程策划与落地，涵盖前期筹备、创意构思、方案设计及现场执行，确保活动符合品牌与业务战略，保障落地质量与效果；\n2、国际化传播与内容营销：协助推进国际化品牌传播项目，对接国际化媒体与KOL/达人，参与高质量营销内容的创意策划、沟通对接及产出落地；\n3、项目管理与资源协调：高效推进跨部门合作与外部供应商管理，把控项目里程碑与进度，确保项目高质量交付；\n4、品牌资产与内容：协助开展品牌调研、产品分析、品牌策略梳理及品牌资产与规范等基础内容的输出。","requirements":"1、本科及以上学历在读，市场营销、传播、广告新媒体等相关专业优先；\n2、熟悉线下活动策划和流程；具有线上下创意、内容、传播等营销能力、项目把控和品控能力；有线下活动策划和执行/支持经验优先；\n3、熟悉各类品牌物料（如品牌视频、海报、Keynote/PPT等）的制作流程与品质标准，可附过往作品；\n4、对营销创新有敏锐感知力和判断力，有创意和较好审美；具备优秀的沟通协调能力，擅长跨部门多方协调；\n5、学习能力强、自驱力，具备灵活处理突发事件的应变能力；实习地点为北京，每周实习5天，6个月以上（中长期）优先；\n6、英语流利，具备优秀的听说读写能力，可支持国际工作场景。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7603658825686452485","sourceKey":"bytedance","company":"字节跳动","title":"大模型测试开发实习生-抖音研发","city":"上海","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7603658825686452485/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、深度参与大模型在质量保障方向的落地，解决当前大模型在落地过程中存在的各种问题；\n2、基于大语言模型（LLM）构建高效、可靠的Agent核心引擎，实现全流程智能化测试开发；\n3、通过对使用结果的数据深入分析，不断提升模型效果，提高使用体验；\n4、深入测试流程的需求和痛点，不断挖掘、改进模型及工具，提升质效；\n5、跟踪Agent领域前沿技术（如ReAct、AutoGPT、CrewAI等），推动技术落地与产品化。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、对大模型和算法方向有浓厚兴趣，熟悉至少一种AI应用开发框架（如LangChain等），熟悉Prompt工程、RAG、智能体（Agent）等理论；\n3、具备优秀的业务理解能力，出色的问题分解与解决能力，能将模糊需求转化成实际应用落地，逻辑思维灵活全面，良好的沟通协作能力；\n4、有扎实的计算机理论基础和代码编写能力，掌握至少一门编程语言，包括但不限于：Java/C/C++/Python/Go；\n5、能保证至少4个月及以上的实习，每周可出勤至少4天及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593324705793214773","sourceKey":"bytedance","company":"字节跳动","title":"算法实习生-抖音","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593324705793214773/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、针对全网超十亿级用户群体，落地精准广告投放触达方案，支撑业务高质量完成新用户获取与老用户增长目标； \n2、负责用户长期价值预估、因果推断等核心模型构建，结合个性化出价、实时流量优选等策略设计，为业务增长提供核心支撑；\n3、持续优化投放模型与策略，不断提升投放ROI等效率指标，持续提升业务广告投放效果。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力、扎实的数据结构和算法功底；\n3、扎实的机器学习理论和应用基础，熟悉任意一种常见的领域算法或者曾经参与相关工作，包括推荐、广告、搜索以及NLP、因果推断等；\n4、具有出色的解决问题能力、良好的理解沟通能力和优秀的团队合作意识，有激情、不畏难、乐于挑战；\n5、加分项：有营销投放相关经验，尤其是自动化投放相关经验者，有高质量论文、机器学习/ACM竞赛奖励者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7679028580386933045","sourceKey":"bytedance","company":"字节跳动","title":"用户产品实习生 - 抖音短剧","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7679028580386933045/detail","duty":"团队介绍：抖音短剧团队，负责抖音短剧的分发-消费-变现全链路环节，致力于为内容创作者拓展多元高效的商业模式，为用户提供更优质、更丰富的短剧内容，引领短剧行业的健康发展。加入抖音短剧团队，你将有机会加入行业领先平台，参与打造服务亿级用户的产品，共同推动短剧的创新与发展，创造更大的商业价值和社会价值。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与抖音短剧用户产品方向的需求分析、产品设计与策略迭代，覆盖短剧播放体验、内容发现、搜索承接、收藏追更等核心消费场景；\n2、基于用户流程、消费数据、用户反馈和产品观察，发现短剧消费链路中的体验问题与增长机会，提出可落地的产品方案；\n3、协同研发、算法、数据、设计、运营、商业化等团队，推动具体功能和策略落地，并跟进实验效果、数据复盘与后续迭代；\n4、参与短剧标签体系、剧目宣发、热点承接、互动剧/互动道具等创新方向探索，帮助提升用户找剧、看剧、追剧和复访效率；\n5、关注短剧行业趋势与用户需求变化，持续挖掘新的消费场景和产品模式，推动抖音短剧成为行业领先的短剧消费平台。","requirements":"1、本科及以上学历在读，计算机、统计学、数据科学、心理学、新闻传播、数字媒体、产品设计等相关专业优先；\n2、对短剧、视频、内容社区、线上娱乐产品有浓厚兴趣，短剧/网文/影视内容重度用户优先；\n3、具备较强的数据分析能力和逻辑思考能力，对数据敏感，能够通过数据发现问题、验证假设、评估效果；\n4、沟通协作能力强，能与研发、设计、数据、运营等多角色高效合作，推动需求落地；\n5、有视频、直播、内容社区、推荐、增长、C端产品实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674900094764452101","sourceKey":"bytedance","company":"字节跳动","title":"商业产品实习生 - 销售运营管理平台","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674900094764452101/detail","duty":"团队介绍：国际化销售运营管理平台团队成立于2022年1月，作为国际商业化产品与技术组织的一部分，整合了之前全球CRM（又名3M平台）团队的几个子支柱。我们的团队旨在赋能全球业务解决方案（GBS）团队，通过3M平台和生态系统中的工具和解决方案，通过高效的销售流程和可信的数据洞察，推动业务增长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与全球化商业产品建设：深入理解不同市场的用户需求和业务场景，参与任务系统需求分析、方案设计及体验优化，推动产品在全球市场落地；\n2、通过数据挖掘产品机会：分析用户行为、产品使用及业务结果数据，发现产品问题与优化机会，并通过数据衡量产品价值；\n3、探索AI产品应用：参与AI在客户洞察、内容生成、智能推荐、自动化工作流等场景的产品设计与落地；\n4、参与产品全流程推进：协助完成用户调研、需求分析、方案设计、测试及上线，与研发、数据、运营等团队协作推动项目落地。","requirements":"1、本科及以上学历在读；\n2、对产品、AI应用或数据分析有兴趣，具备良好的逻辑分析和沟通能力；\n3、具备英文沟通能力，能够适应国际化业务环境；\n4、每周可实习5天，可连续实习3个月及以上；\n5、有产品、AI、数据相关实习或项目经历优先，有个人AI/Vibe coding项目加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670080637871130885","sourceKey":"bytedance","company":"字节跳动","title":"Agent全栈开发实习生 - 数据平台","city":"上海/杭州","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670080637871130885/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与数据平台前端产品与Agent应用的全栈研发，覆盖Web前端、Node/BFF、服务端接口与Agent Skill，完成分配的模块开发与代码提交；\n2、参与Agent能力及相关服务的建设，涉及Prompt-Engineering、Workflow、Multi-Agent、Tool-Calling等技术方向，承担其中可独立完成的子任务；\n3、结合数据分析、数据可视化等业务场景，参与Agent解决方案的原型验证与功能落地；\n4、协助进行日常需求开发、Bug修复与代码优化，配合团队完成迭代节奏；\n5、关注大模型与Agent领域的前沿进展，参与内部技术分享与小范围技术预研。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、能保证每周到岗4天、连续实习3个月（可长期实习者优先），具备Web前端基础，熟悉HTML、CSS、JavaScript/TypeScript与HTTP协议，了解浏览器渲染与常见性能问题的基本概念；\n3、熟悉常用数据结构与设计模式，掌握Python、Java、Go、Node.js中至少一种服务端语言，能够在指导下完成从前端到接口的小型闭环开发；\n4、学习能力强、主动性好，具备良好的团队合作精神与沟通能力，能够按时保质完成导师安排的任务。\n\n加分项\n1、有大模型与Agent相关的动手经验，如基于大模型API、Agent框架、Prompt/评测等课程项目、开源项目或个人实践；\n2、有数据可视化相关项目实践经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670043468333746485","sourceKey":"bytedance","company":"字节跳动","title":"大模型Agent Infra工程师 - 模型数据工程","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670043468333746485/detail","duty":"团队介绍：数据工程与平台团队旨在实现人类知识与经验向模型能力的加速迁移。我们从真实场景出发，通过模型短板识别、高质量数据定义、规模化数据生产，提升模型能力。与此同时，团队还致力于依托训练反馈，反哺数据设计，推动系统迭代，构建业内一流的数据工程能力与平台。\n\n1、参与面向大模型数据场景的Agent Infra平台建设，涵盖但不限于Sandbox、Tool Use、Memory、知识库、轨迹管理等核心能力；\n2、面向数据合成、标注、评测等业务场景，设计并构建高效、稳定、可扩展的数据生产Workflow；\n3、参与平台基础能力建设，持续提升系统在海量并发场景下的稳定性、性能与资源利用效率，完善端到端可观测性体系；\n4、参与Agent Runtime、任务编排、状态管理、执行链路治理等方向的研发工作，支撑复杂任务的稳定运行与持续迭代；\n5、探索Agent在数据生产平台中的应用，推动系统向更智能、更自动化的方向演进。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构、算法、操作系统、计算机网络等基础知识；\n3、具备良好的编程能力和工程实现能力，熟悉至少一种常用编程语言，如Python、Go或C++；\n4、对后端开发、系统设计、平台研发或数据处理有一定理解，对复杂系统和工程问题有持续兴趣；\n5、对大模型、Agent Infra等方向有热情，具备较强的学习能力、问题分析与解决能力；\n6、具备良好的沟通协作能力和自驱力，能够持续学习和迭代。\n\n加分项：\n1、在课程项目、实验室、竞赛、开源或实习中，有服务端开发、虚拟化、容器化、任务调度、分布式系统等相关实践经历；\n2、对大模型、Agent、多模态、模型评测、工作流编排等方向有一定了解或实践经验；\n3、有搭建工具链、开发平台系统、参与复杂工程项目或优化系统性能与稳定性的经历；\n4、有开源贡献、技术竞赛、科研经历或较强的工程作品积累者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669622639389165829","sourceKey":"bytedance","company":"字节跳动","title":"用户产品经理（欧美商城） - TikTok Shop","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669622639389165829/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责商城首页与频道等核心用户场景的产品设计与体验优化，基于用户浏览、决策和购买路径，构建清晰高效的导购链路，提升用户对商城的认知、使用习惯与购买效率；\n2、围绕拉新、留存、转化等业务目标，设计流量分配策略、频道承接机制和营销增长玩法，通过数据洞察持续优化用户分层、触达路径和转化效率，驱动商城用户规模与交易增长；\n3、深入分析不同用户群体的需求、兴趣和消费认知，识别用户决策中的关键影响因素，牵引供给、运营等团队提供更适配用户需求的商品与内容供给，推动优质供给被更高效地发现和转化；\n4、结合AI能力探索更智能的用户理解、内容组织、商品推荐和营销触达方式，提升用户触达效率与决策影响力，推动商城产品形态和增长模式持续创新。","requirements":"1、2027届获得本科及以上学历，数据科学、计算机、AI等相关专业优先；\n2、对电商、内容消费、用户增长、AI产品或平台型业务有浓厚兴趣；具备较强的好奇心和业务敏感度；具备良好的用户同理心和结构化思考能力，能够从用户群体、消费场景、决策链路和业务目标出发，清晰拆解问题并形成产品判断；\n3、具备较好的数据意识、产品设计能力和学习能力，能够通过数据分析、用户反馈和行业观察发现机会，并推动方案验证和持续迭代；\n4、具备良好的沟通协作能力、责任心和自驱力，能够与供给、运营、研发、设计、数据等团队高效协同，英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667967027332811013","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发工程师 - Cross Platform","city":"深圳/上海/杭州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667967027332811013/detail","duty":"团队介绍：字节跳动Cross Platform致力于开发Lynx等业界前沿的应用框架，构建LLM驱动的前沿系统和基础设施，提升开发者和用户体验。\n\n1、参与跨平台技术方案在客户端（Android/iOS）的设计与研发；\n2、推进跨平台技术方案在字节跳动旗下各业务线落地，助力字节跳动的产品线高效发展；\n3、根据团队的整体目标和规划，进行相关的研发工作。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟练掌握C++，计算机相关知识基础扎实；\n3、具备移动客户端Android/iOS App开发经验者优先，具备鸿蒙相关项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667546153173141813","sourceKey":"bytedance","company":"字节跳动","title":"行业策略运营 - TikTok生活服务","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667546153173141813/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间,让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok生活服务(TikTok GO) 是一站式商业解决方案，创造性地通过TikTok POI、短视频、直播和搜索等，连接全球用户与本地服务，提供有价值的真实世界生活体验，激发用户探索周围的世界。以“发现好去处，助力本地商家”为使命，致力于成为最值得信赖的发现好去处和连接本地商家的平台，让社区更轻松地与餐厅、酒店和景点互动，为商家提供全新方式来连接客户并促进交易，结合创新的营销和运营工具，带来可持续增长。团队分布多国，目前积极扩张中。大航海时代，我们欢迎大家一起加入国际化征程，共同打造TikTok生活服务业务!\n\n1、深入参与印尼本地生活餐饮业务运营，围绕堂食券、餐饮电商等业务场景，协助推动业务增长与目标达成；\n2、结合用户需求、商家需求及市场情况，参与业务策略、商品策略和商家增长方案的制定与落地；\n3、关注本地生活及电商行业发展动态，开展市场与行业分析，挖掘业务机会并支持业务决策；\n4、协同数据、产品、运营等团队，跟踪核心经营指标，推动运营策略持续优化，提升业务效率和经营表现。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对本地生活、电商、互联网业务方向有浓厚兴趣；具备良好的沟通协作能力和推动力，能够与跨团队同学高效配合，推进项目落地；\n3、学习能力强，适应变化，具备较强的责任心和自驱力，愿意在复杂业务场景中持续探索；\n4、具备良好的英文沟通能力，熟悉印尼语者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667476145728080133","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - 抖音研发","city":"上海/杭州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667476145728080133/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、构建高效、可靠的AI Agent，精准理解产品的复杂需求，实现自规划、任务拆解及执行；\n2、设计高效的Multi-Agent系统，确保多Agent间任务流转高效，上下文管理准确；\n3、实现AI支撑企业级、大用户规模C端产品的需求端到端生成；\n4、负责研发基于LLM的AI Agent系统，负责构建工程研发不同阶段的Agent；\n5、参与探索Multi-Agent协作机制，推动Multi-Agent系统对复杂任务的规划和拆解，对已有人类经验的学习和引用，不断优化Agent解决实际问题的路径和效果。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的计算机、编程基础，熟悉主流大语言模型的原理及方法；\n3、理解Multi-Agent系统、任务分解、自动化规划、Prompt Engineering等技术领域之一或多个，有AI Agent相关实践项目者优先；\n4、出色的结构化表达能力，较强的技术敏感度与前瞻性，独立的思考和判断力；热爱AI相关技术，对应用和落地工程感兴趣，富有钻研创新精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667157698543864069","sourceKey":"bytedance","company":"字节跳动","title":"嵌入式开发工程师 - 移动OS","city":"上海/深圳/北京","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667157698543864069/detail","duty":"团队介绍：我们隶属于产品研发与工程架构部，是字节跳动在智能硬件领域的软件技术攻坚力量—— 聚焦 AI 与智能硬件的深度融合，如豆包手机助手等；以 “让人与设备的交互更自然、更便捷” 为目标，探索前沿 AI 技术的落地场景，打造行业领先的智能硬件综合解决方案。\n在这里，你将与一支顶尖技术团队并肩：\n- 直击 AI 与硬件结合的核心技术难题，参与从 “技术探索” 到 “场景落地” 的全链路研发；\n- 主导或深度参与关键技术突破，用创新定义智能硬件的交互未来；\n- 站在行业前沿，将技术理想转化为千万用户可感知的产品体验。\n如果你心怀对技术的热忱，渴望在 AI 与智能硬件的赛道上突破自我、创造价值，我们期待你的加入，与我们一起解锁更多技术可能，共筑智能交互的新生态！\n\n1、参与嵌入式软件项目的开发与维护；进行基于C/C++语言的嵌入式软件编码、调试和优化，确保软件在硬件平台上稳定运行，满足功能需求和性能指标，如开发设备驱动程序、通信协议栈等功能模块；\n2、进行硬件平台适配与优化；针对不同硬件架构和资源配置，适配和优化嵌入式软件，包括内存管理、资源调度、功耗优化等，提高软件运行效率和资源利用率，保障系统性能；\n3、协助解决技术难题；与团队成员紧密合作，分析和解决开发过程中的技术问题，如系统崩溃、性能瓶颈、兼容性问题等，排查问题根源并提出解决方案，确保项目顺利推进。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、自动化、通信工程等相关专业优先；\n2、熟练掌握C/C++语言编程，有良好编程规范和代码风格，能独立完成简单嵌入式软件模块设计与开发，熟悉常用数据结构和算法并能应用于实际项目，具备一定代码调试和优化能力；\n3、了解嵌入式系统开发流程和工具链，熟悉至少一种嵌入式硬件平台（如ARM、STM32、Raspberry Pi等），掌握基本硬件架构和接口原理，了解常用嵌入式开发工具（如Keil、IAR、GCC交叉编译工具链等）；\n4、具备良好的自驱力和学习能力，优秀的沟通表达能力，具有一定的产品和业务思维。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667055078772820229","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师（资金业务） - TikTok Shop","city":"北京/杭州/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667055078772820229/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、负责TikTok Shop资金场域相关业务场景下AI Agent的设计、开发与迭代，覆盖从需求分析到架构设计、开发上线的全周期工作，为商家和用户提供智能、高效的产品体验；\n2、将Agent能力深度落地至电商核心场景，包括但不限于智能客服、商品运营辅助、经营决策支持、内容生成与业务流程自动化等，助力商家、达人更好地触达消费者、提升经营效率；\n3、负责Agent技术栈的持续建设与优化，涵盖Context工程、Harness、RAG检索增强、Multi-Agent协同、Memory系统、强化学习、流程编排及知识库构建等方向；\n4、深入理解电商垂直领域的业务逻辑与商家诉求，使Agent能够精准理解并执行专业性强的复杂业务需求，真正解决商家经营中的实际问题；\n5、持续关注AI与大模型领域前沿技术动态，快速将新技术应用于产品迭代。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、具有优秀的代码能力，熟练掌握编程语言；\n3、熟悉Agent架构核心组件的设计原理与调优方案，了解主流开源Agent框架（如LangGraph/Pi等），具备Prompt调优、Harness、RAG、上下文工程、Skill编写等实践经验；\n4、学习能力强，对新技术保有好奇心，善于独立思考与反思总结，具备将复杂问题转化为简洁高效方案的能力；\n5、良好的沟通与跨团队协作能力，热爱技术，拥抱开源，能适应快速变化的业务环境。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666106415873886517","sourceKey":"bytedance","company":"字节跳动","title":"算法工程研发工程师 - 抖音体验","city":"北京/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666106415873886517/detail","duty":"团队介绍：抖音用户体验团队成立于2018年，致力于发展业界独特技术栈，通过技术手段提升抖音及抖音系APP的用户体验，为业务发展提供技术支撑。我们在AI与各类基础技术领域的融合上具备远见与决心，曾开创个性化视频体验、个性化应用体验等多个业界全新的技术子领域和相关技术，在抖音等产品建立市场地位的过程中得到充分验证，并持续关注和探索前沿技术方向。团队交叉融合推荐类系统、因果推断、运筹求解、端智能、大模型训练、音视频、网络、编译器等多种不同的技术领域，并能够最直接、快速地推动新技术落地，带来显著业务价值。\n\n1、负责抖音算法工程工作，搭建超出业界水平的AutoML类平台，支持包含LRM、LLM、Uplift、端智能、运筹求解等核心算法及相应工作流、数据流在内的大规模搜索，并提供相应在线高并发服务；\n2、基于平台多样化需求，开发AI Research、专用Agent框架与完整方案，实现大规模、超长程生产级任务的设计、提交、追踪与运维，构建应用评估并持续优化研究效果与效率；\n3、探索AI Research/专用Agent框架的上限，释放模型能力并逐步达成可自演进的系统。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业；\n2、熟悉Agent相关技术，能针对特定模型能力问题进行SFT、RL训练；精通Python/Golong/C++等编程语言中的一种，具备系统设计能力和优秀的编码能力，具备在Linux开发环境下的开发能力，熟悉至少一种主流大模型应用框架（如LangGraph、LlamaIndex、OpenAI AgentsSDK、GoogleADK等）；\n3、对大模型和Agent有个人理解，熟悉常见的LLM实施模式、提示工程、评估框架、检索框架等，了解Agent Architectures/Structures（Multi-Agent、Context Engineering/Management、ReAct/PlanAct/CodeAct），了解Agent相关的交互协议（MCP、A2A、Function Call）；\n4、对AI Research有相关经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665585620055689525","sourceKey":"bytedance","company":"字节跳动","title":"增长策略产品 - 国际支付","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665585620055689525/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、参与到国际支付和金融业务的增长工作中，协同多部门探索用户量、GMV增长的方法；\n2、日常洞察产品所属行业特性、产品状态和业务长短期目标变化，制定合理的增长方案，协调资源、解决核心问题，联动策略、产品研发等团队推进落地；\n3、对行业增长手段保持敏感，对营销补贴、流量转化、产品工具优化等流量获取手段有一定认知，可以参与A/B测试实验设计与效果追踪，提出优化建议；\n4、与内部增长平台合作，利用并拓展增长中台的能力，基于业务特性制定定制化的获客策略。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、有互联网增长产品相关实习经历优先，结果导向，具有好奇心和创造力，能持续挖掘新的增长机会点；\n3、主动性强，有良好的沟通与团队协作能力；\n4、良好的英语口语和书面沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665188768413042997","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent策略工程师 - 豆包爱学","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665188768413042997/detail","duty":"团队介绍：豆包爱学是豆包旗下的教育产品，提供拍照答疑、作业批改、知识问答等功能。我们致力于使用领先行业的人工智能技术，提升学生的学习体验。加入智能学习团队，你将有机会为全国学生提供优质服务，并与顶尖专家合作，站在科技前沿，推动 AI 与教育科技的发展。\n\n1、负责的Agent技术研发和架构设计，探索更先进的Agent范式，引领行业技术发展；\n2、参与制定评测标准，构建Agent评估体系，通过Context Engineering等优化方式进行策略效果调优；\n3、探索和制定AI应用的模型交互协议，打造内容丰富、互动性强的产品体验；\n4、参与AI产品创新，与产品团队讨论创新想法，孵化项目，制定技术路线决策，解决项目中的技术难题。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、熟悉LLM技术原理与应用方法，理解Agent相关技术方法（如harness、多智能体、RAG、Memory）；\n3、有良好的产品思维，能够主动思考并探索产品创新；\n4、对AI技术和应用有浓厚兴趣，能持续追踪业内最新技术进展。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664983863487629573","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 中国交易与广告","city":"北京/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664983863487629573/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案、核心代码开发、系统调优及机器学习与异构计算系统研发；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7600799265123862837","sourceKey":"bytedance","company":"字节跳动","title":"大模型自动评测算法实习生-剪映数据与智能团队","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7600799265123862837/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：剪映数据与智能团队旨在通过 AI 技术赋能剪映系产品，构建强大的算法能力壁垒。作为剪映系内的算法团队，负责推动整个业务在算法上的迭代与创新，为剪映、CapCut、即梦dreamina、Pippit、醒图等产品提供智能化支持。\n\n1、参与视频/图像自动化评测算法的研发，包括不限于大模型提示词工程、SFT、RL和深度学习模型的设计、训练、调优与部署，持续提升评测算法的准确性、泛化能力和运行效率；\n2、负责调研业界和学界在图像/视频质量评估、AIGC内容鉴别与评估、美学评估等领域的最新评测体系与评估技术，推动业务落地验证及评测体系的不断演进；\n3、协助构建高质量的多维度评测数据集，涵盖数据采集、清洗、标注策略制定与执行等流程；基于业务场景对评估结果进行拟合分析，并探索自动化的质量维度挖掘与归因建模方法，为模型优化提供闭环支撑。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、技术能力：\n1）具备出色的编程能力，精通Python/C++，熟悉TensorFlow/PyTorch等框架，有自然语言处理（NLP）、计算机视觉（CV）或多模态生成模型（如CLIP、Diffusion Models）项目经验；\n2）熟悉大模型理论知识和应用，熟悉常见大模型架构，理解实际业务场景Agent设计理念；有实际大模型预训练、微调或推理优化经验者优先；\n3、学术与实践经验：\n1）在ACL/CVPR/SIGIR/KDD/NeurIPS/ICCV等顶会发表过AIGC、推荐系统、计算广告相关论文者优先；\n2）有图像/视频质量评估、美学打分、AIGC相关项目或研究经验者优先；\n3）热爱视频剪辑，对常用视频剪辑工具有使用经验者优先；\n4、每周出勤至少4天，可实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593190913494550837","sourceKey":"bytedance","company":"字节跳动","title":"算法数据实习生-安全与风控","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593190913494550837/detail","duty":"Bytelntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：我们团队为字节跳动的大型语言模型（LLM）业务线提供端到端安全解决方案。我们针对模型训练、推理及部署全流程识别并防控新型风险，同时研发工具与系统，保障LLM资产及相关应用的安全。通过在实际业务场景中推进人工智能安全技术落地，构建了行业领先的防御体系，为人工智能技术的安全演进提供保障。\n\n1、构建行业领先的安全评测基准，针对Pentest（渗透测试）、Secure Coding（安全编码/漏洞挖掘）、SOC（安全运营） 等重点场景，设计并构建全面、深入且具有挑战性的Agent评测基准与数据集；\n2、全维度能力对标与分析（核心任务），持续追踪并深度对标业内头部模型与安全Agent产品，通过定量评估与定性分析，识别Agent在复杂安全决策、逻辑推理及任务拆解中的能力差距，输出深度评估报告，驱动底层模型能力与Agent 架构策略（如Planning/Reasoning）的双向优化；\n3、建设统一评测出口与Leaderboard，打造“基座模型能力+Agent系统效果”统一的评估结果出口，建立多维度的安全能力打分体系与内部排行榜，确保评估结果能客观反映端到端的业务；\n4、模型与Agent机理性研究，探索Agent在安全任务中的一致性与性能上限，从可解释性角度制定评估标准，分析大模型及其Agent策略在安全决策与修复过程中的透明度与可靠性；\n5、评测效能提速与平台优化，持续优化评测平台的运行效率与自动化程度，提升评估基准在业务快速迭代中的响应速度。","requirements":"1、2027届本科及以上学历在读，计算机、信息安全、人工智能等相关专业优先。\n2、扎实的代码与算法功底，精通Python等主流编程语言；有ACM/ICPC、CTF（侧重自动化/AI赛道）、Kaggle等高水平竞赛获奖经历者优先；\n3、理解大模型相关技术原理（如SFT、强化学习、COT 推理等），对Agentic Workflow（如ReAct，Reflexion，SOP等）有研究兴趣，对安全领域相关模型有了解者优先；\n4、具备敏锐的数据洞察力，能够从复杂的评测结果中拆解出底层的技术缺陷（无论是模型知识短板还是Agent策略缺陷），并自主探索创新性的评估方案；\n5、在AI安全领域顶级会议发表过论文，或深度参与过开源模型评估项目、安全工具开发者优先；\n6、具备良好的沟通能力，能够与研发团队高效配合，共同推动AI安全技术的演进。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669721161882667317","sourceKey":"bytedance","company":"字节跳动","title":"游戏技术美术工程师 - Glow Studio","city":"广州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669721161882667317/detail","duty":"团队介绍：Glow Studio 微光工作室，寓意是照亮梦想、创造快乐。目前的产品是PVP和ARPG品类，后续倾向于在轻竞技和动作竞技上继续尝试。我们的产品理念是：聚焦、积累和创新。未来期望能创造激情游戏，连接数亿玩家，欢迎加入我们。\n\n1、负责游戏引擎开发和管线建设；\n2、负责渲染效果开发和性能优化；\n3、负责产品需求开发和工具建设。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、熟练掌握C/C++/Python等至少一门语言；\n3、具备出色的编码能力，扎实的数学和图形学功底；\n4、学习能力强，能够独立分析和解决复杂问题；\n5、积极主动，高效沟通，具备团队精神。\n\n加分项\n1、热爱游戏，有实习经验，参加过Game Jam；\n2、在ACM/ICPC等编程比赛中斩获过奖项；\n3、熟悉Unity或Unreal引擎，自己动手制作过游戏；\n4、有学术研究经验，发表过图形学会议或期刊论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667887767667624197","sourceKey":"bytedance","company":"字节跳动","title":"大模型产品经理 - 火山引擎","city":"北京/上海/深圳/杭州","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667887767667624197/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责完成创新产品的规划和设计，挖掘新的大模型落地行业机会；\n2、深入了解大模型智能体、多Agent、RAG、意图识别、低代码和零代码等技术，推动技术在产品中的应用；\n3、与跨部门团队紧密合作，协调资源，确保产品的顺利推进和交付；\n4、分析市场动态和市场，提供有针对性的产品策略和建议。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、了解大模型相关技术和应用；\n3、对产品有浓厚兴趣；具备优秀的产品思维、合理的创新思考；具备优秀的沟通能力和自驱力，能够激励项目成员共同达成目标。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667474829412944133","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 抖音研发","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667474829412944133/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、负责架构设计和开发，参与系统技术方案设计、代码开发及系统调优，为亿级用户提供优质顺畅的信息服务和极致体验；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研、新技术引入及机器学习与异构计算系统研发等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667420480446826805","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - 移动OS","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667420480446826805/detail","duty":"团队介绍：我们隶属于产品研发与工程架构部，是字节跳动在智能硬件领域的软件技术攻坚力量—— 聚焦 AI 与智能硬件的深度融合，如豆包手机助手等；以 “让人与设备的交互更自然、更便捷” 为目标，探索前沿 AI 技术的落地场景，打造行业领先的智能硬件综合解决方案。\n在这里，你将与一支顶尖技术团队并肩：\n- 直击 AI 与硬件结合的核心技术难题，参与从 “技术探索” 到 “场景落地” 的全链路研发；\n- 主导或深度参与关键技术突破，用创新定义智能硬件的交互未来；\n- 站在行业前沿，将技术理想转化为千万用户可感知的产品体验。\n如果你心怀对技术的热忱，渴望在 AI 与智能硬件的赛道上突破自我、创造价值，我们期待你的加入，与我们一起解锁更多技术可能，共筑智能交互的新生态！\n\n1、负责移动OS测试领域AI提效的核心Agent及功能链路开发，深入理解测试领域提效重点并设计解决方案，设计和开发AI应用和解决方案原型，驱动AI提效；\n2、负责Agent的开发，参与框架搭建，Prompt调优，工具开发，上下文管理等环节，技术驱动不断优化Agent落地效果，并降低数据中心成本；\n3、负责跟踪AI技术趋势，关注语言模型、多模态模型最新动态，基于对模型的判断，思考人机交互等新范式在测试领域的落地场景，驱动AI提效。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟悉Linux，掌握常用数据结构、算法、设计模式，至少熟练掌握Golang/Java/PHP/Python/C++一门编程语言；\n3、对大模型和Agent有较深入的理解，了解Agent Architectures/Structures（Multi-Agent，Context Engineering/Management，ReAct/PlanAct/CodeAct），了解Agent相关的交互协议（MCP，A2A，Function Call），熟悉常见的LLM实施模式、提示工程、评估框架、代理框架和检索框架等；\n4、了解模型的Post-training训练技术，具备针对特定模型能力问题进行SFT、RL训练优化优先；\n5、具备产品思维，能够以用户为出发点，结合业务有效落地并实现收益，能参与需求设计并提出技术可行性建议，与产品、设计团队高效协作；\n6、对Agent技术有实践经验，并能清晰阐述如何通过Agent解决实际业务问题；熟悉AI应用开发流程、有端到端跨技术栈开发能力或AIGC功能落地经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7626218867478284549","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发实习生-抖音平台产品","city":"深圳","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7626218867478284549/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：平台产品基础部门致力于为抖音各业务提供全面支持，平台业务负责搭建与维护基础平台，保障账号核心资产的管理。开放业务合理开放产品能力与数据，连接外部优质资源。文娱业务聚焦短剧&营收和宣发，形成健康内容生态。生态与运营业务推进作者成长、变现等工作。治理与体验业务为各垂直方向提供诊断等工具，提升问题解决率。营销搭建业务助力业务营销推广。部门为实现业务目标、满足用户需求而不断努力。\n\n1、负责前端和服务端的业务开发工作，覆盖业务全链路，按业务需求统筹各端开发优先级，打破端侧壁垒，实现业务功能高效落地；\n2、深度运用AI Coding工具，开发并维护基于MCP、CLI、Skills等的各类工具，参与AI研发基础设施与Agent工作流建设，对接公司内部系统与模型，打造一体化AI研发体验；\n3、立足全栈发展趋势，推动并沉淀Vibe Coding、Spec Coding等新型AI研发范式在团队内的落地与最佳实践，参与业务全流程开发，推动业务从需求到上线的闭环落地；\n4、负责前沿技术探索与范式推广，持续跟进AI/LLM（包含底层大模型）的最新进展，提供创新的交互解决方案，并推动技术的迭代和升级；\n5、配合团队完成技术方案讨论、架构优化、代码评审等工作，助力团队形成\"按业务分工、AI+全栈协同\"的开发模式，适配未来1~2年全栈发展导向。","requirements":"1、2027届本科及以上学历在读，计算机、通信和电子信息科学、数学等相关专业；\n2、具备良好的计算机基础（数据结构、算法、计算机网络、操作系统等），并熟练使用至少一门编程语言；\n3、熟练使用HTML5/CSS3/JavaScript/TypeScript/Vue/React等前端技术完成页面布局和交互开发，有全栈（Golang）开发经验者优先；\n4、熟练使用TRAE、Claude Code、Codex、Cursor等任一AI Coding工具，维护过Rules、MCP、Skills并了解底层机制与技术细节的同学优先；\n5、认可AI Coder定位，明确自身长期全栈发展规划，具备较强的学习能力和适应能力，能快速上手新领域技术，适配业务驱动的开发模式；\n6、积极乐观，责任心强，具备良好的沟通协作能力、逻辑思维能力以及服务意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594734264314284293","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生（测试工具服务）-TikTok内容安全平台","city":"上海","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594734264314284293/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：国际化内容安全平台团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，以人工智能技术支持业务发展，力求更高效、更敏捷、更全能地维护站内生态安全。\n\n1、深入理解业务线测试需求，参与构建以自动化与智能化为核心的下一代测试服务体系；\n2、针对测试痛点，研发高效测试工具与平台，覆盖白盒测试、功能测试、Diff测试、性能测试、压力测试等关键场景；\n3、搭建与优化CI/CD工具链，打造高可用、可扩展的自动化测试能力，推动在业务线落地并持续提升测试质量与效率；\n4、探索AI在测试领域的应用，包括但不限于：智能用例生成、自动化缺陷检测、测试结果分析与预测、自适应测试策略优化等；\n5、跟踪并引入业界先进测试技术与方法论，持续推动测试体系的技术创新与演进。","requirements":"1、2027届本科及以上学历在读，计算机科学、软件工程等相关专业优先； \n2、熟练掌握C++/Go/Java/Python/Shell中至少一门编程语言，具备良好的编码习惯；\n3、对软件测试有浓厚兴趣，有自动化测试、测试工具开发或AI相关项目经验者优先；\n4、具备良好的逻辑思维、沟通协作能力和学习主动性；\n5、能保证连续实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683787847454820661","sourceKey":"bytedance","company":"字节跳动","title":"数据科学实习生 - TikTok Shop","city":"上海/北京","category":"数据分析","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683787847454820661/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、探索大语言模型（LLM）与智能体（AI Agents）在数据分析、归因、业务诊断及其他分析工作流中的应用；\n2、参与智能体工作流建设并运用相关能力，具体包括：上下文与会话管理、工具调用与可复用技能、多步任务执行、子代理协作、任务状态与结果管理；\n3、将现有分析方法、SQL查询、Python脚本及业务知识转化为可复用的智能体能力；\n4、为智能体（Agents）搭建评估框架，涵盖评估集、指标、误差分析及结果归因等内容；\n5、分析智能体的执行轨迹与日志，以排查与准确性、可靠性及效率相关的问题；\n6、对不同模型、提示词、上下文策略及智能体工作流进行实验，并结合数据对其效果进行评估，同时研究大语言模型（LLM）/智能体（Agent）产品及开源项目，将相关设计模式应用于实际业务场景。","requirements":"1、本科及以上学历在读，数据科学、计算机科学、统计学、数学、人工智能或相关专业；\n2、精通Vibe coding与设计；具备扎实的分析能力，能够识别问题、提出假设并通过数据进行验证，对大语言模型（LLM）与智能体（AI Agents）有浓厚兴趣，对提示工程、上下文、工具调用等相关概念具备基础认知；\n3、学习能力强，愿意研读技术文档、研究开源代码。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677434632173832453","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生 - 番茄小说/红果短剧/番茄畅听","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677434632173832453/detail","duty":"团队介绍：番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责字节跳动红果短剧、番茄小说、番茄畅听等多业务方向的服务端开发工作；\n2、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n3、参与设计系统技术方案、核心代码开发和系统调优，制定代码规范、测试规范，建立开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研、新技术引入等前瞻项目，以及机器学习与异构计算系统研发。","requirements":"1、本科及以上学历在读，计算机相关专业；\n2、实习5个月，一周至少到岗4天及以上；\n3、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n4、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n5、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n6、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675314464131959045","sourceKey":"bytedance","company":"字节跳动","title":"Agent Harness工程师 - 国际化广告质量效能","city":"北京/上海/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675314464131959045/detail","duty":"团队介绍：国际化广告质量与效能技术团队致力于构建覆盖广告生态全链路的质量保障体系，并通过技术驱动效能提升，业务范围涵盖广告管理平台、投放系统、审核系统、转化归因及相关基础设施等。\n\n1、负责国际化广告业务的应急响应、稳定性保障等场景的Agent开发，建设对话机器人中的信息检索、内容创作、记忆管理、任务执行等核心能力；\n2、深度参与Agent在质量保障场景中的AI应用落地，负责上下文工程、工具调用设计、知识检索、任务拆解、多轮交互等方案设计与实现；\n3、解决Agent工程化过程中的关键技术挑战，包括超长任务可靠性、执行链路稳定性、系统成本控制、异常恢复与结果可验证等问题；\n4、持续优化模型迭代依赖的训练基础设施、人效工具和评测闭环，推动Agent从Demo走向可在线上稳定运行的生产级系统；\n5、与研发、产品、算法、SRE、数据等团队协作，将一线工程师的排障经验、质量策略和业务知识沉淀为可复用的智能系统能力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、数学等相关专业优先；\n2、计算机基础扎实，熟悉数据结构、算法、操作系统、计算机网络、数据库等基础知识；\n3、熟练掌握Go/Python/Java/TypeScript/C++等至少一门编程语言，具备良好的代码实现能力和工程习惯；\n4、对大语言模型、AI Agent、RAG、Prompt Engineering、工具调用、模型评测等方向有兴趣或实践经验；\n5、有好奇心、自驱力和负责人意识，愿意面对线上真实复杂问题，并持续追问本质。\n\n加分项\n1、有AI Agent、LLM应用、RAG、智能问答、自动化工作流等项目经验；\n2、有稳定性、AIOps、智能排障、日志分析、监控告警、故障归因相关实践经验；\n3、有工程项目、开源项目、竞赛获奖或高质量实习经历；\n4、能熟练使用AI工具辅助编码、排障、文档理解和方案设计，并能对AI输出进行判断、校验和优化。\n\n加入我们，你会获得\n1、真实全球商业化场景：直接参与商业化核心链路的质量、稳定性和效能建设；\n2、前沿AI工程实践：不是停留在Prompt层，而是深入Agent架构、工具系统、评测体系和生产级落地；\n3、高成长技术环境：资深工程师1v1带教，有机会快速负责真实系统模块；\n4、足够大的技术舞台：在质量保障、稳定性、研发效能和AI Agent交叉地带，做有业务价值也有技术深度的事情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670755680085379381","sourceKey":"bytedance","company":"字节跳动","title":"行业运营 - 抖音生活服务","city":"上海","category":"商业运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670755680085379381/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、交易规模负责（核心目标）：负责本地生活服务商的培育与深度赋能，对所辖服务商大盘的整体交易规模（GMV）、核销增长等核心商业指标负责；\n2、服务商体系化培育：搭建并完善服务商分层体系，制定从入驻破冰、能力升级到标杆打造的标准化SOP；针对不同层级的服务商，输出定制化的赋能方案（如组货选品策略、流量获取、达人撮合等），提升其综合运营能力；\n3、类目拓展与供给丰富：深度洞察市场需求，引导并协助服务商拓宽业务边界，丰富经营类目与供给矩阵；推动多品类交叉营销与组合包装，有效提升服务商的客单价与综合变现效率；\n4、经营诊断与大促策划：定期对服务商进行数据复盘与转化漏斗诊断，精确定位经营卡点并输出破局方案；联动平台营销节奏，策划并推动服务商落地各类大促、节点战役及专项活动；\n5、生态共建与跨界协同：收集并提炼服务商在工具、规则、流程上的痛点，跨部门联动销售、产品研发、营销等团队，推动内部产品与规则迭代，持续优化服务商营商环境。","requirements":"1、2027届获得本科及以上学历；\n2、有本地生活、O2O或内容电商平台相关运营/服务商生态管理的实习经验；\n3、懂平台逻辑与玩法：熟悉主流本地生活/内容电商平台的业务运作逻辑，了解商家的经营痛点、团购/套餐组货逻辑、短视频及直播带货玩法；\n4、数据敏锐度：具备优秀的数据分析与洞察能力，能够熟练通过数据（如核销率、ROI、流量漏斗等）抽丝剥茧发现问题，并推导可执行的落地方案；\n5、B端服务与商业谈判能力：沟通能力与同理心，能与服务商老板/操盘手同频对话，算得清“经营账”和“投入产出比”；\n6、软性素质：强烈的目标导向和拿结果的能力，自驱力，能够高效拿到业务结果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668271920346286341","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师 - Seed 产品研发","city":"杭州/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668271920346286341/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书项目核心模块的前后端全链路研发，端到端负责功能设计、开发、测试与上线；\n2、不断探索各种新技术，参与系统架构演进、性能与稳定性优化，保障平台在大规模企业客户下的高可用；\n3、以AI为默认工作方式，深度实践AI Coding，持续沉淀团队研发提效方法与工具。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、数据结构、算法、操作系统、网络、数据库基础扎实，熟练掌握至少一门主流编程语言（Go/TypeScript/Java/Python等），代码逻辑清晰、结构良好；\n3、至少熟练使用一种AI编码工具Cursor/Claude Code/Copilot/TRAE/Codex等；了解大模型、Agent、RAG、MCP、CLI、Prompt、Harness等核心概念并有自己的理解；能识别AI输出的正确性、风险与边界，并设计验证机制；\n4、具备良好的逻辑思考与问题拆解能力，好奇心与学习动手能力强，主动自驱，面对复杂问题有攻坚钻研的韧性，沟通协作顺畅。\n\n加分项\n1、独立AI相关作品项目经验；\n2、优秀的开源贡献或个人项目；\n3、ACM/NOI/CTF等竞赛获奖；\n4、有To B/SaaS类产品实习或复杂业务开发经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667050433923287301","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师（质量方向） - TikTok Shop","city":"上海/杭州/北京/深圳/珠海","category":"研发","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667050433923287301/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、推进AI产品在TikTok Shop质量领域落地，持续优化工具准确率、召回率与使用体验；\n2、建设AI Testing产品，覆盖风险识别、测试用例生成、自动化测试、效果评测、知识库建设等关键领域，并与AI coding结合打造AI-Native研发模式，提升端到端的交付效率和收敛风险；\n3、跟踪并沉淀行业前沿技术，在实际业务场景落地。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、热爱计算机科学，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665585566877436213","sourceKey":"bytedance","company":"字节跳动","title":"用户账户产品经理 - 国际支付","city":"上海/深圳","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665585566877436213/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、参与国际支付用户账户服务建设，在全球范围内为支付金融业务构建行业领先的服务开通、身份验证、账户安全保障、账户管理等环节的用户服务，保障用户权益，助力业务稳健发展；\n2、跟进钱包、发卡、金融等产品的发展动态，通过客户投诉、数据、行业对标等手段识别用户需求，完善用户账户生命周期各环节的功能建设；\n3、与上下游跨团队协作，完成用户账户产品功能的需求撰写、体验设计、系统设计和方案落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、电子、大数据等专业优先；\n2、能够熟练使用英语进行口头和书面沟通，具备互联网支付金融行业实习经验者优先；\n3、关注用户体验，对用户需求具备敏锐洞察；\n4、具备较强的逻辑能力和抽象思维，对数据敏感，具备从多个视角考虑问题的习惯；\n5、主动性强，具备良好的沟通协作能力、责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7509822276331227410","sourceKey":"bytedance","company":"字节跳动","title":"AI for Science实习生-Seed","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7509822276331227410/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动Seed团队成立于2023年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。Seed团队在AI领域拥有长期愿景与决心，团队研究方向涵盖MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE等超过50个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包App用户量在中国市场排名第一，豆包大模型日均Token调用量行业领先。\n\n1、跟踪业界前沿研究进展，与团队共同建立深入广泛的领域技术认知；\n2、综合机器学习、量子化学、分子动力学等多个领域的方法，探索生物、材料领域前沿应用；\n3、整合业界及团队研究成果，推动研究成果实际落地应用，产生广泛的影响力。","requirements":"1、博士学位在读，计算机、数学、物理、计算材料、量子化学等相关专业优先；\n2、深入了解机器学习算法，有丰富的实操经验和开发能力；\n3、在高影响力的同行评审科学期刊上有良好的发表记录；\n4、具有独立研究能力，能够在跨学科的环境中成长；\n5、具备优秀的团队合作和人际交往能力，能够有效地传达复杂的想法。\n\n有以下项目经验优先考虑：\n1、基于神经网络的电子结构模型与原子力场训练；\n2、Co-Folding模型、分子生成模型、逆合成设计模型；\n3、LLM/Agent Co-Scientist；\n4、大规模数据集建设。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7379088513234798875","sourceKey":"bytedance","company":"字节跳动","title":"PMO项目管理实习生-抖音研发","city":"北京","category":"项目管理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7379088513234798875/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、协助抖音产品研发团队跟进项目，协助完成相关项目的流程设计、执行落地、总结改进；\n2、针对团队协作中发现的问题归纳总结，协助改进；\n3、负责团队日常通用任务管理，有效跟进、推动，确保交付；\n4、推动团队知识库的沉淀、归档。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程相关专业优先；\n2、具备较强的沟通能力与良好的协作能力；\n3、具备较高的责任心，以及目标导向的落地执行能力、问题解决能力；\n4、乐于迎接变化与挑战，具备持续学习能力与自律意识；\n5、每周可实习4天，可实习4个月及以上；\n6、加分项：英语流利，有技术背景，热爱项目管理。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7275280306058316090","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生 - 中国交易与广告","city":"上海/北京/成都/杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7275280306058316090/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与生活服务平台治理相关的后台研发工作，包括各个系统的设计实现和开发工作，支撑业务快速迭代，保证服务质量；\n2、参与业务系统线上维护，解决线上问题；\n3、持续迭代和优化系统，提升性能、可用性以及扩展性；\n4、与产品形成协同，将技术应用到业务场景。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、理解计算机原理，有扎实的数据结构和算法基础；\n3、理解Linux系统及其原理，熟悉TCP/IP、HTTP协议以及网络编程；理解面向对象开发，具备一定的系统分析设计能力；\n4、热爱写代码，对技术有热情，认真负责，乐于协作；\n5、Linux平台上的Java/Go/C/C++/Python等至少一门语言；\n6、每周可以实习4天及以上，连续实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671205168105769269","sourceKey":"bytedance","company":"字节跳动","title":"大模型数据挖掘实习生 - 模型数据工程","city":"北京","category":"数据挖掘","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671205168105769269/detail","duty":"团队介绍：数据工程与平台团队旨在实现人类知识与经验向模型能力的加速迁移。我们从真实场景出发，通过模型短板识别、高质量数据定义、规模化数据生产，提升模型能力。与此同时，团队还致力于依托训练反馈，反哺数据设计，推动系统迭代，构建业内一流的数据工程能力与平台。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、围绕大模型在通用能力、专业领域能力、推理能力、多模态能力、工具使用能力等维度的表现，系统性地挖掘模型短板与能力盲区，通过构建自动化评测集、错误案例归因分析、负面案例聚类挖掘、对抗样本构造等手段，精准定位模型在哪些场景、哪些任务类型、哪些知识领域存在能力缺口，并将这些发现转化为可执行的高价值数据需求定义——明确需要什么样的数据、数据的质与量标准、标注规范和验收标准，形成“发现短板→定义数据→产出提升”的闭环；综合运用数据挖掘、统计分析、机器学习、深度学习以及大模型自身能力（如LLM-as-Judge、合成数据生成、数据增强等），从海量数据中挖掘高价值信息与知识，具体方向包括但不限于：高质量语料挖掘与筛选（基于Perplexity、教育价值评分、信息密度等维度）、推理链数据构造（CoT/ToT/ReAct等）、代码与数学数据挖掘、多轮对话数据挖掘、领域专业知识抽取、难例与对抗样本挖掘、偏好数据自动构建等，通过创新的数据挖掘方法，持续发现并生产能有效提升模型能力的稀缺数据资源；\n2、负责大模型训练数据（包括预训练语料、SFT指令数据、偏好对齐数据RLHF/DPO、安全评测数据等）的全生命周期管理，涵盖数据采集、清洗、去重、质量过滤、脱敏、存储、版本管理与分发，构建稳定、高效、可扩展的数据处理流水线（Data Pipeline），支撑TB/PB级多模态数据的处理与流转；设计数据质量自动化校验机制与数据血缘追踪体系，确保训练数据的可追溯性、可复现性与合规性；持续优化数据存储架构与处理效率，降低数据流转成本；设计从数据发现、采集、清洗、标注到入库、训练、效果验证的全流程数据生产策略，定义各节点的数据交互规范、质量门禁、异常处理机制与验收标准，针对不同类型数据（网页文本、代码、数学推理、多轮对话、专业领域知识、红队对抗样本等）设计差异化的生产SOP；与标注团队、算法团队协作，制定标注指南与质量控制方案（如多人标注一致性校验、主动学习标注策略、难例挖掘策略）；对完整数据生产链路的效率、质量与成本负责，推动链路持续优化；\n3、对业务数据、训练数据、模型评测数据进行深入的多维度分析，产出数据质量报告、模型能力分析报告、数据ROI分析报告等，通过可视化手段清晰呈现数据分布、质量趋势、能力提升效果等关键指标，建立数据驱动的决策机制，为数据生产优先级排序、资源分配、模型迭代方向提供量化依据；跟踪业界前沿数据技术与Benchmark，形成技术洞察，推动数据工程能力的持续升级；在AI数据与安全方向，负责训练数据与模型输出的安全治理工作，包括但不限于：个人隐私信息（PII）识别与脱敏、有毒有害内容数据挖掘与拦截规则构建、版权风险数据识别、价值观对齐数据生产、红队测试数据集构建、越狱攻击样本挖掘与防御数据准备等，构建数据安全风险的主动发现、度量与治理机制，保障模型训练数据的合规性与模型输出的安全可控；\n4、持续跟踪大模型数据领域的前沿进展，包括但不限于数据质量过滤新方法、合成数据技术（Synthetic Data）、数据混合比例策略（Data Mixture）、课程学习（Curriculum Learning）、指令数据自动生成、多模态数据处理、Agent训练数据构建等方向，将前沿技术快速落地到实际数据生产链路中，推动团队数据工程能力与数据挖掘方法论的持续升级。","requirements":"1、本科及以上学历在读，计算机、统计学、数学、数据科学等相关专业；\n2、精通Python、SQL等编程语言，具备良好的算法和数据结构基础；\n3、对大模型的训练流程（预训练、SFT、RLHF/DPO）有基本了解，关注大模型领域发展，有大模型相关项目、竞赛或研究经历者优先；了解Prompt Engineering、RAG、Agent等相关技术者优先；\n4、熟练掌握数据挖掘、机器学习、深度学习等相关技术及工具；熟悉常用数据分析方法，如回归分析、分类、聚类、关联规则挖掘等及统计分析方法，能够从复杂数据中提炼规律、发现问题、形成洞察；具备数据可视化能力，熟练使用Matplotlib、Seaborn、Pandas、NumPy等工具；\n5、熟悉大数据处理技术和平台（如Hadoop、Spark、Hive）有TB级以上数据处理经验者优先；了解向量数据库（Milvus/FAISS等）在大模型场景中的应用者优先；\n6、具备良好的逻辑分析能力、问题解决能力和团队协作能力；有良好的数据敏感性，能够将业务需求转化为数据方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668160009704343861","sourceKey":"bytedance","company":"字节跳动","title":"广告产品经理 - 国际化电商广告","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668160009704343861/detail","duty":"团队介绍：国际化电商广告团队始终以广告主为核心，追求技术卓越。我们与电商、零售、旅游等各行业广告主紧密合作，致力于将国际化产品打造为各类企业不可或缺的增长平台，同时成为消费者发现并购买产品、内容及服务的首选目的地。团队肩负着实现国际化广告营收的重要使命，正在全力构建新一代网络广告解决方案。\n\n1、负责国际化商业化广告及达人相关产品建设；通过产品和策略设计，帮助广告主在平台更容易地完成创意制作及达人撮合，同时帮助达人更好地实现变现；\n2、负责优化广告及达人服务机构的相关产品的客户旅程，让广告主、达人与其服务机构合作流程更畅通，体验更好；\n3、负责与各区域运营沟通合作，明确梳理不同区域的差异化需求，设计通用解决方案；\n4、理解机构相关的业务逻辑，抽象机构参与商业化创意遇到的核心问题，并通过调研完成产品设计；\n5、通过数据分析，明确当前业务增长的问题及痛点，与运营协同完成增长策略的设计。","requirements":"1、2027届获得本科及以上学历；\n2、英语口语、写作能力流畅，可适应多语言工作环境；\n3、积极主动，愿意深入理解业务，对业务及用户需求敏感并擅长沟通；\n4、有同理心、责任感、自驱力，具备优秀的项目管理及推动能力；\n5、有良好的逻辑思维能力，数据敏感，擅长通过数据分析问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664903953716742453","sourceKey":"bytedance","company":"字节跳动","title":"AI综合研发工程师（增长方向） - 国际支付","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664903953716742453/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、负责字节跳动国际支付增长营销工具的后端开发，并学习支付基础能力，以及从支付到支付营销的完整链路；\n2、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n3、负责在线大流量高并发系统设计和性能调优；\n4、参与各专项技术调研，新技术引入等前瞻项目，探索并落地AI在业务上的帮助。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680090534141610245","sourceKey":"bytedance","company":"字节跳动","title":"AIGC策略运营实习生 - 抖音","city":"深圳","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680090534141610245/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责高质量（高画风）AI内容生态建设，制定全局性的AI内容供给策略，并规划中长期内容能力演进路径；\n2、建立并完善AI优质内容的质量与模型效果评估体系，主导AI内容生产Workflow的端到端设计与持续迭代，推动生产效率与质量的提升；\n3、深度协同产品与算法团队，针对泛内容、音乐、电商等赛道，制定差异化策略与产能规划，驱动跨部门项目高效落地，达成产能目标，并基于业务数据反馈，提出建设性方案，反哺并提升底层模型表现。","requirements":"1、本科及以上学历在读；\n2、具备AIGC内容生态、大模型运营或相关领域实操经验者优先，资深内容爱好者，具备敏锐的热点洞察和内容审美；\n3、创意策略：有内容意识及相关实习经验，理解产品亮点及增长目标，明确投放素材内容要点；明确素材要传达的内容信息,将抽象的产品功能，转译为能打动用户的价值点，或挖掘有潜力的优质内容；结合渠道特性、内容特性及用户偏好，选择适配的包装形式，提升内容吸引力；基于效果数据，持续迭代优化，找到最优创意方案；\n4、数据分析：有投放基础知识，能在指导下快速理解各项指标的含义，并建立监控机制，及时跟踪策略效果、做好下钻归因；\n5、逻辑思维严密，理解力强，能迅速洞察复杂业务链路的诉求。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678987676343617797","sourceKey":"bytedance","company":"字节跳动","title":"游戏视觉设计实习生 - 绿洲工作室","city":"北京","category":"游戏美术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678987676343617797/detail","duty":"绿洲工作室2019年4月在北京成立，立足动作与休闲核心赛道，依托移动、PC、主机全平台布局，持续探索 RPG、竞技、休闲、棋牌等多品类精品游戏创作。旗下有《晶核》《雾影猎人》《SlashZero》（又名：《零境·入侵》）《Land of Empires》《芒果斗地主》等多款产品。我们的愿景是希望帮助玩家在令人惊叹的虚拟世界中一起玩耍与创造，加入这里，你将与一群简单、务实的优秀伙伴一起，Work hard，Play harder~\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责游戏产品宣发的视觉包装工作，基于产品美术风格负责主视觉设计、相关品牌及运营物料的平面设计等；\n2、根据需求完成游戏的主视觉海报、Banner、商店图、广告图、视频包装、H5等平面物料的视觉设计；\n3、有优秀的审美能力，能够完成视觉创意策划、设计与制作，充分调动自身创意能力；\n4、协助市场建立并维护品牌视觉设计标准与规范，确保宣发内容调性统一。","requirements":"1、本科及以上学历在读，具备美术&设计相关专业背景，平面设计、动画、数媒等美术相关专业；\n2、熟悉平面排版和视觉传达设计的相关理论，较强的图形和造型功底，熟练使用两款以上2D或3D设计软件，如Photoshop、Illustrator、AE、Blender；\n3、具备优秀的创意思考能力，热爱游戏，熟悉主流游戏风格，思维活跃，眼界开阔；热爱平面设计并熟悉前沿趋势，对游戏营销有敏锐的洞察力；\n4、合作度高，擅长沟通交流，能配合市场、社区、设计同事工作，有良好的团队意识；\n5、投递请附带作品集和简历：\n1）作品集和简历。\n\n加分项：\n1、能进行视频剪辑工作，能使用UE渲染成品图，有成熟的AIGC工具使用经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678265381508991237","sourceKey":"bytedance","company":"字节跳动","title":"内容策略运营实习生 - 今日头条","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678265381508991237/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与今日头条内容生态相关业务的数据分析与策略运营工作，协助分析内容供给、用户消费、流量分发之间的关系，理解不同内容场景下的供需变化和增长机会；\n2、基于线上数据、用户反馈和内容样本，协助发现并拆解内容质量、内容理解、分发效率等问题，沉淀可复用的案例、标准和分析结论，支持业务策略优化；\n3、围绕重点内容场景，参与优质内容、优质作者、内容语料和行业案例的收集与分析，辅助判断内容形态、内容质量和用户消费价值，为策略迭代和产品优化提供依据；\n4、参与特定内容场景的内容理解和策略优化工作，包括内容画风、内容质量、内容结构化、用户反馈等方向，支持内容策略在不同业务场景中的落地；\n5、与产品、技术、算法和运营团队协作，协助推进策略方案落地，跟踪上线效果，整理阶段性复盘材料，支持推荐效果和内容生态效率提升。","requirements":"1、本科及以上学历在读；\n2、能保证较稳定的实习时间，优先每周实习4天及以上，连续实习3个月以上；\n3、对内容平台、推荐产品、内容消费、创作者生态有兴趣，愿意长期观察和理解内容、用户和流量之间的关系；\n4、具备较好的信息搜集、内容判断和结构化整理能力，能从大量内容样本中总结规律，沉淀标准和问题类型；\n5、具备基础数据意识，能够使用Excel/飞书表格等工具完成数据整理、样本标注、效果跟踪和简单分析；有SQL或数据分析经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671251079667501317","sourceKey":"bytedance","company":"字节跳动","title":"质量运营实习生 - 内容质量与数据服务平台","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671251079667501317/detail","duty":"团队介绍：抖音内容质量与数据服务平台（简称CQC）归属于抖音集团，负责今日头条、抖音等产品内容和抖音集团商业内容的安全质量与体验。平台下设内容质量中心、商业生态与安全、生态治理与增长支持等业务，在全国20余个城市均有分布。\n自成立以来，CQC持续守护抖音集团旗下包括抖音、今日头条、番茄小说、飞书、红果短剧等产品在内的安全、质量与体验，优化产品内创作与交流环境，且在各产品运营增长方面开展支持工作。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、质量管理：负责今日头条内容安全执行质量、事故治理、专项提升、外发质量管理、体验优化、治理专项等工作，对齐上游目标制定改善方案及提升计划，挖掘标准、流程、执行、策略、工具等问题，推动问题解决及目标达成；\n2、执行牵引：结合政策热点对平台内容进行安全和风险研判，提出标准优化建议，梳理研判手册做执行牵引；\n3、上下游协作：根据业务不同阶段的目标和方向，对接运营、产品、策略、交付等环节，拆解落地规划协同上下游促进目标达成；\n4、模型应用：通过大语言模型工具等自动化策略运营手段不断优化迭代质量管理及业务流程，优化业务质效指标。","requirements":"1、2027届本科及以上学历在读，新闻、中文等相关专业；\n2、有内容质量把控、内容运营、内容编辑、内容创作等经验优先；有较强的数据敏感度，能够运用EXCEL进行复杂数据分析和结论呈现，可识别风险问题并制定解决方案；\n3、自我驱动，具备一定跨部门沟通和协作能力，具备较强的项目管理能力，能够在业务模块的深度和广度上进行跨团队沟通，推动多部门协作达成目标；\n4、有较强的产品、用户体验分析能力与运营思维方法，对业务发展方向和动态有较强的洞察力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668635915050912005","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型Agent Harness算法工程师 - Data AML","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668635915050912005/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、参与火山方舟Managed-Agent相关的算法研发工作，参与方舟自有Harness的技术架构选型、设计、优化；\n2、优化方舟自有Harness，包括但不限于Harness的运行模式、Buildin-Tools、Context机制、Multi-Agent协作调度、智能的辅助能力（模型选择、Advisor、Grader、Rlaphloop等等）；\n3、和评测团队一起构建面向Harness迭代的Agent评测，构建全面、有效的Agent Harness端到端评测；\n4、定义和实现Harness领域的前沿创新，与模型团队深度合作，参与实现模型与Harness的共同进化，从Harness的角度实现Harness与模型的深度适配。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对Agent Harness有技术热情，对大模型和Agent有较深入的理解，有Agent Harness的优化经验；有使用AI Agent工具进行软件开发的经验；在软件开发领域具有较强的学习能力；能够在AI辅助下，进行有质量保证的编程工作；\n3、了解模型和Agent Harness的基本机制及其技术原理（如LLM API、Reasoning、KV Cache、ToolUse、Skills、ReAct、Multi-Agent、MCP、A2A、FunctionCalling）；\n4、了解和Agent评估方法、Agent构建、RAG检索技术等；\n5、了解流行的各类Agent应用的原理和实现细节，如：OpenClaw、HermesAgent、Codex、ClaudeCode、Managed-Agents。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668233279846730037","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（CoreHR方向） - 集团信息系统","city":"北京/广州/成都/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668233279846730037/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、参与平台产品的服务端研发工作，推动业务的快速发展和高效迭代；\n2、参与系统架构设计、优化，提升系统性能和开发效率，保证设计和编码的质量；\n3、协助团队攻克各种高并发、系统解耦等方面的技术难关；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、通信等相关专业者优先；\n2、有扎实的编程能力，有优秀的设计和代码质量；\n3、深刻理解计算机原理，有良好的数据结构和算法基础；\n4、熟悉MySQL、Redis、消息队列等常用研发组件；\n5、积极乐观，责任心强，工作认真细致，有良好的团队沟通和协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668147008355830069","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师 - 集团信息系统","city":"深圳/上海/广州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668147008355830069/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、参与平台产品的服务端研发工作，推动业务的快速发展和高效迭代；\n2、参与系统架构设计、优化，提升系统性能和开发效率，保证设计和编码的质量；\n3、协助团队攻克各种高并发、系统解耦等方面的技术难关；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、通信等相关专业者优先；\n2、有扎实的编程能力，有优秀的设计和代码质量；\n3、深刻理解计算机原理，有良好的数据结构和算法基础；\n4、熟悉MySQL、Redis、消息队列等常用研发组件；\n5、积极乐观，责任心强，工作认真细致，有良好的团队沟通和协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667551265476888885","sourceKey":"bytedance","company":"字节跳动","title":"大模型赋能交易与商业场景的技术创新及落地实践研究 - Ads Core","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667551265476888885/detail","duty":"团队介绍：Ads Core 是抖音集团广告业务体系中负责交易机制与智能决策的核心技术团队之一。\n \n我们面对的是一个超大规模的商业化经济系统：一端是广告主和商家，希望在可控成本下获得订单、GMV、线索、用户增长和长期生意增长；另一端是抖音等产品中有限而高价值的用户流量。Ads Core 要解决的问题，是预算从哪里来、流量给到哪里，以及如何让每一次商业流量分配都更接近客户增量、用户体验和平台长期收入的共同最优。\n \n团队覆盖出价与竞价、归因与信号、自动化投放、流量机制、激励增长等关键方向，通过机器学习、因果推断、强化学习、机制设计和大规模工程系统，把客户经营目标转化为平台可理解、可执行、可优化的交易决策。\n \n技术上，Ads Core 处在超大规模、高并发、强约束的真实交易系统中。我们需要在每天海量请求里完成预算分配、实时出价、归因度量、自动化决策和流量机制优化；也需要在客户目标、用户体验和平台长期收入之间做多目标建模与系统决策。这里会持续产生因果归因、强化学习、机制设计、长期价值建模、大规模在线实验、实时工程系统等高难度问题，并要求算法能力真正落到线上交易链路和业务结果中。\n \n加入 Ads Core，你将参与建设抖音集团广告业务最核心的底层系统：让广告主真正把生意做大，让用户体验持续被保护，让平台获得长期、合理、可持续的商业化收入。如果你希望在真实商业系统里把算法、机制和工程能力转化为可见的业务影响，这里会提供足够复杂、也足够有成长空间的问题。\n\n课题介绍：\n本课题围绕商业、广告、交易等技术场景，以大型语言模型（LLM）、视觉语言模型（VLM）、智能体（Agent）、强化学习、多模态生成等前沿技术为核心支撑，重点聚焦搜索、广告、推荐、电商、生活服务、广告营销、内容生产等关键业务场景，针对性破解传统技术体系存在的瓶颈问题。课题的核心研究目标为：借鉴大模型规模法则（Scaling Law）与生成式人工智能技术思路，深入探索技术与商业业务的深度融合路径，构建适配各垂直商业场景的智能模型及系统架构。同时，着力解决技术落地过程中的效率优化、场景适配、合规管控等关键问题，助力业务规模增长、运营效能提升与用户体验优化，推动商业场景数字化、智能化转型进程。\n\n课题挑战：\n1、技术适配性：通用LLM与MLLM在垂直商业交易场景存在领域知识薄弱、工具调用不足、语义对齐偏差等问题，需突破多模态协同、时空建模、低标注学习及搜广推融合技术；\n2、效率与性能：大模型时延高、耗算力、吞吐低，难以满足高并发低延迟交易与搜广推需求，需通过轻量化、量化、分布式推理等优化性能与成本；\n3、决策与规划：复杂商业决策对长周期建模、多目标优化、自适应要求高，AIGC与Agent易产生幻觉、决策偏差与因果缺失，需强化可信推理与风险约束；\n4、落地与合规：需解决系统集成、数据质量、内容可控、隐私安全与监管合规问题，保障大模型规模化稳定、安全、合规落地。\n\n课题价值：\n1、理论价值：探索大模型在多商业场景的Scaling Law可行性，完善推荐大模型、Agent决策、多模态融合等技术体系，丰富AI在商业领域的应用理论；\n2、实践价值：破解各商业场景核心痛点，如提升推荐转化、广告ROI、内容生产效率、客服质量等；降低人工成本，实现商业流程自动化；推动搜广推、电商、广告等领域的技术范式革新，支撑业务规模化增长，同时优化用户体验与商家服务能力，构建可持续的商业生态。","requirements":"1、2027届毕业，获得博士学位，人工智能、计算机、自动化、数学相关专业优先；\n2、拥有优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n3、怀有科技改变世界的远大抱负，有志于投身机器学习、人工智能、大语言模型、多模态理解和生成等技术领域；\n4、扎实的机器学习、NLP、RL基础和出色的探索能力，在ACL/EMNLP/NAACL/NeurIPS/ICML/ICLR等顶级会议上发表论文者优先；\n5、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n6、在大模型领域或者RL领域，主导过大影响力的项目或论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664630884095510837","sourceKey":"bytedance","company":"字节跳动","title":"超边缘CDN智能调度开发工程师 - 音视频技术","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664630884095510837/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责超边缘CDN智能调度系统的管理与资源使用优化；\n2、负责保障接入系统的可用性和稳定性，优化性能并提升资源利用率；\n3、负责设计和构建下一代全球大规模超边缘调度系统。","requirements":"1、2027届获得本科及以上学历，计算机科学相关专业优先；\n2、具备良好的沟通表能力及团队协作精神、有较强的主动性、责任心与执行能力；\n3、精通C/C++/Go/Java中一门以上编程语言，有设计能力和良好的自测习惯；\n4、熟悉高性能、高并发、高可用性分布式系统设计。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7589519944268990725","sourceKey":"bytedance","company":"字节跳动","title":"业务安全蓝军实习生-安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7589519944268990725/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：我们团队致力于通过对攻防技术的持续研究，最大限度降低零日漏洞与安全事件造成的影响。\n我们提供红队演练、威胁检测、安全保障工具支持及事件调查等服务，助力提升系统韧性。\n通过不断强化攻防两端能力，我们在巩固公司核心安全基础、保障数据与业务安全方面发挥着关键作用。\n\n1、对字节跳动各类产品的Android、iOS或Windows客户端深入研究，分析算法及协议潜在风险，输出报告；\n2、负责对重点黑灰产工具进行逆向研究，包括反混淆、虚拟机壳还原、协议分析等工作；\n3、以外部视角，模拟真实攻击者，针对业务场景风险，开展业务安全攻防演练，发现相关风险和漏洞。","requirements":"1、本科及以上学历在读，信息安全、网络安全、计算机科学相关专业优先；\n2、熟悉常用逆向工具，如IDA、Jeb、Frida、Xposed等；\n3、了解Android、iOS、Windows或者Linux系统的底层原理和攻防技术；\n4、了解常见的各类业务风险漏洞，熟悉移动端各类安全相关知识；\n5、熟悉至少一种编程语言，Python、Java、C++、Js、Objective-C等；\n6、学习能力强、态度积极，具备良好的沟通能力与团队协作意识，可保证至少3个月全职实习（每周≥4天）。\n\n加分项：\n1、有CTF比赛参与经历、在校AI/安全相关项目经验，或相关技术博客/开源贡献者优先；\n2、了解至少一种AI框架（TensorFlow/PyTorch等）基础用法，对大模型应用、对抗攻击有初步认知者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683070926031964469","sourceKey":"bytedance","company":"字节跳动","title":"产品实习生（收银产品） - 国际支付","city":"上海/深圳","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683070926031964469/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责字节跳动国际支付收银台的优化迭代，包括但不限于支付下单页面优化、用户流程设计以及支付收银台策略；\n2、从用户支付体验出发，持续关注用户下单及支付链路数据表现，结合各方反馈持续推动产品优化；\n3、良好的合作意识和沟通能力，能够与多个团队沟通配合，协同研发、设计等团队推动项目落地；\n4、跟踪和分析产品数据，为产品决策提供数据支持。","requirements":"1、本科及以上学历在读；\n2、对产品和用户体验有浓厚兴趣，具备优秀的沟通和人际交往能力，具备自主数据分析能力和相关技能，积极主动，有责任心，学习能力强；\n3、了解基本的支付流程如微信、支付宝支付逻辑，或有相关产品岗实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670520869705648389","sourceKey":"bytedance","company":"字节跳动","title":"拉美行业策略运营实习生 - TikTok Shop","city":"上海/深圳","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670520869705648389/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、行业策略支持：协助行业负责人开展行业趋势调研与产品分析，基于平台数据与外部洞察，协助制定阶段性招商策略与重点商家画像，为行业策略决策提供数据支撑；\n2、行业活动策划与执行：参与行业促销活动及品牌活动的策划与落地，协同商家理解活动规则，提升关键指标（如报名率、活动GMV），并协助推进活动复盘与方法论沉淀；\n3、跨部门项目协同：与营销、达人、产品等中台团队紧密对接，推动跨部门项目高效落地，跟进项目进度并及时暴露问题；\n4、目标管理与数据分析：通过追踪核心经营指标，帮助团队实时把控目标完成情况，针对指标异常的商家或行业，给出清晰的归因分析与改进建议；\n5、知识库与效率建设：积累和沉淀行业运营经验，整理通用流程与规范，持续为团队知识库贡献内容，提升团队整体协作效率。","requirements":"1、本科及以上学历在读，市场营销、电商、商科、数据分析等相关专业优先；\n2、具备较强的逻辑思维和结构化表达能力，善于从行业视角和平台视角综合思考问题；\n3、具有较强的数据敏感度，能在Mentor指导下拆解关键指标，并形成可落地的改进建议；\n4、具备一定的项目管理与跨部门协作意识，结果导向，能有效推动事项落地；\n5、英语六级及以上，可以用英语进行日常工作沟通（含会议、邮件、文档）；\n6、可实习时间不少于6个月，每周不低于4天，期间工作投入度高。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668579257697831221","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发/测试开发工程师（搜索） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668579257697831221/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、我们希望寻找具备扎实工程基础、全栈潜力和AI原生能力的应届毕业生，加入TikTok各业务质量工程团队，区别于传统意义上的“测试执行”岗位，这是一个以质量场景为切入点，面向复杂系统和智能工程建设的研发岗位；\n2、参与业务质量平台、研发效能工具和自动化基础设施的设计与开发，覆盖前端、后端、数据链路和平台能力建设；\n3、深入客户端、服务端及上下游协同链路，建设功能、接口、稳定性、性能、安全等多维质量保障能力；通过代码分析、链路分析、日志分析、压测、故障演练等方式发现复杂系统中的深层问题，并推动问题闭环；\n4、探索并落地AI在质量工程中的应用，包括测试生成、智能缺陷分析、质量评测、测试智能体、自主探索式测试等方向；\n5、沉淀可复用的工程能力，包括测试框架、诊断工具、自动化脚本、质量方法论与平台化能力；与研发、产品、算法、数据等团队协作，共同推动质量内建、研发提效和工程规范升级。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化、数学等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构与算法的核心思想，能够将抽象问题转化为可实现、可优化的工程方案；熟悉至少一门编程语言，如Go、Java、Python、TypeScript/C++等，具备独立完成中型工程项目或核心模块开发的能力；\n3、理解操作系统、计算机网络、数据库、并发编程、常见系统架构等基础知识；对软件工程有基本理解，熟悉从需求分析、设计实现到测试验证、上线迭代的研发流程；\n4、具备良好的问题拆解能力、系统性思维和学习能力，能够面对复杂问题持续追问本质并推动解决；具备良好的沟通协作能力和责任心，能够在跨团队、多角色合作中推动目标达成；\n5、能熟练使用AI工具辅助编码、排障、文档理解和方案设计，具备对AI输出进行判断、校验和二次加工的能力；对AI在测试与质量场景中的应用有兴趣，对大语言模型、Agent、RAG、模型评测、自动化工作流等AI工程方向有认知或实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668281404838758661","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发工程师 - Seed 产品研发","city":"广州/深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668281404838758661/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、负责飞书相关产品在移动端（iOS、Android、鸿蒙）、PC端及Web端的功能研发与维护，探索AI能力在业务场景中的应用；\n2、参与客户端性能与稳定性优化、跨端能力及研发工具建设，持续提升产品体验、工程质量和研发效率；\n3、参与面向AI Agent的工程体系建设，包括飞书能力的工具/API封装、上下文管理、任务执行与效果评测，提升Agent在软件研发场景中的效率、正确性和可靠性。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程、人工智能等相关专业优先；\n2、具备扎实的数据结构、算法和计算机基础，至少熟练掌握一门主流编程语言；\n3、对客户端开发和用户体验有热情，在移动端、桌面端或Web端至少一个方向有项目实践；有iOS或移动客户端项目经验者优先；\n4、具备良好的学习、分析和动手能力；有使用AI编程或Agent工具解决实际问题的经验，能够理解其局限并验证生成结果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667934239069063429","sourceKey":"bytedance","company":"字节跳动","title":"内容营销经理 - 抖音","city":"北京/深圳/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667934239069063429/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n1、负责字节跳动中国区产品的内容营销工作，在主流内容平台，通过输出符合目标的创意构想、社媒话题、传播主题，与达人做深度内容定制、内容植入，实现品牌声量提升等核心目标；\n2、保障营销创意项目按计划落地，协同商务、代理、产品运营等跨职能团队，推动内容在多平台的传播；\n3、负责跟踪行业营销趋势与热点，结合推广产品，提炼核心传播卖点，完成卖点的创意转译，形成可落地的内容素材方向；\n4、负责项目的效果监测与复盘，分析内容的传播效果，沉淀经验，为后续营销方案优化提供支撑。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对社交平台的达人生态和内容生态有实操经验，熟悉对社交平台的传播逻辑与玩法，对各主流平台上的达人生态及分布有较为深入的了解；有较强的内容创意策划能力和经验，有自建账号、运营官方账号经历，且有成功案例者优先；\n3、对内容营销行业有较高敏感度，对新技术、新体裁有好奇心，有较强的行业信息收集能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667149898932930869","sourceKey":"bytedance","company":"字节跳动","title":"Camera质量开发工程师 - 移动OS","city":"深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667149898932930869/detail","duty":"团队介绍：我们隶属于产品研发与工程架构部，是字节跳动在智能硬件领域的软件技术攻坚力量—— 聚焦 AI 与智能硬件的深度融合，如豆包手机助手等；以 “让人与设备的交互更自然、更便捷” 为目标，探索前沿 AI 技术的落地场景，打造行业领先的智能硬件综合解决方案。\n在这里，你将与一支顶尖技术团队并肩：\n- 直击 AI 与硬件结合的核心技术难题，参与从 “技术探索” 到 “场景落地” 的全链路研发；\n- 主导或深度参与关键技术突破，用创新定义智能硬件的交互未来；\n- 站在行业前沿，将技术理想转化为千万用户可感知的产品体验。\n如果你心怀对技术的热忱，渴望在 AI 与智能硬件的赛道上突破自我、创造价值，我们期待你的加入，与我们一起解锁更多技术可能，共筑智能交互的新生态！\n\n1、对影像交付物整体质量负责，包括功能、效果等的稳定性和一致性等；\n2、搭建完整的图像质量的评测体系和验收标准，为整体画质评价准确性负责；\n3、主导影像评价能力建设，建设兼具影像认知和技术理解的测试开发团队；\n4、与产品团队合作支撑硬件选型与论证工作。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟练掌握计算机基础，包括但不限于操作系统原理，计算机组成原理；\n3、熟练掌握一门计算机编程语言，C/C++优先，MATLAB/Python等也可以；\n4、有图像处理相关项目经验或者实习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667124780703451397","sourceKey":"bytedance","company":"字节跳动","title":"AIGC算法工程师 - 中国交易与广告","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667124780703451397/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、负责商业化广告业务的文案、图片、视频等创意自动化生成相关研发工作，探索并应用Diffusion、LLM、VLM、Omni等模型生成高质量商业化内容，赋能商业化场景创意制作及优化；\n2、参与Diffusion、LLM、VLM、Omni等生成式模型相关算法研发与优化，跟进计算机视觉和自然语言处理领域的前沿技术研究；\n3、追踪业界语言模型、视觉生成、多模态及Generative AI方向最新技术，针对业务场景及问题设计创意算法解决方案，并落地相关自动化创作及优化能力。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、在自然语言处理、多模态、视觉算法、AIGC、LLM、搜索、机器学习、深度学习、智能对话、知识图谱、文本生成等领域有实际的开发和从业经验者优先；\n3、优秀的问题分析和解决能力，能深入解决大模型训练和应用存在的问题，良好的沟通协作能力，能和团队一起探索新技术，推进技术进步；\n4、至少熟悉一门计算机编程语言，包括并不限于C/C++/Java/Go/Python；\n5、有高水平论文者优先，包括但不限于ACL、CVPR、ICLR、ICML、NeurIPS等；\n6、实践动手能力强，ACMICPC，NOI/IOI，Top Coder，Kaggle比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665590441061697797","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 广告业务","city":"上海/北京/杭州/深圳","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665590441061697797/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n1、参与商业场景AI能力效果优化，建设模型评估策略，挖掘各场景模型能力优化点；\n2、通过数据分析、客户调研、行业研究等方式，挖掘商业广告需求生成场景；\n3、积极与业务团队协作，保障需求高质量执行落地。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、有AI产品实习经验优先，对大模型以及AI应用领域有较大热情，对大模型的特性与动态有跟踪和理解；\n3、学习能力优秀，逻辑思维清晰，有较好业务场景理解能力；\n4、具备较好的协调沟通能力，有较好的复杂项目推进经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7633856317665642805","sourceKey":"bytedance","company":"字节跳动","title":"移动研发实习生-App Infra","city":"北京","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7633856317665642805/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：App Infra是字节跳动面向应用的基建中台部门，以App侧性能/稳定性深度优化为基础，结合LLM、Agent、生成式推荐模型等前沿技术，为字节跳动旗下的核心应用提供终端+平台的解决方案。于下层，结合操作系统、虚拟机、工具链、编译器等技术，建设了稳定性、流畅性、电量在内全链路的监控体系和调试分析工具；于上层，则结合端侧特征工程、深度学习模型/决策树模型/SLM 训练等基建，围绕搜索/推荐/广告/直播/电商等场景，建设了云端协同推荐、品质体验优化等端智能解决方案。如果你热爱挑战底层技术、追求极致优化，又渴望把AI转化为千万用户感受得到的流畅与智能——欢迎加入，和我们一起打造下一代移动体验！\n\n1、主导端侧AI基建与架构设计，深度参与框架选型、技术路线决策，与算法团队共建高可用、高性能的端智能体系；\n2、负责SLM、VLM、端侧大模型的工程化落地，攻克轻量化部署、低延迟推理、资源受限场景下的实时智能难题；\n3、面向Android、iOS、鸿蒙多平台做深度适配，解决端侧算力、功耗、内存、稳定性等硬核工程问题；\n4、结合LLM/Agent最新演进方向，迭代工具链与部署方案，持续提升端云协同智能的效率与体验。","requirements":"1、本科及以上学历在读，计算机、人工智能、自动化等相关专业优先；\n2、具备扎实的编程基础，熟悉至少一门开发语言（如C++/Java/Kotlin/Objective-C/Swift/Python等），对技术充满好奇与热情；\n3、逻辑思维清晰，具备良好的沟通协作能力，渴望用技术解决复杂问题。\n\n加分项\n1、理解LLM原理，具备Agent系统设计与落地经验，关注Agent上下文管理、状态维护与效果评估，能持续提升智能体执行效率与可靠性；\n2、有端侧模型部署与优化经验，了解本地大模型推理框架，熟悉模型量化、推理加速等相关技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7574803189789018373","sourceKey":"bytedance","company":"字节跳动","title":"AI产品实习生（评测方向） - 豆包","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7574803189789018373/detail","duty":"团队介绍：字节跳动豆包产品团队，在这里你将有机会参与到行业前沿产品的规划设计，开拓自己的行业视野，与先进团队共同成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深度参与AI大模型一线工作，参与通用主模型的评测业务；\n2、评测业务范围包括人工评估、自动评估、众测等多维度评测方法；\n3、探索模型评测的各类先进方法。","requirements":"1、本科及以上学历在读；\n2、对AI行业充满热情，愿意主动学习最新AI前沿知识，擅长多任务工作，能够并行执行模型评测的日常工作；\n3、优秀的逻辑能力与结构化表达能力，熟悉提示词工程（Prompt Engineering），善于让不同的AI助手帮你完成工作；\n4、对模型评估和训练的相关流程有基础理解或强烈的好奇心；\n5、过往在大模型、战略、计算机或其他相关领域实习过的优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683068495726381365","sourceKey":"bytedance","company":"字节跳动","title":"产品实习生（商户产品） - 国际支付","city":"上海","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683068495726381365/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与国际支付项下To B商户账号产品的设计，结合大语言模型（LLM）与智能识别（如OCR+NLP）等AI技术，重构账号注册、登录鉴权、资质自动解析填表、资产绑定等全生命周期服务，在保障安全合规的前提下打造极致的智能化体验；\n2、负责字节跳动国际电商、直播、广告等不同国家市场商户入驻流程的体验分析，对海量商户反馈、客服工单进行智能聚类与痛点识别，精准定位全链路流程卡点并提出优化迭代方案；\n3、参与To B商户信息的综合管理与资产化项目，探索并落地机器学习、知识图谱（KG）在实名信息验真、同人网络识别、黑产拦截及批量复用中的应用，支撑消费金融、信贷、保险等复杂场景的跨业务调用；\n4、探索GenAI在To B商户服务中的创新落地场景（如Merchant Copilot商户智能助手、合规政策智能问答等），与产品、算法、合规及开发团队紧密协作，推动AI原生功能的MVP（最小可行性产品）设计与敏捷迭代；\n5、跟踪和分析产品大盘数据，借助智能数据分析工具完成归因分析与预测，为产品决策、模型调优提供科学的数据支持。","requirements":"1、本科及以上学历在读，计算机、软件工程、电子、大数据等专业优先；\n2、具备优秀的沟通能力，具备自主数据分析能力和相关技能，具备良好的逻辑思维能力，积极主动，有责任心，学习能力强；\n3、有支付产品，电商商户产品，金融产品实习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675578915612231989","sourceKey":"bytedance","company":"字节跳动","title":"出海大客户/渠道销售（非电商-应用） - Global Business Solutions","city":"北京/深圳","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675578915612231989/detail","duty":"团队介绍：Global Business Solutions (GBS) 负责TikTok为主的全球产品商业化相关工作，为全球品牌和广告商提供集成的数字营销解决方案。具体包括各区域销售、销售运营、渠道管理、商业化战略、To B市场营销、营销科学、商业化合作和商业内容安全等职能。\n\n1、参与制定国际化商业化广告客户及代理体系的运营策略，协助完成客户/代理开发与维护的规划工作；基于市场反馈协助构建需求分析模型，参与设计合作伙伴激励方案及生态运营机制，支持服务生态的良性发展；\n2、协助搭建代理商分层培训体系，参与培训内容的设计与整理（含业务逻辑、产品能力、运营方法等），跟进业务与项目的周期性运营进展；同时结合广告主多元需求，参与市场推广方案的策划、落地执行及效果跟踪迭代；\n3、参与制定多方协同沟通策略，协助构建“专项-培训-中高层”分层沟通机制，支持专项运营计划、培训体系及战略谈判材料的准备，推动内外部目标对齐与协同增长策略的落地；\n4、基于行业与市场信息，协助构建跨境行业趋势洞察体系，参与媒体价值与客户/代理需求的匹配分析，支持合作伙伴与客户痛点研究，并为代理商赋能策略提供数据与信息输入；参与潜力合作伙伴的挖掘分析，协助建立筛选、培育与评估的基本框架，支持市场推广策略的执行与长期合作机制的建设。","requirements":"1、2027届获得本科及以上学历，广告学、市场营销、工商管理、传播学、数据分析等相关专业优先；\n2、对广告和全球营销趋势有浓厚兴趣，具备较强的学习能力与信息整合能力，善于从数据与案例中发现规律；\n3、具备良好的人际沟通与协调能力，乐于与内外部伙伴协作，能够清晰表达观点并推动共识；\n4、思维活跃、逻辑清晰，善于拆解复杂问题，具备较强的执行力和结果导向意识；\n5、自驱力强，能够高效处理多任务并行场景，具备优秀的多任务协同能力；\n6、英语可作为工作语言，有国际化学习、交换或跨文化项目经验者优先；对跨文化沟通与跨国业务协作有热情者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675224348436826421","sourceKey":"bytedance","company":"字节跳动","title":"战略分析实习生 - 广告业务","city":"上海","category":"战略","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675224348436826421/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深入理解商业化业务，分析业务驱动因素，发现业务问题，挖掘业务机会点，为产品决策、市场规划等提供建议；\n2、围绕特定课题，完成信息搜集整理与数据分析，协助完成洞察提炼和材料制作等工作；\n3、研究广告行业需求，基于实际体验、分析、内外部调研，撰写行业、调研报告，形成关键商业模式的洞察；\n4、协同业务重点项目跟进，建设数据过程监控工具，推动项目正常开展。","requirements":"1、本科及以上学历在读；\n2、每周可实习4-5天，可持续3个月及以上，具有较强的商业敏感性、逻辑思维能力以及快速学习能力；\n3、数据处理能力强，熟悉SQL等工具优先；\n4、有过战略、商业分析、数据分析工作经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673508946743019781","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法研究员 - Data AML","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673508946743019781/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、参与多模态大模型后训练（SFT、RL、OPD等）算法研发，提升模型在内容理解等场景的能力表现；\n2、深入分析失败模式，建立从任务与评测、问题定位到数据、训练和系统优化的完整闭环，持续提升模型在复杂场景上的准确度和泛化能力；\n3、跟踪学术界与工业界前沿进展，将最新研究成果转化为线上生产力。","requirements":"1、2027届获得本科及以上学历；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、具有扎实的机器学习和数学基础，熟悉Transformer架构和大模型原理，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、ICML、ACL、EMNLP等顶级会议上发表论文者优先；\n4、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；对AI技术的实际落地和突破性应用充满热情，追求技术创新与现实价值的结合；\n5、具备良好的沟通协作能力与自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671198195599493429","sourceKey":"bytedance","company":"字节跳动","title":"大模型评测后端实习生 - 模型数据工程","city":"北京/上海/杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671198195599493429/detail","duty":"团队介绍：数据工程与平台团队旨在实现人类知识与经验向模型能力的加速迁移。我们从真实场景出发，通过模型短板识别、高质量数据定义、规模化数据生产，提升模型能力。与此同时，团队还致力于依托训练反馈，反哺数据设计，推动系统迭代，构建业内一流的数据工程能力与平台。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、评测体系建设：参与大模型评测的工程基础设施的开发工作，包括评测集的接入、生产、管理，模型推理及采样，机评能力建设，评估结果的分析等评测核心能力的开发工作；\n2、评测Agent搭建：探索自动评测、高质量评测集构建等前沿评测方法，在评测场景搭建AI Agent，为评测业务提供端到端的高效、自动化的交付能力。","requirements":"1、本科及以上学历在读，计算机、人工智能、软件工程等相关专业优先；\n2、具备优秀的逻辑思维能力及较强的学习能力，能快速理解复杂Agent逻辑、评测痛点与业务目标，主动思考能力突出，能够积极推进工作；有大模型/LLM/Agent评测、对话系统评估、模型迭代、模型训练相关经验优先；\n3、具备高度自驱力和卓越的执行力，专注结果达成，勇于突破常规，对高质量工作有执着追求，坚持解决问题；\n4、有评测集构建、评测方案设计、数据分析/结论提炼能力，能从数据中发现核心问题并提出有效解决方案；\n5、熟悉主流大模型生态，有评测工具开发、自动化评测、模型调用经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668657003569203509","sourceKey":"bytedance","company":"字节跳动","title":"增长策略产品经理 - TikTok","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668657003569203509/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、参与国际化用户增长策略的制定与落地，通过数据洞察、产品创新和实验优化，驱动用户规模增长和活跃度提升；\n2、分析国际化不同市场的用户行为、行业环境和增长机会，提出本地化增长方案；\n3、协同算法、数据、运营等多团队，推动增长策略的跨部门落地，监控核心指标并持续优化；\n4、关注行业趋势和新兴增长模式，从内容、技术等多视角出发，探索创新增长点。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感，能通过数据分析发现问题并提出解决方案；\n3、逻辑思维强，能拆解增长问题，并通过实验验证假设；\n4、有较强的沟通能力和团队协作精神，能够高效地与不同部门的人员进行沟通和协作；\n5、具有较强的学习能力和创新思维，能够快速适应新环境和新任务，积极主动地解决问题；\n6、英语能力强，可作为工作语言，具备流利的英语听说读写能力，有国际化学习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668575132492417333","sourceKey":"bytedance","company":"字节跳动","title":"榜单产品经理 - 抖音生活服务","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668575132492417333/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、协助负责榜单流量分发体系与创意互动玩法的产品设计与落地，通过产品手段提升榜单影响力和公信力，配合算法、运营团队完善榜单机制；\n2、参与跨部门协作，对接运营、算法、研发、设计等团队，跟进需求评审、开发排期、测试上线全流程，推动产品功能按时高质量落地；\n3、开展行业产品调研与用户研究，分析国内外优秀榜单产品的流量玩法与产品设计创新点，输出调研报告，为团队提供产品创新思路。","requirements":"1、2027届获得本科及以上学历；\n2、对产品工作有浓厚兴趣，具备清晰的产品思维和逻辑分析能力，能够独立思考并拆解复杂问题；具备基础的数据敏感度，具备优秀的沟通表达能力和跨团队协作能力，有较强的执行力和责任心；具备良好的创意能力和审美能力，对互动玩法、用户激励机制有自己的思考和见解；\n3、对生活服务行业有一定了解和兴趣，有内容产品、榜单产品或用户增长产品实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668269573698881845","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师 - Seed 产品研发","city":"杭州/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668269573698881845/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书项目核心模块的前后端全链路研发，端到端负责功能设计、开发、测试与上线；\n2、不断探索各种新技术，参与系统架构演进、性能与稳定性优化，保障平台在大规模企业客户下的高可用；\n3、以AI为默认工作方式，深度实践AI Coding，持续沉淀团队研发提效方法与工具。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、数据结构、算法、操作系统、网络、数据库基础扎实，熟练掌握至少一门主流编程语言（Go/TypeScript/Java/Python等），代码逻辑清晰、结构良好；\n3、至少熟练使用一种AI编码工具Cursor/Claude Code/Copilot/TRAE/Codex等；了解大模型、Agent、RAG、MCP、CLI、Prompt、Harness等核心概念并有自己的理解；能识别AI输出的正确性、风险与边界，并设计验证机制；\n4、具备良好的逻辑思考与问题拆解能力，好奇心与学习动手能力强，主动自驱，面对复杂问题有攻坚钻研的韧性，沟通协作顺畅。\n\n加分项：\n1、独立AI相关作品项目经验；\n2、优秀的开源贡献或个人项目；\n3、ACM/NOI/CTF等竞赛获奖；\n4、有To B/SaaS类产品实习或复杂业务开发经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667559991893936437","sourceKey":"bytedance","company":"字节跳动","title":"测试开发工程师 - 中国交易与广告","city":"上海/北京/成都/杭州","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667559991893936437/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、负责客户端、服务端及AI产品的质量保障，覆盖功能、性能、稳定性、资产损失、用户体验及模型效果等风险；\n2、深度参与需求全生命周期，从业务建模、风险识别、方案评审到上线监控和问题治理，推动高质量交付；\n3、针对模型、Prompt、Skills及Agent链路，建设评测标准、评测集、评估器、发布门禁和负面案例回流机制；\n4、熟练运用AI，完成测试设计、代码评审、数据构造、自动化验证、问题定位等工作；\n5、将业务知识和质量经验沉淀为结构化知识、Workflow、Skill或Agent，形成可复制、可规模化的质量能力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程及相关专业优先；\n2、具备扎实的计算机基础，熟悉至少一门编程语言，具有良好的工程实践能力；\n3、学习能力强，有好奇心和探索欲；能够快速学习新模型、新工具和新业务，重新建立解决问题的能力；\n4、具备良好的表达能力和判断力；能清晰表达目标、约束和验收标准，能识别AI输出中的事实、幻觉、边界和风险，形成可验证的结论；\n5、具备良好的产品意识、业务理解能力、责任心和跨团队协作能力。\n\n加分项\n1、有大模型应用、Agent、RAG、模型评测或Prompt-Engineering实践；\n2、熟悉自动化测试、性能测试、稳定性治理、数据分析或监控建设；\n3、有AI项目、开源项目、技术竞赛或自主完成复杂项目的经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667523818755492149","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（供给增长方向） - 抖音电商","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667523818755492149/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、支持抖音电商商家端产品团队，负责分析消费者需求，发现商品/内容的供给机会，提供更丰富且高质量的商品供给和内容供给；\n2、在资深同事指导下，做好数据分析、定性调研，明确商家需求；\n3、负责AI技术在商家商品侧产品的应用，分析商家痛点、明确AI解决方案、协同算法工程落地；\n4、参与产品的设计与管理，通过工具、数据、AI手段，帮助商家发布好商品、好内容，并提升操作效率；\n5、根据产品目标，排优先级，协调资源，做好产品研发管理，保障产品按时、高质量上线；\n6、协同产品运营，做好产品上线后持续运营，根据反馈持续优化。","requirements":"1、2027届获得本科及以上学历，计算机/商业分析/统计学/数据分析等相关专业优先；\n2、对AI技术有研究实践的优先，热爱电商行业，有过电商平台实习经历优先，有电商平台开店经验优先；\n3、学习能力强，思维敏捷，逻辑思维能力优秀，数据分析、问题解决能力强；\n4、有良好的沟通能力和团队合作精神，具备快速适应环境变化的能力；\n5、有责任心，确保工作质量与效率。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628214706739792133","sourceKey":"bytedance","company":"字节跳动","title":"下一代多模态智能审核大模型及Agentic技术研究-TikTok内容安全算法","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628214706739792133/detail","duty":"团队介绍：国际化内容安全算法研究团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，团队同时负责产品基座大模型的研发，我们在研发过程中需要解决数据合规、模型推理能力、多语种性能优化等方面的问题，从而为平台上的内容审核、搜索、推荐等多项业务提供安全合规，性能优越的基座模型。\n\n课题介绍：\n随着AIGC爆发与内容生态全球化，审核面临策略动态演变、多语言多模态复杂度激增、生成式对抗攻击升级三大挑战，传统\"感知→分类\"范式已触顶。本课题聚焦两大前沿方向：\n1、多模态审核基座——研究大规模MoE架构训练与路由优化、多模态（文本/图像/视频/音频）跨模态对齐与推理、理解与生成统一建模（Unified Understanding & Generation）、面向审核场景的高质量合成数据生产（Self-play/对抗增强），构建超越现有开源/闭源模型的审核基座；\n2、Agentic审核系统——借鉴Agent-R1等前沿范式，以强化学习（GRPO/PPO）端到端训练审核Agent的多步决策能力，通过Context Engineering动态组装审核上下文，基于MCP协议构建工具生态（OCR/ASR/Knowledge Graph/策略RAG/实时搜索），实现审核任务的自主规划、Tool Call协同与可解释性闭环，驱动审核从被动分类向主动智能决策范式跃迁。\n\n课题挑战：\n1、MoE多模态安全基座：大规模稀疏MoE训练稳定性与路由优化、跨模态Token对齐、理解与生成统一架构设计；\n2、RL驱动Agentic决策：基于GRPO/PPO端到端训练Agent多步推理与工具调用策略，突破样本效率与训练稳定性瓶颈；\n3、Context Engineering与工具协同：动态上下文组装、MCP工具生态构建、多源异构证据融合与GraphRAG策略检索；\n4、泛化与对抗鲁棒性：跨200+语言/策略泛化、AIGC生成内容对抗检测、少样本场景的多维Reward信号设计。\n\n课题价值：\n1、技术引领：RL × Agentic × 多模态大模型的交叉融合是当前AI最前沿方向，本课题率先将其落地于大规模内容审核场景，具备独特的工业级数据规模与真实反馈闭环优势；\n2、业务价值：服务全球数十亿用户内容安全，推动审核从人工+外部API依赖向自主Agent全机审演进，直接降低数亿美元级成本，同时提升审核一致性与响应速度；\n3、行业领先：当前业界尚无成熟的RL驱动Agentic审核系统，本课题有望定义该方向的技术范式，产出具有行业影响力的研究成果。","requirements":"1、2027届毕业，获得博士学位，计算机、电子、数学、物理等相关专业；\n2、丰富的ML/CV/NLP/推荐经验，包括但不限于：\n1）机器学习/数据挖掘/CV/NLP/多模态等相关竞赛或行业经验；\n2）机器学习/数据挖掘/人工智能/大模型相关领域的会议论文（KDD/WWW/NIPS/ICML/CVPR/ACL/AAAI）；\n3）有大模型/强化学习相关的研究经历和创新探索；动手快，在开源社区有大模型相关的贡献记录；在业务场景有大模型落地经验者优先；\n3、具备扎实的编码能力、数据结构和基础算法功底，熟练运用各种算法框架与工程框架，熟悉Python/C++等编程语言；\n4、优秀的分析问题和解决问题的能力，并热衷于解决具有挑战性的问题；\n5、对技术充满热情，良好的沟通能力和团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675940689016998149","sourceKey":"bytedance","company":"字节跳动","title":"模型运营（IP与版权方向） - 内容质量与数据服务平台","city":"成都","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675940689016998149/detail","duty":"团队介绍：抖音内容质量与数据服务平台（简称CQC）归属于抖音集团，负责今日头条、抖音等产品内容和抖音集团商业内容的安全质量与体验。平台下设内容质量中心、商业生态与安全、生态治理与增长支持等业务，在全国20余个城市均有分布。\n自成立以来，CQC持续守护抖音集团旗下包括抖音、今日头条、番茄小说、飞书、红果短剧等产品在内的安全、质量与体验，优化产品内创作与交流环境，且在各产品运营增长方面开展支持工作。\n\n1、通过AI应用提升版权治理、数据采集以及标注等环节交付质量和效率，结合业务要求完成任务拆解、方案设计、实验验证与效果复盘；\n2、围绕LLM、VLM、多模态模型能力，参与数据构建、模型适配、效果治理、部署上线、质量监控、数据回流等关键环节，并与算法、工程、产品、业务等团队协作，推动技术方案落地，并将模型能力转化为可量化的业务收益；\n3、建设和优化治理集、负面案例分析、数据回流、质量监控和SOP机制，推动单项目经验沉淀为可复用的方法论和流程资产；\n4、关注前沿AI Engineering技术栈，包括Context Engineering、Agent Engineering、工具调用、MCP、LLMOps、EvalOps、多模态理解、模型适配、推理部署优化等，并能结合业务场景判断适用性。","requirements":"1、2027届获得本科及以上学历，计算机、数学、人工智能等相关方向优先；\n2、对前沿AI技术保持关注，具备AI模型应用实践经验优先；具备AI模型应用或算法工程相关实践经验，熟悉模型训练/微调、推理调用、效果评测、数据构建、线上应用中的一个或多个关键环节；\n3、熟练掌握Python，具备基础工程开发能力；熟悉SQL/PySpark或其他数据处理工具，能够独立完成数据分析、样本构建、实验验证与效果归因；\n4、具备较强的问题拆解和方案设计能力，能够基于业务需求和问题快速建立分析框架，输出可执行方案；自驱力强，沟通协作能力好，愿意在复杂业务场景中主动探索、推动落地并沉淀方法论。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669711027556305157","sourceKey":"bytedance","company":"字节跳动","title":"B端增长平台产品经理 - 番茄小说","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669711027556305157/detail","duty":"团队介绍：番茄小说是抖音在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n\n1、负责番茄增长平台的产品迭代工作，包括短剧、小说、有声书等体裁的内容推广和功能优化；\n2、深入理解广告投放内容的全链路流程，能够与市场主流广告媒体渠道对接，为客户搭建高效的广告投放工具，支撑业务规模增长；\n3、与内部运营、研发团队紧密配合，积极推动各协作方，保证项目高质量落地，为结果负责；\n4、主动捕捉市场信息变化与行业新机，收集外部客户的平台使用痛点，并提供有效的功能解决方案。","requirements":"1、2027届获得本科及以上学历；\n2、有广告增长相关实习经验优先；\n3、逻辑严谨，目标意识强、执行力强，具备较好的平台型产品抽象能力，有良好的沟通表达能力、项目管理能力及跨部门组织协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7647000977224878341","sourceKey":"bytedance","company":"字节跳动","title":"产品业务架构实习生-数据平台","city":"北京","category":"销售","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7647000977224878341/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、参与客户业务调研，将业务痛点翻译为数据/AI场景需求，识别“可被Demo快速验证”的高价值切入点；\n2、在2–4周内交付可运行原型（含智能问数测试、DataAgent样板间搭建、Agent工作流编排），完成数据接入、Prompt调优、效果验证全链路；\n3、在客户现场独立完成“业务问题→数据→结论→应用”闭环；需求模糊时主动定义问题、推动落地，对结果负责；\n4、将一线发现的高价值需求与产品差距结构化回流至火山引擎产品团队，参与产品路线图迭代；\n5、将单客户验证成功的方案抽象为标准化Skills/Agent模板，推动“碎石路→高速公路”的能力复用。","requirements":"1、2027届本科及以上学历在读，数据相关专业优先；\n2、熟练使用SQL，并了解至少一种主流BI工具；有CDP、UBA、MA等数据产品使用经验更佳；\n3、理解LLM、RAG、Agent、Tool-use等基本原理，能够独立完成端到端Agent Demo搭建，并对“可被Agent消费”的数据形态有认知；\n4、熟悉Python，了解或使用过扣子、HiAgent、Dify等Agent平台；有LangGraph、LangChain、Prompt Engineering、Agent Harness等实践经验优先；\n5、持续关注国内外AI/数据产品和行业趋势，能够结合产品演进判断业务落地价值与可行性；\n6、能清晰拆解复杂技术和业务问题，与客户及产品团队高效沟通：\n1）具备流畅阅读英文技术文档、论文和国际产品资料的能力；\n2）具备较强判断力、独立闭环能力和主动推动意识，能从业务问题出发，完成“问题—数据—结论—应用”的落地，并用业务指标量化交付价值。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7611094049239714101","sourceKey":"bytedance","company":"字节跳动","title":"机器学习算法实习生-TikTok业务风控","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7611094049239714101/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\nTikTok业务风控团队致力于保护TikTok的用户权益，包括但不限于内容消费者、创造者、商业客户等。我们通过建设高效的风控系统和智能的风控算法，提供端到端技术解决方案，以保证平台的健康与社区体验的真实性，为TikTok业务保驾护航。\n\n1、开发TikTok业务域的风控技术；利用规则/算法/模型，打击包括但不限于国际化业务的虚假账号、刷粉刷赞、垃圾导流、信息盗取、欺诈牟利等方向的风险；\n2、结合业务发展方向，建设持久高效、模块化可移植的风险防控体系，提升风控方案在机器学习、分析与防御纵深上的竞争力，降低面对新业务、新作弊手段的风控成本。","requirements":"1、2027届硕士及以上学位在读，人工智能、计算机、软件、数学等相关专业优先；\n2、有坚实的工程能力；熟练操作Linux、Hadoop、Hive、Spark、Storm等相关工程工具中至少两项；\n3、熟悉数据挖掘或机器学习；精通深度学习、时序/图学习、半监督/无监督/迁移学习者优先；\n4、思考与沟通层面，客观全面、数据驱动、自驱力强；\n5、英语听说读写能力满足业务与技术沟通需要。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686503387492878597","sourceKey":"bytedance","company":"字节跳动","title":"活动运营（演出合作方向）实习生 - 汽水音乐","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686503387492878597/detail","duty":"团队介绍：汽水音乐是字节跳动推出的一款音乐应用软件，是一款面向热爱音乐潮流的年轻人的听歌平台。核心功能包括听推荐、歌单、榜单、搜索。其歌曲切换方式与抖音短视频类似，采用手动上下滑屏操作，简单便捷，易于上手。我们致力于成为具有影响力的音乐平台，成为让用户最容易发现音乐、了解音乐、进行音乐表达和创作、围绕音乐交流的社区。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责明星演唱会、音乐节等演出合作项目的活动对接和执行，通过内外团队协作沟通，保障活动落地顺畅；\n2、相关活动资源和物料的制作与交付，运营活动数据的追踪、整理与分析，能够从数据和日常案例中提炼和产出有价值的结论和创新玩法；\n3、日常持续监测演出行业活动、平台玩法等，参与策划并落地相关合作案例，探索多元合作形态。","requirements":"1、本科及以上学历在读，专业不限；\n2、有平台/内容社区/演出公司或厂牌的传播运营、演出及明星合作经验；\n3、细心严谨、关注数据和结果、沟通能力强，有良好的沟通协作能力和负责人意识，能够自主推进项目进度和闭环处理部分问题；\n4、对年轻用户文化、演出生态、追星生态敏感，5G冲浪有网感、有较强的文案功底和审美能力；\n5、熟练掌握PS、PR、AI、Figma等图频编辑软件优先；\n6、每周至少保证4天的全天实习时间，实习期3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680429860201171253","sourceKey":"bytedance","company":"字节跳动","title":"AI数据项目运营（语言方向）实习生 - TikTok","city":"北京/上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680429860201171253/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok ADSO（AI Data Service and Operations）团队负责支撑AI 模型训练、评估与优化的核心数据服务与运营。通过构建高质量、标准化的数据生产体系，以及建立全球化的精益运营模式，为TikTok产品各类 AI 能力的迭代提供稳定、规模化、高性价比的数据支持，推动 AI 技术在复杂业务场景中的深度落地。\n\n加入我们，在真实的全球化 AI 业务中快速成长。你将与顶尖的算法、产品、工程团队协作，在实战中理解 AI 如何真正落地。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、学习大模型方向数据标注的规则和标准，协助标注项目的运营与管理；\n2、熟练使用标注工具，及时监控项目进度，识别并跟进项目风险，保障项目顺利交付；\n3、按计划完成数据质量检查，做好任务的自我管理及分配，保证效率和质量；\n4、定期总结项目质量问题，开展问题分析并提供反馈，推动相关问题解决；\n5、结合项目需求开展多语种及跨文化调研，为项目决策和运营优化提供支持；\n6、协助AI Agent搭建、AI Skill编写及优化，使用AI辅助编程（Vibe Coding）等方式探索运营提效方案并推动落地，以英语作为工作语言与国际同事协作推进项目，做好信息同步、需求对齐和跨文化沟通。","requirements":"1、本科及以上学历在读，应用语言学、翻译、小语种、商业分析等相关专业优先；\n2、具备优秀的英语听说读写能力，能够将英语作为工作语言；具备较强的跨文化沟通能力，能够与国际化同事清晰、高效地协作；\n3、每周保证实习至少4个工作日，能够连续实习3个月及以上；可接受跨时差工作者优先；\n4、具备较强的学习能力和逻辑思维，能够快速理解新业务、新规则和新工具，并具备多项目并行处理能力及适应需求动态调整的工作环境；对AI Agent、AI Skill及AI辅助编程等方向有兴趣；有AI Skill搭建或使用经验者优先；\n5、具备良好的数据分析能力及相关经验，能够使用数据定位问题、形成判断并支持项目推进；\n6、具备较强的沟通协调能力、责任感，能够合理判断优先级并推动任务按计划完成。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670915245922208053","sourceKey":"bytedance","company":"字节跳动","title":"光学设计工程师 - PICO","city":"北京/上海","category":"硬件","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670915245922208053/detail","duty":"团队介绍：作为一家拥有自主创新和研发创造能力的科技品牌，PICO致力于成为领先的世界级XR平台，成就开发者与创作者，共同为全球消费者创造更美好的生活体验。我们开创性地将虚拟现实扩展到了多个领域，为运动、视频、娱乐等消费级场景带来了全新体验；并广泛应用在教育、医疗和企业培训等商用场景，给全球企业级用户提供了多元化的VR解决方案。\n\n1、探索微纳光学结构和系统在AR/VR显示中的应用；\n2、光学模拟与仿真显示系统中的关键光学元件与模组；\n3、开发AR/VR显示系统的光学仿真算法与平台。","requirements":"1、2027届获得硕士及以上学位，物理、光学、电子科学专业优先；\n2、在衍射光学、微纳结构光学和计算电磁学等领域有研究经历和背景；有较强的编程能力，熟悉Python、MATLAB等编程语言；熟练使用Virtual Lab，LightTools、Code V、Zemax等仿真软件；\n3、熟悉近眼显示光学系统的设计、仿真、搭建或者元器件制造。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669623331367241989","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（内容电商B端/商家达人撮合方向） - TikTok Shop","city":"北京/珠海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669623331367241989/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、建设与迭代TikTok Shop Partner的AI智能化产品，为第三方伙伴、商家和达人提供更高效、好用的AI工具与服务能力；\n2、面向全球市场，从平台、商家、达人及服务商/代理商等多角色视角分析业务链路，围绕商家/达人在平台的成长链路，探索并落地从入驻签约、达人/商品推荐、平台撮合、咨询服务、经营诊断等相关场景，提升商家与达人的匹配效率、经营效果和服务满意度；\n3、深入调研服务商/代理商、商家、达人的现状和诉求，结合平台现有能力开展洞察、诊断，为AI化产品改造提供高可行性的建议；\n4、借助AI工具优化内部SOP、FAQ、Wiki等知识管理体系，完成业务数据与标杆案例的高效分析，沉淀方法论，推动跨团队协同，并持续监控效果、复盘总结。","requirements":"1、2027届获得本科及以上学历，数据科学、计算机、AI等相关专业优先；\n2、有电商、交易、AI产品等相关实践经验者优先，目标&结果导向，具备较强的业务理解、产品判断能力、数据意识、逻辑分析和学习能力，能够结合数据、调研和行业观察持续推动产品迭代；\n3、关注AI/大模型在内容生产、选品备货和经营提效中的应用，有相关实践经验者优先优先；\n4、具备优秀的沟通协作能力、自驱力和责任心，能够适应国际化业务环境，英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668570322971478325","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发/测试开发工程师（智能创作） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668570322971478325/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、我们希望寻找具备扎实工程基础、全栈潜力和AI原生能力的应届毕业生，加入TikTok各业务质量工程团队，区别于传统意义上的“测试执行”岗位，这是一个以质量场景为切入点，面向复杂系统和智能工程建设的研发岗位；\n2、参与业务质量平台、研发效能工具和自动化基础设施的设计与开发，覆盖前端、后端、数据链路和平台能力建设；\n3、深入客户端、服务端及上下游协同链路，建设功能、接口、稳定性、性能、安全等多维质量保障能力；通过代码分析、链路分析、日志分析、压测、故障演练等方式发现复杂系统中的深层问题，并推动问题闭环；\n4、探索并落地AI在质量工程中的应用，包括测试生成、智能缺陷分析、质量评测、测试智能体、自主探索式测试等方向；\n5、沉淀可复用的工程能力，包括测试框架、诊断工具、自动化脚本、质量方法论与平台化能力；与研发、产品、算法、数据等团队协作，共同推动质量内建、研发提效和工程规范升级。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化、数学等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构与算法的核心思想，能够将抽象问题转化为可实现、可优化的工程方案；熟悉至少一门编程语言，如Go、Java、Python、TypeScript/C++等，具备独立完成中型工程项目或核心模块开发的能力；\n3、理解操作系统、计算机网络、数据库、并发编程、常见系统架构等基础知识；对软件工程有基本理解，熟悉从需求分析、设计实现到测试验证、上线迭代的研发流程；\n4、具备良好的问题拆解能力、系统性思维和学习能力，能够面对复杂问题持续追问本质并推动解决；具备良好的沟通协作能力和责任心，能够在跨团队、多角色合作中推动目标达成；\n5、能熟练使用AI工具辅助编码、排障、文档理解和方案设计，具备对AI输出进行判断、校验和二次加工的能力；对AI在测试与质量场景中的应用有兴趣，对大语言模型、Agent、RAG、模型评测、自动化工作流等AI工程方向有认知或实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668313449182415109","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发工程师（客户端） - 豆包","city":"杭州/北京","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668313449182415109/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、负责字节跳动AI产品的全栈开发工作（iOS、Android、Harmony、Rust）；\n2、负责高质量的设计和编码，承担重点、难点的技术攻坚，参与项目架构设计与实现，提升研发效率；\n3、参与App性能、体验优化及质量监控评估体系建设；\n4、参与AI研发流程的效率提升。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和技术，对AI产品有浓厚兴趣；\n3、扎实的数据结构和算法基础；精通至少一门编程语言，包括但不限于：Java、Kotlin、Objective-C、Swift、C、C++；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、对新技术保持热情，具备良好的分析、解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668288833993591093","sourceKey":"bytedance","company":"字节跳动","title":"招商运营经理 - 抖音品牌营销与星图达人","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668288833993591093/detail","duty":"团队介绍：品牌营销与星图达人为抖音、今日头条等全产品矩阵提供一体化品牌与达人营销解决方案，助力品牌实现精准触达与高效增长。依托行业领先的达人匹配算法、全链路数据洞察能力及创新的品牌营销产品和样式，我们打破内容与商业的壁垒，让品牌营销更具创意、更显精准、更有温度。\n在这里，你将深度参与全球领先的达人营销生态建设，接触行业前沿的AI与营销产品结合、创新的品牌营销策略。你将与顶尖团队并肩，在品牌广告与达人营销的创新浪潮中，不断探索品牌营销的新可能，在数字营销领域快速成长。\n\n1、深度洞察行业客户全年营销需求与节点（如新品季、大促期、品牌日），设计可规模化复用的行业属性IP矩阵，建立IP标准化运营手册，覆盖创意策划、资源包定价、执行SOP，实现跨行业/行业内快速复制；\n2、具备出色的营销策划能力，结合抖音内容生态及特色，可独立撰写完整且有亮点的方案，熟悉招商模式和资源，有内容生产或者项目策划招商经验；能产出行业突破性的创新创意方案；\n3、强结果导向，为行业的招商收入目标负责；\n4、较强的理解沟通和表达能力，对外建立与销售团队及客户的沟通机制，也可支持对客提案、产出定制IP；\n5、对行业人群、内容和营销策略有较深了解，可整合资源产出用户/行业趋势报告，开展市场教育工作、打造B端影响力。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、有商业化/4A公司/媒体从业经验，有快消、耐消、本地行业经验，具备3个以上完整IP招商案例优先；交付高，协同能力好；对做好的商业内容有热情、有坚持、有信仰；\n3、有内容感知和内容审美。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668193298212735285","sourceKey":"bytedance","company":"字节跳动","title":"滋补保健电商运营 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668193298212735285/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合抖音内容特性，制定行业在抖音产品内的完整运营策略，根据滋补保健行业的特性、发展阶段及竞争趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、对滋补保健行业兴趣度高，有较强的好奇心和快速学习的能力；\n3、了解抖音的短视频和直播流量规律，关注内容电商的玩法。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，有行业运营、类目运营、商品运营等实习经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有团队合作精神，较好的协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667560462148290821","sourceKey":"bytedance","company":"字节跳动","title":"安全合规工程师（认证与制度方向） - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667560462148290821/detail","duty":"团队介绍：安全治理与合规团队在保障字节跳动全域安全与合规要求落地的同时，为业务发展提供支持。\n我们负责制定并维护多领域的治理框架，涵盖安全认证、政策制定、隐私保护、内部威胁防控、数据合规及法规遵循等方面。\n通过推动治理、风险与合规（GRC）领域的精细化建设，我们在字节跳动信息安全战略的构建中发挥着关键作用。\n\n1、负责团队ISO管理体系、SOC审计认证等全流程工作；\n2、独立完成安全资质认证前所需的体系文件、申报资料等材料的编制与梳理；\n3、统筹跟进认证审核过程中发现问题的整改追踪与闭环落地；\n4、参与安全合规相关制度、流程的建设与优化工作。","requirements":"1、2027届获得本科及以上学历，计算机、软件开发、信息安全等相关专业优先；\n2、熟悉网络安全法、等保、ISO27001等相关标准和规范；\n3、责任心强，学习能力优秀，具备良好的逻辑思维能力和跨团队协作能力；\n4、有相关认证或合规项目实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667534821039982853","sourceKey":"bytedance","company":"字节跳动","title":"Agent研发工程师 - 抖音","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667534821039982853/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n1、参与面向业务场景的Agent系统设计与研发，构建覆盖需求理解、测试生成、代码评审、缺陷发现等核心场景的端到端Agent工作流；持续跟进前沿技术，推动新技术在质量场景中的落地应用，形成可验证的业务价值；\n2、参与Agent核心链路建设，包括任务规划、上下文构建、多工具调用编排、结果汇总验证等关键环节，持续提升Agent的分析深度、稳定性与可靠性；\n3、参与可复用Agent框架的设计与沉淀，包括通用任务模板、工具协议规范、执行管控机制、调试与评测能力，提升多场景下的复用效率与工程化水平。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟练掌握Python/Java/Go至少一门编程语言；\n3、熟悉主流Agent编排框架与开源生态，熟悉Agent范式并有实际的项目经验；\n4、良好的结构化表达能力与独立思考能力，能够在快速变化的AI领域中主动探索、持续学习与落地。\n\n加分项\n1、有开源项目贡献、技术博客或优秀的AI Agent个人项目；\n2、有程序分析、质量保障相关领域的研究经验；\n3、发表过AI或软件工程领域顶级会议/期刊论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667097616880404741","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent移动端研发工程师 - 开发者服务","city":"深圳/广州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667097616880404741/detail","duty":"团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、参与字节跳动客户端统一AI测试框架的建设，参与新一代AI自动化测试相关服务建设，包括用例生成、用例驱动，智能执行、智能断言等；\n2、参与AI自动化测试相关的客户端SDK，框架，MCP工具建设，包括测试环境构造，UI驱动，弹窗管理，日志抓取，网络抓包，应用问题排查，模拟器问题排查，设备问题排查等；\n3、深入业务团队（抖音、今日头条、飞书等），解决业务需求，协助业务排查问题，降低测试成本，提升测试效率，提升产品体验。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、自动化、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握至少一门编程语言，包括但不限于Python、Java、Go等；\n3、了解AI Agent相关技术与设计思想，了解主流AI模型及其应用场景；\n4、有从0-1搭建AI Agent应用经验，能够独立完成Agent应用的设计开发者优先；\n5、在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628639914620766517","sourceKey":"bytedance","company":"字节跳动","title":"风控垂域大模型基座和Agentic AI研究-风控","city":"杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628639914620766517/detail","duty":"团队介绍：风控算法团队深耕于抖音（短视频、直播、电商、本地生活等）、今日头条等多个字节系业务，涵盖内容、交易、流量、账号等多个场景的底线风险治理、黑灰产对抗及复杂反作弊等关键任务。风控场景具有对抗性极强、逻辑推理链路长及海量多模态数据等挑战。目前，团队正积极推进大语言模型（LLM/MLLM）与 Agentic AI 技术的深入研究与工业化落地。通过探索前沿的模型训练范式、自主规划的 Agent 架构以及严谨的 Harness Engineering 体系，我们致力于打造下一代智能风控基础设施，为十亿级用户的社区生态保驾护航。\n\n课题介绍：\nAI 技术的飞速发展大幅提升了风控场景下的风险识别与对抗能力，但仍面临多维度挑战：主流 SOTA 大模型在强对抗风险内容理解及 AIGC 深度伪造识别上存在明显瓶颈；面对黑产手法的瞬息万变，风控亟需建设基于 Agent 的自主对抗方案，以强化对抗时效并降低运营成本；针对风控场景依赖数据多、判别规则复杂的挑战，需重点突破跨模态长上下文信息抽取及复杂合规标准的指令遵循难题。\n本课题将通过大模型全链路优化、智能 Agent 体系建设与范式创新，系统性提升全场景风控的智能化水平。\n\n课题挑战：\n1、打造具有优势的风控垂域大模型基座：深入研究CPT、SFT、RL及训练与推理加速等技术的突破与创新；重点攻克强对抗环境下的多模态（文本、图片、音频、视频）理解难题，提升模型在超长上下文、复杂逻辑推理和精准指令遵循等方面的表现；\n2、Agentic AI架构研究与演进：探索与推进风控 Agentic AI的架构设计和工业化落地，打磨领域Skill/Tool框架，优化复杂工具调用、长短期记忆管理、长链路任务编排和Multi-Agent协同等，打造具备自演进能力的下一代智能风控架构；\n3、大模型结构化数据的理解和应用：探索大模型与结构化数据（如行为序列、图谱及表格等）的深度融合方案，研究包括数据语义化表征、跨模态对齐及 Graph-LLM 等前沿架构，利用 LLM 的推理能力，提升复杂风控场景下的风险识别精度与决策可解释性；\n4、科学评估与Harness Engineering体系构建：构建高质量的领域数据集，设计科学严谨的Benchmark评测体系，构建工业级Harness Engineering系统，确保模型能力的规模化验证与安全性，持续驱动模型能力边界的突破。\n\n课题价值：\n1、打造具有优势的风控垂域大模型，显著增强对复杂、跨领域风险的识别，从底层降低风险漏过率；\n2、定义风控场景 Agentic AI 的落地范式，构建自演化对抗体系，在持续对抗新型风险的同时，大幅降低人工运营成本。","requirements":"1、2027届毕业，获得博士学位，计算机、机器学习和数学相关专业优先；\n2、扎实的算法与数据结构基础，熟练掌握Python/Go/C++等至少一门编程语言，具备优秀的工程落地能力；\n3、在LLM/MLM/Agent等AI技术领域有扎实积累，在NeurIPS/ICML/ICLR/ACL/CVPR等顶会发表过相关高质量论文者优先；\n4、具备系统的研究思维与独立思考能力，对风控领域的复杂性、对抗性有浓厚兴趣，敢于挑战现有技术范式。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628624863555143941","sourceKey":"bytedance","company":"字节跳动","title":"【实习】基于多模态大模型与用户行为理解的下一代分发与交互技术-抖音（北京/上海/杭州/深圳）","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628624863555143941/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n课题介绍：本课题旨在探索基于多模态大模型的模态理解与表征、世界知识、推理等能力，并深度的与信息分发（推荐、搜索等）中的用户行为理解和建模结合起来，构建支撑下一代分发与交互技术的基础模型和系统范式。通过基础技术突破和探索，既尝试解决原有分发技术中对长尾兴趣分发、用户复杂意图理解、多模态与行为协同融合、System Bias、分发系统的算力与推理分配等一系列关键问题，也探索基于新的多模态大模型与用户对齐的理解，支持全新的可对话性需求满足、可自然交互性的分发调节与个性化等能力和产品形态上的突破。\n\n课题挑战：\n1、多模态大模型的完整流程的训练，以及与大规模用户行为深度理解和对齐；\n2、突破多模态大模型与长序列高并发高效推理的瓶颈；\n3、实现大模型泛化推理能力与复杂推荐业务目标的深度对齐。\n\n课题价值：\n1、打破信息茧房，提供个性化可解释推荐，提升长尾/冷启分发效率；\n2、沉淀大模型Scaling Up范式，重塑大模型时代的下一代推荐系统；\n3、探索全新的支持下一代交互场景的分发基础技术突破。","requirements":"1、2027届及以后毕业，博士在读，人工智能、计算机、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练C/C++（传统编码方向）或Python（智能编码方向）； \n3、智能编码方向要求有扎实的机器学习基础，在TPAMI/CVPR/NeurIPS/ICCV等顶级期刊会议上发表论文者优先； \n4、有向标准组织提出过提案并参加标准会议经验的同学优先；\n5、出色的问题分析和解决能力，有自主探索解决方案的能力，良好的沟通协作能力，能和团队一起探索新技术，推进技术进步；\n6、出色的心理素质与应变能力，面对困难勇于迎接挑战；面对复杂局面沉着、冷静、灵活。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628089044314114309","sourceKey":"bytedance","company":"字节跳动","title":"【实习】大模型驱动的内容生产与分发：IP跨体裁生成与LLM推荐-番茄（北京/上海/杭州/深圳）","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628089044314114309/detail","duty":"团队介绍：Data-番茄团队，负责字节跳动下番茄小说、红果短剧、番茄畅听、国际化短剧等产品的推荐算法和AI相关工作。我们的工作包括优化业界前沿的大规模推荐系统，探索LLM与推荐的结合，并落地生成式推荐范式，从小说、短剧、音频、音乐等内容方向建设完整的内容生态和AI能力，保持业务规模保持超高速增长。\n\n课题介绍：番茄系聚合海量故事IP，今日头条拥有丰富内容形态，但生产与分发仍面临改编链路长、成本高，以及推荐过度依赖稀疏ID、对新内容/低活用户不友好等问题。本课题以多模态大模型为底座：在番茄通过LLM创作提效与结构化内容理解，构建IP资产并打通“小说→剧本→分镜→动态漫/短剧/音频”的生成与辅助创作；在小说、短剧、今日头条把内容理解信号融入推荐建模，提升兴趣捕捉与可解释分发，最终实现生产与分发协同提升。\n1、大模型推荐和推荐Agent：引入LLM的推理能力，以Seed为基础训练大模型执行推荐任务的能力，推荐Token和自然语言Token联合训练实现模态融合，让推荐系统具备理解自然语言的能力，从而用推荐Agent方式实现更具扩展性的分发交互体验\n2、突出强调利用大模型COT的推理能力，改进被动推荐效果\n3、遵循用户的正向、负向指令的能力，彻底解决用户反馈中“Dislike不生效”、新用户兴趣探索、用户调控推荐画风等难题\n4、在产品中提供和用户进行对话交互的能力，用户可根据自身需求调整推荐的效果\n5、消息推送系统中嵌入大模型的用户-内容推理匹配能力，追求在内容零展、低展的情况下精准、快速的推送给用户，实现极高的推送时效性\n6、构建基于大模型的推荐Agent能力，让大模型能和目前推荐系统业务策略和逻辑能更好的融合和调用。\n\n课题挑战：\n1、跨体裁一致性与可控生成；\n2、结构化理解准确可复用；\n3、模型落地成本/时延/轻量化；\n4、LLM与内容的对齐、解码方案探索，包括纯文本方案或基于SID的方案；\n5、LLM推荐指令COT数据集构建和个性化推荐推理能力的训练方法探索；\n6、用户推荐正向、负向指令理解和线上执行能力探索；\n7、推荐系统能力模块化&工具化，推荐Agent设计。\n\n课题价值：\n1、提效降本，提升IP产能与变现；\n2、增强推荐效果与可解释性；\n3、沉淀多模态通用底座；\n4、探索基于LLM推理能力的推荐范式。","requirements":"1、2027届及以后毕业，博士在读，计算机、软件、人工智能、数学等相关专业优先；\n2、扎实的机器学习基础，深入理解多模态理解及生成、推荐广告等相关技术，具备良好的数理基础和自学能力；\n3、熟练掌握相关机器学习框架和工程框架，具备扎实的编码能力；\n4、在多模态大模型领域有相关经验，尤其在长文本、影视剧领域有经验者优先；\n5、在计算机科学高水平会议和期刊（如NIPS、ICML、CVPR、ICCV、ECCV、IJCAI、AAAI、KDD、SIGIR、WWW、ACL、PAMI、IJCV等）发表过论文或具备竞赛经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594682731310958901","sourceKey":"bytedance","company":"字节跳动","title":"端侧大模型算法实习生-TikTok泛架构","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594682731310958901/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok泛架构团队处于业务和基础架构之间，我们的目标是拥抱AI，构建最先进的业务架构基建，建立公众信任和合规，关注资源管理和成本优化，用户体验和稳定性，提高工程质量和研发效率。在这里你既能感受到技术对上层业务的赋能，又可以提高在架构层面技术深度的理解，期待你的加入！\n\n1、在TikTok客户端环境内构建策略和AI算法模型，在智能决策、意图识别、内容理解等领域进行业务落地；\n2、和工程团队合作，分析和提升模型性能，包括但不限于推理速度、内存占用和能耗优化；\n3、参与适用于客户端的CV、NLP、LLM、MLLM等垂直基础能力模型的优化和落地；\n4、参与端智能算法的长期探索，如端侧大模型应用、隐私计算、端边云协同等；\n5、业务覆盖搜索、推荐、社交、直播等多个核心场景。","requirements":"1、2027届硕士及以上学位在读，计算机、软件工程等相关专业优先；\n2、扎实的算法基础（数据结构/机器学习/深度学习），熟练掌握Python，熟悉PyTorch框架，编码能力优秀；\n3、熟悉ML、强化学习、NLP、CV、等相关的技术，有性能优化策略、用户体验策略、流媒体优化等方向的实战经验优先；\n4、理解Transformer/BERT/GPT等模型架构，有LLM相关项目经验者优先；\n5、加分项：在顶会（CCF-A）发表过相关论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7547989395987613970","sourceKey":"bytedance","company":"字节跳动","title":"创意视觉设计实习生 - TikTok设计","city":"北京","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7547989395987613970/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok设计团队的目标是为全球数亿用户提供一流的用户体验，从而帮助用户更好的创作与表达，发现世界的多元与美好，不断打破隔阂，建立起人与人的连接。我们是一个国际化的设计团队，遍布中国、美国、新加坡等国家，世界各地的产品设计师、创意设计师、效果设计师、内容文案专家与本地化经理通力合作，把一个个不可能变成可能。\n\n加入我们，你就有机会理解世界不同地域的文化差异，分析并解决复杂的体验问题，进行前沿的设计探索，更能亲身主导如何把一个想法转化成服务亿级数量用户的产品体验。 如果你积极自驱，对世界充满好奇心和想象力，有希望通过设计打造一流的产品，同时又脚踏实地，欢迎成为我们的一员！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与TikTok增长玩法及营销活动的创意视觉设计；可根据活动需求快速理解画面的视觉调性，并完成同风格的延展设计；\n2、使用AIGC工具辅助素材生成、筛选、精修与设计落地，并探索通过Agent、固定工作流等方式提升重复性视觉工作的生产效率；\n3、做好交付前的设计自检，确保画面质量、信息准确性、尺寸规范及文件完整性；及时反馈问题和进度；\n4、参与设计素材整理、文件规范维护、资产归档及阶段性设计复盘。","requirements":"1、本科及以上学历在读，视觉传达、数字媒体、美术等设计相关专业；\n2、具备扎实的平面设计基础和良好的审美判断，能够独立判断画面的构图、色彩、版式、素材质量及整体完成度；熟练使用Photoshop、Illustrator、Figma等基础设计工具，并结合各类主流AI平台，以及AI Coding工具（Claude code/Cursor/Codex等）能够独立完成视觉素材的组合、调整和交付；\n3、具备一定工程化和系统化思维，愿意研究如何通过Agent、自动流程或可复用工作流提升视觉生产效率；\n4、能够准确接收设计需求，遇到问题及时沟通，交付前主动自检，对设计结果和交付质量负责；\n5、有较强的自驱力和学习能力、良好的沟通与协作能力，注重沉淀总结和复盘；\n6、热爱视觉设计，对自己的产出作品有严格的质量要求，对未知的事物保持好奇心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668320164205627653","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - Seed","city":"北京/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668320164205627653/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书AI Friendly产品及基础设施的设计、开发和持续演进；\n2、建设面向AI Agent的CLI、SDK、Skills、MCP工具及开放API；\n3、优化Agent执行复杂任务的成功率、延迟、Token消耗和稳定性；\n4、参与Agent身份、授权、事件订阅、审计与安全治理等企业级能力建设；\n5、关注AI Agent、AI Coding和开源生态的发展，探索并验证新的技术方向；\n6、参与开源项目建设，通过代码、文档和社区协作服务全球开发者。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构、算法、操作系统、计算机网络和数据库等基本原理，熟悉至少一种主流编程语言，如Go、Java、Python、TypeScript、C++等；\n3、具备良好的工程意识，能够编写结构清晰、可测试、可维护的代码；\n4、对大语言模型、AI Agent或开发者工具有浓厚兴趣，愿意持续学习并动手实践；\n5、有较强的问题分析能力、责任心和团队协作意识，能够主动推动问题闭环；\n6、不要求已经具备完整的AI项目经历，但希望你对新技术保持好奇，并有把想法做成产品的热情。\n\n【加分项】：\n1、使用过Claude Code、Codex、Cursor、OpenClaw等AI Coding或Agent产品；\n2、了解Function Calling、MCP、RAG、Agent Workflow、上下文工程等相关技术；\n3、有后端系统、分布式系统、开发者工具、CLI、SDK或开放平台开发经验；\n4、有大模型应用评测、Prompt/Skill优化或Agent工具设计经验；\n5、参与过开源项目，或拥有质量较高的课程项目、个人项目及技术博客。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668318655901976885","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent质量效能工程师 - Seed 产品研发","city":"杭州","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668318655901976885/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书AI Harness质量系统的构建与演进，围绕服务端、Web端、移动端及AI相关能力，建设面向真实业务场景的自动化验证、评测执行、结果分析与质量闭环能力；\n2、参与团队AI质量体系与工程体系建设，包括但不限于自动化评测、流程验证、持续集成、上线准入与质量门禁等；\n3、面向AI场景设计质量方案，覆盖结果质量、过程质量与系统稳定性，提升问题发现效率与质量反馈速度；\n4、参与线上问题追踪、归因分析与质量数据建设，推动问题从发现、定位到修复验证的闭环提效；\n5、参与通用质量工具、评测脚本与效率平台建设，提升团队在复杂业务和AI场景下的验证效率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化等相关专业优先；\n2、熟练使用至少一种AI编程工具，包含但不限于Claude、Codex、TRAE等，能够将AI能力应用于自动化验证、评测脚本开发、问题分析与质量效率优化等场景，具备基础的编程能力，至少熟悉一门常用开发语言，包括但不限于Python、Golang、Java、C/C++等，有脚本开发、工具开发或工程实践经验者优先；\n3、具备扎实的计算机基础知识，了解网络通信基础，包括TCP/IP、HTTP等常见协议，了解常见的自动化方法、数据驱动验证思路或持续集成流程，有质量工具、评测平台、自动化流程或工程效率建设经验者优先；\n4、对AI产品质量、自动化验证、评测体系或工程效率方向有兴趣，理解除“结果是否正确”之外，还需要关注“过程是否可控、系统是否稳定、反馈是否高效”；\n5、了解常见算法评测方法与客观评估指标，有大模型、搜索、NLP、语音、多模态等相关评测经验者优先；\n6、具备良好的问题分析与协作能力，能够从业务、流程与系统多个层面推动质量与效率持续优化。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668252752879028533","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发工程师 - 业务中台","city":"北京/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668252752879028533/detail","duty":"团队介绍：团队负责公司多个跨产品业务方向，提供可复用的平台能力及技术解决方案。我们为公司多业务提供如地理位置、行业数据等多类型的中台能力与技术解决方案，积极利用AI等技术做中台能力提效与升级。\n加入我们，你将有机会从中台的多视角参与业务建设，感受不同类型/阶段的业务特点；通过用户场景的开发&架构工作，学习和解决极富挑战的技术问题；你也可以从数据出发，积极利用策略和模型，为业务提供有价值的助力。\n\n1、参与前端、全栈功能开发，提升产品的易用性与交互体验；\n2、与产品、算法、设计等角色协作，理解业务逻辑并实现高质量的产品功能；\n3、优化系统性能与可维护性，参与组件化、工程化建设；\n4、参与代码评审、单元测试与前后端工程规范建设。","requirements":"1、2027届获得本科及以上学历，计算机、通信和电子信息科学、数学等相关专业；\n2、具备良好的计算机基础（数据结构、算法、计算机网络、操作系统等），并熟练使用至少一门编程语言；\n3、具备前端（JS/TS/Vue/React等）、客户端（Flutter/iOS/Android任一）、服务端（Golang/Python/Java任一）任一领域的开发经验，有全栈开发经验者优先；\n4、熟练使用TRAE、Claude Code、Codex、Cursor等任一AI Coding工具，维护过Rules、MCP、Skills并了解底层机制与技术细节的同学优先；\n5、认可AI Coder定位，明确自身长期全栈发展规划，具备较强的学习能力和适应能力，能快速上手新领域技术，适配业务驱动的开发模式；\n6、积极乐观，责任心强，具备良好的沟通协作能力、逻辑思维能力以及服务意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667093439687772421","sourceKey":"bytedance","company":"字节跳动","title":"计算SRE - AI算力基础设施","city":"北京/杭州/上海","category":"运维","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667093439687772421/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、参与大规模计算集群（物理机、容器、GPU）的稳定性建设：容量规划、容灾演练、故障定位与根因治理，保障业务与大模型训推的SLO；\n2、参与算力资源效率经营：CPU、GPU利用率提升、在离线混部、资源池化与弹性调度、成本优化，用数据驱动资源的“存—调—取”闭环；\n3、面向AI Infra建设系统化运维解决方案：训练、推理集群的交付、压测、GPU故障自愈与稳定性守护；\n4、参与设计并实现支撑大规模集群的自动化运营平台与工具链，把重复运维沉淀为可复用的平台能力；\n5、探索AIOps/运维Agent：用LLM与智能体能力做告警降噪、变更观测、无人值守与智能盯屏，降低人力投入、提升响应速度。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、通信等相关专业优先；\n2、扎实的计算机基础（操作系统、网络、数据结构），熟悉Linux负载模型、资源模型、网络IO模型等；\n3、熟悉至少1门开发语言（Go/C、C++/Java/Python/JavaScript等），有独立编码与工程落地能力；\n4、善于从系统全局思考问题，面对复杂、模糊的场景敢于挑战、能拿结果；自驱学习、乐于协作。\n\n加分项（满足其一即可，非硬性）\n1、有分布式系统、云计算（K8s/容器/虚拟化）、或GPU/AI训练推理相关的项目、实习或研究经历；\n2、熟悉调度、资源管理、性能调优，或有可观测性/稳定性方向的实践；\n3、有用AI/LLM/Agent解决实际工程问题的经历，或对AIOps方向有热情；\n4、有开源贡献、ACM/竞赛、顶会论文，或独立完成过有一定复杂度的系统。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7586935421349267717","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-TikTok生活服务","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7586935421349267717/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\nTikTok Local Services，我们以‘激发新生活，助力好生意’为使命，致力于成为全球用户与合作伙伴的首选生活服务平台。我们不断努力为用户提供更丰富、独特的生活体验，同时为合作伙伴打造一个包容且公平的健康商业生态。在这里，你将充分参与国际化生活服务业务的各个阶段，经历早期到全球布局流程。\n\n1、负责国际化短视频算法工作，共同搭建业界领先的推荐系统，为用户提供一流的产品体验；\n2、深度结合机器学习技术和各场景业务（内容消费，社交，推送，关注等），优化模型&策略，持续提升推荐效果；\n3、应用先进的机器学习技术解决各种在线/离线，大数据量/小数据量，长期/短期信号等不同场景遇到的各种挑战，包括标签缺失，反馈周期长，收敛速度慢，信号相关性弱等；\n4、和产品以及运营团队紧密合作，对用户、作者的行为做深入的理解和分析，制定针对的算法策略促进生态良性发展。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n4、对技术有热情，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎相关领域有经验者优先；\n6、实习时间4个月及以上，每周至少4天。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676406754099398965","sourceKey":"bytedance","company":"字节跳动","title":"美区POP商家运营实习生（汽摩工具组） - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676406754099398965/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、挖掘平台特点和商家需求，协助团队跟进和解决商家日常运营问题，梳理商家运营流程并不断迭代；\n2、协助团队跟进营销、直播等重点项目推进；\n3、通过数据分析，不断协助商家优化选品、流量策略、内容策略等运营方向。","requirements":"1、本科及以上学历在读；\n2、熟练使用办公软件；对数据敏感，擅长分析与总结；\n3、对电商行业有基本了解，熟悉短视频平台及欧美社交媒体更优；\n4、英语流利，英文读写能力强，有国际化欧美留学背景更优；\n5、耐心负责，具备良好的团队协作能力，沟通能力强，思维活跃，逻辑清晰，工作高效；\n6、每周可实习5天，可以实习至少3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668630955884267781","sourceKey":"bytedance","company":"字节跳动","title":"大模型推理优化工程师 - Data语音","city":"北京/上海/深圳","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668630955884267781/detail","duty":"团队介绍：Data-语音团队致力于语音、音乐等大模型AIGC技术的研发和产品创新，我们的使命是通过多模态AIGC音频技术赋能内容创作和语音交互，让内容生产、消费与互动变得更加简单、沉浸、多元化。当前团队已有成熟的大模型语音合成、语音理解、音乐生成等多模态音频技术，并持续迭代大模型端到端语音交互方案等，一方面通过中台形式服务于公司众多业务线，例如豆包/Dola、抖音/TikTok、剪映/CapCut、番茄小说、海绵音乐等产品；另一方面，团队已经通过字节跳动旗下的火山引擎开放平台-语音技术和火山方舟平台，向众多企业开放技术成熟稳定的能力和服务。\n\n1、负责构建新一代大模型推理引擎，优化多模态语音理解、语音生成等多模态生成大模型在GPU集群上的推理性能，实现低延迟、高吞吐的工业级部署；\n2、主导模型推理性能优化，涵盖CUDA、Triton算子开发、vLLM、SGLang框架升级、分布式推理策略优化、量化、稀疏化等模型效能加速优化；\n3、研发GPU推理加速技术栈，设计最佳分布式通算结合方案，搭建PCIe通信与高并发推理架构；\n4、负责高性能方案前瞻性建设，构建基于C++、Python研发的高性能推理系统；\n5、与上下游部门深度合作，分析性能瓶颈，通过软硬结合提升模型训推效率，优化和部署语音大模型，支持AI工具链和技术生态建设，推动AI关键业务发展；\n6、负责语音多模态场景下高性能推理系统的开发，支撑各业务场景下的性能优化需求并推动业务落地。","requirements":"1、2027届获得硕士及以上学位；\n2、精通Python，熟悉C++特性，具备高性能代码开发能力和相关经验；至少具备以下一个领域经验：GPU编程（CUDA/Triton/AscendC/TileLang开发）、模型量化/稀疏化/蒸馏、基于vLLM的框架研发、并行计算通算结合（多卡/多机推理优化）；\n3、符合以下条件者优先：拥有推理系统经验、具备vLLM/SGLang开发经验、Tilelang/Tritton开发经验，深入了解Transformer架构，有量化/稀疏化等相关技术落地或者论文发表等相关经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668537102275938565","sourceKey":"bytedance","company":"字节跳动","title":"AI通信库研发工程师 - AI算力基础设施","city":"北京/杭州","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668537102275938565/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、负责集合通信库的研发工作，支持大规模场景下的高性能通信；\n2、解决和优化AI/大模型训练和推理场景的通信问题，保障业务通信的性能和稳定性；\n3、通过通信与计算的协同优化，优化业务模型的通信效率；\n4、洞察集合通信技术趋势，推动集合通信库的架构演进与生态适配。","requirements":"1、2027届获得本科及以上学历，计算机、网络、软件工程等相关专业优先；\n2、热爱技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n4、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668533140160383285","sourceKey":"bytedance","company":"字节跳动","title":"AI/大模型网络研发工程师 - AI算力基础设施","city":"北京/杭州","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668533140160383285/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、高速网络技术的设计和研发，满足AI/大模型业务在训练、推理、存储等多个场景对网络的需求；\n2、支持大规模AI场景的高速网络平台系统研发，包括故障定位和性能分析等；\n3、高性能AI通信框架，网络协议栈以及端网应用协同优化等核心技术的研发，在支持业务规模化扩展的同时，保证网络的高可靠性和高性能；\n4、通过技术创新推动AI网络技术的持续演进，打造适合大规模AI场景的超低时延高速互联技术。","requirements":"1、2027届获得本科及以上学历，计算机、网络、通信等相关专业；\n2、热爱技术，至少精通C/C++、Go、Python、Java中的一门编程语言；\n3、具备优秀的逻辑分析能力，善于将复杂的业务逻辑进行合理抽象与拆分；\n4、拥有强烈的求知欲、出色的学习能力和良好的沟通能力，有AI经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665235491532736773","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent工程师 - 豆包","city":"北京/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665235491532736773/detail","duty":"团队介绍：字节跳动Flow产品研发团队，专注研究AI智能化相关业务落地，目前落地豆包等APP，以及Bot开发平台等AI智能化创新产品。其中，豆包是一款基于字节自研模型的AI智能助手，能为你答疑解惑，查询信息，提供灵感，辅助创作，也可以和你聊任何感兴趣的话题。业务和团队均处于快速发展期，成长空间大，欢迎各位同学加入！\n\n1、负责豆包应用中交易场景（电商/生活服务）Agent相关的服务端技术方案设计、研发工作；\n2、深入参与交易场景的技术方案设计与架构演进，支持复杂业务需求的高质量交付，保障系统在性能、可用性和扩展性上的持续提升；\n3、持续探索AI能力在业务场景中的应用，推动产品创新，提升用户体验与研发效率；\n4、与产品、算法、运营等团队紧密协作，推动大模型能力与业务场景深度结合，支撑业务目标达成。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、学习能力强，有独立解决问题的能力；\n3、熟悉面向对象编程，掌握Java/C++/Python/Go中的至少一门语言，Python/Go背景优先；\n4、有良好的沟通能力和业务理解能力；\n5、对大模型相关技术有好奇心，持续关注熟悉前沿技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664604682400303413","sourceKey":"bytedance","company":"字节跳动","title":"后端研发工程师（AI架构） - 剪映CapCut","city":"北京/广州/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664604682400303413/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、参与后端和AI Agent方向的系统设计、开发和迭代，支持AI策略与模型的高效部署与服务化；\n2、协助构建与优化数据处理、特征生产等AI工程化链路，提升系统智能化能力；\n3、通过数据分析与挖掘，为模型训练、风险感知与治理提供数据与工程支持；\n4、协同算法、数据与前后端团队，推动技术方案从实验到上线的完整落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669721412320676149","sourceKey":"bytedance","company":"字节跳动","title":"游戏硬表面原画设计师 - 深圳射击项目","city":"深圳","category":"游戏美术","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669721412320676149/detail","duty":"团队介绍：一款科幻写实的全平台(手游/PC/主机)射击项目，使用UE5引擎研发，欢迎加入我们。\n\n1、根据项目现有美术风格，独立完成科幻写实风格的武器、硬表面道具设定工作，并能确保角色风格统一、设定合理；\n2、输出高质量的武器，硬表面设定图、装置动画示意图，为建模和动画等后续环节提供清晰的设计依据；\n3、与策划、美术、建模、动画等相关团队紧密协作，确保角色设定在游戏中的表现符合预期，并根据实际效果持续优化。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、有写实科幻类军事类知识储备，熟悉该题材下枪械、道具、载具的设计逻辑；熟练掌握Blender，Photoshop软件，有能力K简单动画，使用3d前期+2d后期的流程；\n3、有科幻、军事风格的硬表面风格设计作品；\n4、热爱游戏行业，了解3A项目角色制作流程，具备良好的沟通协作能力和团队意识；能根据项目需求快速适应并调整设计方向，具备良好的问题解决能力与责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669622651728857349","sourceKey":"bytedance","company":"字节跳动","title":"商城策略运营（欧美市场） - TikTok Shop","city":"北京","category":"频道运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669622651728857349/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责欧美商城核心场域的策略运营工作，围绕首页、频道、活动等关键场景，结合用户浏览、决策和购买路径，制定差异化运营策略，提升用户对商城的认知、使用习惯与购买效率；\n2、围绕拉新、留存、转化等业务目标，结合用户分层、流量分发和营销机制设计商城增长策略，持续优化不同场景下的承接效率、转化效率和用户生命周期运营效果，驱动商城用户规模与交易增长；\n3、深入分析欧美市场用户需求、消费偏好和购物认知，联动供给、产品、营销等团队，推动更符合用户预期的商品、内容和活动供给建设，提升优质供给与用户需求的匹配效率；\n4、结合AI能力探索更智能的用户洞察、策略识别和运营提效方式，提升用户触达效率、策略迭代效率与运营决策质量，推动欧美商城运营模式持续创新。","requirements":"1、2027届获得本科及以上学历，数据科学、计算机、AI等相关专业优先；\n2、对电商、策略运营、用户增长、平台型业务或AI应用方向有浓厚兴趣，具备较强的好奇心和业务敏感度；具备良好的逻辑分析能力和结构化思考能力，能够从用户群体、消费场景、供给匹配和业务目标出发，拆解问题并形成清晰的策略判断；\n3、具备较好的数据意识、学习能力和策略思维，能够通过数据分析、用户反馈和行业观察发现问题与机会，并推动策略优化和迭代落地；\n4、具备良好的沟通协作能力、责任心和自驱力，能够与产品、供给、营销、研发、数据等团队高效协同，英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668265470446913797","sourceKey":"bytedance","company":"字节跳动","title":"AI安全后端开发工程师 - Seed 安全研发","city":"上海/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668265470446913797/detail","duty":"团队介绍：产品研发和工程架构-Seed 安全研发团队，负责豆包、飞书、豆包工作等产品的整体安全建设、风险治理及基础能力输出，是业务与 AI 生产力平台的安全底座。团队覆盖身份与访问管理、数据安全与合规、信任与安全、安全算法、终端安全等方向，以零信任架构构建企业级安全产品能力，全面深耕 AI Agent 安全体系。你将面对多租户权限、跨境数据合规、AI 工具调用风险管控、安全智能运营等业务和技术挑战，与团队一起筑牢安全防线。\n\n1、负责信任与安全相关产品的服务端研发，构建保障用户安全的平台能力与风控体系；\n2、参与AI时代安全体系建设，利用大模型和AI工具提升威胁检测、内容安全治理、风险防控的效率与精准度；\n3、负责团队服务质量与系统稳定性，从工具、系统、流程上持续提升开发与交付效率；\n4、与产品、运营、法务、安全策略等多团队密切协作，推动安全能力落地与跨部门项目高效推进；\n5、主要技术栈为Golang。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、信息安全等相关专业；\n2、具备AI使用和实践经验，有将大模型/AI工具应用于实际业务场景的经验，熟悉Prompt工程、AI Agent编排或LLM应用开发者优先，了解安全相关知识（如Web安全的常见威胁与防护）者优先；\n3、对外沟通协作能力强，能够跨团队、跨职能高效推进项目，善于将技术方案转化为业务语言与非技术团队对齐；\n4、较好的产品意识，愿意将产品效果作为工作的重要驱动因素；\n5、掌握Web后端开发技术：协议、架构、存储、缓存、安全等；\n6、积极乐观，认真负责，乐于协作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667046688703711493","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师（平台方向） - TikTok Shop","city":"北京/上海/深圳/珠海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667046688703711493/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、参与TikTok Shop业务的研发工作，包含从前端页面、服务端接口、数据链路到上线验证的端到端全栈交付；\n2、参与TikTok Shop全栈工程建设，包括：数据模型抽象、性能优化、用户体验优化；\n3、基于AI Coding工具，建设需求理解、方案生成、代码实现、测试验证、Code Review和线上排障的AI辅助研发流程，提升需求效率与质量，参与AI工程化能力在真实业务中落地；\n4、基于业务场景和Agent应用，参与设计AI业务落地场景，帮助业务提效、解决业务痛点。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、具有优秀的代码能力，熟练掌握Go/Java/Python编程语言；\n3、熟悉Agent架构核心组件的设计原理与调优方案，了解主流开源Agent框架（如LangGraph/Pi等），具备Prompt调优、Harness、RAG、上下文工程、Skill编写等实践经验；\n4、学习能力强，对新技术保有好奇心，善于独立思考与反思总结，具备将复杂问题转化为简洁高效方案的能力；\n5、良好的沟通与跨团队协作能力，热爱技术，拥抱开源。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628624685622380805","sourceKey":"bytedance","company":"字节跳动","title":"AI智能创作-剪映（北京/上海/深圳）","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628624685622380805/detail","duty":"团队介绍：负责剪映CapCut、醒图Hypic、即梦Dreamina以及小云雀Pippit等创作工具的算法和数据相关，具体包括各产品的用户增长、内容分发与生态、商业化以及AI创作等，同时也会做深入的技术探索赋能业务，如LRM\\GR\\LLM4rec以及AIGC等相关研究。\n\n课题介绍：当前创作工具（如剪映/CapCut）仍以工具化为主，用户需要手动完成选素材、剪辑、调节节奏等复杂流程，创作门槛较高。同时，内容供给主要依赖人工设计模板与素材，难以快速响应热点和用户个性化需求；推荐系统与创作系统割裂，导致用户兴趣与内容生产之间缺乏联动。\n本课题旨在构建一个以大模型为核心的AI智能创作系统，打通“用户意图理解—个性化内容生成—推荐分发”的全链路，实现从工具型创作向智能创作系统的升级，在剪映、CapCut、即梦等场景中提升创作效率与内容供给质量，实现内容的规模化生产与千人千面的个性化表达。\n\n具体包括：\n1、基于用户行为、历史偏好与上下文的创作意图理解与个性化表征学习；\n2、基于多模态大模型的内容理解与结构化建模（视频结构、节奏、美学与风格）；\n3、基于用户兴趣与创作意图驱动的个性化内容生成（模板、图片、视频、音乐）；\n4、基于用户上传素材的个性化自动成片与剪辑策略生成（节奏、风格、叙事）；\n5、基于热点、推荐与搜索线索的内容生成与供给扩展，并结合用户画像实现差异化生成；\n6、推荐系统与生成模型的联合优化，实现“为用户生成内容”的生成式推荐范式；\n7、超长用户行为序列建模与长期/短期创作偏好建模；\n8、面向创作场景的大模型推理优化与系统性能优化（分层推理、模型压缩等）。\n\n课题挑战：创作场景的AI智能化面临多重挑战。首先，用户创作意图具有高度个性化和隐式性，如何从用户行为、素材及上下文中准确理解其创作目标，并进一步转化为可生成的内容表达，是核心难点。其次，短视频等内容形态具备强多模态特征（视频、图像、音频、文本），需要模型具备高水平的跨模态理解与生成能力。同时，生成内容不仅需要具备美感和创意，还需要满足个性化表达与推荐分发效果（如点击率、完播率、转化率），如何实现“个性化生成”与“推荐效果优化”的统一，是关键挑战。此外，推荐系统对延迟和工程效率要求极高，大模型的引入带来算力与系统复杂度挑战，需要在效果、成本与性能之间取得平衡。因此，有必要构建一套面向创作场景的AI原生系统范式，实现内容生产与分发的一体化升级。\n\n课题价值：构建AI原生创作系统，打通理解、生成与分发闭环，实现内容生产与推荐一体化升级。","requirements":"1、2027届毕业，获得博士学位，计算机、软件、人工智能、数学等相关专业优先；\n2、扎实的机器学习基础，深入理解多模态理解及LLM等相关技术，具备良好的数理基础；\n3、熟练掌握相关机器学习框架和工程框架，具备扎实的编码能力；\n4、在多模态，语言大模型领域有相关经验；\n5、在计算机科学高水平会议和期刊（如NIPS、ICML、CVPR、ICCV、ECCV、IJCAI、AAAI、KDD、SIGIR、WWW、ACL、PAMI、IJCV等）发表过论文或具备竞赛经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592953647437220149","sourceKey":"bytedance","company":"字节跳动","title":"安全运营实习生-安全与风控","city":"深圳","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592953647437220149/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：我们团队致力于通过对攻防技术的持续研究，最大限度降低零日漏洞与安全事件造成的影响。我们提供红队演练、威胁检测、安全保障工具支持及事件调查等服务，助力提升系统韧性。通过不断强化攻防两端能力，我们在巩固公司核心安全基础、保障数据与业务安全方面发挥着关键作用。\n\n1、负责公司安全体系正向建设以及入侵防御体系的搭建和实施；\n2、负责公司安全事件的分析、调查和处置，从中查漏补缺，推动安全能力建设；\n3、负责公司安全产品的告警/日志分析和运营；\n4、负责建设安全运营平台，通过构建策略、模型提升自动化运营能力。","requirements":"1、2027届本科及以上学历在读，信息安全、计算机科学等相关专业优先；\n2、具备扎实的安全基础，包括网络、主机、应用、容器等；\n3、熟悉常见安全攻防对抗手段，有实际的安全防护和安全事件分析经验，有红蓝对抗经验优先考虑；\n4、熟悉常见安全漏洞及技术原理，能根据需要制定和运营检测规则和分析策略；\n5、熟悉WAF、HIDS、NTA、EDR、IPS/IDS、DLP、防病毒其中至少一项产品，有实际的策略制定和事件处置经验，了解业界最佳实践；\n6、熟练Shell/Python/Java/Go等至少一种开发语言；具备良好的沟通表达能力，良好的团队合作意识和自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677797357031950645","sourceKey":"bytedance","company":"字节跳动","title":"美国市场商家达人机构运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677797357031950645/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、机构运营：协助建联、通过机构社群及1v1对接机构，维护机构与平台稳定合作，跟进合作进度；\n2、数据运营：负责机构日常数据整理与分析（GMV、选品匹配率等），为机构提供数据支持和运营指导；\n3、货品撮合：基于商家需求与机构资源，参与选品匹配及供应链协调，推动合作落地并持续迭代撮合效率；\n4、活动支持：协助策划机构培训会、商家对接会等，提升机构服务效率。","requirements":"1、本科及以上学历在读，市场营销、国际商务、英语等相关专业优先；\n2、英语读写可以用于工作沟通，包括但不限于邮件、社交媒体及日常工作交流；\n3、具有相关数据能力，熟练掌握数据分析软件；\n4、有BD和运营相关经验优先，能够快速适应国际化市场的文化差异，具备较强的自我驱动力与问题解决能力；\n5、每周可实习5天，可以连续实习3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673774412449450293","sourceKey":"bytedance","company":"字节跳动","title":"战略分析师 - 红果短剧","city":"北京","category":"战略","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673774412449450293/detail","duty":"团队介绍：红果短剧是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、红果短剧产品及内容战略团队，负责短剧等泛文娱赛道的战略规划和专项落地，擅长专项突破，发现新机会并帮助业务规划关键路径；\n2、深度观察和研究国内外行业，通过定量和定性的行业、产品、数据和用户调研为公司管理层和业务核心团队提供决策支持，和业务方共同探索业务模式并提供策略设计，分析和落地支持；\n3、以战略目标为基础，对业务方各类经营指标进行日常监控和经营分析专题研究，协助业务侧制定年度/季度业务目标，规划实现路径，持续分析业务结果，支持业务复盘与决策；\n4、横向联动产品、运营、内容、推荐、研发等团队，推进部门间重点项目的沟通协作，推进战略落地。","requirements":"1、2027届获得本科及以上学历；\n2、有战略分析实习经历，有文娱方向、内容产品策略经验者优先，有数据分析、经营分析、商业分析实习经验者优先；\n3、具备数据分析、统计知识，熟练使用SQL，SPSS、Tableau、Python等分析工具使用经验加分；\n4、有数据分析背景者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673078415227816197","sourceKey":"bytedance","company":"字节跳动","title":"内容运营（即梦AIGC方向）实习生 - 剪映CapCut","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673078415227816197/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责全球社交媒体官方账号日常运营，为即梦Dreamina提供流量支撑，驱动粉丝规模与互动量提升；\n2、敏锐追踪全网热点趋势与前沿AI玩法，结合产品能力策划制作高质量AIGC创意内容，持续打造具有强传播力的破圈标杆案例，扩大产品市场声量；\n3、挖掘即梦APP内热门玩法与优质创作者精品内容，负责公众号等平台的文章撰写与排版，提升品牌内容影响力与用户参与意愿。","requirements":"1、本科及以上学历在读，影视、编导、动画、数字媒体等相关背景或实践经验者优先；\n2、深入了解AIGC行业，具备高质量AIGC作品制作经验，能熟练使用主流AI创作工具，需提供作品集；\n3、内容意识好，熟悉网络热点趋势，文字功底扎实，能准确判断内容传播价值，有账号运营经验优先；\n4、具备优秀的英语听说读写能力，可将英语作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669716620106107141","sourceKey":"bytedance","company":"字节跳动","title":"游戏关卡策划（搜打撤） - 绿洲工作室","city":"北京","category":"游戏系统策划","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669716620106107141/detail","duty":"绿洲工作室2019年4月在北京成立，立足动作与休闲核心赛道，依托移动、PC、主机全平台布局，持续探索 RPG、竞技、休闲、棋牌等多品类精品游戏创作。旗下有《晶核》《雾影猎人》《SlashZero》（又名：《零境·入侵》）《Land of Empires》《芒果斗地主》等多款产品。我们的愿景是希望帮助玩家在令人惊叹的虚拟世界中一起玩耍与创造，加入这里，你将与一群简单、务实的优秀伙伴一起，Work hard，Play harder~\n\n1、负责设计并跟进制作游戏中的关卡场景；\n2、负责设计并跟进制作游戏中关卡所需的各种功能机制；\n3、负责设计并跟进制作游戏中的各种关卡玩法；\n4、负责设计并跟进制作关卡相关的一些系统功能。","requirements":"1、2027届获得本科及以上学历；\n2、逻辑思维能力强，有优秀的文字和语言沟通表达能力；\n3、有优秀的空间想象能力，能使用软件搭建关卡白模；\n4、动手能力强，能独自设计并验证玩法原型；\n5、了解市面上各种主流的3D游戏关卡和地图设计思路，能分析推导市场游戏系统的核心设计思路和方法论；\n6、游戏面广泛，熟悉主机游戏，对市面上主流动作类游戏和竞技类游戏都有所涉猎，相关游戏水平较高的优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669705617649256757","sourceKey":"bytedance","company":"字节跳动","title":"下一代推荐大模型算法工程师 - TikTok算法","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669705617649256757/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责国际化短视频主页推荐的算法工作，覆盖召回、粗排、精排、重排等全链路，以及内容理解、推荐架构与下一代推荐系统探索，持续打磨全球领先的短视频分发体验；\n2、结合业务场景，运用深度学习、强化学习、Graph Embedding、大规模计算等手段解决效果与效率问题；同步推进推荐大模型、Agentic Rec等前沿探索方向的落地，探索更强的用户理解、决策与长期价值优化；\n3、参与算法基建建设，提升训练/推理资源利用率、效果稳定性与研发效率，沉淀可复用的能力与工具。","requirements":"1、2027届获得硕士及以上学位，计算机、电子、数学、物理等相关专业；\n2、编码能力扎实，具备良好的数据结构与算法功底；熟悉机器学习、自然语言处理、数据挖掘中的一项或多项；有推荐系统、计算广告、搜索引擎经验者优先；了解大模型、强化学习、Agent/多智能体相关方向者优先；有推荐场景落地经验；\n3、分析与解决问题能力强，对技术有热情，沟通协作良好。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669687122374330677","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发工程师 - Seed 产品研发","city":"上海","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669687122374330677/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、负责飞书音视频会议客户端研发，参与架构设计、核心功能开发、性能优化与稳定性建设；\n2、推动实时字幕、智能纪要、妙记等AI能力在多端高质量落地；\n3、解决弱网、低延迟、音视频处理、跨端一致性等工程问题，持续提升会议体验。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、计算机、网络及软件工程基础扎实，熟悉C/C++、Java、Kotlin、Swift、Objective-C等至少一门语言；\n3、对客户端架构、性能优化或音视频技术有兴趣，具备良好的编码习惯和问题分析能力；\n4、学习与动手能力强，关注AI技术发展，重视验证与结果质量，有AI项目或开源实践者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668621579618027781","sourceKey":"bytedance","company":"字节跳动","title":"项目运营 - 抖音生活服务","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668621579618027781/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责全行业重点专项策划与推进，例如：节点战役（破峰/大促）、供给效率提升、商家分层运营机制、广告增长协同等；\n2、辅助设计SOP、运营节奏、提报/评审机制、监控看板，推动规模化复制，做好进度、资源、风险管控，并跟进落地复盘；\n3、推进重点产品在行业的商家覆盖，并能结合不同行业特点和商家需求，帮助产品功能优化；\n4、依托数据分析挖掘业务问题，开展商家分层运营，整合平台资源赋能商户，优化运营策略，输出运营报告，支撑业务决策与增长。","requirements":"1、2027届获得本科及以上学历；\n2、有互联网数据分析，产品/行业运营实习经验者优先；\n3、专业技能：熟练掌握PPT/Excel，SQL技能优先；\n4、基本素质：有良好的数据分析能力和逻辑框架，有钻研探索精神，喜欢挑战，有较高的自我期望和成长诉求。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668275334664308997","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师 - Seed 产品研发","city":"上海/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668275334664308997/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与字节跳动飞书产品线新一代企业智能产品研发工作，打造以人工智能技术为亮点的产品功能；\n2、参与产品功能中搜索问答服务模块的设计研发、部署维护工作；\n3、参与NLP技术为主的算法模型研发任务。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、良好的编码能力，良好的数据结构与算法基础，掌握Python、C/C++、Golang等编程语言之一；\n3、良好的机器学习基础，熟悉机器学习相关类库，了解TensorFlow、PyTorch等深度学习框架之一；对自然语言处理有浓厚兴趣；\n4、优秀的学习与分析能力、沟通与团队协作能力；\n5、有自然语言处理相关研发经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668256688342075653","sourceKey":"bytedance","company":"字节跳动","title":"Forward Deployed Engineer（AI全系产品） - 火山引擎","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668256688342075653/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、深入理解客户业务场景，快速搭建AI应用原型进行验证，持续迭代并推进至生产级部署的Agent系统；\n2、基于AI与云服务进行方案/架构设计，借助AI辅助开发在客户环境中高效落地；对接客户应用API与数据系统，满足客户安全与合规规范；\n3、构建高性能评估管道与可观测性体系，确保Agent系统在准确性、安全性与时延等指标上达标；\n4、识别可复用的应用模式与共性技术问题，沉淀为产品能力/功能诉求，推动产品迭代演进；\n5、与客户工程团队紧密协作，保障AI应用成功上线、长期稳定运行，并持续提升使用率与业务价值。","requirements":"1、2027届获得本科及以上学历，计算机科学与技术、软件工程、人工智能等相关专业；\n2、扎实的工程基础，熟悉至少一门主流编程语言与常见工程化实践；具备良好的编码习惯与问题定位能力；\n3、对AI应用开发有实践或强烈兴趣，具备相关项目/课程/科研/实习经历（如Prompt Engineering、Fine-Tuning、RAG、Agent开发等方向之一或多个）；\n4、了解云服务与分布式系统基础概念，有云服务API/SDK调用、自动化部署、可用性/稳定性设计等相关项目或实习经验优先；\n5、熟悉并愿意使用AI辅助编程（Vibe Coding）提升开发效率，能够在实际项目中形成可复用的开发与交付方式；\n6、具备良好的沟通与协作能力，能在不确定需求下快速推进落地，适应面向客户的交付节奏。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667887768395073797","sourceKey":"bytedance","company":"字节跳动","title":"合规策略 - 国际支付","city":"北京","category":"职能 / 支持","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667887768395073797/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、与业务团队协作，理解业务模式与内在风险暴露，识别可疑交易信号，协助制定、优化交易监控规则；\n2、设计并维护监控有效性矩阵与数据看板，用于评估规则表现与覆盖情况；\n3、支持交易监控全生命周期的制度与流程建设与迭代，包括规则验证、系统优化、底层数据分析等；\n4、与区域及全球团队协作，支持交易监控模型的上线、迭代与持续优化；\n5、与Global Payments内部跨职能伙伴（合规、产品、数据、工程、运营等）协作，推动职责边界清晰、流程高效落地；\n6、进行数据解读与分析，确保结果准确、可复现，并能清晰表达关键结论。","requirements":"1、2027届获得本科及以上学历，数学、Business、Finance、物理、计算机、Data Science或相关专业优先；\n2、具备支付、数据分析或相关领域的实习/项目经历（有交易监控、反洗钱、风控相关更佳）；\n3、具备较强的数据分析能力，熟练使用SQL、Excel及常见分析工具完成数据处理与结论输出；\n4、良好的沟通与协作能力，能够与不同层级、不同职能同学高效沟通并推进任务；\n5、做事细致、条理清晰，能够在多任务环境下保持准确性与执行力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667578700110121221","sourceKey":"bytedance","company":"字节跳动","title":"机器学习算法工程师 - 抖音电商&直播","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667578700110121221/detail","duty":"团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n抖音直播算法团队，负责抖音、抖音极速版、抖音火山版等App的直播推荐算法优化，业务包括直播体裁基建和直播营收。直播体裁基建从用户侧的召回/粗排/精排/混排等模型和策略和主播侧的冷启动算法，结合多模态内容技术动态理解切片和用户兴趣，建立短视频域到直播域的兴趣迁移，在全场景分发直播体裁，满足用户看播需求并服务于营收、电商、生活服务、游戏等多业务。直播营收致力于为歌唱/舞蹈/弹奏/朗读/情感/户外等广泛的具有一技之长的普通人通过直播这个舞台被更多人看到获得收入，并满足用户多层次的精神消费和情感表达诉求，让优质内容供给持续增长反哺整个直播生态。在推荐技术方面，我们持续验证并落地全链路模型的高效scaling up方案，积极探索生成式推荐和LLM4Rec路线，提升模型系统的整体智能。\n\n1、解决抖音电商、即时零售业务中的预测、数据挖掘、建模决策工作，包括对用户履约偏好、商家的经营行为深度理解和分析，并制定适配性算法解决方案，提升用户购前与购后体验，降低商家经营成本；\n2、应用机器学习/深度学习/大模型技术，解决任务包括不限于：销量预测、ETA及时空预测、异常行为识别、地址智能、定价/发券、供给增长等；\n3、深入理解及建模电商内用户、商家、作者的行为模式，制定有效的平台算法策略促进生态良性发展；\n4、参与电商供给生态业务支持，通过前沿深度机器学习算法，建设冷启动/潜爆/出爆/量价等成长预测算法能力，支持商家入驻成长；\n5、深入理解电商导购与商品价格，参与建设智能选品系统实现不同业务目标，支持抖音内容电商、货架电商、用户增长等选品场景，同时参与商品比价、量价建模、智能定价等系统能力建设，支撑电商价格力、智能营销等业务。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、具有深度学习/机器学习/运筹优化/因果推断/统计分析等大数据处理、分析、应用落地经验；\n3、编程动手能力强，擅长Java/Python编程语言，具备Linux环境研发能力，熟悉掌握PyTorch/TensorFlow等进行模型学习和优化，擅长做数据分析类的应用；\n4、有商家商品供给成长/搜推导购/电商比价/智能营销相关业务场景支持经验者优先；\n5、在CCF-A类有发表过论文者优先（KDD、NeurIPS、WWW、ICML、IJCAI、AAAI等），有过机器学习比赛经验者优先；\n6、优秀的分析和解决问题的能力，对挑战性问题充满激情，具备良好的团队合作精神，较强的沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665612044858558773","sourceKey":"bytedance","company":"字节跳动","title":"大模型工程师（AI4SE方向） - 抖音AI","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665612044858558773/detail","duty":"团队介绍：抖音AI团队主要负责抖音项目以及团队内的AI落地相关基础建设工作。我们的职责是用前沿的AI技术去赋能抖音应用以及抖音团队。我们希望在AI技术的加持下，能够更好的给抖音用户带来更好的信息消费体验，也能够让抖音这个大型组织能够更加高效的运转，从而更加及时的满足用户的各项诉求。团队主要负责抖音AI基础建设，包括但不限于模型训练、Agent相关的工程链路开发、通用Agent工具抽象以及AI Native的各类产品开发工作。AGI信仰强，以发展成为AI Native组织为目标，努力拓展传统协作模式的职责边界，充分给同学们提供自身探索的空间。\n\n1、负责代码大模型相关的数据收集、清洗、构建与管理，搭建高效稳定的数据处理Pipeline；\n2、负责Agent Infra，包含Agent运行环境、Agentic RL Scaling等基础能力建设；\n3、负责代码大模型评测体系的建设，包括评测集构建、评测框架开发与评测执行；\n4、探索和实现基于大模型的智能体（Agent），应用于代码生成、Bug修复、测试用例生成等复杂研发任务；\n5、持续追踪并复现LLM+SE领域前沿技术动态，并将其应用于实际业务场景中，推动技术落地。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、优秀的问题分析与解决能力，能够深入解决大模型工程化及应用中的复杂问题；\n3、具备AI+SE结合的项目经验，熟悉代码数据收集、清洗、标注等数据工程流程；\n4、熟悉大模型相关技术，对模型训练Pipeline、推理优化、评测体系构建等方向有深入研究和实践。\n\n加分项\n1、以第一作者在ICML、ICLR、NeurIPS、ACL等顶级学术会议发表过高影响力研究成果者优先；\n2、在ACM/ICPC、NOI/IOI、Kaggle等编程或AI竞赛中获奖者优先；\n3、主导或参与过具有广泛影响力的AI开源或闭源项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664850115949562165","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师（广告业务） - 中国交易与广告","city":"杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664850115949562165/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、依托各类AI Coding工具，独立完成广告业务相关项目的前后端全栈开发、功能迭代与接口联调，负责前/后端技术选型和开发工作，参与广告业务全栈开发，保障业务需求高质量落地；\n2、主导或参与前后端基础设施建设，包括组件库沉淀、工程化工具链优化、CI/CD流程改进，提升团队研发效率；\n3、与产品、算法等团队紧密协作，推动跨团队技术方案对齐，保障项目按时交付；\n4、能够参与Agent在广告业务场景中的落地探索（如Agent产品交互开发、工作流编排等）；\n5、利用AI Coding工具提升个人及团队开发效率，跟进前沿Agent开源方案，沉淀可复用的调度模板与工程最佳实践。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程等相关专业；\n2、掌握Python/Go/Java/JavaScript任意2门开发语言，熟悉Node.js/Go，具备前后端一体化开发能力；\n3、理解LLM基础原理，熟悉AI Agent核心模块（Prompt、记忆机制、工具调用、RAG、多智能体），能区分不同层级模型的业务适用场景；\n4、熟练掌握主流AI编码工具（TRAE、Claude Code、Codex等），能够利用AI完成需求拆解、代码编写、复杂逻辑重构、Bug定位修复、单测编写、代码评审，具备AI协同研发思维；\n5、熟悉Git基础操作，具备良好的沟通能力与团队合作精神；对技术保持好奇心，善于独立思考并反思总结；\n6、有相关岗位实习及项目开发经历优先。\n\n加分项：\n1、有AI辅助前后端全栈开发、Agent项目部署与二次开发实战经验；\n2、实操过Agent任务拆分、多智能体并行调度、模型自动择优等核心功能；\n3、熟悉MCP协议、LLM工具调用、AI自动化工作流搭建；\n4、有对话应用、智能编排、知识库平台等相关项目开发经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664528817566615861","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发工程师 - 番茄小说/红果短剧/番茄畅听","city":"北京/上海","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664528817566615861/detail","duty":"团队介绍：\n番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、负责番茄小说、红果短剧等多业务方向的客户端开发工作；\n2、参与APP性能、体验优化及质量监控评估体系建设、客户端基础组件及架构设计，推进研发效率；\n3、参与Hybrid容器搭建，插件、React Native等动态技术调研；\n4、AI Coding实践：使用AI Coding工具（如Cursor、Copilot、TRAE、Claude Code等）辅助日常开发，探索AI驱动的研发提效方式；\n5、参与将AI能力融入到业务技术方案设计与落地，在实践中验证和优化AI驱动开发流程，持续提升生产力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、熟练使用至少一种AI Coding工具（Claude Code、Cursor、Codex、Cline等），了解其现原理有加分；\n3、扎实的数据结构和算法基础；精通至少一门编程语言，包括但不限于：Java、Objective-C、Swift、C、C++；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n6、良好的沟通能力与自驱力，能在AI辅助下独立推进任务。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7597372062310877445","sourceKey":"bytedance","company":"字节跳动","title":"机器学习算法实习生-抖音电商","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7597372062310877445/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n1、解决抖音电商、即时零售业务中的预测、数据挖掘、建模决策工作，包括对用户履约偏好、商家的经营行为深度理解&分析，并制定适配性算法解决方案，提升用户购前与购后体验，降低商家经营成本；\n2、应用机器学习/深度学习/大模型技术，解决任务包括不限于：销量预测、ETA及时空预测、异常行为识别、地址智能、定价/发券、供给增长等；\n3、深入理解及建模电商内用户、商家、作者的行为模式，制定有效的平台算法策略促进生态良性发展；\n4、参与电商供给生态业务支持，通过前沿深度机器学习算法，建设冷启动/潜爆/出爆/量价等成长预测算法能力，支持商家入驻成长；\n5、深入理解电商导购，参与建设智能选品系统来实现不同的业务目标，支持抖音内容电商、货架电商、用户增长等各类选品场景；\n6、深入理解商品价格，参与商品比价、量价建模、智能定价等系统能力建设，支持电商价格力、智能营销等业务支撑。","requirements":"1、2027届硕士及以上学位在读，计算机相关专业；\n2、具有深度学习/机器学习/运筹优化/因果推断/统计分析等大数据处理、分析、应用落地经验；\n3、编程动手能力强，擅长Java/Python编程语言，具备Linux环境研发能力，熟悉掌握PyTorch/TensorFlow等进行模型学习和优化，擅长做数据分析类的应用；\n4、有商家商品供给成长/搜推导购/电商比价/智能营销相关业务场景支持经验者优先；\n5、在CCF-A类有发表过论文者优先（KDD、NeurIPS、WWW、ICML、IJCAI、AAAI等），有过机器学习比赛经验者优先；\n6、优秀的分析和解决问题的能力，对挑战性问题充满激情，具备良好的团队合作精神，较强的沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592517407815239941","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用开发实习生-风控","city":"深圳","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592517407815239941/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：风控工程研发团队聚焦抖音、今日头条等全产品黑灰产对抗工程化落地，覆盖社区安全、交易风控等多领域风险治理。依托高并发架构、大数据、大模型等核心技术，构建端云一体多层对抗体系，提供全时效基建能力；同时搭建技术情报体系，实现威胁前置预警与精准打击，并联动算法、策略团队推进技术转化，打造高效可靠的智能风控解决方案。\n\n1、负责风控场景Agent相关应用落地，结合风控业务探索AI解决方案，推动风控平台在智能化方向的升级；\n2、负责风控场景Agent基础设施建设，为Agent提供可迭代、可评测的基础条件，丰富风控Agent生态；\n3、支撑风控场景垂类大模型的构建，建设强有力的AI Infra，助力算法高效解决风控问题。","requirements":"1、2027届本科及以上学历在读，计算机、通信等相关专业者优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Go、C/C++、Java、Rust；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有创新意识，对问题能深入分析本质并能不拘泥现状提出解决方案；\n5、积极追踪开源社区进展，熟悉Agent相关建设工作优先；\n6、了解大模型相关原理，有丰富的大模型应用或者优化经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7584712343945988357","sourceKey":"bytedance","company":"字节跳动","title":"创意视觉设计实习生 - TikTok设计","city":"深圳","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7584712343945988357/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok设计团队的目标是为全球数亿用户提供一流的用户体验，从而帮助用户更好的创作与表达，发现世界的多元与美好，不断打破隔阂，建立起人与人的连接。我们是一个国际化的设计团队，遍布中国、美国、新加坡等国家，世界各地的产品设计师、创意设计师、效果设计师、内容文案专家与本地化经理通力合作，把一个个不可能变成可能。\n\n加入我们，你就有机会理解世界不同地域的文化差异，分析并解决复杂的体验问题，进行前沿的设计探索，更能亲身主导如何把一个想法转化成服务亿级数量用户的产品体验。 如果你积极自驱，对世界充满好奇心和想象力，有希望通过设计打造一流的产品，同时又脚踏实地，欢迎成为我们的一员！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责TikTok国际化直播产品功能运营视觉设计的创作，如教育/活动的H5，产出创意，参与制定风格和设计提案；\n2、协助完成创意落地，如周边、设计延展等；\n3、理解娱乐、直播业务，了解运营玩法，挖掘业务创新点，协同产品、运营、设计、研发推动项目落地；\n4、了解提效方法，沉淀运营设计规范与素材，管理把控供应商流程、产出质量等。","requirements":"1、本科及以上学历在读；\n2、熟练掌握AI、Photoshop、Illustrator、Figma、C4D等常用设计工具，擅长插画/3D/排版/UI，会动效更佳；\n3、对潮流文化、青年群体、社交传播热点具备良好感知；\n4、具备主动学习、沟通协作能力。\n\n加分项\n1、有较好的英文阅读能力，有国际化项目经历加分；\n2、有实习经历加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7456630541577521416","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发（偏前端）实习生 - 中国交易与广告","city":"北京/上海/成都","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7456630541577521416/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责前端技术选型和开发工作；\n2、优化前端功能设计，解决各种浏览器和终端设备的兼容性问题；\n3、通过技术手段，提升用户体验并满足高性能要求；\n4、通用组件、类库编写，提升开发效率和质量。","requirements":"1、本科及以上学历在读，计算机、通信等相关专业优先；\n2、扎实的计算机基础，包括但不限于网络协议、数据结构、算法以及良好的编码能力等；\n3、熟悉前端技术栈HTML5/ES6/CSS/React/Vue者加分；\n4、有过竞赛经历（如ACM）且获奖者优先；\n5、热爱前端技术，有较强的学习能力，有强烈的求知欲、好奇心和进取心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680565406628710661","sourceKey":"bytedance","company":"字节跳动","title":"战略分析实习生 - Global Business Solutions","city":"北京","category":"战略","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680565406628710661/detail","duty":"团队介绍：Global Business Solutions (GBS) 负责TikTok为主的全球产品商业化相关工作，为全球品牌和广告商提供集成的数字营销解决方案。具体包括各区域销售、销售运营、渠道管理、商业化战略、To B市场营销、营销科学、商业化合作和商业内容安全等职能。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、作为战略伙伴，支持国际化广告销售团队，与业务团队紧密合作，通过重点专项的方式寻找收入提升机会；\n2、对接业务负责人，根据业务需求，完成产品洞察、数据分析和客户调研，产出策略建议，协助业务负责人做出关键产品决策；\n3、主动发现问题和业务痛点，组织关键协作方讨论，产出可落地的解决方案，并协调资源推动落地。","requirements":"1、2027届本科及以上学历在读；\n2、有互联网战略分析相关实习经验优先；\n3、英语可以达到商务交流水平，可以独立承担英文桌面研究以及外部访谈；\n4、有数据分析经验，能够使用Excel、SQL、Tableau等数据分析和可视化工具；\n5、具有较强的商业敏感性、钻研精神、以及快速学习能力；\n6、具有跨团队合作能力和较强的沟通协调能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680464962810726661","sourceKey":"bytedance","company":"字节跳动","title":"后端研发（财务系统方向）实习生 - 集团信息系统","city":"上海","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680464962810726661/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与平台产品的服务端研发工作，推动业务的快速发展和高效迭代；\n2、参与系统架构设计、优化，提升系统性能和开发效率，保证设计和编码的质量；\n3、协助团队攻克各种高并发、系统解耦等方面的技术难关；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、本科及以上学历在读，计算机、通信等相关专业者优先；\n2、热爱AI技术，积极钻研与实践，熟练使用AI Coding编程工具；\n3、有扎实的编程能力，有优秀的设计和代码质量；\n4、深刻理解计算机原理，有良好的数据结构和算法基础；\n5、熟悉MySQL、Redis、消息队列等常用研发组件；\n6、积极乐观，责任心强，工作认真细致，有良好的团队沟通和协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7679000408761567493","sourceKey":"bytedance","company":"字节跳动","title":"国际电商数据科学实习生 - TikTok Shop","city":"北京/上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7679000408761567493/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责业务日常数据统计分析，针对异常情况协调资源进行跟踪和深入分析；\n2、协助分析师完成数据洞察以及定性、定量分析工作，迅速定位内部问题或发现机会；\n3、协助分析师进行数据分析体系建设和完善，挖掘流量、产品、策略方面的业务机会。","requirements":"1、本科及以上学历在读，计算机、统计、数学等相关专业优先；\n2、熟练使用SQL、Excel、Python等至少一种脚本语言，熟悉常用数据统计和分析方法；\n3、良好的沟通能力、团队合作精神和主动意识；\n4、良好的逻辑思维能力、业务解读能力和快速学习能力；\n5、对数字比较敏感，热爱数据分析工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676049219773810997","sourceKey":"bytedance","company":"字节跳动","title":"产品交付运维工程师（AI Agent和办公安全） - 火山引擎","city":"北京","category":"运维","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676049219773810997/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责云和安全类产品交付和运维，产品范围包括：AI Agent、办公安全等；\n2、积累项目售中、售后阶段的关键问题，推动产品和工具优化，提升交付运维效率；\n3、参与工单和Oncall值班，提炼问题、需求，推动产品稳定性和体验优化。","requirements":"1、2027届获得本科及以上学历，计算机、网络工程、软件工程等相关专业优先；\n2、扎实的计算机软件基础知识，熟练掌握Linux操作系统、网络、容器等相关原理，具备常见问题排障能力；\n3、了解大语言模型（LLM）基本原理及应用场景，对AI技术感兴趣，有AI Agent使用经验；\n4、中英文流利（书面及口头沟通），能够与全球客户、跨区域团队开展专业沟通；\n5、有良好的沟通协调能力，较强的团队合作精神和责任心，优秀的执行力；\n6、有客户服务意识，能建立和维护良好的客户关系，能接受出差。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672333892670851381","sourceKey":"bytedance","company":"字节跳动","title":"3D视觉算法工程师（数据方向） - PICO","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672333892670851381/detail","duty":"团队介绍：作为一家拥有自主创新和研发创造能力的科技品牌，PICO致力于成为领先的世界级XR平台，成就开发者与创作者，共同为全球消费者创造更美好的生活体验。我们开创性地将虚拟现实扩展到了多个领域，为运动、视频、娱乐等消费级场景带来了全新体验；并广泛应用在教育、医疗和企业培训等商用场景，给全球企业级用户提供了多元化的VR解决方案。\n\n1、支持第一视角下的多模态数据和AI方案的结合，构建高价值的方案、评价体系和应用场景；\n2、负责3D高精数据方案相关的前沿技术的探索研究，包括但不限于静态/动态重建、重建大模型、多模态可控生成等方向，通过实际采集和仿真等形式生成高质量的3D数据；\n3、支持高精数据方向的技术影响力建设，形成高质量的专利和技术报告等知识产物。","requirements":"1、2027届获得硕士及以上学位，计算机视觉/图像处理/机器视觉相关专业优先；\n2、在计算机视觉/深度学习的一个或多个领域有研究和实践经验，深耕以下至少一个核心方向：\n1）基于NeRF/3DGS等技术的静态/动态高保真3D重建技术；\n2）3D生成大模型、LRM、DiT等多模态可控3D生成技术；\n3）大规模3D数字资产自动化生产、处理与优化技术；\n3、有扎实的图像处理和多视图几何基础，熟悉任一深度学习开源框架；\n4、熟练掌握算法设计和实现，精通C/C++/Python等计算机语言；\n5、具备优秀的沟通协作能力，对XR技术兴趣浓厚，具备快速学习新技术的能力；\n6、具备优秀的科研能力，在CVPR、ICCV、ECCV、SIGGRAPH等顶会或期刊上发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667393096102971701","sourceKey":"bytedance","company":"字节跳动","title":"集团内控业务伙伴 - 内控","city":"北京/上海/深圳","category":"职能 / 支持","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667393096102971701/detail","duty":"团队介绍：字节跳动内控部，我们关注全球业务在开展过程中面对的风险和挑战，并辅助业务管理者建立适当的内部程序，为业务有序发展保驾护航。在这里，你将有机会学习字节跳动的多元的业务生态、理解他们运作的原理、资源调度的方式，并参与到内部管理机制的设计中。\n\n1、聚焦业务流程和产品，根据业务战略、组织目标、工作流程及系统数据生命周期，识别潜在风险点；\n2、平衡风险、成本、效率，参与设计恰当的制度、流程、系统等管控方式，并持续监控效果；\n3、对业务中的重大事件进行中立的监督、研判，提供风险管理的有效预案；\n4、通过数据模型、AI等工具，不断迭代风险识别和应对的技术手段，沉淀行业最佳实践。","requirements":"1、2027届获得本科及以上学历，计算机科学、统计学、数据科学、人工智能、数学、管理战略等专业优先；\n2、有风控策略、数据策略、AI产品经理、AI研发、管理决策、管理战略、数据分析、风险管理、内控等相关实习经验者优先；具备ACCA联合培养经历者优先；\n3、英语可作为工作语言者优先；\n4、逻辑清晰，具备良好的沟通表达能力与同理心，具有较强的团队合作精神，快速学习能力和执行力强；\n5、乐于思考，具备高度的责任心与自我驱动力，愿意在实践中持续成长。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667049108856277253","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师（治理风控） - TikTok Shop","city":"上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667049108856277253/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、负责TikTok Shop治理和风控等业务场景下AI Agent的设计、开发与迭代，覆盖从需求分析到架构设计、开发上线的全周期工作，为商家和用户提供智能、高效的产品体验；\n2、将Agent能力深度落地至电商核心场景，包括但不限于智能客服、商品运营辅助、经营决策支持、内容生成与业务流程自动化等，助力商家、达人更好地触达消费者、提升经营效率；\n3、负责Agent技术栈的持续建设与优化，涵盖Context工程、Harness、RAG检索增强、Multi-Agent协同、Memory系统、强化学习、流程编排及知识库构建等方向；\n4、深入理解电商垂直领域的业务逻辑与商家诉求，使Agent能够精准理解并执行专业性强的复杂业务需求，真正解决商家经营中的实际问题；\n5、持续关注AI与大模型领域前沿技术动态，快速将新技术应用于产品迭代。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、具有优秀的代码能力，熟练掌握编程语言；\n3、熟悉Agent架构核心组件的设计原理与调优方案，了解主流开源Agent框架（如LangGraph/Pi等），具备Prompt调优、Harness、RAG、上下文工程、Skill编写等实践经验；\n4、学习能力强，对新技术保有好奇心，善于独立思考与反思总结，具备将复杂问题转化为简洁高效方案的能力；\n5、良好的沟通与跨团队协作能力，热爱技术，拥抱开源，能适应快速变化的业务环境。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7663082289291790597","sourceKey":"bytedance","company":"字节跳动","title":"模型运营（生活服务方向） - 内容质量与数据服务平台","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7663082289291790597/detail","duty":"团队介绍：CQC（中国内容质量与数据服务平台）归属于抖音集团，负责今日头条、抖音、西瓜视频等产品内容和抖音集团商业内容的安全质量与体验，支持各产品的运营和增长，以及为产品线提供AI算法算力的基础支持服务。\n\n1、基于生活服务业务场景（商家、商品、直播、短视频、POI、互动内容质量把控等）及规则理解，设计并编排大模型方案，提升生活服务模型对用户体验、风控等方面的治理能力，输出针对性解决方案；\n2、承接生活服务行业需求，结合数据分析能力（如VVR、漏放率、误杀率等核心指标），建立“需求分析-策略优化-效果反馈-持续跟进”的全链路机制；\n3、对生活服务各业务场景的模型进行调优，挖掘模型优化机会点，协同产品、算法团队推进方案落地，提升内容质量治理效率、降低人力内容质量治理成本；\n4、监控模型异常指标，优化Prompt编排及Workflow架构，对大模型/RAG效果负责，保障大模型内容质量治理策略的稳定性与有效性。","requirements":"1、2027届获得本科及以上学历，自然语言处理、计算机、人工智能、数据科学等相关专业优先；\n2、其余专业有模型领域研究实践经验亦可；了解模型技术，参与过模型训练和优化迭代过程，熟练掌握Prompt编写、应用和优化技巧，了解AI Agents原理，对人机辅助有兴趣有行动；\n3、具备良好的学习能力和沟通协调能力，协调推进各方达到项目目标。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7597372906439657781","sourceKey":"bytedance","company":"字节跳动","title":"运筹优化算法实习生-抖音电商","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7597372906439657781/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n1、参与抖音电商&即时零售业务供应链、物流与即时配送的全链路智能化建设，优化供应链与配送成本，提升用户购物体验；\n2、应用运筹优化&管理、统计推断&机器学习算法手段，对供应链与物流中的各环节建模优化，并与流量分发结合作机制设计，从而实现效率显著优化，作用点包括但不限于：供应链InBound&OutBound决策、配送服务全链路规划设计、实时订单分配/合单决策、物流路径规划等；\n3、深度参与到业务场景的决策设计中，基于海量的用户行为、物流履约数据，挖掘流程优化点，基于数据决策/优化模型，进行商业模式设计和效率优化。","requirements":"1、2027届硕士及以上学位在读，计算机相关专业；\n2、编程动手能力强，擅长Java/Python编程语言，擅长做优化建模解决实际问题、熟悉掌握PyTorch/TensorFlow等进行模型学习和优化。\n3、在计算机CCF-A顶会（KDD、NeurIPS、AAAI、ICML、ACL等）、运筹学顶会有发表过论文者优先、有过实际的物流/供应链建模优化解决经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7456686937463408914","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生 - 中国交易与广告","city":"北京/上海/杭州/成都","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7456686937463408914/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；参与设计系统技术方案，核心代码开发和系统调优；\n2、参与制定代码规范、测试规范，建立起开发质量控制方法；\n3、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n4、参与各专项技术调研、新技术引入等前瞻项目及机器学习与异构计算系统研发。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685659558149064965","sourceKey":"bytedance","company":"字节跳动","title":"产品设计实习生 - 国际支付","city":"上海","category":"UI","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685659558149064965/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与面向国际多市场产品界面设计，深入理解用户需求，推动设计方案从概念到落地；\n2、负责国际支付产品功能设计，包括产品研究、需求对接、流程梳理以及界面优化；\n3、与产品、研发团队协作，确保设计方案的高质量交付。","requirements":"1、本科及以上学历在读，设计相关专业优先；\n2、具备扎实的视觉基础；\n3、熟练使用Figma及其他主流设计工具；\n4、有基础交互设计经验，了解常见设计原则和用户体验思维；\n5、具备良好的沟通协作能力，能清晰表达设计思路，英语表达。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680144862659922181","sourceKey":"bytedance","company":"字节跳动","title":"国际AI增长销售 - 火山引擎","city":"深圳","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680144862659922181/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责对国际化客户进行远程销售，熟练运用IM工具、电话、在线会议、邮件等多元化渠道，推广公司AI相关产品及解决方案；\n2、对客户进行系统性的分类管理，制定差异化销售策略，实现客户价值最大化；\n3、参与从市场策略制定、系统优化、销售转化的运营完整销售链条，实现终端产品销量最大化；\n4、深度运用AI销售工具（如CRM智能分析、自动化营销工具等）进行客户触达、需求分析和销售策略优化；\n5、与全球客户建立良好关系，适应不同文化背景的商务交流模式；\n6、未来发展路径：\n1）外派国际化机会：表现优异者将有机会外派至国际化市场，担任区域销售管理者；\n2）销售领袖培养：通过系统化培训及轮岗实践，快速成长为具备全局视野的销售团队领导者；\n3）AI销售专家：深耕AI产品销售领域，成为兼具技术理解与销售技巧的复合型专家。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、英语可作为工作语言，有AI实践，逻辑思维清晰，具备优秀的学习能力和分析能力，能够快速掌握AI产品技术特点；\n3、对AI产品有浓厚兴趣，具备一定动手能力，乐于探索和应用新技术工具；\n4、小语种优先，英语可作为工作语言，能够流畅进行商务沟通；\n5、具备较强的成就动机，有强烈的目标导向和结果意识，并积极主动完成目标。\n\n我们提供\n1、系统化培训体系：包括AI产品知识、销售技巧、客户关系管理、市场分析等全方位培训；\n2、全球化工作平台：接触国际市场的机会，与全球AI产品团队协同工作；\n3、快速晋升通道：明确的职业发展路径，优秀者将快速晋升至管理岗位；\n4、有竞争力的薪酬福利：具备市场竞争力的薪资方案及完善的福利体系。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675746086036506933","sourceKey":"bytedance","company":"字节跳动","title":"商业化治理宣发实习生 - 广告业务","city":"北京/上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675746086036506933/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、梳理商业信任与安全相关对外传播素材，协助完成案例集锦、稿件初稿等筹备工作；\n2、熟练调用AI工具产出视频脚本、海报文案、图文物料等外宣内容，确保符合品牌调性与传播目标；\n3、协助线下活动的物料准备、现场执行与复盘归档，整理传播数据并输出基础报告；\n4、跟踪行业与产品传播动作，定期输出简报，为团队策略优化提供输入。","requirements":"1、本科及以上学历在读，广告、传播、新闻、市场营销等相关专业优先；\n2、每周到岗至少4天，可连续实习3个月，熟悉字节跳动系产品生态，对互联网广告有基础理解，有相关实习或项目经验者优先；\n3、熟练使用主流AIGC工具完成文案、图像、视频、音频等多模态内容生产；\n4、具备基础Prompt设计与迭代能力，能围绕传播目标高效产出可用成稿；\n5、能将AI工具嵌入日常宣发工作流，独立完成简单文案与基础数据报告撰写；\n6、沟通协作与执行力强，能在多任务并行下按节奏推进交付。\n\n【加分项】\n1、具备一定审美能力，熟练使用平面设计/视频剪辑工具；\n2、拥有可展示的AIGC作品集或完整项目案例；\n3、有自媒体账号运营经验，可提供账号截图或数据表现作为佐证。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670076745041348869","sourceKey":"bytedance","company":"字节跳动","title":"研发工程师（AI垂直场景Agent方向） - 集团信息系统","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670076745041348869/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、作为AI应用工程师，你将端到端地实践AI在业务系统中的应用；通过合理的架构方案，确保平台高效、稳定且可持续演进；你需要与产品、设计及跨区域工程团队紧密协作，推动平台能力、可靠性和开发者体验的持续提升；\n2、设计、构建并持续演进后端服务，确保可维护性、可扩展性与可观测性；通过性能分析、调优和代码质量改进提升系统可靠性；\n3、与产品、设计及跨职能团队合作，交付新功能并优化用户体验；\n4、通过代码评审、架构指导和知识分享指导团队成员成长；\n5、驱动中长期技术路线图，制定清晰的演进策略；\n6、运用成熟方法解决复杂问题，帮助团队更高效地应对技术挑战。","requirements":"1、2027届获得本科及以上学历，计算机科学或相关专业；\n2、后端开发经验或同等技术深度，能够独立负责中等及以上复杂度的系统；\n3、精通Golang/Java/Python（一种或多种），具备扎实的后端架构经验；\n4、熟悉消息中间件、关系型数据库及常见后端设计模式（幂等、重试、限流、异步任务等）；\n5、具备AI Agent相关经验和技能者优先，包括但不限于：\n1）熟悉AI Agent架构设计与开发（如基于LLM的自主决策Agent、多Agent协作系统）；\n2）有Agent工具调用（Tool Use/Function Calling）、规划与推理（Planning&Reasoning）、记忆管理（Memory Management）等核心机制的实践经验；\n3）了解主流Agent框架（如LangChain/LangGraph、Claude Agent SDK等）并有实际项目落地经验；\n4）熟悉RAG（检索增强生成）技术及其在企业级系统中的工程化实践；对Prompt Engineering、上下文管理、Agent可观测性与评估（Eval）有深入理解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669734885844240645","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（数据方向） - 风控","city":"杭州/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669734885844240645/detail","duty":"团队介绍：风控团队由算法、工程、产品三大团队协同构成，为抖音、今日头条、豆包、剪映等字节跳动业务的内容、交易、流量、账号场景提供智能风控，服务十亿级用户；场景对抗性极强、推理链路长、多模态数据海量，是 AI 时代最有挑战的实战领域之一。算法团队推进 LLM/MLLM 与 Agentic AI 的工业化落地，构建下一代智能风控基建；工程团队依托高并发、大数据与大模型，搭建端云一体的多层对抗体系与情报预警；产品团队评估业务风险、制定策略、探索 AI 在风控中的边界。三线协同，打造高效、前瞻的智能风控防线。\n\n1、基于风险数据分析与挖掘，设计可复用、可落地的AI数据产品，参与LLM、Agent、RAG、智能工作流等风控解决方案设计与落地，推动风控数据能力的产品化、平台化沉淀；\n2、综合运用数据挖掘、图谱关联、行为序列分析、逻辑推理等方法，还原互联网风险事件链路（账号安全、交易欺诈、内容安全、营销作弊、爬虫对抗等），挖掘风险行为模式、作弊链路与关键数据特征；\n3、深入理解业务模式与攻防链路，推动风控数据能力在业务场景的深度应用和价值回收，与策略、算法、工程、治理等团队协同，围绕重点风险问题制定解决方案，推动风险治理闭环落地。","requirements":"1、2027届获得本科及以上学历，信息安全、计算机、人工智能、数据科学等相关专业优先；\n2、具备扎实的数据分析能力，熟练掌握SQL，能够独立完成复杂数据提取与建模分析；对LLM及AI Agent有持续兴趣和实践，能够借助AI编程工具快速搭建并验证产品原型；有AI产品、Agent、RAG或智能工作流相关的独立项目、科研竞赛或实习经历者优先；\n3、具备良好的产品化思维、优秀的跨团队沟通和项目推进能力，能够协调策略、算法、工程、治理等多方资源，推动数据能力复用与规模化落地应用，取得业务价值。\n\n加分项\n1、有一定安全技术理解能力，有移动端逆向、Windows逆向、渗透测试、Web攻防等经验；\n2、对数据挖掘或行为算法有认知，掌握Python、Go、Java、C/C++、JavaScript等一门编程语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667456050472929541","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生 - TRAE","city":"杭州","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667456050472929541/detail","duty":"团队介绍：TRAE是字节跳动旗下AI办公工具，产品已上线国际版与中国版，拥有TRAE IDE和TRAE Work两种产品；既可以用TRAE IDE写代码、读项目、改Bug，也可以用TRAE Work写方案、做分析、做应用、推进协作。TRAE当前支持PC、手机、Web多端使用，让用户随时随地高效产出！ Let TRAE Work For You！同时我们正在寻找充满热情、富有创造力的人才。期待你的加入！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与TRAE产品与技术体系的持续演进，共同打造覆盖办公与研发场景的端到端智能协作平台；\n2、以全栈视角参与AI产品的探索与开发，覆盖AI Native交互、Agent、上下文工程、工具调用、服务编排及基础框架等方向；\n3、与产品、设计、算法及工程团队协作，参与功能从需求探索、技术设计、开发验证到上线迭代的完整过程。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、理解计算机原理，有良好的数据结构和算法基础，有扎实的编程能力；\n3、具备强烈的好奇心和快速学习能力，有良好的沟通表达能力和团队协作能力；\n4、掌握JavaScript／TypeScript，熟悉React或Vue等Web开发主流框架，关注前端前沿趋势。\n\n有以下经验者加分：\n1、使用过TRAE／Claude Code／Codex等AI产品并提交过反馈；\n2、GitHub有前端项目／开源贡献；\n3、参与过编程竞赛或黑客马拉松。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664635491589884213","sourceKey":"bytedance","company":"字节跳动","title":"RTC视频工程开发工程师 - 音视频技术","city":"上海","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664635491589884213/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责对话式AI、抖音连麦、社交IM通话、云游戏等RTC场景下的视频引擎的工程研发、算法实现及性能优化；\n2、负责对话式AI、抖音连麦、社交IM通话、云游戏等RTC场景下的视频引擎的架构演进、先进技术研究；\n3、负责对话式AI、抖音连麦、社交IM通话、云游戏等RTC场景下的视频体验优化。","requirements":"1、获得2027届本科及以上学历，计算机科学相关专业优先；\n2、掌握常见视频编解码标准（H.264/H.265/H.266等），能够进行各平台硬件编码器（比如VideoToolBox、MediaCodec、OH_AVCodec、NvEnc等）的适配调优；\n3、熟悉常见流媒体传输协议，如RTP/RTCP、RTMP等；\n4、熟悉流媒体视频传输的各式弱网对抗算法，含动态升降级、带宽估计及冗余策略、多人适配；\n5、有性能优化经验，熟悉CPU/GPU性能分析工具，能定位并解决性能瓶颈；\n6、有OpenGL和视频采集渲染经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7639665619631278341","sourceKey":"bytedance","company":"字节跳动","title":"战略分析实习生-广告业务","city":"北京","category":"战略","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7639665619631278341/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：广告业务为抖音集团的商业变现提供产品、技术、运营及市场支持，负责端到端大型广告系统建设，覆盖抖音、今日头条、西瓜视频、番茄小说、穿山甲等产品矩阵，践行“激发生意新可能”理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的AI营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到全球先进的商业产品架构、模型、算法、运营模式和营销理念，在互联网广告行业始终创新。\n\n1、支持商业化AI方向战略分析项目，协助完成外部信息搜集、洞察报告撰写等工作；\n2、深入研究AI技术&应用层，洞察电商、广告等行业动态并跟踪竞媒动作，参与商业化行业和产品策略的洞察与落地。","requirements":"1、本科及以上学历在读；\n2、有咨询/战略/行业研究/投资经历加分，逻辑清晰、总结概括能力强；\n3、热爱AI行业，且对行业产品更迭保持好奇，有深度应用经验，如有自行搭建AI产品/应用经验加分；\n4、可线下实习5个月及以上、每周4天及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7633862453017790725","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发实习生-App Infra","city":"杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7633862453017790725/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：App Infra是字节跳动面向应用的基建中台部门，以App侧性能/稳定性深度优化为基础，结合LLM、Agent、生成式推荐模型等前沿技术，为字节跳动旗下的核心应用提供终端+平台的解决方案。于下层，结合操作系统、虚拟机、工具链、编译器等技术，建设了稳定性、流畅性、电量在内全链路的监控体系和调试分析工具；于上层，则结合端侧特征工程、深度学习模型/决策树模型/SLM训练等基建，围绕搜索/推荐/广告/直播/电商等场景，建设了云端协同推荐、品质体验优化等端智能解决方案。如果你热爱挑战底层技术、追求极致优化，又渴望把AI转化为千万用户感受得到的流畅与智能——欢迎加入，和我们一起打造下一代移动体验！\n\n1、面向字节跳动客户端研发场景，搭建稳定、高效的Agent Harness（涵盖移动运行时知识库、Skills&CLI、规模化验证体系等），并基于Trace机制持续优化长程执行的效率与效果；\n2、面向客户端研发全流程，整合Issue Diagnosis、Coding、回顾与Validation等能力，构建并标准化AI Agent体系，推动在TRAE等IDE及研发平台的规模化落地，持续提升Agent在真实研发场景中的稳定性、可控性与研发效率。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备扎实的软件工程基础与客户端研发经验，有完整的研发流程经历；\n3、熟悉大模型与AI Agent相关技术，具备良好协作能力，能与团队协作持续优化Agent效果。\n\n加分项\n1、具备在IDE或研发平台侧推动能力落地的实践经验；\n2、有AI Coding、自动化测试或开发工具链相关项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594312137523497269","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-抖音","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594312137523497269/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音APP产品的算法工作，共同搭建业界领先的推荐系统、内容理解系统，为用户提供一流的产品体验；\n2、深入理解业务和机器学习技术，优化模型&策略，持续提升推荐效果；\n3、深入理解用户行为，结合数据挖掘等技术，优化用户创作和浏览等体验；\n4、在抖音各个业务场景应用内容算法，改进内容社区的运行效率，支持下游的算法和产品需求；\n5、和产品、运营团队紧密合作，通过对产品和用户的深入理解和分析，制定算法策略促进抖音生态的长期繁荣发展。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、对推荐算法和机器学习有热情、乐于学习、思考和创新；\n4、优秀的分析问题和解决问题的能力，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎、CV、NLP、语音、LLM、AIGC等相关领域有经验者优先；\n6、每周可实习4天以上，实习时间3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593366734639171845","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-AI Platform","city":"深圳","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593366734639171845/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、负责LLM驱动的AI Agent框架及平台的研究和实现，确保技术的创新与前瞻性；\n2、根据应用场景的需求，优化并提升Agent效果；\n3、持续追踪AI Agent领域的最新技术趋势和研究成果，将前沿技术整合进我们的产品中。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、自动化、数学相关专业优先；\n2、精通Go、Python、C++等一种或多种编程语言，具备扎实的编程技能和算法设计能力；\n3、对AI Agent技术有深入了解，熟悉LangChain等框架，熟悉LangSmith等平台；\n4、具备出色的团队协作精神和良好的英文阅读及沟通能力。\n\n加分项：\n1、在LLM工程领域有落地经验；\n2、对AgentOps平台熟悉，如LangSmith、Langfuse等；\n3、有不错的研究和探索精神，对最新Agent技术趋势和论文有不错的了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7584739373306644741","sourceKey":"bytedance","company":"字节跳动","title":"VLM数据运营（世界模型）实习生 - AI数据与安全","city":"成都/北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7584739373306644741/detail","duty":"团队介绍：AI 数据与安全团队为 Seed 基座模型及 AI 原生应用提供跨模态数据服务，覆盖数据生产全流程，包含模型评估标准的制定、数据规模化生产、数据飞轮搭建，不断提升数据质量，支持模型快速迭代。\n团队由产品经理、数据工程、数据运营等跨职能人才组成，并通过与 Seed 研究员、行业专家、全球顶尖数据供应商紧密合作，从真实场景中收集反馈并分析模型表现数据，解决 AI 前沿突破过程中的复杂数据问题，推动模型性能与用户体验的双重提升。我们既是帮助模型技术迭代的一线贡献者，也是模型和 AI 产品的一手用户。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深度参与世界模型训练所需视频、图像的数据生产及标注全流程，基于模型能力边界与训练目标，输出视觉数据标注策略及标准，支撑图像、视频数据资产的规模化交付；\n2、负责对接数据供应商及数据标注团队，明确任务需求，把控任务交付进度及质量，独立完成项目交付；设计并优化高质量多模态（文本、图像、视频、3D资产）数据集的构建流程，主导清洗、标注、SFT及RL的数据策略设计；\n3、基于摄影、剪辑、绘图、3D建模或视觉设计等实操经验，完成图像、视频素材的标准化处理及标注，实现自动化数据处理链路，探索合成数据的生成策略；\n4、具备一定代码能力，能够利用Python或其他编程语言实现标注辅助（如数据提取、数据质检、格式校验等），提升人工标注效率与一致性；\n5、结合世界模型场景，参与Prompt策略设计与效果验证，提升模型生成结果的可控性与语义对齐度。","requirements":"1、本科及以上学历在读，数字媒体、计算机、人机交互、图形学等计算机相关交叉学科专业背景优先；\n2、具备优秀的视觉感知力、结构化表达能力，逻辑清晰、表达严谨，拥有跨职能协作意识与快速学习能力；熟悉摄影、视频剪辑、数字绘画、3D建模、主流游戏引擎（UE/Unity）、3D空间逻辑、物理引擎仿真，掌握至少1类主流视觉内容生产工具（如Photoshop、Premiere、Blender、Procreate等）；能从创作视角理解画面构成、光影逻辑与语义层次；\n3、理解大模型基础原理（如Transformer架构、SFT/RLHF训练范式），持续追踪AIGC前沿进展；具备基础编程能力（Python优先），可通过脚本辅助完成数据清洗、数据标注、格式校验等自动化任务；\n4、有面向大模型训练的数据标注、描述撰写或质量校验项目经历者优先；能主动识别数据偏差（如描述模糊、细节遗漏、逻辑断裂）并提出可落地的优化建议；熟悉Prompt Engineering基本方法。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7581808582627281205","sourceKey":"bytedance","company":"字节跳动","title":"安全攻防实习生-安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7581808582627281205/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动安全与风控部门，负责公司信息安全的建设、规划和管理工作。致力于为亿万用户的数据安全保驾护航，为字节跳动的每一位用户打造健康自由交流的防护盾。作为企业信息安全的新生力量，以技术为基石，全面提升前瞻性研究和自动化能力。团队积极布局安全人才培养与招募，在北京、上海、深圳、杭州、南京、硅谷、伦敦、新加坡均设有安全研发中心，逐步和信息安全领域的知名高校、研究机构建立深度合作，与安全人才、高校、行业共同努力，建设并反哺互联网安全生态。\n\n1、AI赋能红队：将大模型、机器学习等技术应用于红队攻防，搭建自动化攻击工具，提升漏洞挖掘、红队攻防效率；\n2、AI安全红队：开展AI系统（大模型/AI应用等）安全测试，挖掘数据、算法、对抗攻击等方面的安全风险；\n3、参与实战演练与技术预研，跟踪前沿动态，总结攻防经验，优化技术方案与工具；\n4、撰写技术文档/测试报告，参与团队分享，协助提升团队AI攻防综合能力。","requirements":"1、本科及以上学历在读，计算机/信息安全/人工智能等相关专业；\n2、对红队攻防、AI安全领域有浓厚兴趣，了解基础的Web渗透、漏洞挖掘概念者优先；\n3、了解至少一种AI框架（TensorFlow/PyTorch等）基础用法，对大模型应用、对抗攻击有初步认知者优先；\n4、熟悉Python编程语言，具备基础的代码编写与简单工具使用能力；\n5、学习能力强、态度积极，具备良好的沟通能力与团队协作意识；可保证至少3个月全职实习（每周≥4天）。\n\n加分项：\n1、有CTF比赛参与经历、在校AI/安全相关项目经验，或相关技术博客/开源贡献者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7478196331363191058","sourceKey":"bytedance","company":"字节跳动","title":"内容生态产品运营实习生-TikTok","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7478196331363191058/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、负责TikTok内容社区的生态与作者相关工作，对内容和创作者体验有自己的了解，深入理解平台的生态治理系统，通过数据定量分析和定性观察，从用户与作者体验角度发现和推动问题的解决；\n2、通过标注分析发现和归类问题，协助标注项目运营和管理；\n3、能够跨团队进行产品设计与落地，与研发、推荐算法、数据分析师协同，改善体验问题。","requirements":"1、本科及以上学历在读，专业不限；\n2、实习6个月以上，每周保证5天实习时间优先，能尽快到岗者优先；\n3、英语可作为工作语言；\n4、有较强的数据分析能力，掌握SQL等语言能力者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674944037608409349","sourceKey":"bytedance","company":"字节跳动","title":"AIGC产品实习生（IAA方向） - 广告业务","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674944037608409349/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、了解广告主需求和投放策略，结合AIGC等新技术，参与短漫剧×游戏广告/内容素材的自动化生产与优化；\n2、协助端到端的产品能力设计和方案执行落地，包括但不限于素材生成策略、投放策略适配等；\n3、关注AIGC与游戏行业、短漫剧行业趋势，探索更原生化的创新变现模式。","requirements":"1、本科及以上学历在读，专业不限；\n2、能保证每周实习4天，可连续实习3个月，有广告策略或素材生产经验，熟悉AIGC生成模型的优化及评测方法优先；\n3、对AIGC和生成模型相关技术有了解或强兴趣，学习能力强；\n4、具备良好的逻辑思维能力、沟通协作能力和自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671247934645766405","sourceKey":"bytedance","company":"字节跳动","title":"招聘（研发方向）实习生 - 人力与管理部","city":"上海","category":"人力","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671247934645766405/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、主要支持的岗位类型包括但不限于大语言模型算法、大模型数据、高性能计算/基础架构等岗位；\n2、深入了解所支持业务和团队运作状况，理解业务目标并促进人力资源战略在业务部门的有效实施；\n3、负责AI、搜索、推荐、算法、计算机等技术人才的寻访、人才面试与判断、人才升级，管理招聘相关项目（如人才地图搜索、参与业内人才薪酬调研等）及招聘渠道（如猎头渠道管理、招聘网站资源管理）；\n4、分析招聘数据，向业务团队和人力资源业务伙伴提供人才与岗位配置的建议，提升招聘有效性。","requirements":"1、2027届本科及以上学历在读，理工类、管理类相关专业背景优先；\n2、乐于并善于与不同背景的技术人员交流，能够快速建立信任；\n3、人才甄选面试与甄选能力，较高的人际敏感度和影响力；\n4、热爱招聘，自我驱动力强；\n5、乐于思考，具备高度的责任心与自我驱动力，愿意在实践中持续成长；\n6、请在简历中标注：\n1）意向工作地点。\n\n加分项：\n1、英文流利，愿意接受调剂到其他岗位面试。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668599371989010693","sourceKey":"bytedance","company":"字节跳动","title":"智能体安全攻防工程师 - 安全与风控","city":"北京/深圳","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668599371989010693/detail","duty":"团队介绍：我们团队研发尖端云安全解决方案，为字节跳动及企业客户提供规模化安全防护。\n依托安全部门深厚的技术积累，以及对客户安全需求的深刻理解，我们借助领先技术与产品，通过全方位智能防御体系应对各类实际安全挑战。\n我们的工作确保云环境始终安全、可靠，为整个组织的创新实践提供有力支撑。\n\n1、负责构建AI-Native安全平台能力，包括但不限于RedTeaming，智能分析研判、溯源和运营；\n2、负责智能体的先进性预研、开发和安全效果保障；\n3、负责跟踪业界安全动向，特别是安全方向智能体AI for Security相关最新技术；\n4、负责协同研发团队，形成安全引擎的技术需求；\n5、负责团队的安全能力输出；\n6、协助部门负责人培养安全攻防和运营相关人员。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、熟悉网络和主机安全原理和攻防；\n3、熟悉智能体架构、开发相关；\n4、熟练掌握Python、Shell、Yara、Lua或Golang语言；\n5、快速掌握AI Coding最佳实践。\n\n加分项：\n1、参加过CTF类竞赛并拿过名次优先；\n2、参加过HW攻防、值守等优先；\n3、熟悉大模型/智能体Harness Engineering,SFT等实践优先；\n4、To B安全厂商核心攻防能力开发者、研究者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665996013031393541","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 抖音平台产品","city":"北京/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665996013031393541/detail","duty":"团队介绍：\n平台产品基础：作为抖音平台支撑团队，以 AI为核心抓手，打造高效能平台底座，为全业务线筑牢坚实底层支撑\n生态与运营：聚焦创作者成长与商业化，激活生态活力，夯实内容根基\n营销搭建：全链路营销体系，助力业务推广，实现品效增长\n文娱业务：深耕短剧赛道，打通内容 - 营收 - 宣发全链路，构建健康文娱生态\n变现与资金平台：筑牢交易结算核心底盘，提供全链路支付与清结算能力，保障平台资金安全与高效流转\n治理・体验・客服：三位一体守护平台安全、用户体验 以及 高效响应解决用户诉求\n开放业务：有序开放平台能力与数据，链接外部资源，拓展生态边界\n全体团队以业务增长与用户价值为核心，持续深耕、协同共进，推动抖音生态持续繁荣。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验，参与设计系统技术方案、代码开发和系统调优；\n2、参与制定代码规范、测试规范，建立起开发质量控制方法；\n3、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n4、参与各专项技术调研，新技术引入等前瞻项目；\n5、参与机器学习与异构计算系统研发。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665338691738863877","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 飞书多维表格","city":"北京/深圳","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665338691738863877/detail","duty":"团队介绍：多维表格是一款无代码搭建平台。凭借强大灵活的数据库、丰富富多样的视图组件、自由高效的自动化与工作流、开放的生态体系,以及专业级的BI仪表盘和应用模式,让每个人都能快速构建属于自己的业务系统。\n在此基础上,我们正在全面融合AI,让系统真正具备智能化能力。我们的愿景是：打造下一代办公人的Work OS--一个可以构建任何解决方案的平台，没有边界，没有限制。\n\n1、参与多维表格的产品规划和设计，结合用户需求与AI技术提出创新方案；\n2、推动AI技术在多维表格业务场景和功能模块中的实际应用，提升产品竞争力；\n3、参与用户需求调研和数据分析，撰写需求，与研发、设计团队合作推进产品落地；\n4、参与产品效果评估，关注用户反馈和行业进展，推动产品迭代。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、数学、工业设计等相关专业优先；\n2、对AI技术与应用充满热情，对AI产品有优秀的理解能力；\n3、具备优秀的逻辑思维能力和产品意识，有团队协作精神；\n4、注重用户体验，对产品设计和用户交互有一定认识；\n5、具备较好的技术基础，熟悉深度学习/语言模型等AI相关知识、Python等编程语言优先；\n6、积极主动，勇于学习和尝试新事物，有产品经理实习或项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7433729711546976521","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法（质量智能方向）实习生-开发者服务","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7433729711546976521/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、参与开发者服务型产品建设和算法研究工作；实习内容涉及大模型相关的Prompt、微调、智能体、RAG等方向探索、智能运维、数据工程、AI评测等；\n2、持续跟进LLM前沿技术，为团队提供前沿的知识和见解，支持模型效果的研发落地和持续优化。","requirements":"1、硕士及以上学位在读，计算机、人工智能、自动化、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握至少一门编程语言，包括但不限于Python、Java、Go等，在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、拥有机器学习领域的研究经历，特别是在大语言模型（LLMs）和生成式人工智能等方面，在NeurIPS、ICLR、SIGGRAPH等顶会上发表过论文者优先，主导过业内影响力较大的项目者优先；\n4、熟悉大模型领域的数据工程建设、预训练、SFT、RLHF等流程，具备实操经验及项目实践者优先；\n5、熟悉Prompt Engineering、AI Agent、RAG等技术者优先，有使用LangChain、Data-Juicer等经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680090754324351285","sourceKey":"bytedance","company":"字节跳动","title":"增长产品运营实习生 - TikTok直播","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680090754324351285/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播是全球领先的直播业务，以实时互动为核心，提供多元化的商业化模式和创作工具。我们为用户提供独特的内容和消费体验；为创作者找到合适的观众，提供最好的工具和一系列盈利模式，帮助创作者创造更多机会、改变他们的生活；通过直播，平台也能从中获得健康、客观的商业化收益，持续发展。我们一直听到这样的故事 —— “LIVE changes my life” —— 他们更好，我们才会更好。\n\n加入我们，一起探索 “不可能的事”—— 我们是行业的先行者，在一步步改变行业。我们持续让行业了解直播是一种新的内容形式，是创作者可以依赖的商业模式。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、围绕TikTok LIVE产品能力，负责新功能及直播工具的全平台推广，协助协调平台及区域资源，对Creator Network、主播及用户进行教育与渗透，提升功能使用规模及用户满意度；\n2、协助搭建TikTok LIVE供应商体系，帮助创作者进行工具和设备升级，同时建设AI创作能力生态，总结沉淀AI工具在直播场景中的最佳实践，探索AI驱动的内容创新玩法及互动形式；负责AI实时互动内容创作工具的运营与落地，推动AI工具在直播场景中的渗透，设计创作者使用路径与运营策略，基于数据反馈与用户洞察推动AI能力持续优化与产品迭代；\n3、负责直播工具及核心功能的运营策略设计与执行，推动互动玩法、内容生产工具等在直播场景中的使用率提升，优化用户体验与内容表现；\n4、基于平台核心指标，建立高频数据监控与分析机制，及时识别业务波动与风险，通过数据分析支持运营策略优化及业务决策，同时对接数仓及数据团队，优化现有数据后台体系，推动新业务数据能力建设；\n5、以提升平台优质内容供给为目标，持续优化内容结构与创作效率，推动TikTok LIVE生态健康增长。","requirements":"1、本科及以上学历在读，理工科背景；\n2、有产品运营/增长经验优先；具备较强的数据及业务分析能力，善于通过数据分析挖掘共性问题并推动相关方共同制定解决方案；\n3、思维逻辑清晰，沟通表达好，具备较强的跨团队协作能力；\n4、自驱力强，具备较强的学习能力；\n5、对体验类运营具有较高的热情，认可体验类运营的价值并愿意为之长期投入；\n6、英语流利，有国际化工作或留学经历者优先。\n\n加分项：\n1、目对人工智能内容创作（AIGC）方向有兴趣或基础认知，有相关工具使用或项目经验者优先（如内容生成、互动玩法、人工智能辅助创作等）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669713389022791989","sourceKey":"bytedance","company":"字节跳动","title":"增长策略产品经理 - 今日头条","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669713389022791989/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n1、负责今日头条系各产品的用户增长承接推荐策略，直接对DAU、DNU、留存、LT等结果负责；\n2、理解效果广告逻辑，挖掘用户体验和消费的价值路径，做好新用户承接，优化投放效果，带动DAU增长；\n3、深入做好某一增长方向的目标制定和思路拆解，定位核心问题，找到关键解法，具备平台化思维，能沉淀多端可复用的策略方法提效；\n4、跨部门高效协同投放、研发、运营、分析师等多团队，共同实现产品增长。","requirements":"1、2027届获得本科及以上学历，具有增长策略产品、广告投放策略、商业化产品运营等背景优先；\n2、理解计算广告，对广告系统、媒体能力等有深刻理解或应用经验；\n3、具备清晰的逻辑思维框架，善于分析问题和归纳总结，结果导向，有较强的数据分析能力；\n4、具备优秀的沟通协作能力，责任心强、执行力强、有韧性。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669707798918007045","sourceKey":"bytedance","company":"字节跳动","title":"数据分析师 - 番茄小说","city":"北京","category":"数据分析","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669707798918007045/detail","duty":"团队介绍：番茄小说是抖音在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n\n1、负责番茄小说相关业务的数据分析工作；\n2、分析各项影响产品提升与增长的因素，结合业务方向，给出可落地的整体产品优化方案；\n3、与产品/运营/研发等配合，推进优化方案落地执行，带来业务的实际提升增长；\n4、负责业务上各类A/B实验设计与分析，产品优化效果、市场活动分析评估等工作；\n5、建设业务分析模型，并不断评估和优化。","requirements":"1、2027届获得本科及以上学历，数学、统计学、计算机相关专业优先；\n2、有数据分析经验、一线产品或运营业务优化经验者优先；\n3、逻辑清晰，对数据敏感，能发掘业务细节和数据之间的联系，并通过数据指标推动优化；\n4、精通SQL，熟练使用R/Python进行数据分析、挖掘，掌握Tableau等BI工具尤佳；\n5、具有良好的团队配合能力，沟通能力；\n6、热爱阅读，对小说、漫画、有声书等内容品类产品有深入思考、分析经验者尤佳。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669706686816569605","sourceKey":"bytedance","company":"字节跳动","title":"分发策略产品经理 - 番茄小说","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669706686816569605/detail","duty":"团队介绍：番茄小说是抖音在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n\n1、负责悟空浏览器推荐系统的核心算法策略迭代，提升推荐分发效率；\n2、针对短剧、小说、漫剧、音乐、网页等多体裁内容，设计差异化的分发策略，能够从用户视角和经营视角，提升流量的使用效率；\n3、以用户消费与活跃为核心目标，设计并推动相关产品策略落地；关注内容生态的健康度与多样性建设，构建科学的指标体系与实验框架，精准归因策略价值，并有效控制产品与业务风险；\n4、积极探索前沿AI技术在推荐系统中的应用，利用大模型等能力提升内容理解、用户洞察与策略调控的智能化水平，驱动业务创新。","requirements":"1、2027届获得本科及以上学历；\n2、具备优秀的数据分析能力和数据驱动的决策习惯，精通A/B测试方法论，能从数据中发现问题并定位根本原因；\n3、对内容生态建设有深入思考和实践经验，熟悉内容生产、消费、治理等环节，有社区或内容平台经验者优先；\n4、逻辑严谨，具备出色的产品抽象和系统化思考能力，能清晰地规划复杂系统的演进路径；\n5、自我驱动，对新技术和新方向充满好奇心，能快速学习并应用于实践；\n6、具备卓越的沟通、协调和项目管理能力，能够高效推动跨团队合作，确保复杂项目的顺利落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668616776146487605","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师 - 豆包","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668616776146487605/detail","duty":"团队介绍：字节跳动Flow产品研发团队，专注研究AI智能化相关业务落地，目前落地豆包等APP，以及Bot开发平台等AI智能化创新产品。其中，豆包是一款基于字节自研模型的AI智能助手，能为你答疑解惑，查询信息，提供灵感，辅助创作，也可以和你聊任何感兴趣的话题。业务和团队均处于快速发展期，成长空间大，欢迎各位同学加入！\n\n1、负责豆包创意Agent技术研发，提升大模型在创意场景的应用能力，包括Multi-Agent框架、评测机制等基础能力建设；\n2、探索Agent方向的创新方法与技术，提出更先进的Agent范式，引领行业技术发展；\n3、探索面向Agent的评估方法，构建豆包的Agent评估体系；\n4、设计并实现易用高效的Agent开发周边套件工具，提升开发效率，降低使用Agent技术的门槛，保障交付质量。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、熟练掌握Python/Java/Go等至少一门语言，有项目开发经验者优先；\n3、对大模型有深入理解，熟悉LLM技术原理与应用方法，有Agent系统设计与实现经验；了解Memory机制、RAG、工具调用、规划执行等Agent关键技术，有相关实践经验；\n4、深入理解Agent相关技术方法，具备强化学习、规划算法实践经验者加分；\n5、对AI原生应用有热情，具备快速复现论文及工程化能力，顶会论文或开源项目贡献者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668599082802039045","sourceKey":"bytedance","company":"字节跳动","title":"大模型安全研发工程师 - 安全与风控","city":"北京/深圳","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668599082802039045/detail","duty":"团队介绍：我们团队研发尖端云安全解决方案，为字节跳动及企业客户提供规模化安全防护。\n依托安全部门深厚的技术积累，以及对客户安全需求的深刻理解，我们借助领先技术与产品，通过全方位智能防御体系应对各类实际安全挑战。\n我们的工作确保云环境始终安全、可靠，为整个组织的创新实践提供有力支撑。\n\n1、深度参与安全智能体应用的研发，工程优化和应用过程中的技术落地工作；\n2、负责大模型应用关键技术突破，构建安全智能体核心竞争力，支撑安全智能体业务的快速推进和迭代；\n3、跟踪前沿技术与行业动态，持续创新安全应用解决方案，保持公司在安全技术领域的竞争力。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、熟练掌握Linux/Mac/Windows平台的各种开发技能；\n3、精通一种或几种以下语言，Python/Go/Java/C++等等；\n4、熟悉常用算法和数据结构，熟悉网络编程、多线程编程技术；\n5、善于学习和运用新知识，具有良好的分析和解决问题能力；\n6、具有良好的团队合作精神和积极主动的沟通意识。\n\n加分项：\n1、了解大模型应用，有Agent/Prompt/RAG相关设计及实践参与者更优，了解CoT、ToT等智能体组织形式；\n2、有过LangChain/AutoGPT/K8s等工具使用经验，熟悉常规大模型工程开发体系，有大模型部署、推理优化加速经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668294219304470837","sourceKey":"bytedance","company":"字节跳动","title":"成本管理专员 - Corporate Services","city":"北京","category":"职能 / 支持","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668294219304470837/detail","duty":"团队介绍：企业服务团队致力于为全球ByteDancer提供最佳的管理和员工体验，我们支持员工协同并高效地完成工作，同时保护和促进公司的业务发展。企业服务团队通过专业服务来改善ByteDancer的体验，同时建立并不断探索可广泛共享的新行业最佳实践。\n\n1、全球成本数据管理：收集、整理并分析全球各办公室的成本数据，确保数据完整、准确、可追溯；\n2、项目资料整理：协助归档、整理各类项目资料，维护资料的结构化与规范化；\n3、专项数据分析与文档支持：参与专项数据分析工作，并支持相关文档撰写；\n4、价格数据沉淀：负责标准清单及历史项目数据库的价格信息沉淀与维护，逐步搭建可复用的价格基线。","requirements":"1、2027届获得本科及以上学历，工程造价、工程管理、建筑工程、机电工程等相关专业优先；\n2、具备较强的数据整理与分析能力，对数据敏感、善于发现规律与异常；\n3、学习能力强，逻辑思维清晰，能快速理解业务与分析框架；\n4、细心踏实，责任心强，能耐心处理大量明细数据；\n5、英语能力较好，可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668267255849355573","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师 - Seed 产品研发","city":"杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668267255849355573/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书项目核心模块的前后端全链路研发，端到端负责功能设计、开发、测试与上线；\n2、不断探索各种新技术，参与系统架构演进、性能与稳定性优化，保障平台在大规模企业客户下的高可用；\n3、以AI为默认工作方式，深度实践AI Coding，持续沉淀团队研发提效方法与工具。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、数据结构、算法、操作系统、网络、数据库基础扎实，熟练掌握至少一门主流编程语言（Go/TypeScript/Java/Python等），代码逻辑清晰、结构良好；\n3、至少熟练使用一种AI编码工具Cursor/Claude Code/Copilot/TRAE/Codex等；了解大模型、Agent、RAG、MCP、CLI、Prompt、Harness等核心概念并有自己的理解；能识别AI输出的正确性、风险与边界，并设计验证机制；\n4、具备良好的逻辑思考与问题拆解能力，好奇心与学习动手能力强，主动自驱，面对复杂问题有攻坚钻研的韧性，沟通协作顺畅。\n\n加分项\n1、独立AI相关作品项目经验；\n2、优秀的开源贡献或个人项目；\n3、ACM/NOI/CTF等竞赛获奖；\n4、有To B/SaaS类产品实习或复杂业务开发经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667811127270934837","sourceKey":"bytedance","company":"字节跳动","title":"国际直播前端开发工程师（活动方向） - TikTok研发","city":"深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667811127270934837/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与业务产品研发，深度参与产品需求讨论，C端和B端的功能构建等；\n2、参与设计基于前端和全栈的解决方案，核心代码开发、组件抽象以及系统调优等；\n3、参与系统工程效率和性能优化，提升研发效率以及用户体验；\n4、调研和学习前端新技术，进行技术分享并在重要项目内落地，参与部门前端和全栈技术建设。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学，对数据分析、前端架构、渲染和性能等技术有热情；\n3、精通JavaScript、HTML、CSS，熟悉DOM、HTTP协议等前端领域知识，至少掌握一种主流前端框架（如React/Vue等）；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习能力和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666017588976535861","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师（AI创作方向） - 抖音用户产品","city":"北京/杭州/广州/深圳/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666017588976535861/detail","duty":"团队介绍：抖音用户产品研发团队为抖音全业务提供研发支持与底层技术能力，是驱动业务持续进化的重要工程力量之一。团队围绕首页、推荐、搜索、图文、中长视频、AI 创作、相机、账号及社交通讯等核心场景，承担从客户端、服务端到 AI 工程链路的端到端建设，在亿级 DAU 的真实流量下，持续攻坚极致体验与前沿 AI 系统的工程命题。\n我们相信，AI 正在重塑产品的底层架构。团队依托大模型与多模态技术、Multi-Agent 系统工程、在线推理与评测基础设施，面向下一代 AI 原生应用持续投入：在社交与通讯场景，探索长期记忆、多模态理解与人格化对话的技术边界，构建真正能陪伴用户的 AI 交互系统；在内容与创作场景，建设面向亿级创作者的多模态生成与可控创作引擎，让 AI 成为创作者的表达延伸；在搜索与信息获取场景，探索生成式检索、Agentic Search 与个性化推理的新一代系统架构，重新定义 \"人与信息\" 的连接方式。\n这里有工业界领先规模的真实流量，有最前沿的 AI 工程命题，也有一群把技术做到极致的同行者。诚邀热爱技术、追求极致、渴望在真实世界解决硬核问题的你加入我们，一起在 Agent 驱动的技术浪潮中，构建支撑大规模用户的新一代产品。\n\n1、负责抖音AI创作多场景下的智能体应用服务开发、包括不限于为多轮对话，形象、视频生成、剧本生成、自由开放式创作等场景提供解决方案；\n2、负责上述业务的智能服务链路稳定性、效果的持续优化，以及线上监控保障体系构建；\n3、负责各智能体涉及到的多端工具、技能、知识库、记忆等服务架构的设计，在效果与稳定性上配合好评测团队达到用户体验和上线标准；\n4、能够协同算法团队在智能体应用服务环节落地垂类算法模型，打磨效果的同时降低推理成本；\n5、紧跟行业AI范式，从模型到智能体架构到工作流能够做到快速复现和推动在业务中落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、开发语言和技术栈不限，熟悉Golang/Python/TypeScript优先，并熟悉常见的软件开发模式；\n3、对AI应用方向有强烈的兴趣，熟悉Agent相关的常见范式架构，如Plan&Excute、ReAct、Workflow等，熟悉模型的工作原理和特性，并能结合原理和特性做稳定性、成本和效果优化优先；\n4、业务理解能力强，能够针对业务上的需求梳理业务边界并快速匹配最适合的Agent工作流范式；\n5、对行业流行的常见模型优缺点有大致的了解，并了解如何系统科学的评测帮助做模型选型；\n6、掌握模型原理优先，对常见的CNN、RNN、Transformer模型结构及推理架构有一定的了解优先，对模型的二次训练原理及方法了解优先，如SFT、LoRA-SFT、DPO等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7597386874797345077","sourceKey":"bytedance","company":"字节跳动","title":"智能营销与增长算法实习生-抖音电商","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7597386874797345077/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n1、负责端到端出价大模型研发落地，基于RL/DT构建框架，优化离线模拟系统，推动出价决策向大模型范式升级；\n2、参与One-Transformer架构设计，主导多特征统一建模，探索召粗精多任务框架，提升营销效果与算力效率；\n3、负责智能营销全域优化，搭建边际成本模型，设计发券机制，建模营销体验痛点，实现全局效率最优；\n4、研究大模型蒸馏技术，设计多端Teacher-Student架构，优化训练与推理方案，平衡性能与成本；\n5、融合LLM与多模态技术研发营销方案，优化排序逻辑，解决信息茧房、冷启动等痛点；\n6、探索因果建模方法，结合RCT与观测数据优化模型，实现短期转化与用户长期价值协同建模。","requirements":"1、2027届硕士及以上学位在读，计算机、数学、机器学习等相关专业优先；\n2、扎实掌握机器学习核心理论，熟悉LLM/LRM、强化学习、TransFormer等技术，深入理解大模型Scaling Law与蒸馏技术；\n3、熟练使用Python、TensorFlow/PyTorch，具备全流程工程实现能力，可独立完成模型设计、训练与部署；\n4、具备强业务理解力与问题解决能力，能定位电商核心痛点，设计落地方案，对数据敏感且擅长数据分析；\n5、熟悉千川广告等场景者优先，有相关技术应用经验（多模态等）者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7571311590334056709","sourceKey":"bytedance","company":"字节跳动","title":"推荐大模型算法实习生-番茄","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7571311590334056709/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：Data-番茄团队，负责字节跳动下番茄小说、红果短剧、番茄畅听等产品的推荐算法和AI相关工作。我们的工作包括优化业界前沿的大规模推荐系统，探索LLM与推荐的结合，并落地生成式推荐范式，从小说、短剧、音频、音乐等内容方向建设完整的内容生态和AI能力，保持业务规模保持超高速增长。\n\n1、提升强算力下推荐模型的泛化、推理能力与算力利用率，完成推荐系统范式的转变；\n2、包括设计并探索Scale上限更高，ROI更好的结构；紧跟行业前端科研，推动优化推荐大模型的训练与推理算力利用率；\n3、LLM4Rec，包括研究如何让LLM输出与下游推荐模型更好的对齐以及探索将LLM的推理能力融入到排序模型；\n4、生成式推荐，探索番茄小说各体裁的最佳Tokenize方案，研究推荐场景下Reward Model如何更好地协同Encoder-Decoder生成架构，完成生成式模型对传统推荐模型的替换落地。","requirements":"1、本科及以上学历在读，人工智能、计算机、数学相关专业者优先；\n2、对推荐大模型技术有浓厚兴趣，紧跟行业前沿发展；\n3、具有扎实的机器学习基础和编码能力，熟练掌握主要的算法和数据结构；\n4、在搜索广告推荐大模型领域，有实习或者实践过关键项目的优先；\n5、在国际顶级会议发表论文者优先，包括但不限于KDD、SIGIR、RecSys、ACL、NeurIPS等；有推荐大模型相关论文者优先；\n6、具备良好的沟通协作能力，能够与团队共同探索新技术，推动新技术在业务落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7571311509964392709","sourceKey":"bytedance","company":"字节跳动","title":"推荐大模型算法实习生-番茄","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7571311509964392709/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：Data-番茄团队，负责字节跳动下番茄小说、红果短剧、番茄畅听等产品的推荐算法和AI相关工作。我们的工作包括优化业界前沿的大规模推荐系统，探索LLM与推荐的结合，并落地生成式推荐范式，从小说、短剧、音频、音乐等内容方向建设完整的内容生态和AI能力，保持业务规模保持超高速增长。\n\n1、提升强算力下推荐模型的泛化、推理能力与算力利用率，完成推荐系统范式的转变；\n2、包括设计并探索Scale上限更高，ROI更好的结构；紧跟行业前端科研，推动优化推荐大模型的训练与推理算力利用率；\n3、LLM4Rec，包括研究如何让LLM输出与下游推荐模型更好的对齐以及探索将LLM的推理能力融入到排序模型；\n4、生成式推荐，探索番茄小说各体裁的最佳Tokenize方案，研究推荐场景下Reward Model如何更好地协同Encoder-Decoder生成架构，完成生成式模型对传统推荐模型的替换落地。","requirements":"1、本科及以上学历在读，人工智能、计算机、数学相关专业者优先；\n2、对推荐大模型技术有浓厚兴趣，紧跟行业前沿发展；\n3、具有扎实的机器学习基础和编码能力，熟练掌握主要的算法和数据结构；\n4、在搜索广告推荐大模型领域，有实习或者实践过关键项目的优先；\n5、在国际顶级会议发表论文者优先，包括但不限于KDD、SIGIR、RecSys、ACL、NeurIPS等；有推荐大模型相关论文者优先；\n6、具备良好的沟通协作能力，能够与团队共同探索新技术，推动新技术在业务落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680930058664560949","sourceKey":"bytedance","company":"字节跳动","title":"内容安全研判运营（印尼语方向） - TikTok","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680930058664560949/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、解读社区规范及平台政策，转化为可执行的研判口径，搭建案例库并保障不同场景下判定一致性；\n2、监测平台UGC、PGC内容生态，主动识别显性及隐晦、擦边类内容风险，提炼风险特征规律；\n3、处理突发内容安全风险事件，快速定界、排序优先级，推动跨部门协作完成处置闭环并复盘优化；\n4、输出风险研判报告，为平台规则、内容质量把控策略优化提供决策支撑；\n5、熟练使用内容质量把控工具、舆情监测系统及数据分析工具，协同运营和产品团队落地风险防控策略。","requirements":"1、2027届获得本科及以上学历，新闻传播、社会学等相关专业优先；\n2、英语和印尼语沟通流利；有内容运营、内容审核或内容安全相关工作经验，具备国内主流内容平台从业经验者优先；\n3、具备敏锐的内容安全意识和网感，能精准识别隐晦风险，有政策理解与规则落地能力；\n4、具备较强的规律总结能力，熟练掌握内容审核、舆情监测及Excel等常用工具；\n5、思维灵活，责任心强，具备良好的跨部门沟通协调能力及应急处置能力；学习能力强、理解能力强，能快速适配政策与平台内容生态变化。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669686857256405301","sourceKey":"bytedance","company":"字节跳动","title":"Agent研发工程师 - Seed 产品研发","city":"深圳/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669686857256405301/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与面向国际市场的AI原生办公产品研发，打造能理解需求、调研分析并交付专业内容的智能任务体验；\n2、设计多Agent协作、任务规划、工具调用、知识连接、内容生成与事实校验等核心能力；\n3、建设可扩展的后端、评测和安全机制，在快速迭代中将想法转化为真实用户价值。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能等相关专业优先；\n2、编程基础扎实，熟悉Python、Golang、Java、C/C++等至少一门语言；\n3、了解大模型应用开发，对Agent、RAG、工具调用或评测体系有实践或浓厚兴趣；\n4、深度使用AI工具，具备强好奇心、主人翁精神和成长型思维；有AI产品或开源实践者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668280223222745397","sourceKey":"bytedance","company":"字节跳动","title":"抖音版权治理策略 - 抖音社区治理","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668280223222745397/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n1、负责版权、IP治理策略设计：深入理解内容社区版权生态，围绕版权风险识别、分级、处置、申诉等关键环节，搭建全链路治理体系；结合真人、影视综、动漫、音乐、品牌、虚拟形象等不同版权场景，制定差异化治理策略，并持续完善治理标准、风险标签体系及效果评估机制；\n2、建设AI驱动的版权治理能力：结合最新AI技术，推动版权治理能力升级，探索并落地LLM在版权风险理解、案例分析、策略生成中的应用，VLM在视频理解、主体识别、多模态审核中的应用，以及Embedding、向量检索在版权识别、相似内容发现中的应用，提升治理识别精度和策略有效性；\n3、推动智能化治理工具和工作流建设、基于Agent Workflow推动版权治理场景下的策略制定、自动分析和运营提效，提升复杂问题处理效率；结合RAG知识库建设版权知识沉淀与策略辅助能力，增强治理经验复用和知识支持能力；\n4、搭建版权治理标准与评估机制：围绕不同版权场景和治理目标，建立清晰的治理标准、标签体系、效果评估和迭代优化机制，持续提升版权治理的准确性、稳定性和可解释性；\n5、协同业务与技术团队推动治理落地：与产品、算法、审核、运营等团队紧密协同，推动版权治理策略、智能识别能力及治理工具在业务场景中的落地应用，持续提升内容社区版权治理的整体效率和效果。","requirements":"1、2027届获得本科及以上学历，计算机、统计学、数学、算法等专业背景优先；\n2、有AI大模型产品使用或实习经验优先，逻辑性强，有一定的数据分析能力，能够通过数据分析确定问题，制定策略；\n3、对内容安全和生态治理有热情，具备内容判断能力，能够判断其中的安全风险；\n4、对大模型的原理有一定了解，熟悉大模型的典型应用场景及市场常见产品。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7657161187786688773","sourceKey":"bytedance","company":"字节跳动","title":"3D美术设计实习生-数据平台","city":"上海","category":"视觉设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7657161187786688773/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、协助数字孪生项目中的三维模型工作，依据项目需求及相关标准，参与不同等级建筑、设备、构件等各类模型的创建，保障模型的准确性、精细度与规范性；\n2、参与数字孪生场景的制作与优化，结合项目的行业特性和视觉风格定位，协助完成场景的布局搭建、材质与纹理制作、灯光氛围营造等工作；\n3、与团队紧密配合协作，积极参与项目需求评审、方案讨论等环节，提供三维美术技术支持与建议；\n4、关注数字孪生领域的前沿技术与行业动态，持续提升个人的三维美术制作水平与效率。","requirements":"1、本科及以上学历在读，美术、数字媒体、动画、游戏设计、建筑/BIM等相关专业优先；\n2、了解UE5引擎的基本使用，包括场景搭建、材质编辑、蓝图逻辑、动画制作、渲染输出等模块，能在指导下完成三维资源在UE5引擎中的整合与调试；\n3、熟悉3ds Max、Blender等主流三维建模软件，以及Substance Painter等材质制作软件；\n4、了解CAD图纸的解读流程，对Revit等BIM建模软件有一定认识者优先，有意愿学习模型数据的处理与整合并应用于数字孪生场景；\n5、有一定的美术功底和设计审美，对色彩搭配、构图、材质、光影效果等有观察力和学习热情。\n\n加分项\n1、了解基于WebGL技术的数字孪生项目，对场景性能优化（加载速度、运行帧率、PC/移动端流畅交互）有学习兴趣或相关尝试经验；\n2、提供个人作品集（数字孪生、3D可视化、三维建模、场景、材质等方向均可）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615821783838542085","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent服务端研发实习生-开发者服务","city":"广州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615821783838542085/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、围绕研发高可用治理，质量保障AI化，研发环境管理等方向进行Agent应用开发工作，推动AI技术在相关场景的落地与突破；\n2、参与大模型应用开发全流程，包括但不限于模型接入、AI Agent开发、RAG优化、MCP及工具开发、数据工程等；\n3、跟踪AI领域的发展动态，推动Agent应用的持续优化。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、自动化、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握至少一门编程语言，包括但不限于Python、Java、Go等；\n3、了解AI Agent相关技术与设计思想，了解主流AI模型及其应用场景；\n4、有从0-1搭建AI Agent应用经验，能够独立完成Agent应用的设计开发者优先；\n5、在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684173864747829509","sourceKey":"bytedance","company":"字节跳动","title":"内容运营实习生 - 今日头条","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684173864747829509/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、对接优质创作者，协助解决创作者对平台的诉求；\n2、能深入理解项目对外合作策略，针对不同创作者提供定制化合作方案；\n3、对优质内容有深度的了解和洞察，有优秀的文案能力；\n4、能运营热点，对热点新闻有一定程度的判断能力；\n5、能掌握数据分析逻辑，针对关键数据，进行归纳总结与洞察。","requirements":"1、本科及以上学历在读；\n2、能够每周实习4天及以上，连续实习3个月以上；\n3、对社群经营有一定程度的了解，能调度创作者在平台创作的积极性，对优质图文内容有辨别及引导的能力；\n4、热点敏感度高，能第一时间捕捉到全网热点事件；\n5、具备良好的沟通能力，学习能力，自驱力强，积极有战斗力，拥有团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680934779415677189","sourceKey":"bytedance","company":"字节跳动","title":"内容质量与评估 - TikTok","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680934779415677189/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、负责内容安全核心评测集（Golden Set）的构建与持续迭代，通过挖掘长尾、高危及复杂边缘样本，为平台安全策略、AI模型评估与全球执行团队提供高准确度的数据标准（Ground Truth）；\n2、深入剖析高风险与争议性安全案例，准确洞察误判模式与风险演变趋势；主导复杂规则的降维与抽象，将宏观政策转化为逻辑严密、可执行度高的标准化运营指南（SOP）；\n3、推动内容安全数据闭环建设，跨部门协同运营、算法、产品及全球团队，基于评测集指标识别漏洞，实现人工质量与Agent拦截效能的双向提升；\n4、负责内容质量管理体系的通用方法论沉淀，建立并完善日常质量把控机制；通过核心数据指标的追踪与归因，提升整体数据准确率与运营效率。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具备互联网内容安全、质量保证（QA）、AI数据评测、策略运营相关工作经验者优先；具备优秀的逻辑推理与归纳提炼能力，能够穿透复杂的业务表象洞察底层问题，并独立输出结构化的解决方案；具备较强的自驱力与负责人意识，能够在多地跨国协同的业务环境中适应动态变化，高效推进多线任务并拿到业务结果；\n3、英语可作为核心工作语言（听、说、读、写精通），注重细节与标准的一致性，具备出色的跨文化沟通与书面表达能力；\n4、熟练掌握第二外语（如日语、泰语、韩语、德语等），或熟悉机器学习逻辑、数据标注框架者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680764226151844149","sourceKey":"bytedance","company":"字节跳动","title":"后端开发（公会方向）实习生 - TikTok直播","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680764226151844149/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播研发团队，旨在实现TikTok直播业务的研发工作，搭建及维护业界领先的产品。\n加入我们，你能接触到包括：社交互动、营收活动、主播生态、消费订阅、游戏直播、公会&运营平台等核心业务场景，支持产品在全球赛道上高速发展；\n也能接触到包括服务架构、大模型算法、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 \n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队专业且纯粹，合作氛围平等且轻松。\n目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，核心代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法、操作系统、网络、数据库、软件工程相关知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力；\n6、加分项：分布式系统设计与实现、负载均衡、容灾、高可用技术；参加过大学生数学建模竞赛，ACM，“挑战杯”，机器人足球比赛等；在学校的时候作为骨干参与学生网站的建设和开发。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675268171120953605","sourceKey":"bytedance","company":"字节跳动","title":"HR（芯片方向）实习生 - Data","city":"北京","category":"职能 / 支持","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675268171120953605/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持国际化人才市场调研，围绕重点区域及研究方向开展信息搜集、整理与分析；\n2、基于多种渠道进行潜在候选人搜索，协助完成人才筛选、推荐及初步沟通；\n3、协助搭建并维护候选人信息库，持续跟进候选人关键信息的更新；协助推进招聘全流程工作；\n4、熟练运用AI工具提升信息检索、数据整理与分析效率，支持研究结论输出。","requirements":"1、本科及以上学历在读，专业不限，人力资源、行业研究、电气电子工程等相关专业或经历优先；\n2、英语读写能力良好，能够独立阅读英文资料，具备较好的英语沟通与文献检索能力者优先；\n3、具备较好的AI工具使用能力，能够将其应用于信息搜集、整理及分析场景；\n4、有国际化学习、交流或实习经历优先；有计算机硬件或相关技术领域爱好优先；连续实习6个月及以上优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669742777393334533","sourceKey":"bytedance","company":"字节跳动","title":"黑灰产情报开发工程师 - 风控","city":"北京/杭州","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669742777393334533/detail","duty":"团队介绍：风控团队由算法、工程、产品三大团队协同构成，为抖音、今日头条、豆包、剪映等字节跳动业务的内容、交易、流量、账号场景提供智能风控，服务十亿级用户；场景对抗性极强、推理链路长、多模态数据海量，是 AI 时代最有挑战的实战领域之一。算法团队推进 LLM/MLLM 与 Agentic AI 的工业化落地，构建下一代智能风控基建；工程团队依托高并发、大数据与大模型，搭建端云一体的多层对抗体系与情报预警；产品团队评估业务风险、制定策略、探索 AI 在风控中的边界。三线协同，打造高效、前瞻的智能风控防线。\n\n1、挖掘业务重点场景的黑灰产业链，构建黑灰产业链情报收集工具，帮助业务了解黑灰产业链运作、盈利模式、规模态势；\n2、追踪黑产攻击，逆向分析黑产工具、作弊软件等，还原攻击手法和攻击路径，找到防御遗漏点；\n3、针对黑灰产进行溯源，推进相关部门进行取证打击；\n4、模拟黑灰产角色，对业务防御发起蓝军攻击，测试业务防御水位并找到防御漏点；\n5、探索并利用AI Agent能力提升情报收集与分析效率，包括但不限于：借助Agent自动化完成黑灰产信息采集、工具链分析、攻击路径还原等重复性工作流，缩短情报响应周期；\n6、参与风控场景下Agent工具/工作流的设计与开发，将情报分析、逆向溯源等经验沉淀为可复用的自动化Agent能力。","requirements":"1、2027届获得本科及以上学历，信息安全、网络空间安全、计算机科学相关专业优先；\n2、熟悉至少一门编程语言，包括但不限于Python、Go、Java、C/C++、JavaScript；\n3、了解互联网风险场景和常见的黑灰产业链运作模式和作弊手法；\n4、了解常见Web、应用、系统漏洞原理以及对应的检测、解决方案，有移动端逆向、Windows逆向、渗透测试等经验优先；\n5、好奇心强，具备良好的学习能力、分析和解决问题的能力，关注前沿安全攻防技术研究，有正义感；\n6、熟悉大语言模型（LLM）及AI Agent的基本原理与使用，有通过Agent/Copilot类工具提升个人工作效率的实际经验优先；有Agent开发经验者优先，熟悉主流Agent框架，能独立完成Agent应用的设计与开发。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669720483260647733","sourceKey":"bytedance","company":"字节跳动","title":"游戏研发特性产品经理 - 深圳射击项目","city":"深圳","category":"项目管理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669720483260647733/detail","duty":"团队介绍：一款科幻写实的全平台(手游/PC/主机)射击项目，使用UE5引擎研发，欢迎加入我们。\n\n1、参与射击游戏玩法与系统特性的研发管理，协助推进特性从需求拆解、研发跟进的全流程落地；\n2、协助制定特性研发计划，拆解关键里程碑、排期与交付节点，保障研发任务按计划推进；\n3、协调策划、程序、美术、测试等多职能团队，推动信息同步、问题暴露与协作闭环；\n4、跟进特性研发过程中的进度、质量与风险，协助识别体验偏差。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、游戏设计、项目管理等相关专业优先；\n2、热爱游戏，尤其对FPS、TPS、PVE射击等品类有持续体验和深入兴趣；\n3、具备良好的逻辑拆解、结构化表达和文档撰写能力，能够清晰梳理目标、任务与风险；\n4、具备较强的沟通协作意识、责任心和执行力，能够推动多角色协作并跟进问题闭环；\n5、具备基础的数据意识和复盘意识，能够通过进度、质量、问题反馈等信息辅助项目判断。\n\n加分项\n1、有游戏项目、课程项目、Game Jam、MOD、独立游戏或相关实习经历；\n2、熟悉UE5、Unity或任一游戏引擎基础工作流，了解游戏研发协作方式；\n3、有技术背景、敏捷项目管理经验，或对AI工具、自动化流程、研发效能提升有兴趣。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669689677919504645","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（时尚婴宠） - 商业化","city":"北京/上海/广州/杭州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669689677919504645/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、按照商业化战略规划，负责消费品行业/互动影视/互动应用/互动娱乐（游戏）/金融/电商平台/教育行业/MCN及达人等方向的客户的开拓与维护工作；\n2、与企业建立深度合作关系，完成既定销售指标；\n3、与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，以及建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669426827601398069","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（国际化内容社区） - TikTok研发","city":"上海/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669426827601398069/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、深度参与业务的服务端研发，并探索AI+业务的创新玩法落地；\n2、在真实业务场景中，利用行业前沿大模型编码助手辅助方案设计、代码实现与高质量重构，共同打磨极致的用户体验；\n3、参与产品需求分析，设计系统技术方案，关键代码开发和系统调优；\n4、参与各专项技术调研，改进系统性能与稳定性；\n5、借助AI完成日常研发，并持续探索AI研发范式。","requirements":"1、2027届获得本科及以上学历，计算机、软件、电子信息等相关专业；\n2、扎实的计算机、网络和软件开发相关基础，熟悉或掌握至少一门软件开发语言（例如Java、Kotlin、Object-C、C++、C、JavaScript）；\n3、学习能力强，对客户端开发技术有好奇心，对新兴技术趋势感兴趣，具备较强的动手能力、良好的沟通能力和优秀的团队协作能力；\n4、良好的编程习惯，编码思路清晰；\n5、有移动端开发经验，热爱移动端开发，在工程技术上追求卓越。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667893314209384757","sourceKey":"bytedance","company":"字节跳动","title":"Agent解决方案架构师 - AI算力基础设施","city":"北京/杭州","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667893314209384757/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、深入研究和洞察不同行业AI的发展方向，梳理各业务场景在AI应用的需求和价值，帮助客户设计AI产品落地路径；\n2、行业解决方案设计：从重点行业客户典型业务场景出发，结合火山引擎的AI产品，帮助软件企业设计和落地AI Agent解决方案；\n3、AI Agent场景洞察与价值挖掘：理解客户业务场景、整体技术架构，与客户共创业务和技术的关键问题与效果标准，理解行业内AI场景的价值；\n4、售前支持与技术影响力建设：通过标杆案例及Demo演示展示火山引擎AI Agent方案的竞争优势，建立在客户侧的技术影响力，影响客户的决策；向客户高层展示火山引擎AI全栈产品的竞争优势，确保技术方案与客户业务目标深度绑定。","requirements":"1、2027届获得本科及以上学历，计算机科学、人工智能、软件工程、电子信息、通信工程等相关专业优先；\n2、具备技术方案产品化能力，能将复杂技术转化为客户可感知的价值；\n3、具备优秀的管理能力和跨团队沟通能力，能协调研发、产品、客户多方资源推动项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667090841039948085","sourceKey":"bytedance","company":"字节跳动","title":"国际化广告算法工程师（推荐大模型） - Commercial AI","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667090841039948085/detail","duty":"团队介绍：Commercial AI隶属于国际化广告（国际化商业产品与技术），聚焦在商业化场景下的AI研发与创新，包括围绕广告场景，探索超长序列复杂模型、生成式推荐和 AI 广告素材生成等核心能力。简化产品流程，提升客户体验，并推动广告系统从素材生成到推荐建模的持续升级，助力广告效果提升和收入增长。\n\n1、探索大模型与广告算法结合的下一代广告投放系统，结合大模型的世界知识和训推优化大幅提升广告变现效率，主要方向为超长序列Transformer建模、生成式推荐、推荐Foundation Model与Scaling Law；\n2、在广告投放系统中充分使用广告素材、落地页的多模态信息，结合多模态建模对齐行为和模态的表征，打造Entity Based的广告投放系统；\n3、在广告投放高并发场景落地大模型推理，结合Sparse Attention、Sparse MoE、KV Cache等算法-工程联合优化，极致提升推理ROI；\n4、紧跟行业技术发展，在新一代GPU上探索大模型前沿技术在广告投放系统的技术落地。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业；\n2、熟悉C++和Python，有扎实的编程基础、良好的编程风格和工作习惯，优先：有数据挖掘、分布式计算经验，熟悉Hadoop、Spark框架；\n3、较好的机器学习/深度学习理论和实践经验，熟悉深度学习算法，优先：发表过KDD、AAAI、CIKM、WWW、RecSys、NeurlPS、ACL、EMNLP等顶会论文，或在Kaggle/ACM等赛事中获得优异名次，熟悉TensorFlow/PyTorch框架和原理；\n4、熟悉搜广推算法、大语言模型、多模态大模型、深度学习、强化学习等相关领域；\n5、具备良好的工程意识，能结合工程优化设计并落地大模型方案；\n6、工作态度积极主动，有强烈的主人翁意识和良好的团队协作精神，愿意接受有挑战性的工作，具有刨根问底的精神，优秀的分析和解决问题的能力，逻辑清晰，具有严谨科学的实验习惯。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665565689764038965","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师 - 中国交易与广告","city":"杭州","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665565689764038965/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与字节跳动系平台（抖音、抖音火山版、今日头条、西瓜视频等）电商消费端以及商家达人端前端架构设计、系统开发与优化工作；\n2、工作范围涉及前端基础架构、跨端应用、全栈开发、数据可视化、前端智能化等多个方向；\n3、深入参与业务解决方案设计，承担业务重点技术攻坚，通过高质量的编码设计支持业务的快速发展；\n4、与产品经理、设计师、后端工程师一起，提升产品的用户体验，打造卓越的互联网产品；\n5、关注前端前沿技术发展，能够将新知识传递给团队，并且转化到潜在项目中。","requirements":"1、2027届获得本科及以上学历，计算机、通信工程等相关专业；\n2、计算机基础扎实，熟练掌握JavaScript、CSS、HTML等前端技术及相关标准规范；\n3、熟悉一种主流前端框架以及相关技术栈，包括但不限于React、Vue等，有实际项目研发经验；\n4、具备良好的编码能力、较好的抽象设计能力，关注国内外各大开源社区和技术论坛；\n5、具备较强的责任感、团队合作精神、逻辑思维能力和表达能力；\n6、熟悉数据结构与算法，能够对具体的日常业务做基础的抽象建模。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628077579979409717","sourceKey":"bytedance","company":"字节跳动","title":"AI-3D创作引擎 - TikTok研发","city":"北京/上海","category":"多媒体","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628077579979409717/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n课题介绍：\n图形渲染作为多媒体应用的核心基建，在短视频与互动娱乐爆发的当下，其传统制作管线“周期长、成本高、门槛高”的痛点，严重制约了大众创意的释放。近年来，随着AIGC技术的突破（如NeRF、3DGS等新型表征的崛起），3D生成正从实验探索走向商业化落地，并成为未来构建“空间智能”的关键载体。\n本课题核心在于探索3D生成前沿技术，推动3D制作从传统的“建模-仿真-渲染”向“AI物体-AI场景-AI动画-AI渲染”的AIGC新链路演进。通过这一跨越，课题旨在极致降低3D创作门槛，全面赋能泛娱乐互动生态，并为未来的空间智能构筑坚实的技术底座。\n\n课题挑战：\n1、3D数据不足：当前全球高质量原生3D模型数据严重不足（不足1000万套），远落后于图文和视频领域，导致3D生成面临“数据越来越不够用”的困境。为了支撑庞大的生成需求，我们不仅需要探索更高效的筛选与收集手段，还要攻克如何低成本地从海量短视频和直播场景中提取高质量3D与交互数据的难题；\n2、3D大模型训练门槛与复杂度极高：3D生成模型本质上是一个真正的大模型，其训练门槛极高，需要深厚的分布式多卡训练经验和不断“踩坑”试错的过程。在实际训练中，不仅要解决长序列记忆管理、计算资源分配等复杂的工程难题，还必须在“照片级真实感”、“3D多视角一致性”和“生成可控性”之间找到最佳的算法平衡；\n3、AI渲染缺乏物理交互与编辑能力：尽管AI渲染（如3DGS）发展迅速，但在实际业务落地中仍受限于算力、效果和一致性。例如，高斯点云难以进行光照交互，仿真互动；同时，由于缺乏传统3DMesh的显式几何特征，AI渲染在处理复杂曲面（如毛发）、支持精细化编辑修改以及保持物理规律一致性上仍存在明显的缺陷；\n4、强大的视频生成能力如何有效融合到3D渲染：视频生成模型在动态捕捉和真实感上表现优异，但往往缺乏3D空间的一致性和物理可控性。未来的核心难点在于，如何理清视频生成与3D引擎渲染的交错关系，将视频生成模型中强大的空间/时间语义先验有效借鉴并融入到3D渲染领域，从而弥补隐式生成的缺陷，实现从“被动的视频生成”向“主动交互式3D场景”的跨越。\n\n课题价值：\n1、降低3D内容生成成本门槛：极致降低3D内容的生成门槛与制作成本，彻底打破传统“建模-仿真-渲染”管线周期长、成本高的专业壁垒。通过AI赋能，让普通用户仅需通过文字、图片或视频等极简输入，即可快速生成可在移动端实时渲染的高质量3D内容，真正实现3D创作的平民化；\n2、拓展3D内容应用场景：大幅提升3D内容的应用多样性与场景泛化性，深度契合日均调用超10亿次的泛创作业务场景（如相机特效、直播礼物、数字人等）。依托海量短视频与直播生态的数据飞轮，推动平台从“提供低门槛创作工具”向“下一代UGC-3D互动娱乐平台”跨越，全面激活业务生态；\n3、空间智能的底座基石：为未来的空间智能构筑坚实的技术基石。3D生成不仅是构建数字世界虚实融合的核心基础设施，更是实现3D空间理解、推理与交互的关键载体。长远来看，该能力将直接打破纯视觉生成的局限，广泛赋能并应用于XR原生交互、自动驾驶、具身智能以及前沿世界模型的发展。","requirements":"1、2027届毕业，获得博士学位，图形学、人工智能算法、计算机、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练C/C++，熟悉实时图形渲染技术；\n3、深入理解神经渲染技术（如NeRF、3DGS）或AIGC-3D技术，具备相关项目科研&落地经验，在SIGGRAPH/SIGGRAPH ASIA/TOG等顶级期刊会议上发表论文者优先；\n4、主动性和自驱力强，愿意接受挑战；\n5、优秀的分析问题和解决问题能力，对技术有热情，有良好的沟通表达能力和团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592959433702099205","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-TikTok直播","city":"上海","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592959433702099205/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播研发团队，旨在实现TikTok直播业务的研发工作，搭建及维护业界领先的产品。\n加入我们，你能接触到包括：社交互动、营收活动、主播生态、消费订阅、游戏直播、公会&运营平台等核心业务场景，支持产品在全球赛道上高速发展；\n也能接触到包括服务架构、大模型算法、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 \n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队专业且纯粹，合作氛围平等且轻松。\n目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责TikTok直播的质量保障工作；\n2、深度参与产品研发全生命周期，协同产品经理、业务开发交付高质量产品，手段包括但不限于功能测试、自动化实施、性能测试、安全测试、专项测试、稳定性监控、流程改进等；\n3、通过质量和效率数据分析，持续完善产品质量和用户体验；\n4、通过工具或平台开发，提升研发效率，完善质量保障策略；\n5、参与质量体系的规划和建设，参与自动化、无人值守、智能测试、故障演练等创新测试方法的实施。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和互联网技术，对质量保障工作有浓厚兴趣，熟悉测试理论和方法；\n3、有扎实的计算机理论基础和代码编写能力，掌握至少一门编程语言，包括但不限于：Java/C/C++/Python/Go；\n4、具备优秀的业务理解能力，逻辑思维灵活全面，良好的沟通协作能力，善于发现问题和解决问题；\n5、能保证至少4个月及以上的实习，每周可出勤至少4天及以上，实习优秀者提供转正机会。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7591838323873696005","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-中国交易与广告","city":"北京","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7591838323873696005/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与产品测试的全流程，包括需求评审、设计评审、制定测试计划、测试用例设计及执行、缺陷跟踪、测试报告等；\n2、开发测试工具和自动测试框架、自动测试脚本，进行自动化测试，提升测试效率；\n3、对产品、流程提出持续性改进意见，提升产品质量和研发效率。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟练掌握至少一门编程语言，包括但不限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、学习能力强，有较强分析、定位和解决问题的能力，较强逻辑思维能力和表达能力；\n5、每周可以实习4天及以上，连续实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7565801440034081077","sourceKey":"bytedance","company":"字节跳动","title":"战略资源管理实习生-TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7565801440034081077/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、参与商家、作者、机构的策略输出，协调各团队资源，推动监控指标体系的更新和迭代；\n2、对国际化电商业务模块的运营表现进行评估，通过数据分析，持续洞察业务运营表现；\n3、深入理解平台对于不同对象的激励体系、资源分配策略，进行跨团队协作，协助推动落地。","requirements":"1、本科及以上学历在读；\n2、熟练使用EXCEL，熟悉常用数据统计和分析方法，熟练使用SQL更佳；\n3、良好的逻辑思维、业务解读能力和快速学习能力，良好的自驱力、沟通能力和团队合作精神；\n4、可以使用英文作为工作语言；\n5、实习周期为4-6个月，每周4-5天。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7509419457706838290","sourceKey":"bytedance","company":"字节跳动","title":"多媒体开发实习生-抖音","city":"北京","category":"多媒体","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7509419457706838290/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：抖音研发团队，主要负责抖音短视频的业务和技术研发、公司全部产品的内容安全业务。截至2020年8月，抖音日活用户超6亿，并继续保持高速增长。\n未来一年，抖音将更多关注对创作者和社会的价值。团队汇聚各种背景的顶尖人才，在更大体量更为复杂的业务场景中不断提升，在项目0-1的过程中影响上亿用户。期待你的加入！\n\n1、参与多媒体SDK改造、精简、性能优化等工作；\n2、参与音视频、图形图像等基础模块的优化工作；\n3、参与行业技术调研等工作。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、图像处理或图形学相关专业或主修过相关课程； \n3、具备深厚的C++功底、严谨的逻辑思维能力、成熟稳健的编程风格； \n4、熟悉OpenCV或者OpenGL，具备主流3D引擎使用经验者优先，如：Unity，UE，CryEngine，Irrlicht，GamePlay3D等；\n5、了解iOS或者Android工程开发者优先；\n6、有机器视觉方面的机器学习、深度学习经验者优先；积极乐观，责任心强，工作认真细致，具备良好的服务意识，具有良好的团队沟通与协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685369238918220037","sourceKey":"bytedance","company":"字节跳动","title":"主播策略实习生 - TikTok直播","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685369238918220037/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播是全球领先的直播业务，以实时互动为核心，提供多元化的商业化模式和创作工具。我们为用户提供独特的内容和消费体验；为创作者找到合适的观众，提供最好的工具和一系列盈利模式，帮助创作者创造更多机会、改变他们的生活；通过直播，平台也能从中获得健康、客观的商业化收益，持续发展。我们一直听到这样的故事 —— “LIVE changes my life” —— 他们更好，我们才会更好。\n\n加入我们，一起探索 “不可能的事”—— 我们是行业的先行者，在一步步改变行业。我们持续让行业了解直播是一种新的内容形式，是创作者可以依赖的商业模式。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与TikTok LIVE直播营收活动的全链路运营，包括市场营销方案、宣发及用户教育，并协同产品、研发、设计、文案、合规等团队推进项目落地及效果复盘；\n2、辅助直播营收活动方案设计，与产品、研发等团队协作推进方案落地及后续迭代；\n3、与全球区域运营团队密切协作，理解不同市场需求，支持重点区域活动运营及宣发方案设计与落地；\n4、支持全球区域活动及相关功能教育，包括教育材料制作、区域宣讲及信息同步等。","requirements":"1、本科及以上学历在读；\n2、有产品运营、市场营销、国际业务相关实习经验优先；\n3、具备良好的英语听说读写能力，能够使用英语进行日常工作沟通及材料撰写；\n4、对社交媒体、直播行业及国际化业务有较强兴趣，对TikTok等内容平台有一定了解；有国际学习、生活或跨文化协作经历优先；\n5、具备良好的沟通协作及项目推进能力，能够同时对接多个职能团队，对细节和项目进度有较强责任心；\n6、具备较好的活动策划、内容策划和文字表达能力，有活动、市场营销、视频/视觉素材制作或内容运营相关经验，实习3个月以上、每周出勤4天以上优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668646515574294837","sourceKey":"bytedance","company":"字节跳动","title":"用户增长产品经理 - TikTok Shop","city":"上海","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668646515574294837/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责区域市场用户增长（拉新、促活、复购），基于市场洞察与数据分析开展策略设计与落地；\n2、结合用户生命周期特征，制定差异化运营策略或产品方案，涉及补贴、投放、玩法工具等手段；\n3、基于市场研究与数据分析，制定补贴和投放标准，推动运营及经营效率提升；\n4、深化对全球市场的理解，与供给、产品、算法等团队紧密合作，推动方案与产品落地。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具备较高的数据逻辑和数据敏感性，熟练使用SQL、Excel，掌握分析工具如R，Python，SAS等加分；\n3、对用户购买决策路径有良好的敏感度，有结合数据和用户洞察、制定增长策略或产品的具体实践案例者优先；\n4、英文可作为工作语言、有国际化留学经验加分；\n5、责任心强、可跨部门沟通和处理问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7579981940179978501","sourceKey":"bytedance","company":"字节跳动","title":"算法实习生-用户增长（User Growth）","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7579981940179978501/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动用户增长（User Growth）负责抖音、今日头条、番茄小说、剪映等多个产品的用户增长业务，建立行业领先的增长和营销技术，打造极致的用户体验。加入我们，有机会参与亿级用户场景的开发与架构工作，也有机会从数据出发，利用策略和模型为业务带来更大的助力。\n\n1、负责字节跳动产品的智能广告创意，为抖音、今日头条、番茄小说、西瓜视频等产品实现用户增长的目标；探索应用DiffusionModel，GPT，CV/NLP在营销场景/短视频/小说领域实现对广告文案、视频、图片等素材进行内容理解并高质量生成投放竞争力素材；\n2、自动化素材生产平台的算法能力优化，拆解起量创意进行创意洞察，视频智能剪辑，内容优选，并以数据驱动的方式，优化素材投前、投中环节的效果；\n3、调研业界创意、多模态及Generative AI方向最新技术，落地应用并提升广告创意理解、自动生成和优化等场景的效果。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、具有扎实的机器学习基础，在Diffusion Model、GAN、VAE、图像及视频生成/编辑、多模态内容理解等至少一个领域有开发经验的优先；在NLP方向：熟悉文本理解、生成等NLP算法，有GPT类模型优化及应用的实践经验优先；数理功底扎实，自学能力强；\n3、工程能力强，熟练掌握Python/C++语言，有成功的项目经验；熟悉常见的机器学习和深度学习算法，熟练使用至少一种深度学习框架，如PyTorch、TensorFlow、MXNet等；\n4、优秀的理解沟通能力，能快速理解业务背景，对数据敏感，崇尚数据说话，深信数据在驱动业务、支撑决策上的价值；\n5、专业领域有以下任意即可：\n1）图像生成领域掌握基本原理并有相关实践：StableDiffusion，Video Diffusion，Lora，GAN，3D视觉等相关技术，能够综合运用各类算法实现特定功能；\n2）多模态内容理解：了解文本，图像，视频的多模态表征方式，在模态对齐，模态融合，预训练等方向有深刻理解，在VQA，视频搜索，Video Caption等方向有过实践经验；\n3）大语言模型：了解大模型预训练技术和NLP生成任务，对LLM的SFT，RLHF等技术方向有过实践，用于广告文案等文本内容生成和改写；\n4）广告投放：素材优选和投放效果预估，投前素材的召回，粗排，精排等广告投放相关任务。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7688663211319052549","sourceKey":"bytedance","company":"字节跳动","title":"游戏技术美术实习生 - 绿洲工作室","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7688663211319052549/detail","duty":"绿洲工作室2019年4月在北京成立，立足动作与休闲核心赛道，依托移动、PC、主机全平台布局，持续探索 RPG、竞技、休闲、棋牌等多品类精品游戏创作。旗下有《晶核》《雾影猎人》《SlashZero》（又名：《零境·入侵》）《Land of Empires》《芒果斗地主》等多款产品。我们的愿景是希望帮助玩家在令人惊叹的虚拟世界中一起玩耍与创造，加入这里，你将与一群简单、务实的优秀伙伴一起，Work hard，Play harder~\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助编写和维护Shader，实现角色、场景的材质效果，配合美术团队落地视觉需求；\n2、参与美术生产管线优化，开发简单自动化工具，提升资源制作效率；\n3、配合程序与美术团队，排查游戏渲染性能问题；\n4、调研行业前沿技术（如程序化生成、AI辅助美术），参与技术验证与落地。","requirements":"1、本科及以上学历在读，计算机、人工智能、数字媒体等相关专业优先；\n2、熟悉至少一款主流游戏引擎（Unity/Unreal），了解渲染管线基础原理；\n3、具备基础编程能力，熟悉Python、C++、C#、HLSL中任意一种语言，有简单代码编写经验；\n4、熟悉常见美术工具（Maya/Blender/Max/Photoshop），具备基础美术审美与资源制作认知；\n5、热爱游戏，对技术美术领域有强烈兴趣，学习能力强，善于跨团队沟通。\n\n加分项\n1、了解Houdini和程序化生成工具及制作流程；\n2、了解机器学习和人工智能的相关知识，有常见AIGC工具的使用经验；\n3、参与过校园游戏项目、独立游戏开发，或有相关实习经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684163197936453893","sourceKey":"bytedance","company":"字节跳动","title":"POP运营实习生（英欧市场） - TikTok Shop","city":"深圳/上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684163197936453893/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、跟进POP商家入驻事宜，优化入驻体验，熟练掌握全流程后可独立协助单个品牌完成入驻；\n2、收集、分析行业信息，对现有库内数据进行分层，为商家输出专业经营建议；\n3、落地商家沙龙、峰会活动，完成相关内容产出，营造欧日共识；\n4、独立负责一个类目招商工作，挖掘类目业务机会，熟练使用AI工具者优先考虑。","requirements":"1、本科及以上学历在读；\n2、擅长逻辑思考，跨文化/跨背景沟通；\n3、乐于发现问题、解决问题，从持续成长中获得乐趣；\n4、英语可以作为日常工作沟通语言，有目标国家生活经历更优；\n5、擅长数据处理分析，从数据中发现问题、方向；\n6、可以长期实习，每周实习5天，不少于4个月。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7682625038218692917","sourceKey":"bytedance","company":"字节跳动","title":"行业产品经理（C侧） - 抖音电商","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7682625038218692917/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、深入行业，设计C端交易履约方案，学习并理解垂类电商行业的经营模式与商业逻辑，基于对电商行业的深度洞察，参与设计最优的C端用户交易履约链路，包括但不限于商业模式拆解、流量提升、交易转化、全流程体验优化等分行业差异化解决方案；\n2、识别机会，推动方案落地，主动发现C端用户体验与业务增长中的机会点，参与设计C端全流程解决方案，协同行业运营及各中台产品团队，推动方案从0到1落地，助力行业规模增长与用户体验提升；\n3、结合AI能力，提效提质，学习并应用主流AI能力，在产品方案设计、数据分析、项目管理等过程中探索提效与提质的新方式，助力提升各行业用户侧解决方案能力。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对电商、零售、互联网产品有浓厚兴趣，有相关实习经历者优先，具备优秀的同理心和用户洞察力，习惯从用户视角思考问题，乐于探索用户需求背后的本质；\n3、具备良好的逻辑思维与跨团队沟通能力，能够清晰表达观点，协同多方推进项目落地；\n4、对常见技术实现逻辑有基本认知，能够与开发团队顺畅沟通，理解需求实现的可行性与成本；\n5、较强的学习能力与自驱力，对主流AI能力有一定了解或强烈好奇心；对工作充满热情，富有创新精神，喜欢挑战，善于思考。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677540909055150341","sourceKey":"bytedance","company":"字节跳动","title":"产品运营（AI方向）实习生 - TikTok产品","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677540909055150341/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok产品团队的目标是促进TikTok的发展并能持续性成为业界领先的产品。团队包括但不限于产品架构、用户增长、搜索、社交、创作、Lemon8、PGC、音乐、开放平台、内容生态、平台安全、数据科学、商业分析等关键业务场景，支持产品在全球赛道上高速发展，保障业务持续高质量、高效率、且安全地为用户服务。同时覆盖国际化直播场景，为TikTok用户提供独特的内容和消费体验，以及国际化生活服务场景，链接海外线下商家、创作者与用户。\n\nTikTok的使命是通过提供一个创造性表达的产品，通过真实、快乐和积极的体验激发创造力和带来快乐。在TikTok，我们的员工谦逊、聪明、富有同情心和创造力。我们创造是为了激励--为了你，为了我们，也为了我们平台上的10亿用户。我们带着好奇心领导，追求最高目标。在这里，对于那些敢于追求超越可能性边界的大胆想法的人充满机会。加入我们，在TikTok的职业生涯中产生影响。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责体验平台的产品建设：参与需求梳理、功能设计、上线跟进与迭代优化，持续提升平台的可用性与体验；\n2、负责平台内Agent的搭建与日常维护：完成Agent配置、调优与问题排查，保障其稳定运行与效果达标；\n3、参与PE（Prompt Engineering）优化：结合业务场景打磨提示词，持续提升模型输出的准确性与稳定性；\n4、参与产品评测相关工作：设计评测方案、执行效果评估、沉淀评测数据与结论，为产品迭代提供依据；\n5、配合团队完成日常运营与协作事项，推动跨团队需求对接与落地。","requirements":"1、本科及以上学历在读，理工科、计算机、产品设计等相关背景优先；\n2、有做过智能产品或B端产品实习经验；Agent搭建经验；PE（提示词）优化经验；产品评测经验者优先；\n3、具备较强的逻辑思维、学习能力与责任心，善于沟通协作，能快速上手新工具与新场景；\n4、全职实习，一周工作5天，可稳定实习者优先；\n5、具备理工/计算机背景叠加产品设计能力者；对AI、Agent、大模型应用有浓厚兴趣；\n6、英语听说读写流利。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670457476447684869","sourceKey":"bytedance","company":"字节跳动","title":"豆包AI大模型评测算法工程师 - 火山方舟","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670457476447684869/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、深入理解豆包AI大模型To B客户需求，将客户反馈转化为评测任务，确保评测结果真实反映客户使用效果，引导模型的方向发展；\n2、基于真实业务场景构建端到端评测Pipeline（含Agent工具调用、RAG检索、多轮对话等复合链路）；\n3、从实际使用视角设计评测案例——模拟客户真实Workflow，评估模型在完整工作流中的表现；\n4、设计Agent和Coding场景的过程评测指标（如工具调用准确率、代码通过率、多步规划成功率等），能拆解模型每一步的效果；\n5、实现评测自动化，在AI工具的帮助下，实现To B复杂场景的评测自动化。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程、人工智能等相关专业；\n2、对主流Agent和VibeCoding工具非常熟悉，有丰富的使用经验；\n3、对主流大模型（GPT系列、Claude系列、开源模型）有深入使用经验，熟悉各模型能力边界；\n4、有数据分析能力，能从评测数据中发现Pattern、定位问题根因；\n5、较强的自驱力，能主动提出新的思路，并推动落地执行。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669757119566514485","sourceKey":"bytedance","company":"字节跳动","title":"游戏数值策划 - ZERO36工作室","city":"上海","category":"游戏数值策划","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669757119566514485/detail","duty":"团队介绍：ZERO36工作室旗下有《航海王热血航线》、《花亦山心之月》、《初音未来：缤纷舞台》多款游戏产品。\nZERO，是从0开始，是不念过往，不畏将来；是回到原点，对知识诚实；是一切开始的基础。\n36，如果加上°C，即为人体的温度，戒骄戒躁保持初衷，用\"温度\"拉齐大家的目标和价值观，做有温度的产品，有温度的运营，成为一个有温度的团队，欢迎加入我们！\n\n1、协助核心数值策划，参与游戏核心数值体系搭建，包括角色成长、装备属性、技能效果、经济系统等相关数值设计与优化，确保数值逻辑严谨、平衡且符合游戏玩法定位；\n2、负责基础数值文档的整理、录入与维护，协助完成数值模拟、测试与调优，收集并分析测试数据，提出合理的数值调整建议，解决数值相关异常问题；\n3、配合战斗策划、关卡策划等岗位，完成数值与玩法的适配，确保数值设计贴合游戏核心体验，提升玩家可玩性与留存率；\n4、关注行业内同类游戏数值设计趋势，积累数值设计经验，参与数值相关创意讨论，为游戏数值优化提供新思路；\n5、配合团队完成其他与数值相关的辅助工作，快速适应项目节奏，积极推进任务落地。","requirements":"1、2027届获得本科及以上学历，数学、统计、计算机等相关专业优先；\n2、逻辑思维能力强，具备扎实的数学基础，对游戏数值有浓厚兴趣和基本认知；\n3、热爱游戏，深度体验过多款ARPG游戏，能清晰分析游戏数值设计的优缺点，有自己的思考与见解；\n4、具备良好的沟通协调能力、学习能力和问题解决能力，工作认真负责，有团队协作意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668294727842531589","sourceKey":"bytedance","company":"字节跳动","title":"采购政策与合规 - Corporate Services","city":"北京","category":"采购","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668294727842531589/detail","duty":"团队介绍：企业服务团队致力于为全球ByteDancer提供最佳的管理和员工体验，我们支持员工协同并高效地完成工作，同时保护和促进公司的业务发展。企业服务团队通过专业服务来改善ByteDancer的体验，同时建立并不断探索可广泛共享的新行业最佳实践。\n\n1、参与梳理采购全流程合规风险清单，识别招投标、供应商、合同、付款等环节的风险点；\n2、制定风险分级标准，收集并整理数据，支持风险发生概率与影响的量化评估；\n3、参与集团及各品类流程的设计与迭代，协助把管控要求落到制度与系统中；\n4、协助跟踪合规指标与执行数据，发现异常与失效环节并反馈；\n5、关注行业政策与合规实践，收集外部对标信息，支持策略建议输出。","requirements":"1、2027届获得本科及以上学历；\n2、了解采购或合规基本流程，对风险控制逻辑有基本认知且对合规管理有热情；\n3、具备较强的数据整理与分析能力；逻辑清晰、责任心强，细心、能推进事情落地；\n4、学习能力强，善于沟通与跨团队协作；\n5、有用AI工具解决问题的能力；英文口语及书面语流利，可作为办公语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668179479581509893","sourceKey":"bytedance","company":"字节跳动","title":"数据仓库开发工程师 - 集团信息系统","city":"北京/杭州","category":"大数据","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668179479581509893/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、参与集团信息系统部离线和实时数据仓库建设工作，面向PB级超大规模数据问题，完成对近百亿条级别业务数据的存储、计算与分析；\n2、参与企业服务场景下的AI应用研发，包括但不限于：基于LLM的智能问答、智能助手、RAG检索增强、Agent工作流编排、Text2SQL、智能数据分析等方向的探索与落地；\n3、参与构建AI数据基础设施，包括高质量训练、评测数据集建设、Prompt工程与效果评估体系，为大模型应用提供数据支撑；\n4、为大数据与AI全生命周期提供服务，覆盖数据产生、传输、建模、统计分析、模型训练、推理服务、可视化的全流程；\n5、构建设计良好的数据流、数据仓库、数据服务、AI服务、分析系统、流程规范与数据、AI工具产品，降低数据与AI能力的使用门槛，保证系统稳定高效运行，以实现数据与智能的最大价值。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、数据科学、统计学、数学等相关专业优先；\n2、熟悉数据仓库实施方法论、了解数据仓库体系；对大数据存储、计算引擎的原理有基本认知；\n3、熟练使用SQL，掌握Java、Python、Scala、Go、C/C++中任意一门编程语言；\n4、具备以下经验之一者优先：\n1）有大数据集、分布式计算工具（MapReduce、Hadoop、Hive、Spark、Flink等）经验；\n2）熟悉主流大语言模型（GPT、Claude、Doubao、LLaMA、Qwen等）的原理与应用，有Prompt Engineering、RAG、Agent相关实践；对于harness、loop engineering等框架有比较深入研究和实践；\n3）有Text2SQL、智能数据分析、NL2Data、多模态等方向的实践或研究经验；\n5、思路清晰，善于思考，有较强的数据分析能力与工程落地能力，能独立分析问题并推动解决问题；\n6、对AI技术在企业服务场景的应用有浓厚兴趣，具备良好的学习能力、沟通协作能力与责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7550964671864539410","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-AI Platform","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7550964671864539410/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：AI Platform团队负责 AI 应用开发工具平台的产品研发及相关能力建设。具体包括为字节跳动内外的 LLM 应用开发者提供开发框架、DevOps、可观测、LLMOps 等效率工具，以满足其生产活动需求；支持开发者进行数据处理、Prompt 工程、模型训练评测及推理部署等端到端的模型迭代流程，不断提升 AI 应用的效果。团队整体致力于构建 LLM 应用开发者生态，并推动产品的商业化建设。\n\n1、负责LLM驱动的AI Agent框架的研究和实现，确保技术的创新与前瞻性；\n2、根据应用场景的需求，优化并提升AI Agent的算法性能和用户体验；\n3、持续追踪AI Agent领域的最新技术趋势和研究成果，将前沿技术整合进我们的项目与解决方案中。","requirements":"1、本科及以上学历在读，计算机、人工智能、自动化、数学相关专业优先；\n2、精通Go、Python、C++等一种或多种编程语言，具备扎实的编程技能和算法设计能力；\n3、对AI Agent技术有深入了解，熟悉AutoGPT、LangChain等现代AI框架；\n4、具备出色的团队协作精神和良好的英文阅读及沟通能力；\n5、每周可实习4天以上，可实习3个月以上。\n\n加分项：\n1、在LLM工程领域有落地经验；\n2、有Agent、RAG、Tool方向的研究或者工作经验；\n3、开发过AI应用。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665585620057098549","sourceKey":"bytedance","company":"字节跳动","title":"算法开发工程师（搜索） - 抖音研发","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665585620057098549/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、深度参与字节跳动垂类搜索以及AI搜索中台的各个环节，利用模型算法提升用户体验；包括但不限于：查询规划（Query planner）、语义匹配、相关性计算、离线数据处理等；\n2、利用大模型对数据知识做结构化提取、融合和增强，并研究和探索先进的chunk、graph构建等技术的落地应用；\n3、升级迭代数据检索技术包括Agentic search、Graph RAG、生成式检索等，提升大模型场景下的数据检索天花板；利用自动化评估、标注、数据飞轮等技术，不断提升基础模型的迭代效率和泛化能力；\n4、深入洞察业务数据，分析潜在的问题并提出策略提升方向，不断提升迭代模型效果，促进业务效果提升；\n5、打磨算法通用性，平台化输出算法模型效果，提升产品上线效率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、熟悉机器学习、自然语言处理、数据挖掘、大模型等相关知识，有大模型SFT/RL应用、search Agent、RAG等经验者优先；\n3、具备优秀的编码能力，扎实的数据结构和算法功底，掌握C++、Go、Python等一项或多项编程语言，有TensorFlow、PyTorch等深度学习框架相关经验；\n4、对技术有追求，跟进前沿的相关技术并应用；有ACL、EMNLP、SIGIR、KDD、CIKM等相关顶会论文优先；\n5、乐于分享，良好的沟通表达能力和团队精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7654156497513695541","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-抖音","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7654156497513695541/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、深入参与抖音App及其衍生矩阵（抖音极速版、火山版、PAD版等）的视频推荐算法迭代，优化业务核心指标，提升用户体验和内容生态健康度；\n2、针对今日头条/番茄等跨端场景，构建高效的跨域迁移学习和多场景联合学习框架，解决数据稀疏和冷启动问题，实现全场景流量的全局最优分发；\n3、深入挖掘全链路（召回、粗排、精排、重排/混排）的优化空间，通过深度学习模型结构创新、特征工程迭代和策略机制设计，持续打破业务天花板；\n4、与工程团队紧密合作，解决超大规模模型在千亿级特征、万亿级样本下的分布式训练与在线高并发低延迟推理问题。","requirements":"1、2027届本科及以上学历在读，计算机、数学、统计学、自动化等相关专业；\n2、具备扎实的数据结构与算法功底，编程基础扎实；熟练使用Python/C++，熟悉Linux开发环境；熟练掌握PyTorch或TensorFlow等至少一种深度学习框架，有独立实现复杂模型结构的能力；\n3、对机器学习、深度学习的基础理论有透彻理解；了解推荐系统、自然语言处理（NLP）或计算机视觉（CV）的基础概念及经典算法（如CTR预估经典模型、序列建模、双塔模型等）；\n4、持续关注AI领域尤其是大语言模型（LLM）的发展；了解Transformer架构及主流预训练模型，有开源大模型微调（SFT、RLHF）或多模态相关学术项目经验者优先；\n5、具备优秀的逻辑思维能力与自驱力，具备好奇心和快速学习能力；面对未知和挑战具备积极解决问题的能力；具备良好的沟通表达能力与团队协作精神。\n\n加分项\n1、在KDD、NeurIPS、ICLR、ACL、EMNLP、CVPR等人工智能、数据挖掘相关顶级会议有第一作者论文发表；\n2、在Kaggle、KDD Cup、天池等国内外数据挖掘或算法竞赛中获得过优异成绩；\n3、获得过ACM/ICPC、CCPC等程序设计竞赛区域赛金牌及以上荣誉。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7633277916961884469","sourceKey":"bytedance","company":"字节跳动","title":"创意视觉设计实习生 - TikTok设计","city":"深圳","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7633277916961884469/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok设计团队的目标是为全球数亿用户提供一流的用户体验，从而帮助用户更好的创作与表达，发现世界的多元与美好，不断打破隔阂，建立起人与人的连接。我们是一个国际化的设计团队，遍布中国、美国、新加坡等国家，世界各地的产品设计师、创意设计师、效果设计师、内容文案专家与本地化经理通力合作，把一个个不可能变成可能。\n\n加入我们，你就有机会理解世界不同地域的文化差异，分析并解决复杂的体验问题，进行前沿的设计探索，更能亲身主导如何把一个想法转化成服务亿级数量用户的产品体验。 如果你积极自驱，对世界充满好奇心和想象力，有希望通过设计打造一流的产品，同时又脚踏实地，欢迎成为我们的一员！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责TikTok国际化直播产品功能运营视觉设计的创作，如教育/活动的H5，产出创意，参与制定风格和设计提案；\n2、协助完成创意落地，如周边、设计延展等；\n3、理解娱乐、直播业务，了解运营玩法，挖掘业务创新点，协同产品、运营、设计、研发，推动项目落地；\n4、了解提效方法，沉淀运营设计规范与素材，管理把控供应商流程、产出质量等。","requirements":"1、本科及以上学历在读，设计类专业优先；\n2、熟练掌握AI、Photoshop、Illustrator、Figma、C4D等常用设计工具，擅长插画/3D/排版/UI，会动效更佳；\n3、对潮流文化、青年群体、社交传播热点有敏感度；\n4、具备主动学习、沟通协作能力，能接受项目环境。\n\n加分项\n1、有较好的英文阅读能力，有国际化项目经历优先；\n2、有实习经历优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7599917301123893557","sourceKey":"bytedance","company":"字节跳动","title":"算法实习生-中国交易与广告","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7599917301123893557/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与关键业务和产品的算法工作，包括提高业务场景下的决策信息覆盖、提升转化效率、改善用户体验、探索更高效的商业模式等；\n2、深入理解业务和机器学习技术，优化模型和策略，持续提升用户体验；\n3、应用先进的机器学习技术，解决不同场景中遇到的各种挑战，如各种内容理解相关性，在线或离线，大数据量或小数据量，长期或短期信号等；\n4、深入理解与分析用户行为，制定有针对性的算法策略，促进生态良性发展。","requirements":"1、2027届本科及以上学历在读；\n2、具备优秀的编码能力，扎实的数据结构和算法功底，至少熟练掌握C/C++/Go/Python一种开发语言；\n3、掌握机器学习、因果推断、概率统计、数据分析等领域的基础知识，了解前沿算法；\n4、熟悉常用机器学习工具和深度学习编程框架（TensorFlow/PyTorch/Scikit-learn/XGBoost等）；\n5、熟悉常用的大数据开发工具（Spark/Hive/Hadoop等）；\n6、有激情、不畏难、乐于挑战，具有良好的团队合作意识、理解沟通能力及独立解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594830975655414069","sourceKey":"bytedance","company":"字节跳动","title":"点播算法实习生（模型方向）-TikTok","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594830975655414069/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、协助开展核心模型相关工作，聚焦“视频-策略”“人群-策略”匹配场景，参与模型数据处理、特征工程等基础环节，助力提升模型对业务指标的撬动效果；\n2、参与因果推断模型、深度学习模型的落地优化，包括数据清洗、实验验证、效果评估等，探索模型泛化能力提升方案；\n3、协助挖掘视频侧（音画质、元数据等）、人群侧（用户画像、行为特征等）有效特征，参与特征字典构建与特征准确性验证；\n4、配合团队完成其他与模型研发、策略落地相关的辅助工作。","requirements":"1、2027届本科及以上学历在读，计算机、数学、统计学、数据科学等相关专业优先；\n2、具备基础的机器学习/数据挖掘知识，了解常见模型及因果推断基本概念者优先；\n3、熟练使用Python，掌握Pandas、Scikit-learn、PyTorch、TensorFlow等库，有SQL数据查询与提取经验者优先；\n4、具备良好的逻辑思维能力、数据分析能力，能快速理解业务问题并配合开展实验验证；\n5、工作积极主动，有责任心，具备良好的沟通能力与团队协作意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683435587500263733","sourceKey":"bytedance","company":"字节跳动","title":"经营分析 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683435587500263733/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合行业的运营逻辑和业务发展趋势，承接自上而下的目标任务拆解、做好对应预算资源管理，支持业务健康发展；\n2、基于经营视角，搭建业务指标体系，覆盖行业、品牌商家、经销商、类目等业务模块，向下拆解各模块过程指标和关键路径，完成数据看板搭建，推动行业数据报表化及产品化，协助业务和管理者高效决策；\n3、支持解决业务核心卡点和问题，撰写专题分析报告，分析内容涵盖GMV增长、品牌份额提升策略、专项支持等方面，具备驱动行业策略落地的能力；\n4、具备较强的分析报告撰写能力和数据可视化能力，定期开展经营分析和问题诊断，拆解和定位业绩达成核心链路和关键因素，产出可落地的策略建议；\n5、持续关注电商市场环境、竞争格局、行业趋势、类目趋势等，发现潜在机会，输出专项报告及策略。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，策略分析/数据分析/商业分析/经营分析经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有团队合作精神，较好的协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680936166642682117","sourceKey":"bytedance","company":"字节跳动","title":"内容质量与评估（韩语方向） - TikTok","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680936166642682117/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、负责内容安全核心评测集（Golden Set）的构建与持续迭代，通过挖掘长尾、高危及复杂边缘样本，为平台安全策略、AI模型评估与全球执行团队提供高准确度的数据标准（Ground Truth）；\n2、深入剖析高风险与争议性安全案例，准确洞察误判模式与风险演变趋势；主导复杂规则的降维与抽象，将宏观政策转化为逻辑严密、可执行度高的标准化运营指南（SOP）；\n3、推动内容安全数据闭环建设，跨部门协同运营、算法、产品及全球团队，基于评测集指标识别漏洞，实现人工质量与Agent拦截效能的双向提升；\n4、负责内容质量管理体系的通用方法论沉淀，建立并完善日常质量把控机制；通过核心数据指标的追踪与归因，提升整体数据准确率与运营效率。","requirements":"1、2027届获得本科及以上学历；\n2、具备互联网内容安全、质量保证（QA）、AI数据评测、策略运营相关工作经验者优先；具备优秀的逻辑推理与归纳提炼能力，能够穿透复杂、模糊的业务表象洞察底层问题，并独立输出结构化的解决方案；具备较强的自驱力与责任意识，能够在与多地跨国协同的业务环境中适应动态变化的业务环境，高效推进多线任务并拿到业务结果；\n3、英语和韩语可作为核心工作语言（听、说、读、写精通），注重细节与标准的一致性，具备出色的跨文化沟通与书面表达能力；\n4、熟悉机器学习逻辑、数据标注框架者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676033399521839413","sourceKey":"bytedance","company":"字节跳动","title":"ASIC设计工程师（混合信号/高速接口） - 芯片研发","city":"北京/上海/深圳","category":"硬件","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676033399521839413/detail","duty":"团队介绍：字节芯片研发团队目前工作主要集中在芯片设计环节，主要围绕字节自身业务展开芯片探索，为字节多项业务的专用场景定制硬件优化，设计多款基于先进半导体工艺的云端复杂芯片，以期提升性能、降低成本。早期若干芯片项目已经进入到量产部署阶段，有多次一版成功的投片经历，所用工艺包含多个主流的先进工艺节点。与基础设施各团队之间工作的整体协同，能更容易和更好地发挥芯片研发的价值。\n\n1、参与定义并设计state-of-the art混合信号高速互联IP，包括架构定义，前端设计，后端实现，硅后测试，量产等等。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、熟悉数字电路设计，熟练掌握Verilog、SystemVerilog等设计语言；\n3、熟练掌握时序分析，了解reset，CDC相关流程和要求；\n4、熟悉芯片SoC架构，计算机架构相关知识。\n\n加分项\n1、了解高速接口设计，熟悉数字信号处理，模拟电路设计等加分；\n2、了解芯片DFT，可靠性，以及硅后测试等加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670155059057133829","sourceKey":"bytedance","company":"字节跳动","title":"Camera显示效果开发工程师 - 移动OS","city":"深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670155059057133829/detail","duty":"团队介绍：我们隶属于产品研发与工程架构部，是字节跳动在智能硬件领域的软件技术攻坚力量—— 聚焦 AI 与智能硬件的深度融合，如豆包手机助手等；以 “让人与设备的交互更自然、更便捷” 为目标，探索前沿 AI 技术的落地场景，打造行业领先的智能硬件综合解决方案。\n在这里，你将与一支顶尖技术团队并肩：\n- 直击 AI 与硬件结合的核心技术难题，参与从 “技术探索” 到 “场景落地” 的全链路研发；\n- 主导或深度参与关键技术突破，用创新定义智能硬件的交互未来；\n- 站在行业前沿，将技术理想转化为千万用户可感知的产品体验。\n如果你心怀对技术的热忱，渴望在 AI 与智能硬件的赛道上突破自我、创造价值，我们期待你的加入，与我们一起解锁更多技术可能，共筑智能交互的新生态！\n\n1、负责AON多模态显示技术、AutoBrightness策略优化、图像注意力特征分析等，推动显示效果、性能与功耗的平衡；\n2、负责创新型显示效果方向的探索与研究（结合多模态的AI显示、Ultra HDR原理应用等AI HDR技术），推动显示效果竞争力提升；\n3、负责结合显示影像联动的场景端到端的效果提升策略设计与实现，从RawRGB->YUV->RGB->SF->HWC->MIPI RGB->panel全链路探索。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、光信息技术等相关专业优先；\n2、熟练掌握一门计算机编程语言，C/C++优先，MATLAB/Python等也可以；\n3、有图像处理相关项目经验或者实习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668524368616540421","sourceKey":"bytedance","company":"字节跳动","title":"质量效能开发工程师 - AI算力基础设施","city":"成都/西安","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668524368616540421/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、围绕字节跳动全球网络真实研发场景，建设网络软件研发质量与效能体系，提升网络软件交付质量和交付效率；\n2、参与研发场景AI工具、平台和工程能力建设，构建并推进相关研发模式，覆盖AI能力集成、研发流程重塑、工程自动化、度量洞察建设等，并沉淀为可复用工程能力和最佳实践；\n3、持续跟踪AI软件工程、研发效能技术趋势，结合网络研发现状和痛点，引入新技术、工具和方法，优化质量保障和研发效能。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、网络工程、人工智能等相关专业优先；\n2、熟悉至少一门编程语言，具备使用AI编码、学习和问题分析的经验；\n3、理解软件研发流程和质量保障基础，了解需求分析、代码开发、测试验证、代码评审、CI/CD、发布准入等；\n4、具备良好的问题分析、沟通协作和推动闭环能力，愿意通过平台化、自动化和智能化解决研发质量与效率问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668519595087759669","sourceKey":"bytedance","company":"字节跳动","title":"高性能网络研发工程师 - AI算力基础设施","city":"北京/杭州","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668519595087759669/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、负责低时延高吞吐的高速网络技术研发，以及在计算、存储、AI、机器学习、推荐等公司关键业务上的应用；\n2、应用高速网络技术到虚拟机和容器网络，加速网络虚拟化场景；\n3、高性能通信框架以及拥塞控制等核心技术的设计和研发；\n4、高速网络平台系统研发，推动高速网络技术在字节跳动数据中心的大规模部署；\n5、通过技术创新推动高速网络技术的持续演进，打造下一代的超低时延高速互联技术。","requirements":"1、2027届获得本科及以上学历，计算机、网络、软件工程等相关专业优先；\n2、热爱技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n4、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667889676602149125","sourceKey":"bytedance","company":"字节跳动","title":"合规运营 - 国际支付","city":"上海","category":"职能 / 支持","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667889676602149125/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、AML分析与调查：\n1）在既定政策与流程框架下，执行AML相关工作，识别并记录合规风险，推动解决方案落地；\n2）与业务团队协作，理解业务模式与内在风险暴露，识别可疑交易信号，协助制定/优化交易监控规则；\n3）设计并维护监控有效性矩阵与数据看板，用于评估规则表现与覆盖情况；\n4）支持交易监控全生命周期的制度与流程建设与迭代，包括规则验证、系统优化、底层数据分析等；\n2、项目管理与运营协同：\n1）与区域及全球团队协作，支持交易监控流程的上线、迭代与持续优化；\n2）与Global Payments内部跨职能伙伴（合规、产品、数据、工程、运营等）协作，提升运营效率并明确职责分工；\n3）运用项目管理方法推动运营类项目执行，保障交付质量与节奏；\n4）进行数据解读与分析，确保结果准确、可复现，并能清晰表达关键结论。","requirements":"1、2027届获得本科及以上学历，Finance、Data Science、Business或相关专业优先；\n2、具备合规运营实习/项目经历，有交易监控、反洗钱、风控相关经历更佳；\n3、具备较强的数据分析能力，熟练使用SQL、Excel及常见分析工具完成数据处理与结论输出；\n4、良好的沟通与协作能力，能够与不同层级、不同职能同学高效沟通并推进任务；\n5、做事细致、条理清晰，能够在多任务环境下保持准确性与执行力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667855124563511557","sourceKey":"bytedance","company":"字节跳动","title":"AI平台产品运营（User Education） - TikTok","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667855124563511557/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、协助设计和优化新用户Onboarding流程及学习路径，帮助用户更快熟悉平台和功能；\n2、支持用户手册、Quick Guide、培训材料、E-Learning等内容的制作与维护；\n3、协助组织线上/线下培训、产品Demo及其他用户教育活动；\n4、收集培训反馈，并通过数据和用户反馈持续优化培训内容及Onboarding体验；\n5、协助开展NPS、用户调研、访谈及其他用户体验研究，汇总并分析来自工单、用户反馈、调研和平台指标等不同渠道的VoC，识别高频用户痛点、体验趋势及潜在平台问题，支持将分散用户反馈整理成结构化Insight，为产品和业务优化提供输入；\n6、协助整理用户增长、培训、体验及问题治理相关指标和Dashboard，通过数据识别趋势、异常和改善机会。","requirements":"1、2027届获得本科及以上学历，商业/数据分析、信息系统、市场营销、教育/课程设计、商业沟通或相关专业优先；\n2、对平台、产品运营、用户增长、用户体验或AI产品有浓厚兴趣，对用户反馈和用户行为保持好奇心，能够从用户视角思考产品问题；\n3、具备较强的结构化思考和问题解决能力，能够从复杂信息中提炼重点，对数据敏感，具备基础的数据分析能力，熟悉Excel/Sheets，有SQL、Dashboard或数据可视化经验者优先，有LLM或其他AI工具进行分析、内容制作或提升工作效率经验者优先；\n4、具备良好的沟通、写作和内容组织能力，能够制作清晰易懂的用户材料，具备良好的中英文沟通能力，能够在跨文化、跨团队环境中协作；\n5、主动、有责任心，具备较强的主人翁精神，愿意在模糊环境下学习并推动事情落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667802679746742533","sourceKey":"bytedance","company":"字节跳动","title":"精选内容AI策略产品经理（抖音AI产品人才校招） - 抖音生态","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667802679746742533/detail","duty":"团队介绍：抖音生态团队，负责抖音旗下产品的生态工作。我们为抖音生态的健康与繁荣，以及对应的用户心智与场景规模负责。通过看清楚影响抖音生态发展的关键问题，推动问题的解决，维持健康的生态发展环境；通过加强平台多参与角色对平台的正向感知和认知，提升平台长期口碑。我们是一群文理兼修的内容热爱者，既会熟练运用数据工具展开深入分析获取洞察，与算法密切合作拿到数据结果；也会对内容有独到见解和深刻认知，能够清晰定义产品价值下的内容取舍。加入抖音生态团队，可以走在深度好内容的最前沿，和各领域最优质的作者一起创造长期用户价值。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责抖音精选内容生态策略产品，深入洞察用户需求，站在用户视角结合数据、调研等信息，发现业务关键问题并做出合理假设；\n2、深入理解推荐机制流程以及算法基本原理，和推荐算法团队协作，完成策略效果验证及迭代；具备AI应用能力，探索AI在内容推荐场景的落地，主导AI驱动的内容策略迭代项目；\n3、对内容有深入理解，并能够结合数据反馈输出内容判断，定位内容分发价值导向；能定义理想态、建立评估体系、提升大模型效果；\n4、具备完整系统建设能力，规划方向并设定合理目标，进而推进跨部门协作，完成落地与迭代，达成可衡量收益。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、有扎实的数据分析能力，学习能力强；\n3、对内容有鉴赏和判断力，作为用户对主流视频平台内容有深度消费和见解为佳；\n4、自驱力强，对做价值认同的好内容产品有热情；\n5、有内容意识，并能够和数据反馈做结合并输出内容判断，理解和定位长期用户价值指导策略方向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665347150176520501","sourceKey":"bytedance","company":"字节跳动","title":"AIG3D算法工程师 - 音视频技术","city":"北京/上海/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665347150176520501/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责3D AIGC前沿算法的探索与研发，聚焦但不限于文生3D、图生3D、3D场景生成等方向，推动技术创新；\n2、深入研究3D生成模型的关键模块，如3D VAE、3D DiT、智能布线、UV展开、物理属性估计等，并提出创新的解决方案；\n3、主导或参与大规模3D基础模型的训练与优化，包括高效的数据清洗与预处理流程、模型压缩与蒸馏等，构建高效、稳定的3D AIGC基础模型与数据管线；\n4、与产品和工程团队紧密合作，将前沿算法转化为实际应用，确保技术在字节跳动产品中的成功落地与迭代。","requirements":"1、2027届获得硕士及以上学位，计算机、人工智能、数学等相关专业优先；\n2、具备扎实的计算机图形学、计算机视觉、多视几何与深度学习理论基础；\n3、熟练掌握Python，并具备优秀的C++编程能力；熟悉PyTorch/TensorFlow等至少一种深度学习框架，并有较强的工程实现和动手能力；\n4、对技术充满热情，具备出色的分析与解决问题能力、良好的沟通技巧和团队协作精神；\n5、在3D视觉、AIGC、图形学等相关领域有深入的研究或项目经验。\n\n加分项\n1、熟悉NeRF、3D Gaussian Splatting、SDF、Diffusion Models、Transformer等前沿技术，有实际落地经验或在相关领域取得突出成果者优先；\n2、在CVPR、ICCV、ECCV、SIGGRAPH、NeurIPS等顶级会议或期刊上发表过相关论文者优先；\n3、有大规模模型训练、模型压缩/蒸馏、高性能计算（CUDA）或大规模数据处理经验者优先；\n4、有知名开源项目贡献或在Kaggle等算法竞赛中取得优异成绩者优先；\n5、对3D内容创作工具（如Blender,Unreal Engine等）有使用经验或深入理解者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665293565169895685","sourceKey":"bytedance","company":"字节跳动","title":"国际直播后端开发工程师（基础架构方向） - TikTok研发","city":"深圳","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665293565169895685/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，核心代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、软件、电子信息等相关专业；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7645265900954929461","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用实习生-技术风险","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7645265900954929461/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动技术风险团队，提供变更、资金、运维、蓝军等技术风险领域的基建能力，支撑公司数十条业务线的稳定性建设。同时也在积极探索利用大模型技术，在技术风险领域对基建能力做持续的优化和提升，包括智能化资金核对、发布过程的智能检测等。\n\n1、探索大模型技术在技术风险领域中的落地应用，提供基于大模型的智能交互、根因定位和异常检测等服务；\n2、搭建大模型应用的框架，融入技术风险平台，为研发效率提升提供智能服务；\n3、持续跟进大模型前沿技术、开源方案及其在技术风险领域的应用。","requirements":"1、本科及以上学历在读，计算机、软件工程、人工智能等相关专业；\n2、有相关领域项目/研究经验优先，包括但不限于异常检测、日志检测、故障诊断、根因分析等；\n3、熟练掌握业界主流大语言模型（GPT、ChatGLM、LLaMA等）的算法原理，Fine-Tuning策略、Prompt策略、向量数据库和LangChain等应用范式；\n4、优秀的数据敏感性和业务理解能力，能够从复杂业务数据中发掘有效洞见。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622204931247966517","sourceKey":"bytedance","company":"字节跳动","title":"多模态Agent算法研究员-Seed大模型人才校招","city":"深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622204931247966517/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、探索构建GUI、Code、游戏等虚拟世界的通用多模态Agent；\n2、探索研究多模态理解、生成式、机器学习、强化学习、AIGC、计算机视觉、人工智能等前沿技术；\n3、探索大规模/超大规模多模态理解与生成交织的基础模型，并进行极致系统优化；数据建设、指令微调、偏好对齐、模型优化；提升数据合成、Scalable oversight、模型推理、规划能力，构建全面客观准确的评测体系，探索提升大模型能力；\n4、利用预训练、仿真等技术对虚拟/现实世界的各类环境进行建模，提供多模态交互探索的基本能力，推动应用落地，研发以人工智能技术为核心的新技术、新产品。","requirements":"1、2027届获得本科及以上学历，计算机、数学等相关专业优先；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、具有扎实的计算机视觉、机器学习基础，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议上发表论文者优先；\n4、在大模型领域或者RL领域，主导过大影响力的项目者优先；\n5、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；\n6、具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615253077386545413","sourceKey":"bytedance","company":"字节跳动","title":"AI跨端开发实习生-剪映CapCut","city":"广州","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615253077386545413/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：剪映研发团队，主要支持剪映、Capcut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、负责剪映前端和跨端开发工作，包括工具、生态、主框架等业务方向，服务全球用户，业务前景好；\n2、负责挑战较大的技术架构演进和性能稳定性建设工作，通过技术手段为业务赋能；\n3、探索AI技术在业务和技术场景的应用，如AI Coding、AI Agent等。","requirements":"1、2027届本科及以上学历在读，计算机、通信和电子信息科学等相关专业优先；\n2、过硬的编码能力，掌握各种前端技术，包括HTML/CSS/JavaScript/Node.js等；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、对AIGC相关技术感兴趣，有AI Agent建设经验者优先；\n6、有项目经验优先，每周出勤至少4天，实习4个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594312879714126133","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-抖音","city":"深圳","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594312879714126133/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音APP产品的算法工作，共同搭建业界领先的推荐系统、内容理解系统，为用户提供一流的产品体验；\n2、深入理解业务和机器学习技术，优化模型&策略，持续提升推荐效果；\n3、深入理解用户行为，结合数据挖掘等技术，优化用户创作和浏览等体验；\n4、在抖音各个业务场景应用内容算法，改进内容社区的运行效率，支持下游的算法和产品需求；\n5、和产品、运营团队紧密合作，通过对产品和用户的深入理解和分析，制定算法策略促进抖音生态的长期繁荣发展。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、对推荐算法和机器学习有热情、乐于学习、思考和创新；\n4、优秀的分析问题和解决问题的能力，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎、CV、NLP、语音、LLM、AIGC等相关领域有经验者优先；\n6、每周可实习4天以上，实习时间3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7591855659815029045","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生-抖音直播","city":"杭州","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7591855659815029045/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、负责抖音直播团队的前端研发工作；\n2、深入发掘和分析业务需求，撰写技术方案和系统设计；\n3、根据产品需求，进行系统设计和编码。","requirements":"1、2027届本科及以上学历在读，计算机相关专业优先；\n2、具备良好的编码习惯，结构清晰，命名规范，逻辑性强，代码冗余率低；\n3、数据结构和算法基础扎实，计算机理论知识体系完善；\n4、理解并掌握JavaScript语言核心技术DOM、BOM、Ajax、JSON等，对JavaScript框架应用（如jQuery/Bootstrap等）有一定的经验；\n5、对用户体验、互联网产品常见交互有一定了解；\n6、对CSS/JS性能优化有了解者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668588899530901813","sourceKey":"bytedance","company":"字节跳动","title":"Agent客户端开发工程师（剪映PC） - 剪映CapCut","city":"深圳/广州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668588899530901813/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、负责剪映PC端AI Agent相关功能的客户端开发，包括智能对话交互、多模态内容理解与生成等核心模块的设计与实现；\n2、参与AI Agent框架的客户端架构设计，探索Agent调度、工具调用、上下文管理等关键技术方案；\n3、与算法、产品团队紧密协作，将大模型能力高效集成到客户端产品中，打造流畅的AI创作体验。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程或相关专业；\n2、熟悉C++/Python/TypeScript中至少一门语言，有良好的编程习惯和数据结构算法基础；\n3、了解桌面端开发框架（如Qt、Electron、CEF等），有跨平台开发经验者优先；\n4、对AI/LLM应用开发有浓厚兴趣，了解Prompt Engineering、Function Calling、RAG等概念优先；\n5、具备良好的学习能力和团队协作精神，有较强的问题分析和解决能力；\n6、有开源项目贡献、竞赛获奖或AI相关项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668280649551890741","sourceKey":"bytedance","company":"字节跳动","title":"抖音泛娱乐治理策略（大模型方向） - 抖音社区治理","city":"杭州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668280649551890741/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n1、职能范围：作为策略BP对抖音直播泛娱乐内容安全各风险域风险问题负责，工作内容包括不限于违规标准制定、风险感知预警、内容策略体系搭建、提升内容审核效率、协同业务需求等；\n2、治理大模型：通过算法合作，落地大模型应用，推动治理链路整体效率提升；\n3、内容违规标准制定：参与内容违规的定性和审核标准制定，明确需要管控风险形式和范围以及决策与危害程度相对应的处置力度；\n4、风险预警：通过舆情分析或者巡检反馈等方式，提前预警可能的热点或者潜在的内容风险问题，判断优先级和解决方案；\n5、风险策略制定：通过工具和数据分析能力主动挖掘线索，建立基于人和场景的分层管控策略体系，打击黑灰产业，解决业务痛点问题；\n6、产品链路完善：与产品、数据、技术团队协同合作，完善风控产品链路，驱动风险治理工作高效良性循环。","requirements":"1、2027届获得本科及以上学历，计算机、统计学、数学、算法等专业背景优先；\n2、有AI大模型产品使用或实习经验优先，有大模型治理应用经验优先，有较强的逻辑思维能力和数据能力，能有效进行数据处理和策略决策；\n3、具备良好的团队沟通和协作能力；\n4、熟悉大模型原理。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667912716720326965","sourceKey":"bytedance","company":"字节跳动","title":"AI产品设计师 - 抖音基础体验","city":"北京","category":"设计","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667912716720326965/detail","duty":"团队介绍：抖音基础体验团队，负责抖音的产品架构和Feeds消费等基础产品工作，同时通过产品设计规范和体验设计落地来保障抖音的整体用户体验。\n\n1、负责抖音的全局基础设施，同时通过产品设计规范和体验设计落地来保障抖音的整体用户体验；\n2、围绕核心内容容器，持续构建与优化体验规则与设计资产（组件、交互、表达方式），支撑多场景、多业务的接入与演进；\n3、将AI融入设计与产品工作流，在体验定义、方案生成与验证过程中提升效率与探索空间；\n4、探索AI对内容消费、互动方式与表达形态的影响，结合业务实践推动新的体验模式与产品形态落地。","requirements":"1、2027届获得本科及以上学历；\n2、有相关项目研究和实践经历，有可展示证明自己的案例和作品；热爱设计，对行业、产品、设计的发展趋势有关注，有寻求改变和创新的热情；\n3、重视细节，对美有高标准的追求，扎实的专业能力；\n4、在实际项目中使用过AI参与设计或产品流程，能够清晰说明其在体验定义、创意探索或方案生成中的作用；\n5、具备AI Coding/AI Prototyping/动效等能力为加分项。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615510704532310277","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent移动端研发实习生-开发者服务","city":"广州","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615510704532310277/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、参与字节跳动客户端统一AI测试框架的建设，参与新一代AI自动化测试相关服务建设，包括用例生成、用例驱动，智能执行、智能断言等；\n2、参与AI自动化测试相关的客户端SDK，框架，MCP工具建设，包括测试环境构造，UI驱动，弹窗管理，日志抓取，网络抓包，应用问题排查，模拟器问题排查，设备问题排查等；\n3、深入业务团队（抖音、今日头条、飞书等），解决业务需求，协助业务排查问题，降低测试成本，提升测试效率，提升产品体验。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、自动化、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握至少一门编程语言，包括但不限于Python、Java、Go等；\n3、了解AI Agent相关技术与设计思想，了解主流AI模型及其应用场景；\n4、有从0-1搭建AI Agent应用经验，能够独立完成Agent应用的设计开发者优先；\n5、在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683396275805276421","sourceKey":"bytedance","company":"字节跳动","title":"欧洲区域生态运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683396275805276421/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、制定产品指标与产品需求策略；\n2、进行关键数据分析，追踪业务关键指标，发现数据背后的问题和机会点；\n3、支持跨部门沟通、项目管理、信息收集等工作。","requirements":"1、本科及以上学历在读；\n2、熟练使用Excel，具备一定的数据分析能力；\n3、英语表达及书写流利，可作为工作语言，有国际化留学或经历者优先；\n4、每周至少实习4天，实习时间3-6个月。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670802558391781637","sourceKey":"bytedance","company":"字节跳动","title":"游戏策划（回合制卡牌）实习生 - ZERO36工作室","city":"上海","category":"游戏策划","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670802558391781637/detail","duty":"团队介绍：ZERO36工作室旗下有《航海王热血航线》、《花亦山心之月》、《初音未来：缤纷舞台》多款游戏产品。\nZERO，是从0开始，是不念过往，不畏将来；是回到原点，对知识诚实；是一切开始的基础。\n36，如果加上°C，即为人体的温度，戒骄戒躁保持初衷，用\"温度\"拉齐大家的目标和价值观，做有温度的产品，有温度的运营，成为一个有温度的团队，欢迎加入我们！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、根据需求，协助落地系统功能、战斗设计，能根据设计方案产出功能、美术需求，并持续跟进落地，确保最终效果符合预期；\n2、维护负责模块的配置表和引擎工具，根据需求进行工具优化的推进和落地；\n3、参与游戏体验优化，关注剧情感受、系统交互、战斗体验、视听反馈等最终体验问题，能基于自己的理解进行反馈并输出建议。","requirements":"1、本科及以上学历在读，专业不限，游戏设计、计算机、数学、数字媒体等相关专业优先；\n2、能保证每周至少4天，实习时长不少于6个月；\n3、对游戏设计有浓厚的兴趣，对优质内容创作有强烈诉求；熟悉并深度体验过多款回合制战斗游戏/女性向剧情游戏，并至少有1款服务型回合制卡牌游戏/女性向游戏长期体验经验（1个月及以上）；\n4、逻辑思维清晰，学习能力强，能够快速适应新技术和业务需求；善于沟通表达，有团队合作精神，对待工作有责任心；\n5、须至少随简历附以下内容之一：\n1）对1款回合制游戏战斗/女性向游戏系统的深度拆解分析；\n2）自制的回合制战斗/女性向游戏系统的设计方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670156313842075957","sourceKey":"bytedance","company":"字节跳动","title":"图书教育电商运营 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670156313842075957/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合抖音内容特性，制定行业在抖音产品内的完整策略，根据图书教育行业的特性、发展阶段及市场趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、对图书教育行业兴趣度高，有较强的好奇心和快速学习的能力；\n3、了解抖音的短视频和直播流量规律，关注内容电商的玩法。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，有行业运营、类目运营、商品运营等实习经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有团队合作精神，较好的协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669994408255326517","sourceKey":"bytedance","company":"字节跳动","title":"推荐产品实习生 - 抖音电商","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669994408255326517/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、用户导购优化：深入研究抖音电商猜你喜欢场景下的用户行为与痛点，建立用户体验评估体系，设计并落地提升“逛买”体验的产品方案，从导购样式、交互流畅性到内容呈现等多维度优化用户浏览体验，提升用户对推荐场景的信任度与满意度；\n2、数据驱动决策：通过用户调研、A/B测试、行为数据分析等手段，持续验证产品假设，推动数据化迭代；\n3、跨团队协作：与研发、设计、测试等多角色紧密配合，推动方案高效落地，并主动挖掘业务创新机会；\n4、具备1段以上产品经理实习经验，有导购产品或电商相关背景优先；具备敏锐的用户洞察力，擅长从复杂业务场景中提炼核心问题，并能通过产品化手段解决；数据敏感，熟练使用SQL、Excel等工具，能独立分析问题并驱动决策；\n5、热爱电商行业，对抖音生态有深刻理解者更佳；自驱力强，具备目标感和强烈的责任心，为达成目标坚持不懈，勇于承担责任并接受挑战。","requirements":"1、本科及以上学历在读；\n2、1段以上产品经理实习经验，有导购产品或电商相关背景优先；\n3、具备敏锐的用户洞察力，擅长从复杂业务场景中提炼核心问题，并能通过产品化手段解决；\n4、数据敏感，熟练使用SQL、Excel等工具，能独立分析问题并驱动决策；\n5、热爱电商行业，对抖音生态有深刻理解者更佳；\n6、自驱力强，有目标感和责任心强，为了目标坚持不懈，敢于承担和挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668335125199259909","sourceKey":"bytedance","company":"字节跳动","title":"Agent全栈开发工程师（AI剪辑方向） - 剪映CapCut","city":"深圳/广州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668335125199259909/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、负责业务和系统的全栈开发以及体验优化；\n2、负责和Agent相关功能的迭代，参与框架搭建、功能开发和效果优化；\n3、参与领域模型的全流程工作，根据实际业务场景，将创新性技术方案高效落地，推动创作AI能力的持续突破。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、有良好的编程习惯，代码结构清晰，命名规范；\n3、熟练掌握数据结构与算法、计算机网络、操作系统、编译原理等课程，熟练掌握Swift/Kotlin/Go/C++/C/JavaScript等一种或多种语言；\n4、充满技术热情，有较强的自驱力和学习能力；\n5、业余爱好视频拍摄、视频编辑，有移动端、桌面端视频编辑软件使用经验者优先；\n6、至少掌握1款Coding Agent工具；对AI感兴趣，有AI实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667869116247820549","sourceKey":"bytedance","company":"字节跳动","title":"大模型评测算法工程师 - 抖音直播","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667869116247820549/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、参与构建新一代多模态大模型评测体系，覆盖3D生成、动态3D（4D）、数字人、世界模型等AIGC方向，驱动模型效果持续优化与业务规模增长；\n2、基于计算机视觉（CV）、音频理解、多模态大模型（MLLM）、多模态Agent、强化学习（RLVR）等技术，构建Score Model、Reward Model等自动化评测能力，将人类感知与偏好有效建模，并融入评测闭环，提升生成模型评估与优化效率；\n3、参与构建行业领先的多模态评测体系，融合元评估等方法，持续迭代评测标准与数据集构建范式，提升评测结果的可靠性、细粒度与可解释性，系统刻画模型能力边界；\n4、作为算法角色，与工程和质量团队协作，将评测能力落地到实际业务场景，支撑模型训练、调优与上线决策。","requirements":"1、2027届获得本科及以上学历，计算机、电子工程、数学或相关专业优先；\n2、在计算机视觉、多模态学习、AIGC、机器学习或图形学等方向具备扎实基础，至少在一个方向有深入理解或项目经验；\n3、具备良好的问题分析与解决能力，能够深入理解并解决大模型训练及应用中的关键问题；\n4、具备良好的沟通与协作能力，积极主动，具备较强的自驱力与技术探索意愿。\n\n加分项\n1、具备多模态大模型、基础模型、3D生成、世界模型等方向的训练或评测经验；\n2、具备扎实的算法基础，熟悉CV、NLP、RL、AIGC等技术方向，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议/期刊发表论文者优先；\n3、具备优秀的工程能力，熟练掌握C/C++或Python，具备竞赛经验（如ACM/ICPC、TopCoder、Kaggle等）者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664592727619193141","sourceKey":"bytedance","company":"字节跳动","title":"大模型评测工程师（番茄小说） - 抖音研发中台","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664592727619193141/detail","duty":"团队介绍：抖音研发中台团队主要负责抖音、剪映、今日头条、番茄小说、财经等产品的质量建设，面向质量、体验、安全提供全方位、深层次、高效的解决方案。\n\n1、负责大模型评测技术建设，面向实际业务场景设计并落地实践，持续提升专业度、稳定性与效率；\n2、负责评测框架设计、评测模型的训练、部署和调优，分析模型表现与问题归因，沉淀评测洞察，支撑模型优化和版本迭代；\n3、面向LLM、多模态理解、生成、Agent、世界模型等场景，探索科学、可扩展的评测方法论与技术体系；\n4、持续关注和调研大模型领域的前沿技术或最佳实践，并在评测工作中落地创新。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备扎实的机器学习、深度学习或自然语言处理基础，有大模型相关算法经验；\n3、能够将算法能力应用于实际评测场景，熟悉Python，有评测框架设计、评测模型训练部署或评测系统落地经验；\n4、具有出色的分析、解决问题的能力，能深入解决大模型训练、应用存在的问题，有自主探索解决方案的能力；\n5、具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新的AI技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664558120950384949","sourceKey":"bytedance","company":"字节跳动","title":"传输智能算法工程师 - 音视频技术","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664558120950384949/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责网络传输大模型及智能算法的设计与开发，提升网络传输能力和智能化水平；\n2、负责国际顶级会议高水平论文的跟踪、验证，推动先进算法在实际业务中的落地。","requirements":"1、2027届获得本科及以上学历；\n2、熟悉主流机器学习和深度学习算法，掌握PyTorch等深度学习框架；\n3、熟练掌握至少一种编程语言，具备良好的编程能力和习惯；\n4、有大模型、自动驾驶、强化学习或网络传输智能算法相关经验者优先；\n5、在ICLR、CVPR、ICML、NIPS、ACL、ICCV、AAAI等顶级会议发表过论文优先；\n6、具备良好的团队协作和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592519727835728181","sourceKey":"bytedance","company":"字节跳动","title":"反作弊产品实习生-风控","city":"杭州","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592519727835728181/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：风控产品部门负责规划和执行字节跳动业务风控工作，致力于构建和输出相关能力，以助力业务提升安全风控水平，增强对抗和运营效率。日常工作涵盖业务问题对接、风险评估、策略分析、风控方案的制定和推进，以及产品能力的建设和应用，理解机器学习和大模型的能力边界，不断探索 AI 在风控领域的应用以提升对抗的效率。\n\n1、深入了解字节跳动各产品线反作弊业务，设计和规划相关产品策略体系，协调资源并推动相关团队高效完成目标；\n2、完成平台需求分析和产品方案，收集整理具体业务遇到的各类作弊问题，通过数据分析挖掘用户行为动机，并给出解决方案；\n3、跟进产品需求的设计、开发、测试和上线等环节并确保项目开发进度；\n4、通过对风险数据分析和特征挖掘，沉淀风险特征和业务防控经验，构建风险画像和指标体系，并推动数据能力的产品化和服务化落地。","requirements":"1、2027届本科及以上学历在读，计算机、信息安全、统计学、数学及相关专业优先；\n2、英语熟练者优先，对各类作弊行为有感知，能够准确的描述和识别作弊特征；\n3、熟练掌握SQL和Excel，具有数据分析相关经验；\n4、良好的逻辑思维和数据敏感度，注重细节；\n5、对新事物有较强的好奇心和钻研探索的自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7589516329020180789","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-番茄","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7589516329020180789/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-番茄团队，负责字节跳动下番茄小说、红果短剧、番茄畅听、国际化短剧等产品的推荐算法和AI相关工作。我们的工作包括优化业界前沿的大规模推荐系统，探索LLM与推荐的结合，并落地生成式推荐范式，从小说、短剧、音频、音乐等内容方向建设完整的内容生态和AI能力，保持业务规模保持超高速增长。\n\n1、番茄各产品（番茄小说、红果短剧、番茄畅听、国际化短剧等）目前在各自领域都处于行业头部，用户规模在同类产品和同等规模产品中无论体量还是增速都处于领先；番茄系产品专注于构建故事领域的全体裁内容平台，从小说、短剧、音频、音乐等内容方向建设完整的内容生态；\n2、参与番茄全系产品中的推荐算法工作，与拥有丰富业界经验的同学合作，共同搭建业界前沿的推荐系统，提高产品使用体验，保持产品规模继续高速增长；\n3、具体负责小说、短剧、音频、音乐等体裁的各场景全链路推荐工作，包括召回、粗排、精排、混排等；结合业务问题设计推荐模型和优化目标，促进内容生态持续繁荣，和业务团队紧密合作。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、有扎实的编程基础、良好的编程风格和工作习惯，扎实的数据结构和算法功底；\n3、有扎实的机器学习/深度学习理论和丰富的实践经验，熟悉至少一种主流深度学习编程框架；\n4、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；善于沟通，工作积极主动，责任心强，具备良好的团队协作能力；\n5、在顶级会议发表论文，或ACM/机器学习等竞赛获奖，或有大规模推荐系统、计算广告、搜索引擎等核心算法业务经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7581451859225053445","sourceKey":"bytedance","company":"字节跳动","title":"安全攻防实习生-安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7581451859225053445/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：我们团队为字节跳动旗下各类业务线提供信息安全保障。\n通过与各业务团队紧密协作，我们针对其特定的运营及业务需求，设计并落地专属安全策略。\n依托安全部门的专业能力，我们交付与业务目标高度契合、兼具成本效益与可扩展性的安全解决方案，助力各团队获取最高效、最可靠的安全服务与工具。\n\n1、负责办公相关系统安全渗透测试、漏洞挖掘工作，并可以协助业务完成漏洞修复；\n2、参与一些安全项目的推进工作；\n3、可以开发一些小工具在项目中使用。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、计算机基础知识扎实，熟悉常见安全风险的原理、攻防策略；\n3、熟悉Golang、Python、Java或Node.js至少一门语言生态，能进行代码审计及开发；\n4、有CVE挖掘和CTF比赛获奖经历者优先；\n5、熟悉Web、PC、APP客户端等漏洞挖掘及安全测试；\n6、有良好的沟通能力、学习能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7451901743686486290","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-国际化社区","city":"上海","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7451901743686486290/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：国际化社区研发团队，旨在建立面向海外的兴趣种草社区，以图集和视频为内容呈现形式，专注于美妆、时尚、美食、旅行、居家、健身、艺术、萌宠等内容领域，为用户提供有信息价值的优质内容。用户可以在这里发现新的想法，分享通往美好生活道路上的真实经历，共同打造精致、时尚的兴趣种草社区。 加入我们，从业务上你能接触到包括用户增长，社交，内容，消费等核心业务场景，从技术上也能够接触到包括基础技术，服务架构等方向上的挑战；会让你具备保障业务持续高质量高效率安全的为用户服务的能力的同时，还能具备为不同的业务场景提供全面的技术解决方案的能力，享受专业且纯粹的团队带来的工作乐趣和个人成长。\n\n1、参与架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届本科及以上学历在读，计算机、软件、电子信息等相关专业； \n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分，有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683799719558302005","sourceKey":"bytedance","company":"字节跳动","title":"行业策略实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683799719558302005/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、活动管理与执行：组织并跟进商家参与平台直播活动，及时完成各项活动报名，协调资源确保活动落地；\n2、商家沟通与支持：解答商家关于直播功能、规则及活动的日常咨询，协助优化商家沟通流程，提升协作效率；\n3、文档撰写：撰写面向商家的英文教育文档，确保信息清晰易懂，参与直播活动文案策划，协助设计吸引美国消费者的营销话术；\n4、数据分析与洞察：负责直播数据的整理、分析与可视化，搭建数据看板，辅助团队监控业务表现并制定优化策略，定期输出数据报告，提炼关键指标。","requirements":"1、本科及以上学历在读；\n2、英文口语和书写均达到流利水平，能够在邮件沟通、社交媒体交流以及日常工作中顺畅地使用英语进行沟通；\n3、具备数据清理和分析能力，熟练掌握数据分析软件，熟练使用SQL、Excel，精通Excel各种公式，能够独立完成数据的整理、分析及可视化展示工作；\n4、有电商平台/电商机构实习经验优先；\n5、每周可实习5天，可以实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675583335754697013","sourceKey":"bytedance","company":"字节跳动","title":"出海大客户/渠道销售（非电商-游戏） - Global Business Solutions","city":"上海/深圳","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675583335754697013/detail","duty":"团队介绍：Global Business Solutions (GBS) 负责TikTok为主的全球产品商业化相关工作，为全球品牌和广告商提供集成的数字营销解决方案。具体包括各区域销售、销售运营、渠道管理、商业化战略、To B市场营销、营销科学、商业化合作和商业内容安全等职能。\n\n1、参与制定国际化商业化广告客户及代理体系的运营策略，协助完成客户/代理开发与维护的规划工作；基于市场反馈协助构建需求分析模型，参与设计合作伙伴激励方案及生态运营机制，支持服务生态的良性发展；\n2、协助搭建代理商分层培训体系，参与培训内容的设计与整理（含业务逻辑、产品能力、运营方法等），跟进业务与项目的周期性运营进展；同时结合广告主多元需求，参与市场推广方案的策划、落地执行及效果跟踪迭代；\n3、参与制定多方协同沟通策略，协助构建“专项-培训-中高层”分层沟通机制，支持专项运营计划、培训体系及战略谈判材料的准备，推动内外部目标对齐与协同增长策略的落地；\n4、基于行业与市场信息，协助构建跨境行业趋势洞察体系，参与媒体价值与客户/代理需求的匹配分析，支持合作伙伴与客户痛点研究，并为代理商赋能策略提供数据与信息输入；参与潜力合作伙伴的挖掘分析，协助建立筛选、培育与评估的基本框架，支持市场推广策略的执行与长期合作机制的建设。","requirements":"1、2027届获得本科及以上学历，广告学、市场营销、工商管理、传播学、数据分析等相关专业优先；\n2、对广告和全球营销趋势有浓厚兴趣，具备较强的学习能力与信息整合能力，善于从数据与案例中发现规律；\n3、具备良好的人际沟通与协调能力，乐于与内外部伙伴协作，能够清晰表达观点并推动共识；\n4、思维活跃、逻辑清晰，善于拆解复杂问题，具备较强的执行力和结果导向意识；\n5、自驱力强，能够高效处理多任务并行场景，具备优秀的多任务协同能力；\n6、英语可作为工作语言，有国际化学习、交换或跨文化项目经验者优先；对跨文化沟通与跨国业务协作有热情者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668543382147238149","sourceKey":"bytedance","company":"字节跳动","title":"AI娱乐方向Agent Harness研发工程师 - Flow","city":"上海/杭州","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668543382147238149/detail","duty":"团队介绍：字节跳动Flow产品研发团队，专注研究AI智能化相关业务落地，目前落地豆包、Dola等APP，以及对应的Bot开发平台等AI智能化创新产品，业务和团队均处于快速发展期，成长空间大，欢迎各位同学加入！\n\n1、参与AI娱乐/陪伴场景下的Agent Harness系统设计与开发，在导师指导下完成智能体规划、工具编排、RAG增强、长上下文管理、任务调度等核心模块的迭代与优化；\n2、参与Agent效果评估和质量保障工作，协助设计场景化评测用例与数据集，支持自动化评测流水线、版本回归与A/B实验，让模型和Agent的迭代效果可量化、可溯源；\n3、参与Agent全链路可观测相关工具的开发，包括执行轨迹追踪、结构化日志、性能监控与异常告警，协助改进调试工具与链路回放工具，提升问题排查效率；\n4、结合内部真实任务与用户反馈，参与Harness产品的持续迭代，并协助维护相关技术文档与链路。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能等相关专业优先；\n2、对Agent及其工程化有浓厚兴趣；熟悉TypeScript/JavaScript开发，具备一定的工程模块设计意识；了解Go或其它至少一门后端语言，有能力搭建简单的服务与API；\n3、对LLM与Agent的基本机制与原理有初步了解（如LLM API、Agent Loop、Tool Use、Planning、Memory、RAG、MCP等概念）；\n4、是AI Agent产品的深度使用者（如Codex、Claude Code、Cursor、OpenClaw、Manus、Cowork等），并已经把它们融入到自己的学习或生活中；\n5、具备良好的沟通与团队协作意识，乐于在导师带领下共同成长。\n\n【加分项】\n1、有AI行业实习、创业或开源项目经验，尤其是Agent相关的0-1项目实践；\n2、作为团队或个人开发者快速迭代产品的经历（如独立作品、黑客松项目等）；\n3、参与开源社区，有个人作品或贡献记录；\n4、学习能力强，能够借助AI辅助，在缺乏直接经验的领域（如新语言、新框架）快速上手并系统性学习。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667889677916260661","sourceKey":"bytedance","company":"字节跳动","title":"服务端研发工程师 - 飞连","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667889677916260661/detail","duty":"团队介绍：飞连团队研发新一代零信任安全平台，为人工智能时代的内部系统及企业客户提供安全保障。凭借多年企业安全领域实战经验积累的深厚专业能力，我们致力于提升网络安全防护水平，助力字节跳动及客户在数字化转型之路。通过构建具备韧性的智能防御体系，为字节跳动及其客户生态系统守护核心资产，赋能安全可信的创新实践。\n\n1、参与公司安全To B业务的后台服务及通用组件开发；\n2、参与服务端相关的需求分析与技术方案设计，结合业务场景提出合理的技术实现并落地实施；\n3、参与服务端系统的性能优化、架构演进及技术难题攻关，提升系统的稳定性、可扩展性和安全性；\n4、与产品、前端及测试等团队紧密协作，推进项目进度，确保功能按计划交付。","requirements":"1、2027届获得本科及以上学历，计算机及相关专业背景；\n2、了解MySQL、Redis、消息队列、RPC等技术；\n3、理解计算机原理，具有良好的操作系统、网络、数据结构及算法基础，了解前后端开发协作流程；\n4、熟练掌握Linux环境下的C/C++/Go/Python/Java等至少一种语言，具有扎实的编程能力和模块化设计能力，追求优秀的代码质量；\n5、学习能力强，对产品有强烈的责任心，具备良好的沟通能力和优秀的团队协作能力，能够有效地进行跨部门团队合作；\n6、有AI技术深度研究实践或开源项目深度参与者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7579520509315975477","sourceKey":"bytedance","company":"字节跳动","title":"AI数据产品运营（质量管控方向）实习生 - TikTok","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7579520509315975477/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok ADSO（AI Data Service and Operations）团队负责支撑AI 模型训练、评估与优化的核心数据服务与运营。通过构建高质量、标准化的数据生产体系，以及建立全球化的精益运营模式，为TikTok产品各类 AI 能力的迭代提供稳定、规模化、高性价比的数据支持，推动 AI 技术在复杂业务场景中的深度落地。\n\n加入我们，在真实的全球化 AI 业务中快速成长。你将与顶尖的算法、产品、工程团队协作，在实战中理解 AI 如何真正落地。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与AI大模型相关的内容安全数据标注、质量管控；\n2、深度学习内容安全政策，能快速掌握内容安全质检全流程，独立完成内容安全风险评估与合规校验；\n3、精准识别政策在实际应用中的适配问题，输出落地性政策优化建议；\n4、有良好的团队合作能力，能配合团队推进内容安全项目的进度、质量跟进，协助跨部门的协作落地。","requirements":"1、本科及以上学历在读；\n2、英语可作为工作语言，适应跨文化沟通；能快速理解规则类内容，具备较强的逻辑梳理和分析能力，可短时间掌握复杂流程；\n3、细心负责，能把控高风险内容的质量细节；\n4、有良好的沟通协作能力，能适应工作节奏；\n5、对内容安全、社区生态有兴趣。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675745742295697717","sourceKey":"bytedance","company":"字节跳动","title":"广告产品实习生 - 广告业务","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675745742295697717/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与广告产品整体需求分析和规划，设计产品原型，并撰写需求文档；\n2、具备较好的数据分析能力，对产品运营数据进行追踪和分析，制定优化方案并推动产品持续迭代；\n3、负责用户调研、用户反馈收集，辅助决策及方案的输出，反哺产品上线迭代；\n4、与研发、运营等部门密切合作，推进产品的快速升级，保证产品按时、高质量上线。","requirements":"1、本科及以上学历在读；\n2、出色的产品规划能力，能主导产品方向和制定长期规划，并拆分为可实施项目；\n3、良好的沟通协调能力，可独立完成跨职能和跨部门沟通；\n4、有商业产品实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668526256773990709","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师（网络） - AI算力基础设施","city":"北京/成都","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668526256773990709/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、参与字节跳动网络产品前端研发与体验技术创新工作；\n2、面向全球客户，深入发掘、理解、分析业务需求，撰写技术方案并落地实现；\n3、参与前端架构设计演进、AI研发效能提升、自动化测试、运维等建设工作；\n4、参与Agent中间件、大规模网络节点可视化、页面自动化生成与操作等多个方向的探索。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、熟练掌握主流前端技术栈与应用框架，具备AI编程实践经验，理论与工程能力兼备；\n3、良好的沟通和团队协作能力，热爱技术、责任心强，具备强烈的好奇心和快速学习能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668259939832088837","sourceKey":"bytedance","company":"字节跳动","title":"C++客户端开发工程师 - Seed 桌面OS","city":"北京/深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668259939832088837/detail","duty":"团队介绍：产品研发和工程架构-Seed 桌面OS是字节跳动桌面端技术团队，支撑豆包、飞书、Trae IDE、剪映等业务。团队覆盖从浏览器内核、工程基建、操作系统底层到 AI Agent 执行层的完整技术栈。真正有杠杆的工程价值就在这里：一次内核升级服务数亿用户，一个沙盒方案定义 AI Agent 的安全边界，一套基础设施让所有业务共同受益。如果你对“难而正确”的技术有热情，这里有足够复杂的真实场景，完整的技术闭环，以及足够大的技术影响力。\n\n1、负责字节跳动PC客户端基础设施与跨平台运行体系的设计与演进，持续提升在Windows/macOS/Linux平台上的性能、稳定性与可扩展性；\n2、负责PC端运行框架和渲染引擎的品质提升，包括功能迭代、安全加固、性能优化、稳定性提升；\n3、负责飞书/豆包/TRAE的Chromium升核和内核增强能力拆分，设计“可持续升核”的架构和流程，把一次次大项目沉淀为体系；\n4、探索AI技术在PC客户端中的工程化落地，面向Chromium/PC架构的智能化工具与基础能力探索。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的数据结构和算法基础；熟练掌握至少一门编程语言，包括但不限于：C、C++、Rust；\n3、对某个操作系统的某个机制的细节有足够深的理解和掌握；\n4、可以熟练运用各系统级的调试工具来发现和定位问题（如IDA/WinDBG/XPerf）；\n5、有负责人/闭环/单件流意识，有技术追求。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667544823326509365","sourceKey":"bytedance","company":"字节跳动","title":"云与AI咨询销售 - 火山引擎","city":"深圳","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667544823326509365/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、梳理不同行业客户信息，直接或通过渠道伙伴收集客户信息，触达并维护决策关系，挖掘需求并捕获项目机会；\n2、推进双方在技术、产品和商务等多层面的沟通，全局掌控项目节点与节奏，并推进项目落地；\n3、协同产品和解决方案，对不同产品线在某行业拓展的标杆客户落地、客户覆盖数及营收目标负责；\n4、具备体系化与数据化的业务思路，能够根据销售过程管理数据分析，发现业务问题，提出改进方案，制定业务策略和规划，优化业务模型；协助业务团队建立可执行、可追溯的动作；\n5、你将获得：有效传递火山引擎对客户的价值并输出成果；有机会参与完整的客户业务合作，收获一线实践经验，快速提升个人综合能力，为职业发展奠定坚实基础。","requirements":"1、2027届获得本科及以上学历，科学技术或计算机相关背景；\n2、其他学科可以快速学习AI和云产品知识；具备良好的沟通能力、学习能力以及团队合作能力；\n3、对AI、云、大数据等感兴趣并且愿意长期从事相关工作；\n4、熟悉主流大模型与AI应用，持续关注火山引擎AI领域前沿动态，具备动手实践能力。\n\n加分项：\n1、在校期间担任学生干部、组织过校级项目并担任负责人；\n2、有实习等相关经验；\n3、如有相关作品或项目成果（如自主开发的AI应用、微调模型、开源项目、技术文章、竞赛获奖作品等），可在简历中附上作品链接或上传附件展示。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665928642694007093","sourceKey":"bytedance","company":"字节跳动","title":"数据科学 - TikTok","city":"上海/北京","category":"数据分析","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665928642694007093/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、负责设计、搭建和维护平台内容安全与风险相关的指标体系，包括但不限于内容违规、用户反馈、账号风险等，搭建完善的监控和异动归因体系，能够快速定位和分析安全事件，为风险预警和策略调整提供数据支撑；\n2、运用严谨的统计科学方法，包括A/B实验、因果推断、回归分析等，评估各项安全策略的效果，深入分析实验结果，为业务决策提供量化的依据，并不断优化实验设计，提升评估效率；\n3、针对具体的业务挑战，构建量化分析体系，运用数据挖掘技术识别潜在的优化机会，与产品、运营、研发、算法等团队紧密合作，将分析洞察转化为可执行的改进方案，并推动其落地，最终提升平台安全；\n4、持续探索和归纳数据分析方法论，沉淀可复用的分析框架和工具，提升团队整体的分析能力，参与数据产品的设计和迭代，将数据分析能力产品化，为业务团队提供更高效、便捷的数据服务。","requirements":"1、2027届获得本科及以上学历，统计学、数据科学、经济学、计算机科学、数学或相关专业优先；\n2、精通SQL，熟练掌握Python/R等数据分析工具，具备优秀的可视化能力；熟悉常用机器学习算法原理，了解因果推断、A/B实验等方法；\n3、具备优秀的逻辑思维能力、问题分析和解决能力，以及良好的沟通表达和跨团队协作能力；\n4、具备一定的英语工作能力；有内容安全、风控、合规相关经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665619699312445749","sourceKey":"bytedance","company":"字节跳动","title":"医疗大模型数据运营 - 小荷健康","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665619699312445749/detail","duty":"团队介绍：小荷健康是字节跳动旗下的医疗健康品牌，我们致力于利用大模型技术，探索医疗健康服务的新范式，孵化了“小荷AI医生”app，为用户提供专业的健康咨询服务。小荷健康拥有专业的医学和互联网产研团队，认真探索AI医疗。\n\n1、模型评估：对用户产品有一定理解，结合用户真实需求制定评测标准，建设自动评估能力，指导线上模型内容效果优化；\n2、数据策略：根据模型表现缺陷，拆解待提升的能力点，根据算法的训练目标、训练方式，调研分析并确定训练数据策略，探索医疗模型能力天花板；\n3、数据获取：根据不同的数据需求和特征，通过广泛调研、机器构造、人工标注的方法，通过获取高质量的数据和语料，协同算法优化模型效果，确保线上内容安全，提升医疗用户体验。","requirements":"1、2027届获得本科及以上学历，医学，临床医学、公共卫生等相关专业优先；\n2、对大模型和用户产品感兴趣，对模型能力边界有理解，具备sp调优、Workflow搭建经验优先，具备基础代码或者vibe-coding能力者优先；\n3、对优质内容有判断力，深刻理解用户需求和内容调性，具备良好的用户调研和内容评估能力，项目管理能力佳者优先；\n4、目标感强，逻辑思维佳，数据分析能力好，责任心强，善于学习和独立思考。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7626693471651219765","sourceKey":"bytedance","company":"字节跳动","title":"长视频生成算法实习生-Seed","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7626693471651219765/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动Seed团队成立于2023年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed团队在AI领域拥有长期愿景与决心，团队研究方向涵盖MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE等超过50个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包App用户量在中国市场排名第一，豆包大模型日均Token调用量行业领先。\n\n1、研发长视频生成模型，聚焦自回归视频生成范式、超长时序建模及长视频一致性保持等核心技术难点；\n2、研发多模态长上下文技术，包括超长上下文高效编码与检索压缩、视频长序列稀疏化及注意力机制优化，提升长视频生成的效率与质量；\n3、研发交互式视频生成技术，赋予模型多轮交互、及时响应能力，探索模型长期记忆机制，实现基于用户实时反馈的动态视频生成；\n4、研发带思维链（CoT）的视频生成技术，引入分步推理、逻辑规划、自我验证等能力，提升长视频创作的连贯性、完整性及效果可控性。","requirements":"1、2027届硕士及以上学位在读，计算机、电子信息、软件工程、人工智能、数学等相关专业优先；\n2、AIGC生成技术一个或多个领域的研究和实践经验，包括但不限于以下方向：\n1）视频生成模型的大规模训练；\n2）世界模型、自回归视频生成、交互式视频生成技术；\n3）多模态创作Agent（CoT、Harness Engineering）；\n4）多模态数据生产或模型评测；\n3、动手能力强，熟练的编程能力，熟悉Python编程；\n4、对AI技术的实际落地和突破性应用充满热情，追求技术创新与现实价值的结合；\n5、良好的自驱力，思维敏捷，追求本质，敢于挑战未知问题，乐于在技术攻关中探索技术前沿，能主动学习并快速成长；\n6、在CVPR/ICCV/ECCV/ICLR/NeurIPS/ICML/SIGGRAPH等顶级会议上发表论文者优先；有数学、编程竞赛经验者有加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594360485674617093","sourceKey":"bytedance","company":"字节跳动","title":"网络研发实习生（ZTNA智能体）-安全与风控","city":"杭州","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594360485674617093/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：我们团队研发新一代零信任安全平台，为人工智能时代的内部系统及企业客户提供安全保障。\n凭借多年企业安全领域实战经验积累的深厚专业能力，我们致力于提升网络安全防护水平，助力字节跳动及客户在数字化转型之路上稳步前行。\n通过构建具备韧性的智能防御体系，为字节跳动及其客户生态系统守护核心资产，赋能安全可信的创新实践。\n\n1、参与飞连网络模块相关的架构设计与研发，构建高可用、高并发、可扩展的网络架构体系；\n2、参与VPN、代理网关、SD-WAN、SASE等技术方向的持续演进与优化，支撑飞连业务场景；\n3、和产品、研发、测试及需求方密切配合，参与需求讨论、功能设计、开发测试及运维等工作。","requirements":"1、2027届本科及以上学历在读，计算机、网络、通信等相关专业背景；\n2、深刻理解计算机及网络原理，熟悉TCP/IP协议栈，如NAT、DHCP、DNS、TCP/UDP等；\n3、具有扎实的编程能力和模块化设计能力，追求优秀的代码质量；\n4、具备较强的逻辑分析及沟通能力，有强烈的求知欲和自驱意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7591814136301373749","sourceKey":"bytedance","company":"字节跳动","title":"芯片系统软件实习生-芯片研发","city":"北京","category":"硬件","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7591814136301373749/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节芯片研发团队目前工作主要集中在芯片设计环节，主要围绕字节自身业务展开芯片探索，为字节多项业务的专用场景定制硬件优化，设计多款基于先进半导体工艺的云端复杂芯片，以期提升性能、降低成本。早期若干芯片项目已经进入到量产部署阶段，有多次一版成功的投片经历，所用工艺包含多个主流的先进工艺节点。与基础设施各团队之间工作的整体协同，能更容易和更好地发挥芯片研发的价值。\n\n1、负责芯片底层软件开发和SoC Bring-up;\n2、负责BootROM/Server固件（SCP/U-Boot/Linux Kernel）开发。","requirements":"1、2027届本科及以上学历在读，计算机技术、软件工程等专业优先；\n2、了解UNIX环境编程，Linux C/C++开发经验；\n3、熟练掌握BSP、Linux内核Debug/Trace的工具与技术，具备调优能力；\n4、熟悉x86/ARM/RISC-V CPU体系架构，掌握其Privilege Level/Interrupt/MMU的实现原理；\n5、对PCIe，DDR，CXL等高速接口协议了解者优先；\n6、熟悉各种低速接口的软件人员，包括UART/I2C/SPI/GPIO等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7454110593421166866","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发实习生-TikTok社交","city":"上海","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7454110593421166866/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok社交团队业务覆盖国际化短视频产品内所有社交场景,包括评论、点赞、通知,以及多种创新社交场景，对增加用户活跃度和用户粘性有着至关重要的作用。\n在这里，有大牛带队与大家一同不断探索前沿,突破想象空间。\n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队人专业且纯粹,合作氛围平等且轻松。\n\n1、深度参与TikTok评论、点赞、通知等核心模块的客户端研发，并探索AI+社交的创新玩法落地；\n2、在真实业务场景中，利用行业前沿大模型编码助手辅助方案设计、代码实现与高质量重构，共同打磨极致的用户体验；\n3、参与产品需求分析，设计系统技术方案，关键代码开发和系统调优；参与各专项技术调研，改进系统性能与稳定性。","requirements":"1、2027届本科及以上学历在读，计算机、软件、电子信息等相关专业；\n2、对数据结构、算法、操作系统、网络协议有深刻理解；至少熟悉一门移动端编程语言（Java/Kotlin/Swift/ObjC/C++等）；\n3、对AI coding保持高度好奇心，不仅是“使用者”，更愿意探索如何将其转化为核心生产力；\n4、有AI编码工具使用经验、AI产品使用经验者优先；\n5、拥抱开源社区、有技术博客沉淀、竞赛经历或有意思的个人项目优先；\n6、有移动端项目实战经验、了解iOS或Android平台的特性与挑战优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685278156750194949","sourceKey":"bytedance","company":"字节跳动","title":"服饰行业商家运营实习生（美国市场） - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685278156750194949/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助完成美区跨境商家日常运营沟通和重点项目推进；\n2、挖掘平台特点和商家需求，协助团队跟进和解决商家日常运营问题，梳理商家运营流程并不断迭代；\n3、通过数据分析，不断协助商家优化选品、流量策略、内容策略等运营方向。","requirements":"1、本科及以上学历在读，商科相关专业优先；\n2、熟练使用办公软件，具备优秀的审美；对数据敏感，擅长分析与总结；\n3、了解，对跨境电商行业以及美区本地市场有基本了解，熟悉短视频平台及欧美社交媒体更优；\n4、英语流利，英文读写能力强；\n5、耐心负责，具备良好的团队协作能力，沟通能力强，思维活跃，逻辑清晰，工作高效；\n6、每周可实习5天，可以实习6个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675202999161227525","sourceKey":"bytedance","company":"字节跳动","title":"机器学习研发实习生 - TikTok Search","city":"北京/上海","category":"机器学习","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675202999161227525/detail","duty":"团队介绍：TikTok Search 团队面向TikTok搜索业务，支撑海量流量的高并发、高性能、高可用搜索基础架构与业务中台。我们长期深耕搜索引擎检索、相关性/个性化排序、算法服务与深度学习工程，打造了覆盖多地区、多数据中心的搜索系统架构。面向大模型时代，我们将生成式搜索、SVLM相关性排序、个性化推荐、多模态理解等多项前沿技术深度融入搜索全链路，持续构建高效、稳定、可扩展的大模型基础设施，同时也积极探索新的搜索范式如视搜、AI搜，和使用 AI Coding 大幅加速搜索系统重构与演进，为TikTok搜索业务提供强有力且可持续演进的技术基座。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与搜索场景下，机器学习和深度学习架构的设计与实现；\n2、关注在高吞吐、大规模场景下的文本相关性模型、多模态、LLM模型、生成式召回等深度学习模型，在搜索场景中的性能和成本优化；\n3、提高模型训练效率，加速推理性能，优化GPU吞吐；\n4、设计和开发高性能算子库，研究最新的GPU计算技术和优化方法，充分利用GPU并行计算能力，支持各种模型在不同硬件上的构建和部署。","requirements":"1、本科及以上学历在读；\n2、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n3、有强烈的求知欲，快速学习和沟通能力；\n4、编程能力扎实，有良好的编程习惯；有ICPC/CCPC/NOI/IOI等相关竞赛获奖经历优先；\n5、如熟悉主流的深度学习框架（PyTorch、TensorFlow）、熟悉主流高性能并行编程技术、有GPU编程经验（CUDA或Triton）、熟悉vLLM/TRT-LLM/SGLang等大模型推理框架与原理优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673816932219062581","sourceKey":"bytedance","company":"字节跳动","title":"投放策略产品实习生 - 抖音","city":"北京/深圳","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673816932219062581/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助支持字节跳动旗下全产品线的广告投放策略设计，参与RTA、DPA、人群定向、智能出价等媒体能力在实际投放中的应用与效果分析；\n2、参与广告模型与投放策略的数据监控与基础分析，协助产出优化建议和产品迭代方向；\n3、理解业务需求，协助跨团队沟通协调，参与策略从方案设计到上线落地的全流程。","requirements":"1、本科及以上学历在读，计算机、数学、统计、信息管理等相关专业优先；\n2、对互联网广告、计算广告或推荐系统有浓厚兴趣并有一定了解；\n3、逻辑清晰，思维严谨，对数据敏感，能通过数据发现问题；\n4、责任心强，学习意愿高，具备良好的沟通能力和团队协作意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673343622427527477","sourceKey":"bytedance","company":"字节跳动","title":"商城策略运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673343622427527477/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、玩法策略：协助进行平台营销玩法的策略制定、数据分析、产品优化，提升营销玩法效率，实现平台GMV的增长；\n2、资源运营：协助进行商城资源的管理和排期，通过资源合理排期，实现GMV的长期增长；\n3、AB实验：负责日常简单AB实验策略的设计和落地，通过实验验证玩法、资源策略有效性，产出清晰的复盘报告；\n4、数据分析：协助进行数据分析，监控相关关键指标，输出优化策略；\n5、配合完成部门其他相关工作。","requirements":"1、本科及以上学历在读；\n2、能保证一周5天的出勤，至少实习3个月及以上，6个月优先；\n3、具备较强的英文听说读写能力，口语可日常沟通；\n4、具备较强的数据分析能力，有设计和落地AB实验的经验为佳。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667894678415788341","sourceKey":"bytedance","company":"字节跳动","title":"国际消费金融产品经理 - 国际支付","city":"上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667894678415788341/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、定义与优化产品链路：负责BNPL或Personal Loan两大产品的关键转化漏斗（Conversion Funnel）分析与优化，识别用户痛点，设计能够显著提升用户体验与业务指标的产品方案；\n2、驱动业务增长与风险平衡：与解决方案团队、增长团队协作，策划并执行拉新、促活、留存等增长策略；与风控团队紧密配合，在业务扩张与风险控制之间找到最佳平衡点；\n3、推动跨区域与跨职能协作：与不同国家和地区的本地化团队、工程、设计、法务、合规等团队高效沟通，确保产品方案在满足全球一致性的同时，也符合本地市场需求与监管要求；\n4、数据驱动与实验验证：深度利用数据分析，建立并监控业务核心指标，设计并执行A/B测试，以科学的方法验证产品假设，驱动产品迭代。","requirements":"1、2027届获得本科及以上学历，专业不限，计算机、数学、物理等理工类专业优先；\n2、具备逻辑分析能力与结构化思维，能够将复杂问题拆解为可执行的模块，并清晰地呈现思考过程；\n3、沟通、表达与组织协调能力，能够积极主动地与不同背景的团队成员协作，推动项目顺利进展；\n4、对国际业务和消费金融领域有浓厚兴趣，具备强烈的主人翁意识（主人翁精神），自我驱动，能在富有挑战的环境中持续学习和成长；\n5、具备流利的中文与英文沟通能力，能够适应跨国工作环境。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628612570892945669","sourceKey":"bytedance","company":"字节跳动","title":"大模型赋能交易与商业场景的技术创新及落地实践研究（AI Infra） - Commercial AI","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628612570892945669/detail","duty":"团队介绍：Commercial AI 负责中国交易与广告的to B应用统一模型建设，包含基础模型能力、AI Infra、统一商业数据、评测等方向。\n\n课题介绍：\n本课题围绕商业、广告、交易等技术场景，以大型语言模型（LLM）、视觉语言模型（VLM）、智能体（Agent）、强化学习、多模态生成等前沿技术为核心支撑，重点聚焦搜索、广告、推荐、电商、生活服务、广告营销、内容生产等关键业务场景，针对性破解传统技术体系存在的瓶颈问题。课题的核心研究目标为：借鉴大模型规模法则（Scaling Law）与生成式人工智能技术思路，深入探索技术与商业业务的深度融合路径，构建适配各垂直商业场景的智能模型及系统架构。同时，着力解决技术落地过程中的效率优化、场景适配、合规管控等关键问题，助力业务规模增长、运营效能提升与用户体验优化，推动商业场景数字化、智能化转型进程。\n\n课题挑战：\n1、技术适配性：通用LLM与MLLM在垂直商业交易场景存在领域知识薄弱、工具调用不足、语义对齐偏差等问题，需突破多模态协同、时空建模、低标注学习及搜广推融合技术；\n2、效率与性能：大模型时延高、耗算力、吞吐低，难以满足高并发低延迟交易与搜广推需求，需通过轻量化、量化、分布式推理等优化性能与成本；\n3、决策与规划：复杂商业决策对长周期建模、多目标优化、自适应要求高，AIGC与Agent易产生幻觉、决策偏差与因果缺失，需强化可信推理与风险约束；\n4、落地与合规：需解决系统集成、数据质量、内容可控、隐私安全与监管合规问题，保障大模型规模化稳定、安全、合规落地。\n\n课题价值：\n1、理论价值：探索大模型在多商业场景的Scaling Law可行性，完善推荐大模型、Agent决策、多模态融合等技术体系，丰富AI在商业领域的应用理论；\n2、实践价值：破解各商业场景核心痛点，如提升推荐转化、广告ROI、内容生产效率、客服质量等；降低人工成本，实现商业流程自动化；推动搜广推、电商、广告等领域的技术范式革新，支撑业务规模化增长，同时优化用户体验与商家服务能力，构建可持续的商业生态。","requirements":"1、2027届毕业，获得博士学位，计算机、软件工程、人工智能等相关专业优先；\n2、计算机基础知识扎实，对操作系统、数据库、网络基础知识充分掌握，熟悉常见的服务端技术组件，对常见的服务端场景有架构设计和优化思路；\n3、编码能力优秀，对代码质量与代码风格有高标准要求，对所熟悉的编程语言（Golang、Python优先）有一定的深入了解；\n4、有Agent系统开发经验，对Memory/RAG/MCP/SFT/RL/评测等Agent生态中的一项或多项技术有深入理解；\n5、对AI应用/LLMOps/AgentOps方向有浓厚兴趣和热情，自驱力强，对新事物的学习与探索能力强，具备出色的问题分析与解决能力；\n6、良好的沟通协作能力，能和团队一起探索新技术，推进技术进步。\n\n加分项：\n1、熟悉LLM、NLP、CV相关的算法和技术，熟悉大模型训练、Diffusion、RL算法者优先；\n2、有以下某一方向领域的经验：CUDA，RDMA，AI Infrastructure，HW/SW Co-Design，High Performance Computing，ML Hardware Architecture（GPU、Accelerators、Networking），ML for System，Distributed Storage。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594783232512969013","sourceKey":"bytedance","company":"字节跳动","title":"智能视频云国际产品实习生-音视频技术","city":"深圳","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594783232512969013/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责音视频相关的产品功能及体验的设计和优化；\n2、参与市场趋势、用户需求、音视频及AI技术发展的调研工作，收集和整理相关信息，挖掘产品优化点，为产品决策规划提供支持；\n3、完成需求分析、产品设计工作，确保功能与体验符合市场需求，并具有竞争力的领先性；\n4、协助制定项目计划，跟踪项目进度，参与跨部门沟通协调工作，协助推进项目高效迭代。","requirements":"1、2027届本科及以上学历在读，计算机科学、数字媒体技术、人工智能、软件工程、产品设计等相关专业优先；\n2、有互联网及音视频产品、运营实习经验优先，对音视频、大语言模型、计算机视觉等前沿技术及其应用有强烈兴趣和一定的认知；\n3、具备良好的产品思维、逻辑思维能力、判断力；\n4、具有出色的目标拆分能力，能够保持高效的执行力及工作节奏，能够快速完成复杂业务逻辑的梳理与落地；\n5、英语可作为工作语言，具备良好的沟通能力和团队合作精神，能够积极融入多元背景团队，配合完成各项工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7591392868318251317","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-中国交易与广告","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7591392868318251317/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与系统架构设计、优化，提升系统性能和开发效率，保证高并发高可靠；\n2、通过不断的技术研究和创新，推动业务的快速发展和高效迭代；\n3、善于从工作中抽象和归纳问题，用技术方案高效解决。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟练掌握算法、数据结构等基础知识；\n3、至少熟练使用一门编程语言（C/C++/Python/Go等)；\n4、积极乐观，责任心强，工作认真细致，具有良好的团队沟通与协作能力；\n5、热爱编程，有较强的学习能力，有强烈的求知欲、好奇心和进取心 ，能及时关注和学习业界最新技术；\n6、每周可实习4天及以上，可实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680933977968216373","sourceKey":"bytedance","company":"字节跳动","title":"内容安全研判运营（葡萄牙语方向） - TikTok","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680933977968216373/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、解读社区规范及平台政策，转化为可执行的研判口径，搭建案例库并保障不同场景下判定一致性；\n2、监测平台UGC、PGC内容生态，主动识别显性及隐晦、擦边类内容风险，提炼风险特征规律；\n3、处理突发内容安全风险事件，快速定界、排序优先级，推动跨部门协作完成处置闭环并复盘优化；\n4、输出风险研判报告，为平台规则、内容质量把控策略优化提供决策支撑；\n5、熟练使用内容质量把控工具、舆情监测系统及数据分析工具，协同运营和产品团队落地风险防控策略。","requirements":"1、2027届获得本科及以上学历，新闻传播、社会学等相关专业优先；\n2、英语和葡萄牙语沟通流利；有互联网内容运营、内容审核或内容安全相关工作经验，具备国内主流内容平台从业经验者优先；\n3、具备敏锐的内容安全意识和网感，能精准识别隐晦风险，有政策理解与规则落地能力；思维灵活，责任心强，具备良好的跨部门沟通协调能力及应急处置能力；学习能力强、理解能力强，能快速适配政策与平台内容生态变化；\n4、具备较强的规律总结能力，熟练掌握内容审核、舆情监测及Excel等常用工具。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673723745315408181","sourceKey":"bytedance","company":"字节跳动","title":"豆包搜索开发实习生 - 抖音研发","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673723745315408181/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与豆包、搜索工具后端系统的设计、开发与维护，涵盖综合搜索、垂类搜索（医疗、金融、法律、电商、生活服务等）、结构化数据与如意卡片等核心链路；\n2、参与搜索数据系统开发，支持垂类数据的接入、清洗、标准化、建库与质量验真；\n3、配合算法团队完成自动评估、负面案例归因、历史回放等工程能力建设，提升搜索效果迭代效率。","requirements":"1、本科及以上学历在读，计算机、软件工程、人工智能或相关专业；\n2、计算机基础扎实，熟悉数据结构、算法、操作系统和计算机网络；\n3、熟练掌握Go、C++、Java、Python中至少一门编程语言，具备良好的编码习惯；\n4、理解LLM/Agent的原理，具备较强的问题分析能力、学习主动性与沟通协作能力，做事认真细致；\n5、每周可实习4天，可连续实习3个月。\n\n加分项\n1、有搜索引擎、推荐系统、RAG、大模型应用或知识库相关项目经验；\n2、了解分布式系统，有高并发服务、存储系统或数据处理项目经验；\n3、有后端研发实习、开源项目贡献、技术竞赛或高质量个人项目经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671123264605915445","sourceKey":"bytedance","company":"字节跳动","title":"产品营销项目实习生（全球商业解决方案-亚太区-行业运营） - Global Business Solutions","city":"上海","category":"营销策划","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671123264605915445/detail","duty":"团队介绍：Global Business Solutions (GBS) 负责TikTok为主的全球产品商业化相关工作，为全球品牌和广告商提供集成的数字营销解决方案。具体包括各区域销售、销售运营、渠道管理、商业化战略、To B市场营销、营销科学、商业化合作和商业内容安全等职能。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、定期向团队提供区域、国家的产品数据洞察，并将数据报告与产品优先级相结合；\n2、设计和实施数据报告看板及相关数据管道，以提供数据洞察并优化内部团队的工作流程，与数据工程师和数据产品经理合作，落实用户需求并确保数据的准确性和可用性；\n3、直接与产品营销经理合作，评估“待解决问题”对我们业务的潜在影响规模；\n4、研究各种业务流程，发现瓶颈并提出改进建议，探索创新方法来监控我们的流程，以便轻松识别低效环节。","requirements":"1、本科及以上学历在读，市场营销、广告、数据分析、产品、商业分析等相关专业优先；\n2、能够进行严谨的分析，并向技术和非技术受众清晰传达结论；\n3、每周可实习5天，实习周期不少于6个月；\n4、熟练使用Excel、Tableau或类似数据可视化工具者优先；\n5、适应不断变化和快速增长的工作环境，对媒体和/或广告行业充满热情；\n6、精通日语和英语，可直接与日本及区域内利益相关者沟通，处理日本市场产品运营相关工作。\n\n加分项：\n1、有数据分析相关经验，熟练掌握SQL；\n2、具备跨部门协作经验，有较强的沟通协调和推动能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669691022977845557","sourceKey":"bytedance","company":"字节跳动","title":"AI学习能力产品运营 - 商业化","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669691022977845557/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、职责：\n1）参与建设巨量学AI营销经营能力提升产品建设，把营销经营知识、优秀经验和产品能力转成可在AI调用、训练和评测的解决方案（Skill、AI Buddy等），包括：需要参与调研内外部真实工作场景，拆解出任务、能力要求、输入输出和成功标准；\n2）协助培训专家设计知识单元、任务模板、提示词、Skill与AI Buddy原型；\n3）建设评测样本、评分标准、案例库等，并参与真实用户试点，分析任务质量、耗时和反馈数据，与培训专家、产品、研发共同迭代；\n4）沉淀场景说明书、产品需求文档、评测报告和复制SOP，并于从学习产品专家提供学习解决方案；\n2、要求：\n1）有大模型、知识库、工作流或Agent项目实作优先；\n2）具备结构化分析、用户研究和数据意识；\n3）能独立完成原型并用证据说明效果。","requirements":"1、2027届获得本科及以上学历，学习发展、人力资源、教育学、市场营销、心理学等相关专业优先；\n2、有培训项目等相关实习或实践经历者优先，关注广告和销售行业者加分；\n3、具备较强的学习能力与逻辑思维，能够通过数据等方式分析问题、提出思路；\n4、乐于创新与持续学习，愿意主动探索外部信息与行业实践，有AI应用能力者优先；\n5、乐观、开放、高能量，善于沟通协作，愿意接受挑战与变化，能在复杂环境中主动推进事情落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668344961570310453","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发工程师 - Seed 产品研发","city":"杭州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668344961570310453/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、负责APP的全栈开发（Android/iOS/Harmony/服务端）；\n2、负责APP基础架构和研发效率体系建设；\n3、负责AI在移动端的应用场景研发；\n4、参与AI Coding体系搭建，系统性提效。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的数据结构和算法基础；精通至少一门编程语言，包括但不限于：Java、Kotlin、Objective-C、Swift、ArkTs、Rust、C++；\n3、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n4、对AI技术有浓厚兴趣，持续提升AI认知，有AI Coding/Agent实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667476318612048181","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - 抖音研发","city":"广州/深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667476318612048181/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、构建高效、可靠的AI Agent，精准理解产品的复杂需求，实现自规划、任务拆解及执行；\n2、设计高效的Multi-Agent系统，确保多Agent间任务流转高效，上下文管理准确；\n3、实现AI支撑企业级、大用户规模C端产品的需求端到端生成；\n4、负责研发基于LLM的AI Agent系统，负责构建工程研发不同阶段的Agent；\n5、参与探索Multi-Agent协作机制，推动Multi-Agent系统对复杂任务的规划和拆解，对已有人类经验的学习和引用，不断优化Agent解决实际问题的路径和效果。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的计算机、编程基础，熟悉主流大语言模型的原理及方法；\n3、理解Multi-Agent系统、任务分解、自动化规划、Prompt Engineering等技术领域之一或多个，有AI Agent相关实践项目者优先；\n4、出色的结构化表达能力，较强的技术敏感度与前瞻性，独立的思考和判断力；热爱AI相关技术，对应用和落地工程感兴趣，富有钻研创新精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667140283127548213","sourceKey":"bytedance","company":"字节跳动","title":"云安全工程师 - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667140283127548213/detail","duty":"团队介绍：我们团队研发尖端云安全解决方案，为字节跳动及企业客户提供规模化安全防护。\n依托安全部门深厚的技术积累，以及对客户安全需求的深刻理解，我们借助领先技术与产品，通过全方位智能防御体系应对各类实际安全挑战。\n我们的工作确保云环境始终安全、可靠，为整个组织的创新实践提供有力支撑。\n\n1、参与云平台网络隔离策略设计与实施，保障多租户环境安全隔离；\n2、跟踪AIGC安全风险（如LLM对抗攻击、数据泄露防护、智能体安全），探索并落地防御方案；\n3、协助构建AI云原生应用安全防护体系（LLM/MCP/Agent）；\n4、参与安全风险评估、安全培训和漏洞评估，以主动识别和解决安全风险；\n5、与跨职能团队合作，将安全能力集成到云产品和底层基础设施中。","requirements":"1、2027届获得本科及以上学历，信息安全等相关专业优先；\n2、对云安全或AI安全领域有强烈探索欲，能通过技术博客/论文等快速掌握新知识；\n3、理解传统网络安全攻防基础（如DDoS/Web攻击/容器安全攻防等原理）；\n4、了解云计算核心概念（虚拟化/微服务/K8s/容器等）；\n5、掌握Python/Golang/Java任一语言，具备简单工具开发能力；\n6、具备系统性分析思维，能独立拆解复杂技术问题。\n\n加分项：\n1、拥有云安全相关实习经历；\n2、参与过CTF竞赛/漏洞挖掘（提交CVE或平台致谢证明）；\n3、发表过AI安全、云安全相关论文/专利；\n4、在GitHub有高质量安全项目（如安全工具开发、复现分析）；\n5、熟悉大模型安全风险（提示注入/模型窃取等）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7603657615755823365","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-抖音平台产品","city":"杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7603657615755823365/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：平台产品基础部门致力于为抖音各业务提供全面支持，平台业务负责搭建与维护基础平台，保障账号核心资产的管理。开放业务合理开放产品能力与数据，连接外部优质资源。文娱业务聚焦短剧 & 营收和宣发，形成健康内容生态。生态与运营业务推进作者成长、变现等工作。治理与体验业务为各垂直方向提供诊断等工具，提升问题解决率。营销搭建业务助力业务营销推广。部门为实现业务目标、满足用户需求而不断努力。\n\n1、参与系统架构设计、优化，提升系统性能和开发效率，保证高并发高可靠；\n2、通过不断的技术研究和创新，推动业务的快速发展和高效迭代；\n3、善于从工作中抽象和归纳问题，用技术方案高效解决。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具有扎实的编程能力，有优秀的设计和代码质量；\n3、深刻理解计算机原理，有良好的数据结构和算法基础；\n4、熟悉MySQL、Redis、消息队列等常用Web组件；\n5、积极乐观，责任心强，工作认真细致，具有良好的团队沟通和协作能力；\n6、每周可实习4天以上，可实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7595625227373152565","sourceKey":"bytedance","company":"字节跳动","title":"NLP自然语言处理实习生-抖音","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7595625227373152565/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音内容理解、内容安全、内容生态、对话Bot等场景的NLP应用算法落地；\n2、NLP相关新技术的跟进和研究，探索大模型等技术的潜在发展方向和应用；\n3、结合算法模型的业务流程建设和代码框架研发工作。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟悉常用的NLP、机器学习相关技术；对文本分类、实体识别、语言模型、意图识别等常用技术，并有相关实践经验；熟悉大语言模型相关技术，有LLM相关开发和应用落地经验者优先；\n3、有较扎实的代码编程能力，熟练掌握C/C++/Python；\n4、熟悉PyTorch等开源深度学习框架；\n5、有高水平论文者、相关实习经验者优先，包括但不限于ACL、EMNLP、NIPS、AAAI等；\n6、每周可实习4天以上，实习时间3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7591388908170398005","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发实习生-中国交易与广告","city":"上海","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7591388908170398005/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、负责电商业务相关产品迭代改进及移动新产品的开发；\n2、参与APP性能、数据基建、体验优化及质量监控评估体系建设； \n3、参与客户端基础组件及架构设计，推进研发效率；\n4、参与鸿蒙新技术开发，Lynx、KMP等跨平台&动态化技术开发。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n3、扎实的数据结构和算法基础，熟练掌握至少一门编程语言（包括但不限于：Java、Kotlin、Objective-C、Swift、C、C++、JS、Python）；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、对新技术保持热情，具备良好的分析、解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668482841099258117","sourceKey":"bytedance","company":"字节跳动","title":"开放平台AI产品运营 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668482841099258117/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、深度调研欧美、东南亚、中国等各国电商市场，梳理各国商家、电商相关ISV生态，定性和定量分析主要生态角色，深入挖掘商家、ISV等的需求；\n2、基于市场调研，结合国际化电商的业务和产品策略，以优化用户体验、促进商家/达人的业务增长为目标，规划各市场的开放生态，包括：业务架构，产品架构，运营计划；\n3、负责和参与重点商家产品解决方案的制定，推进解决方案的落地；\n4、制定和管理开放平台的政策、规则、版本发布等；能够有计划地推进商家以及第三方的对接和升级；根据各国信息安全相关法律，结合国际化电商的业务和产品策略，参与设计开放平台在各国的业务和产品适配，推动相关服务商进行适配工作。","requirements":"1、2027届获得本科及以上学历，数学、统计学、经济学、运筹学、计算机、营销相关专业优先；\n2、具备数据分析能力，能够以数据驱动进行产品需求发现、改进和完善；\n3、优秀的逻辑思维能力、沟通能力和自我驱动能力；\n4、优秀的组织和协作能力，自驱力强，结果导向，为结果负责。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7681123223581182261","sourceKey":"bytedance","company":"字节跳动","title":"物流战略实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7681123223581182261/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责通过案头研究、专家访谈等方式进行日常的行业研究、市场扫描、客户需求分析；\n2、负责内外部数据处理，整理发现结论和报告整理。","requirements":"1、本科及以上学历在读；\n2、英语熟练，掌握葡萄牙语者优先；\n3、一周出勤3天以上，实习4个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668288515009169717","sourceKey":"bytedance","company":"字节跳动","title":"产品运营经理 - 抖音品牌营销与星图达人","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668288515009169717/detail","duty":"团队介绍：品牌营销与星图达人为抖音、今日头条等全产品矩阵提供一体化品牌与达人营销解决方案，助力品牌实现精准触达与高效增长。依托行业领先的达人匹配算法、全链路数据洞察能力及创新的品牌营销产品和样式，我们打破内容与商业的壁垒，让品牌营销更具创意、更显精准、更有温度。\n在这里，你将深度参与全球领先的达人营销生态建设，接触行业前沿的AI与营销产品结合、创新的品牌营销策略。你将与顶尖团队并肩，在品牌广告与达人营销的创新浪潮中，不断探索品牌营销的新可能，在数字营销领域快速成长。\n\n1、负责巨量云图、AiMars产品价值传递与场景化落地深入理解产品能力与客户营销场景，提炼核心价值与应用路径，沉淀产品说明、操作手册、最佳实践案例、场景化解决方案等内容资产，并推动重点能力对内外部及时触达；\n2、负责用户全生命周期运营与分层运营策略设计面向内部行业团队推动试用推广、培训赋能与反馈收集；面向外部客户，根据腰部、自助等不同客群特征，设计分层运营策略，提升用户活跃、粘性与产品采纳率；\n3、建立产品使用数据监测体系，推动数据驱动的产品迭代持续跟踪活跃率、采纳率、adopted value、NPS等核心指标，识别用户需求与使用痛点，定期输出分析报告与优化建议，联动产品、研发形成“反馈—迭代—验证”闭环；\n4、负责重点产品及专项项目运营围绕全域度量、品牌形象度量、转化路径度量、“巨量云图极速版”等重点产品，从客户营销场景出发定位产品价值，推动产品推广、客户转化、行业标杆案例与方法论沉淀；\n5、开展生态内容运营及日常运营支持联动内外部资源推进案例共创、行业活动、生态合作等项目，扩大产品影响力；同时承接数据关系维护、电商、巨量星图绑定、账号纠偏、产品异常响应等日常运营工作，保障业务稳定运行。","requirements":"1、2027届获得本科及以上学历，市场营销、广告、数据分析、产品、商业分析等相关专业优先；\n2、具备产品运营、客户运营、营销运营或商业化运营相关经验，有MarTech、广告营销、数据产品、SaaS平台或B端产品运营经验者优先；\n3、具备较强的客户营销理解能力，能够将产品能力转化为客户可感知的业务价值；\n4、具备良好的产品价值包装与内容沉淀能力，能独立产出产品说明、最佳实践案例、OnePage、解决方案等内容材料；\n5、具备数据分析意识和指标化运营能力，能围绕活跃率、采纳率、Adopted Value、NPS等指标建立监测与分析机制；\n6、具备较强的项目推进与跨团队协同能力，能协调产品、研发、市场、销售等多方资源高效落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668225095961938229","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 飞书 Aily & 妙搭","city":"北京/杭州","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668225095961938229/detail","duty":"团队介绍：飞书一方/官方 Agent开发团队，致力于探Agent在办公、开发等企业生产力场景的应用，目前有Aily、妙搭等AI-Native的产品，覆盖个人提效、团队协作提效、业务提效等场景。 在交付AI-Native产品的同时，我们也致力于打造AI-Native的团队，日常工作中深度拥抱AI，探索更高效的办公模式。\n\n1、参与AI产品的规划与设计：参与AILY或妙搭产品的需求分析与产品设计，将大模型、Agent、知识库、工作流、工具调用等AI能力转化为清晰、可信、可控的产品体验；\n2、参与AI Coding产品的功能迭代与体验优化，探索如何让普通用户也能通过自然语言对话快速搭建高质量的企业应用，覆盖灵感模式、应用模式到专业模式的全链路体验；\n3、参与智能伙伴的产品设计与迭代，围绕信息检索、文档生成、数据分析、办公自动化等场景，持续优化用户的使用效率、结果质量和信任感；\n4、持续跟踪产品效果与模型表现，结合用户反馈、业务数据和用户行为洞察，驱动AI能力与产品体验的双向优化；\n5、关注AI Agent、AI Coding、企业协作、开发者工具等方向的前沿趋势，主动发现有价值的产品机会；\n6、与产品、研发、算法、设计等团队紧密协作，推动方案在真实业务场景中落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、信息管理等相关专业优先；\n2、对大模型、AI Agent、AI Coding等方向有浓厚兴趣，愿意主动探索对话、生成、配置、编排、自动化、人机协作等新型交互范式；\n3、具备良好的逻辑分析能力和产品意识，能从用户需求和业务场景出发思考问题，不仅关注界面细节；\n4、能够通过数据分析发现问题，制定解决方案，有数据分析或用户研究相关经验者优先；\n5、学习能力强，能快速跟进AI工具、Agent产品和开发者工具的发展，并主动应用到工作中；\n6、具备良好的沟通表达能力和团队合作精神，能在跨团队协作中高效推进工作。\n\n加分项\n1、有AI Agent、AI Coding相关的产品或开发经验；\n2、有从0到1参与产品设计或项目落地的经历；\n3、有开源项目贡献、技术博客、产品分析文章等可展示的作品。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668208806895356213","sourceKey":"bytedance","company":"字节跳动","title":"女装行业运营 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668208806895356213/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合抖音内容特性，制定女装行业在抖音产品内的完整运营策略，根据女装行业的特性、发展阶段及竞争趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、深度理解行业细分市场，负责品类业务规划及商家分层运营，推动品类增长，有较强的好奇心和快速学习能力；\n3、了解抖音的短视频和直播流量规律，关注内容电商的玩法；\n4、分析业务数据，归纳问题并落实解决方案，挖掘标杆案例/方法论；\n5、跨部门协同推进项目，整合资源实现业务目标。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，有行业运营、类目运营、商品运营等实习经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有较好的团队合作精神和协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667579681265535285","sourceKey":"bytedance","company":"字节跳动","title":"AI技术支持工程师 - 数据平台","city":"上海/杭州","category":"运维","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667579681265535285/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、负责客户对接过程中技术问题的分析定位和排查，协助客户顺利完成产品的集成开发上线；\n2、处理客户的技术反馈，能进行代码查阅、分析解决问题，给予客户及时响应，提升客户满意度；\n3、归纳和总结常见技术问题，输出可读性强的规范化技术文档；\n4、梳理客户技术需求并反馈，促进数据产品迭代优化；\n5、编写相关产品问题和技术支持分析的报告，定期整理和归纳常见问题，进行技术相关培训。","requirements":"1、2027届获得本科及以上学历，计算机、数学等相关专业优先；\n2、掌握以下至少一个方向：\n1）工程应用开发，熟练使用至少一种编程语言，如Java、Go、Scala、Python；\n2）移动端工程应用开发，客户端Android、iOS开发经验；\n3）大数据生态环境，了解hadoop、Spark、Flink、Hive、kafka等大数据技术，具有OLAP引擎（ClickHouse、starRocks等）经验是加分项；\n3、较强的分析问题能力和逻辑思维能力，具备Debug能力和Troubleshooting经验，以解决问题为导向；\n4、愿意接受挑战、愿意解决综合性强的问题，具备多线程工作能力，关注行业的前瞻性发展；\n5、积极乐观、责任心强、认真细致，具备良好的沟通能力和团队协作能力，有主动的服务意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665585547041802549","sourceKey":"bytedance","company":"字节跳动","title":"用户钱包产品经理 - 国际支付","city":"上海/深圳","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665585547041802549/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、参与国际支付用户钱包服务建设，在全球多个国家构建合规、易用、有吸引力的数字钱包产品，扩展数字钱包的应用场景，实现钱包业务的用户和交易量增长，推动支付普惠；\n2、辅助钱包业务的经营分析，关注行业发展动态，识别数字钱包业务增长机会点，设计并落地钱包应用场景和基础能力的建设；\n3、与上下游跨团队协作，完成钱包业务相关的解决方案文档撰写、体验设计、系统设计和方案落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、电子、大数据等专业优先；\n2、具备互联网支付金融行业实习经验者优先；\n3、关注用户体验，对用户需求具备敏锐洞察；\n4、具备较强的逻辑能力和抽象思维，对数据敏感，具备从多个视角考虑问题的习惯；\n5、主动性强，具备良好的沟通协作能力、责任心；\n6、能够熟练使用英语进行口头和书面沟通。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628896759561193781","sourceKey":"bytedance","company":"字节跳动","title":"【实习】广告场景下的生成式搜广推大模型技术研究-Ads Core（北京/上海）","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628896759561193781/detail","duty":"团队介绍：广告核心团队在不同的广告投放阶段建立关键的变现机制\n1. 我们建立排序、出价、预算、样式、诊断和其他框架，作为中台，使其他广告团队能够并行迭代他们的产品。\n2. 我们实施流量策略，在用户体验的约束下实现收入最大化，实现广告主受众的完全探索。\n3. 我们的模型驱动自动化解决方案从头到尾优化广告投放性能。\n\n课题介绍：本课题深耕TikTok全球化广告核心场景，聚焦生成式搜广推前沿技术创新与落地，深度融合大模型与广告业务，攻坚推荐大模型（Large Recommender Model）、大语言模型（LLM）领域的核心技术难题，打造具备自主决策能力的下一代智能广告引擎。\n我们布局推荐大模型Scaling Law、端到端统一建模、基于多模态Semantic ID的用户行为序列统一建模、生成式全链路技术（生成式召回、生成式排序、AIGC素材生成、生成式出价）、广告投放智能Agent、超长序列建模、因果推断等前沿方向，应对千亿级特征、毫秒级响应的极致挑战，推动广告推荐向 Foundation Model 范式演进，实现变现效率与用户体验的双向跃升。\n\n课题挑战：\n1、探索推荐广告大模型Scaling Law，构建多模态语义统一建模的基础模型；\n2、构建面向用户长期价值（LTV）和长周期ROAS的智能广告投放系统，实现商业价值与用户体验的双向平衡了；\n3、优化大模型全流程训练与在线推理框架，平衡算力成本与实时响应性能，破解效果-延迟的落地瓶颈。\n\n课题价值：\n突破原有技术瓶颈，推动广告系统从“匹配”向“生成与推理”范式升级，提升全链路ROI、泛化性与决策智能化，沉淀行业领先技术壁垒，提升用户体验和商业价值。","requirements":"1、2027届及以后毕业，博士在读：Computer Science, Statistics, Operation Research, Applied Mathematics, Physics or similar quantitative fields；\n2、在LLM/生成式/RL等方向有研究经验优先，在推荐/广告场景有相关迭代经验的同学加分；\n3、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，ACM获奖者优先；\n4、在国际会议或期刊发表论文者（包括但不限于ACL、EMNLP、NeurIPS、ICML、ICLR、CVPR等）优先；\n5、扎实的机器学习基础，熟悉TensorFlow/PyTorch/MXNet相关框架，有顶会发表优先；\n6、对技术有热情，有出现的问题发现/分析/解决能力，有自主探究能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7496386717864577288","sourceKey":"bytedance","company":"字节跳动","title":"音频算法实习生-视频与边缘","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7496386717864577288/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责流媒体场景（RTC、点播、直播等）音频编解码压缩需求和功能开发维护；\n2、针对流媒体场景（RTC、点播、直播等）特点研发音频编码算法，提升音频体验，降低成本；\n3、负责撰写技术方案、专利申请、论文发表和算法集成落地等开发工作。","requirements":"1、博士学位在读，计算机、人工智能、信号处理、模式识别或者电子相关等专业优先；\n2、具备出色的Python/C/C++编程能力，并有实际算法开发经验；\n3、具备较强的主观能动性、团队协作和创新能力，优秀的分析、解决问题能力，对解决挑战性问题充满激情；\n4、具备丰富Pytorch框架模型开发经验，包括但不限于AI Codec（Soundstream/Dac/Vocos等）、TTS、VAE、Vocoder、模型轻量化或者知识蒸馏等，发表过音频顶会（AES/ICASSP/Interspeech等）论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7470894524367522066","sourceKey":"bytedance","company":"字节跳动","title":"语言学实习生-Data语音","city":"北京","category":"产品运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7470894524367522066/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：Data语音团队致力于语音/音频/音乐相关的AI核心技术研发和产品创新。部门支撑音频和多模态内容从生产、编辑到消费的全流程，赋能内容创作和互动，并以中台形式支持集团多个业务，提供业界前沿的技术能力与解决方案。\n\n1、与算法团队一起搭建具有通用性和可拓展性的数据方案，跟进语音对话大语言模型训练过程中各阶段数据质量的评估；\n2、设计大模型评估方案，跟进语音对话大语言模型训练过程中各阶段模型效果的评估；\n3、制定产品和项目流程机制，协调项目各个角色高效工作；\n4、负责项目资源的协调与组织，并与项目各方进行良好沟通，确保项目团队各干系人协同工作。","requirements":"1、本科及以上学历在读，语音学、计算语言学、语用学、心理学、汉语言等相关专业优先；\n2、较强的分析和沟通能力，擅长从评估数据中发现有价值的产品改善建议，并能推动落地；\n3、有大语言模型任务设计和标注的科研或工作经历者优先，有语义学或语用学、语音学或音系学研究经历者/论文发表者优先；\n4、会基础编程/有深度学习经验/了解模型原理或评测方案者优先；\n5、熟练掌握至少1门小语种者优先；\n6、具备较强的逻辑思维，富有创新精神，解决问题能力强。\n\n加分项：\n1、具备配音相关经历、音频处理能力、文本创作或文本处理能力者优先；\n2、具备一定的听觉审美，对配音风格和语音合成效果有较好的感知能力；\n3、熟练使用Adobe Audition者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680412039055919413","sourceKey":"bytedance","company":"字节跳动","title":"IDC成本合约实习生 - DCE","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680412039055919413/detail","duty":"团队介绍：字节跳动基础设施DCE【Data Center Engineering】团队，负责字节跳动全球数据中心的技术支撑和CN自建&合建数据中心的建设交付。职责涵盖数据中心选址、规划设计、技术选型、交付管理、成本管理的全链条实现，同时从技术侧保障数据中心实现高可用、高可靠、高效率的稳定运行。致力于实现新一代数据中心技术可靠性与先进性双突破，同时推进高性价比、高可靠性数据中心园区建设。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助部门对自建数据中心项目变更进行测算及台账统计；\n2、协助部门编制自建数据中心项目产值计划、资金计划；\n3、协助部门对接造价咨询日常工作并做进度跟踪，配合计量、询价、招标采购、结算及转固工作；\n4、协助部门对自建数据中心项目甲供设备供应进行管理，包括下单、排产、发货、验收等；\n5、协助部门对自建数据中心项目供应商引入、交流、考察、履约等进行管理。","requirements":"1、本科及以上学历在读，工程造价、工程管理、土木、电气、暖通及相关专业优先；\n2、熟悉工程造价及工程采购的基本原理、方法和工具，对数据中心有基本的了解；\n3、能熟练应用各类办公软件及AI工具者优先，具备良好的数据整理及分析能力者优先；\n4、具备良好的自驱力与学习能力，优秀的沟通能力、组织协调与项目推动能力；英语可作为工作语言者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669458168032676101","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（AM运营方向） - TikTok Shop","city":"上海","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669458168032676101/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、参与电商运营场景下业务洞察工具的产品设计，围绕AI智能体、运营策略产品化、协同流程提效等方向，助力运营团队提升效率和业务效果；\n2、深入理解电商运营团队的工作场景，协助梳理用户需求、业务流程和产品目标，参与产品迭代规划与需求设计，与产品、技术、数据、测试等团队协作，推动产品方案从需求分析、方案设计到上线落地；\n3、关注产品使用数据和用户反馈，参与智能体效果评估、准确性抽检和产品优化，持续提升产品体验与业务价值。","requirements":"1、2027届获得本科及以上学历，专业不限，计算机、数据、商科、电子商务、管理科学等相关背景优先；\n2、对电商、商业化、AI产品、CRM或SaaS工具有浓厚兴趣，有相关实习、校园项目、竞赛或研究经历者优先；\n3、具备较强的学习能力和结构化思考能力，能够快速理解业务场景，并将复杂流程拆解为清晰的问题、角色和行动；\n4、目标感强，主动性高，乐于在环境中解决问题，具备良好的沟通表达和跨团队协作能力；\n5、具备基础的数据分析意识，能够通过数据和用户反馈发现问题、验证假设并推动优化。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668289574554110213","sourceKey":"bytedance","company":"字节跳动","title":"行政策略分析 - Corporate Services","city":"北京","category":"行政设施","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668289574554110213/detail","duty":"团队介绍：企业服务团队致力于为全球ByteDancer提供最佳的管理和员工体验，我们支持员工协同并高效地完成工作，同时保护和促进公司的业务发展。企业服务团队通过专业服务来改善ByteDancer的体验，同时建立并不断探索可广泛共享的新行业最佳实践。\n\n1、参与行政相关的政策、法规及行业动态研究，完成信息收集、分析和初步评估，识别项目推进中的关键问题与潜在挑战，并提出可参考的解决思路；\n2、参与政策、操作指南及相关项目的制定与优化，帮助业务更好地应对变化、推动创新实践，持续提升项目运行质量与效率；\n3、参与区域团队战略规划及实施方案的梳理与推进，协助推动重点政策和项目方案落地；在跨团队协作中，支持开展沟通、协调与合作，共同推动形成系统性、可持续的解决方案；\n4、协助开展项目数据的整理、分析与洞察输出，运用基础数据分析方法跟踪项目执行情况，支持搭建和完善监测评估机制，评估政策及相关举措的实施效果；\n5、支持与利益相关方、运营团队及管理团队的日常沟通，协助输出研究结论、项目建议与支持材料，协助识别和解决问题；\n6、参与项目全流程管理，包括前期策划、过程执行、阶段复盘与持续优化；在导师或团队指导下，支持变革与转型相关项目的推进、培训及落地。","requirements":"1、2027届获得本科及以上学历，专业不限；公共管理、行政管理、法学、政治学、社会学、经济学、管理学、统计学等相关专业优先；\n2、对政策研究、项目管理、公共事务、企业服务或组织运营方向有浓厚兴趣，愿意在实践中持续学习和成长；\n3、具备较好的信息搜集、逻辑分析与文字表达能力，能够基于已有资料进行整理、归纳并形成清晰结论；\n4、对数据有基本敏感度，具备基础数据分析能力或相关项目经历者优先；对AI工具的学习与应用有浓厚兴趣，有运用AI提升工作效率的意识或相关实践经验者优先；英文能作为工作语言；\n5、具备良好的沟通协作能力和责任意识，能够在多团队协作场景中主动推进事项、有效配合他人完成任务；\n6、做事细致认真，具备较强的学习能力、适应能力和执行力，面对复杂问题时愿意主动思考并寻找解决办法。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7660351459062483253","sourceKey":"bytedance","company":"字节跳动","title":"基于多模态大模型与用户行为理解的下一代分发与交互技术-抖音（北京/上海/杭州/深圳）","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7660351459062483253/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n课题介绍：\n本课题旨在探索基于多模态大模型的模态理解与表征、世界知识、推理等能力，并深度的与信息分发（推荐、搜索等）中的用户行为理解和建模结合起来，构建支撑下一代分发与交互技术的基础模型和系统范式。通过基础技术突破和探索，既尝试解决原有分发技术中对长尾兴趣分发、用户复杂意图理解、多模态与行为协同融合、System Bias、分发系统的算力与推理分配等一系列关键问题，也探索基于新的多模态大模型与用户对齐的理解，支持全新的可对话性需求满足、可自然交互性的分发调节与个性化等能力和产品形态上的突破。\n\n课题挑战：\n1、多模态大模型的完整流程的训练，以及与大规模用户行为深度理解和对齐；\n2、突破多模态大模型与长序列高并发高效推理的瓶颈；\n3、实现大模型泛化推理能力与复杂推荐业务目标的深度对齐。\n\n课题价值：\n1、打破信息茧房，提供个性化可解释推荐，提升长尾/冷启分发效率；\n2、沉淀大模型Scaling Up范式，重塑大模型时代的下一代推荐系统；\n3、探索全新的支持下一代交互场景的分发基础技术突破。","requirements":"1、2027届毕业，获得博士学位；人工智能、计算机、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练C/C++（传统编码方向）或Python（智能编码方向）；\n3、智能编码方向要求有扎实的机器学习基础，在TPAMI/CVPR/NeurIPS/ICCV等期刊会议上发表论文者优先；\n4、有向标准组织提出过提案并有标准会议经验的同学优先；\n5、出色的问题分析和解决能力，有自主探索解决方案的能力，良好的沟通协作能力，能和团队一起探索新技术，推进技术进步；\n6、出色的心理素质与应变能力，面对困难勇于迎接挑战；面对复杂局面沉着、冷静、灵活。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7603649728014354741","sourceKey":"bytedance","company":"字节跳动","title":"大模型测试开发实习生-抖音研发","city":"深圳","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7603649728014354741/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、深度参与大模型在质量保障方向的落地，解决当前大模型在落地过程中存在的各种问题；\n2、基于大语言模型（LLM）构建高效、可靠的Agent核心引擎，实现全流程智能化测试开发；\n3、通过对使用结果的数据深入分析，不断提升模型效果，提高使用体验；\n4、深入测试流程的需求和痛点，不断挖掘、改进模型及工具，提升质效；\n5、跟踪Agent领域前沿技术（如ReAct、AutoGPT、CrewAI等），推动技术落地与产品化。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、对大模型和算法方向有浓厚兴趣，熟悉至少一种AI应用开发框架（如LangChain等），熟悉Prompt工程、RAG、智能体（Agent）等理论；\n3、具备优秀的业务理解能力，出色的问题分解与解决能力，能将模糊需求转化成实际应用落地，逻辑思维灵活全面，良好的沟通协作能力；\n4、有扎实的计算机理论基础和代码编写能力，掌握至少一门编程语言，包括但不限于：Java/C/C++/Python/Go；\n5、能保证至少4个月及以上的实习，每周可出勤至少4天及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675270069605255477","sourceKey":"bytedance","company":"字节跳动","title":"数据科学实习生 - TikTok Shop","city":"北京/上海","category":"数据分析","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675270069605255477/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持国际化电商直播数据分析，深入理解电商业务，驱动业务科学决策，助力快速增长；\n2、基于对商家、达人、商品、直播的理解，通过科学的指标体系定义和探索性数据分析，准确描述业务现状，快速发现、定位各个业务与技术方向的问题与机会；\n3、将复杂问题进行拆解定义，根据业务需求完成专项分析与洞察；\n4、与协同团队紧密配合，支撑团队横向数据建设。","requirements":"1、本科及以上学历在读，数学、统计学、计算机、经济学等相关专业；\n2、过往有相关实习经验优先，熟练掌握SQL及相关数据库操作，有夯实的统计学基础，过往有AB实验经验优先；\n3、能实习3个月以上且保障一周至少4天onsite，5天全勤或可实习6个月以上优先；\n4、能够主动、独立思考，有良好的沟通协作能力，英文流利优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672804729569659141","sourceKey":"bytedance","company":"字节跳动","title":"生态合作商务（豆包方向）实习生 - 技术产业研究与合作","city":"北京","category":"商务拓展BD","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672804729569659141/detail","duty":"团队介绍：主要负责对外技术合作与产业研究，覆盖对外技术类战略合作全生命周期管理、全球前沿技术与产业趋势研究、跨部门技术合作项目协同推进。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、合作方对接支持：协助BD跟进合作方的日常沟通与需求承接；\n2、商务与协议流程推进：协助梳理不同合作方的费率、结算与商务条款诉求，跟踪双签协议，推动内部法务、财务、税务闭环；\n3、产品、技术接入协同：作为合作方与内部产品研发之间的桥梁，将合作方在接入环节的问题结构化记录并推动工单闭环；\n4、合作方问题库与知识沉淀：沉淀高频Q&A、卡点、决议与最佳实践，形成标准化的对外FAQ与内部知识库；\n5、协助组织相关会议，产出会议纪要并跟进后续落地情况，协助整理相关内容，撰写材料。","requirements":"1、本科及以上学历在读，经济、金融、市场营销、计算机、信息管理等专业优先；\n2、每周出勤4天及以上，可保证连续实习6个月及以上；\n3、有较强的结构化思维与文字功底，熟练使用飞书、Excel/Sheets、PPT/Keynote；\n4、沟通表达清晰、有服务意识，具备多方协同能力；\n5、责任心强、细节敏感，能够处理商务条款、协议、财务口径等对准确性要求较高的信息；对合作方信息有强保密意识；\n6、具备优良的应急响应能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669731730924177717","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法工程师 - TikTok内容安全算法","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669731730924177717/detail","duty":"团队介绍：国际化内容安全算法研究团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，团队同时负责产品基座大模型的研发，我们在研发过程中需要解决数据合规、模型推理能力、多语种性能优化等方面的问题，从而为平台上的内容审核、搜索、推荐等多项业务提供安全合规，性能优越的基座模型。\n\n1、负责直播安全算法体系的建设与演进，统筹规模化风险治理能力与高不确定性风险响应能力，打造AI原生、可持续演进的直播安全系统；\n2、推动多模态模型、大模型及前沿技术在解决长尾/复杂治理标准/高响应速度/样本不均衡等问题的最佳应用；\n3、探索前沿AI技术，包含但不限于AIGC、LLM、多模态内容理解（视频/图像/音频/文本）等，以构建下一代安全模型；\n4、突破现有安全治理系统的流程，探索下一代内容安全业务交互模式。","requirements":"1、2027届获得硕士及以上学位，计算机、电子等相关背景；\n2、有搜索、推荐、风控、审核或安全等算法系统建设经验，熟悉多模态模型、大模型或实时风险建模体系优先；\n3、具备在高不确定性环境下快速决策与落地能力；\n4、优秀的分析问题和解决问题的能力，并热衷于解决具有挑战性的问题；\n5、对技术充满热情，良好的沟通能力和团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669697357131286789","sourceKey":"bytedance","company":"字节跳动","title":"PUSH运营（策略运营方向） - 内容质量与数据服务平台","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669697357131286789/detail","duty":"团队介绍：抖音内容质量与数据服务平台（简称CQC）归属于抖音集团，负责今日头条、抖音等产品内容和抖音集团商业内容的安全质量与体验。平台下设内容质量中心、商业生态与安全、生态治理与增长支持等业务，在全国20余个城市均有分布。\n自成立以来，CQC持续守护抖音集团旗下包括抖音、今日头条、番茄小说、飞书、红果短剧等产品在内的安全、质量与体验，优化产品内创作与交流环境，且在各产品运营增长方面开展支持工作。\n\n1、基于抖音、今日头条等产品的个性化推荐需求，识别AI在Push内容质量把控场景下的提效机会点，负责技术方案开发、模型效果评测、抽样验收、数据复盘、持续优化性能，量化AI带来的收益；\n2、负责多模态大模型在短视频/图文/直播等场景的落地优化，基于图像、音频、文本、视频时序多维度能力，定位场景适配能力边界，推进内容质量管控业务AI智能化提效；\n3、深入Push业务全流程，运用模型和数据分析能力，结合阈值调优、场景分层、规则联动、样本回流等业务策略进行问题诊断，提高内容流转效率和处置质量；\n4、基于业务洞察，与运营、产品、推荐等团队构建高效协作机制，输出迭代需求与高质量样本，沉淀方法论，探索供给链路优化及收益突破。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能等相关专业优先；\n2、有模型运维、AI策略、视频多模态模型落地等实习经验优先，掌握SQL、Python能力，深入理解AI Agent原理，能够独立设计并优化Prompt策略形成工作流，有机审治理或内容质量把控提效相关实操经验优先；\n3、对内容质量把控场景的指标逻辑有一定了解，擅长案例分析、数据统计、问题聚类归因，逻辑清晰，能独立输出评测结论与优化策略；\n4、积极性强，具有自主学习和独立解决问题的能力，良好协作意识和沟通能力，能推动模型工具与业务深度融合；\n5、短视频平台用户，有一定网感和内容理解能力，对互联网内容安全和质量有基础认知。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667551275686594821","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - 抖音体验","city":"北京/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667551275686594821/detail","duty":"团队介绍：抖音用户体验团队成立于2018年，致力于发展业界独特技术栈，通过技术手段提升抖音及抖音系APP的用户体验，为业务发展提供技术支撑。我们在AI与各类基础技术领域的融合上具备远见与决心，曾开创个性化视频体验、个性化应用体验等多个业界全新的技术子领域和相关技术，在抖音等产品建立市场地位的过程中得到充分验证，并持续关注和探索前沿技术方向。团队交叉融合推荐类系统、因果推断、运筹求解、端智能、大模型训练、音视频、网络、编译器等多种不同的技术领域，并能够最直接、快速地推动新技术落地，带来显著业务价值。\n\n1、参与抖音体验团队AI Native研发工具建设，推动AI Native基建建设，协同产品、算法等团队提升用户体验；\n2、参与抖音体验团队基建Agent开发，负责需求开发中代码生成效果、全流程交付效果，参与Agent框架建设、编排调度、上下文工程建设、模型适配等，提升需求交付效率；\n3、参与评测、知识库、上下文管理等基础能力建设，对大模型应用效果进行持续调优，通过数据分析与策略改进，提升工具的性能和体验；\n4、跟踪AI技术趋势，思考AI研发新范式、AI新技术在研发提效中的落地场景，驱动产品创新。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、开发语言和技术栈不限，熟悉Golang/Python/TypeScript优先，并熟悉常见的软件开发模式；\n3、对AI应用方向有强烈的兴趣，熟悉Agent相关的常见范式架构，如Plan&Excute、ReAct、Workflow等，熟悉模型的工作原理和特性，并能结合原理和特性做稳定性、成本和效果优化优先；\n4、业务理解能力强，能够针对业务上的需求梳理业务边界并快速匹配最适合的Agent工作流范式；\n5、对行业流行的常见模型优缺点有大致的了解，并了解如何系统科学的评测帮助做模型选型；\n6、掌握模型原理优先，对常见的CNN、RNN、Transformer模型结构及推理架构有一定的了解优先，对模型的二次训练原理及方法了解优先，如SFT、LoRA-SFT、DPO等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667548798541531445","sourceKey":"bytedance","company":"字节跳动","title":"战略分析师 - 火山引擎","city":"北京","category":"商业运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667548798541531445/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责制定火山引擎在AI大模型领域的战略规划，包括大模型、AI应用、GPU基础设施等的AI全栈战略；\n2、追踪、分析全球大模型等领域的前沿技术趋势，研究全球顶尖的AI公司，思考、探索下一代AI产品形态与商业模式，推动业务创新；\n3、参与AI大模型相关业务的孵化与落地，支持业务落地中的行业和公司研究、目标与战略制定、产品长期演进路线讨论等；\n4、协助潜在的战略投资及生态合作项目，协调资源、推动开展外部战略合作和内部跨团队协同类项目。","requirements":"1、2027届获得硕士及以上学位，理工科/经济管理相关专业优先；\n2、对AI等新技术、新趋势有兴趣，希望在新领域探索和成长；\n3、自驱、学习能力强、较好的沟通和协作能力，具备良好的英文书面及口头表达能力；\n4、较强的逻辑思考、信息收集分析能力和认知挖掘能力，具有商业思维；\n5、在科技企业战略或投资部、咨询公司、VC/PE等有丰富的实习经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7663060794766084405","sourceKey":"bytedance","company":"字节跳动","title":"软硬件协同工程师 - AI算力基础设施","city":"北京/深圳/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7663060794766084405/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、研究和分析关键Workload（如AI、大数据、云计算、高性能计算等）的特征，探索对芯片设计的优化方案；\n2、评估和优化芯片软硬件协同设计，包括指令集优化、微架构改进、编译器/运行时优化等；\n3、搭建和使用性能模拟器、仿真工具进行实验，验证新架构方案的可行性和性能收益；\n4、参与ARM、RISC-V及其他开放架构生态的研究，探索开源硬软件协同优化的可能性；\n5、撰写研究报告，并有机会参与学术论文或专利的撰写。","requirements":"1、2027届获得硕士及以上学位，计算机体系结构、电子工程、计算机科学等相关专业；\n2、具备良好的编程能力，熟悉C/C++、Python；\n3、熟悉计算机体系结构基本知识，如流水线、缓存、分支预测、乱序执行等；\n4、了解RISC-V或其他主流CPU指令集，如X86、ARM，有相关优化经验者优先；\n5、熟悉CPU/GPU性能分析工具，如perf、VTune、Gem5、Simics等；\n6、具备良好的分析能力和研究能力，有学术论文发表经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7642222838862121269","sourceKey":"bytedance","company":"字节跳动","title":"算法实习生-中国交易与广告","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7642222838862121269/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、供给策略与算法建模：参与电商商品供给结构（如质量、潜力、生命周期）的分析与建模，协助探索大模型（LLM）与传统机器学习在多目标策略中的结合与落地；\n2、大模型与Agent探索：参与构建基于LLM的Multi-Agent辅助决策工具，协助优化Agent的Prompt、工具调用（Tool Use）及协同机制，探索策略自动生成的路径；\n3、大促预测与实验迭代：参与大促场景下销量、GMV等预测模型的训练与调优（基于XGBoost、DNN等常用模型），配合团队完成A/B实验的数据分析与效果评估。","requirements":"1、本科及以上学历在读，计算机、数学、统计学等相关专业；\n2、熟练使用Python、SQL进行数据处理和建模，掌握PyTorch、TensorFlow等常用深度学习框架；\n3、具备扎实的机器学习理论基础，了解主流的预训练模型（如Transformer架构）或常见的预测模型；\n4、具备LLM（微调/Agent）、多模态、强化学习或搜推方向实践经验，或有相关顶会论文/高水平竞赛经历者优先；\n5、在算法领域，主导过具有重要影响力的项目或发表过相关论文者优先；\n6、逻辑清晰，沟通表达能力较好，对前沿AI技术有强烈的好奇心，能够主动学习并具备良好的团队协作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7638936342751496501","sourceKey":"bytedance","company":"字节跳动","title":"AI大前端开发实习生 - 番茄小说/红果短剧/番茄畅听","city":"北京/上海","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7638936342751496501/detail","duty":"团队介绍：番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、负责业务的产品迭代改进及移动新产品的开发；\n2、深度使用AI Coding工具进行日常开发，提升代码开发效率与质量；\n3、关注AI Coding前沿技术和行业动态，贴合产品业务场景，探索AI工具在客户端多端开发场景的优化空间，提升团队效率。","requirements":"1、2027届本科及以上学历在读，计算机、通信和电子信息科学等相关专业优先；\n2、熟练使用至少一种AI Coding Tool（Claude Code、Cursor、Codex、Cline等），了解其现原理有加分；\n3、掌握至少一门编程语言（Golang、TypeScript、Swift、Kotlin、Python等）使用，掌握多门语言有加分；\n4、充满技术热情，有较强的自驱力和学习能力，有优质开源项目、博客的加分；\n5、有较强的学习意愿，有LLM、NLP、AIGC等技术经验的加分；\n6、每周出勤至少4天，可实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628897677983533365","sourceKey":"bytedance","company":"字节跳动","title":"【实习】广告场景下的生成式搜广推大模型技术研究-Ads Core（北京/上海）","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628897677983533365/detail","duty":"团队介绍：广告核心团队在不同的广告投放阶段建立关键的变现机制\n1. 我们建立排序、出价、预算、样式、诊断和其他框架，作为中台，使其他广告团队能够并行迭代他们的产品。\n2. 我们实施流量策略，在用户体验的约束下实现收入最大化，实现广告主受众的完全探索。\n3. 我们的模型驱动自动化解决方案从头到尾优化广告投放性能。\n\n课题介绍：本课题深耕TikTok全球化广告核心场景，聚焦生成式搜广推前沿技术创新与落地，深度融合大模型与广告业务，攻坚推荐大模型（Large Recommender Model）、大语言模型（LLM）领域的核心技术难题，打造具备自主决策能力的下一代智能广告引擎。\n我们布局推荐大模型Scaling Law、端到端统一建模、基于多模态Semantic ID的用户行为序列统一建模、生成式全链路技术（生成式召回、生成式排序、AIGC素材生成、生成式出价）、广告投放智能Agent、超长序列建模、因果推断等前沿方向，应对千亿级特征、毫秒级响应的极致挑战，推动广告推荐向 Foundation Model 范式演进，实现变现效率与用户体验的双向跃升。\n\n课题挑战：\n1、探索推荐广告大模型Scaling Law，构建多模态语义统一建模的基础模型；\n2、构建面向用户长期价值（LTV）和长周期ROAS的智能广告投放系统，实现商业价值与用户体验的双向平衡了；\n3、优化大模型全流程训练与在线推理框架，平衡算力成本与实时响应性能，破解效果-延迟的落地瓶颈。\n\n课题价值：\n突破原有技术瓶颈，推动广告系统从“匹配”向“生成与推理”范式升级，提升全链路ROI、泛化性与决策智能化，沉淀行业领先技术壁垒，提升用户体验和商业价值。","requirements":"1、2027届及以后毕业，博士在读：Computer Science, Statistics, Operation Research, Applied Mathematics, Physics or similar quantitative fields；\n2、在LLM/生成式/RL等方向有研究经验优先，在推荐/广告场景有相关迭代经验的同学加分；\n3、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，ACM获奖者优先；\n4、在国际会议或期刊发表论文者（包括但不限于ACL、EMNLP、NeurIPS、ICML、ICLR、CVPR等）优先；\n5、扎实的机器学习基础，熟悉TensorFlow/PyTorch/MXNet相关框架，有顶会发表优先；\n6、对技术有热情，有出现的问题发现/分析/解决能力，有自主探究能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7626645162544892165","sourceKey":"bytedance","company":"字节跳动","title":"AI异构计算优化工程师-Seed大模型人才校招","city":"上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7626645162544892165/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、评估：负责评估符合业务要求的异构计算芯片，建立/完善评估体系、负载模型，预估业务收益；\n2、推理：负责异构计算芯片落地实际推理业务，适配异构计算芯片特性，降低推理时延，提高推理吞吐；\n3、训练：负责异构计算芯片落地实际训练业务，根据芯片计算、通信特性，优化显存占用，提高训练吞吐；\n4、算子：负责开发异构计算芯片的高性能算子，根据芯片特性，优化算力、带宽利用率；\n5、编译：负责通过编译技术实现异构计算芯片在不同业务场景中落地，负责实现更加高效的异构硬件编程范式；\n6、调研：负责调研、验证前沿软硬件结合方向，比如稀疏计算（Sparse Computation）、存内计算（In-Memory Computing）、数据流计算（DataFlow）等。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程、人工智能、电子信息等相关专业；\n2、熟练掌握Linux环境下的C/C++、Python语言；\n3、具备扎实的计算机科学功底和编程能力，熟悉常见算法和数据结构，具有良好的编程习惯；\n4、能够熟练使用至少一种主流的机器学习框架（TensorFlow/PyTorch等），熟悉框架内部实现；\n5、熟悉至少一种经典深度学习模型及其应用场景，如GPT、SD、DiT、W&D等；\n6、熟悉至少一种并行计算架构，熟悉其编程模型，并知晓其优、劣所在。\n\n加分项：\n1、了解推理/训练/通信相关优化，有高性能算子、大规模训练、通算融合领域经验者优先；\n2、了解SIMD/SIMT外其他并行计算模型及算法，了解其并行编程模型及其优、缺点者优先；\n3、了解模型剪枝、量化、LLM投机采样等优化方法原理，具备相关模型优化经验者优先；\n4、了解常见AI编译器方案及其优、缺点（如XLA、TVM、MLIR），有实际开发经验者优先；\n5、了解GPU硬件架构，了解GPU软件栈（CUDA、cuBLAS、cuTLASS)，具备GPU性能分析的能力者优先；\n6、了解AI Compiler技术栈（MLIR等），熟悉Torch2.0+编译栈、Triton优先者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7626405832338557237","sourceKey":"bytedance","company":"字节跳动","title":"葡语短剧运营实习生-TikTok","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7626405832338557237/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、负责葡语短剧标题、剧情介绍、字幕的校对优化，修正语言错误与翻译偏差，确保表达地道贴合巴西文化；\n2、协助巴西地区TikTok短剧账号发布及日常运营，包括内容发布、话题标签配置、评论区互动，跟踪播放量、完播率、粉丝增长等核心数据；\n3、调研巴西TikTok用户偏好与流行趋势，结合本地文化为账号及短剧内容优化提供建议，提升传播力；\n4、整理短剧相关素材（字幕文件、单集视频、海报、宣传文案等），建立规范素材档案。","requirements":"1、本科及以上学历在读，葡萄牙语相关专业优先；\n2、熟悉平台操作，了解巴西地区用户内容偏好，具备一定的数据复盘能力，对国际化短剧有浓厚兴趣；\n3、严谨细心，具备良好沟通协调能力、执行力与学习意愿，能高效配合团队工作；\n4、英语可作为工作语言，一周可实习4-5天，实习期稳定3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7595626050760116533","sourceKey":"bytedance","company":"字节跳动","title":"NLP自然语言处理实习生-抖音","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7595626050760116533/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音内容理解、内容安全、内容生态、对话Bot等场景的NLP应用算法落地；\n2、NLP相关新技术的跟进和研究，探索大模型等技术的潜在发展方向和应用；\n3、结合算法模型的业务流程建设和代码框架研发工作。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟悉常用的NLP、机器学习相关技术；对文本分类、实体识别、语言模型、意图识别等常用技术，并有相关实践经验；熟悉大语言模型相关技术，有LLM相关开发和应用落地经验者优先；\n3、有较扎实的代码编程能力，熟练掌握C/C++/Python；\n4、熟悉PyTorch等开源深度学习框架；\n5、有高水平论文者、相关实习经验者优先，包括但不限于ACL、EMNLP、NIPS、AAAI等；\n6、每周可实习4天以上，实习时间3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7589612134234228997","sourceKey":"bytedance","company":"字节跳动","title":"AI算法实习生-风控","city":"深圳","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7589612134234228997/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：风控算法团队致力于解决各个产品（包括抖音、今日头条等）面临的各种黑灰产对抗问题，涵盖内容、交易、流量、账号等多个方面的风险治理领域。利用机器学习、多模态、大模型等技术对用户行为、内容进行理解，从而识别潜在的风险和问题。不断深入理解业务和用户行为，进行模型和算法创新，打造业界领先的风控算法体系。\n \n1、负责字节跳动各产品（包括抖音、今日头条等）各种作弊风险的发现与治理，包括内容、交易、流量、账号等方面的风险；\n2、通过指标监控归因，及时感知风险及业务的变化，主动识别潜在攻击，持续优化调整风控方案，并推动风控治理建设及业务模式调整； \n3、通过CV、NLP、大语言模型、多模态大模型、表征学习、图模型、深度学习、迁移学习、多任务学习等技术，提升问题发现的效率，从而快速阻断风险，优化平台的各项生态指标；\n4、挖掘和分析海量内容和用户行为进行用户长短期画像建设，提升模型的精准性和召回面； \n5、结合各场景业务（抖音短视频、电商、直播、生活服务、用户增长等）特性，进行模型和算法创新，打造业界领先的风控算法体系。","requirements":"1、2027届本科及以上学历在读，计算机、机器学习和模式识别相关专业者优先； \n2、热爱计算机科学和互联网技术，对人工智能类产品有浓厚兴趣； \n3、具备优秀的编码能力，熟悉Linux开发环境，熟悉C++和Python语言优先； \n4、有扎实的数据结构和算法功底，熟悉机器学习、自然语言处理、数据挖掘、分布式计算、计算机视觉、计算机图形中一项或多项；\n5、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7564347936323389701","sourceKey":"bytedance","company":"字节跳动","title":"安全开发实习生-TikTok Shop","city":"上海","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7564347936323389701/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战，还有出差外派机会在等你！\n\n1、参与SDLC与安全技术风险评估工作、安全体系的建设；\n2、参与安全自动化工具、平台的研发工作；\n3、参与安全合规事项的治理工作，推动电商内部具体整改措施落地与进展把控。","requirements":"1、本科及以上学历在读，计算机、信息安全等相关专业优先；\n2、具备Linux环境下开发能力，掌握Python/Shell/C/C++任一种语言；\n3、符合以下任意要求者优先：\n1）对Web安全有浓厚的兴趣和实践经验，熟悉OWASP Top10漏洞原理与防御技术；\n2）有Windows/Linux客户端安全攻防的经验，或了解Android/iOS移动安全；\n3）参加过CTF比赛，并在国家级比赛中获奖；\n4）对安全合规、安全管理工作有兴趣或者实习经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7409912809109473587","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-TikTok","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7409912809109473587/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责字节跳动TikTok亿级视频内容发现相关方面的工作，支持海内外客服平台，生活服务业等多个业务场景的建设；\n2、参与产品的完整生命周期，和TikTok团队一起推进产品的迭代，在技术、产品、运营效率、用户体验等方面创造价值；\n3、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n4、负责业务需求调研，撰写技术方案和系统设计；持续改善已有服务，优化系统薄弱点，提升系统性能和稳定性。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、掌握Golang或C++语言，有扎实的数据结构和算法功底；\n3、理解计算机原理、计算机网络，熟悉业内常用的基础组件；\n4、对技术有热情，既有高远目标，也能脚踏实地，责任心强、积极主动；\n5、喜欢研究开源新技术，开源贡献者、GitHub源码者、技术博客者优先；\n6、每周可以实习4天及以上，连续实习3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685308521659844917","sourceKey":"bytedance","company":"字节跳动","title":"数据分析实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685308521659844917/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责业务日常数据统计分析，针对异常情况协调资源进行跟踪和深入分析；\n2、协助分析师开展数据洞察、定性与定量分析工作，迅速定位内部问题或发现机会；\n3、协助分析师进行数据分析体系建设和完善，挖掘流量、产品、策略方面的业务机会；\n4、开展AI数据应用探索与落地，助力分析工作提效。","requirements":"1、本科及以上学历在读，计算机、统计、数学等相关专业优先；\n2、熟练使用SQL、Excel、Python等至少一种脚本语言，熟悉常用数据统计和分析方法；\n3、良好的沟通能力、团队合作精神和主动意识；\n4、良好的逻辑思维能力、业务解读能力和快速学习能力；\n5、对数字比较敏感，热爱数据分析工作；\n6、对AI应用感兴趣、有实践动手经历优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7681617025368459525","sourceKey":"bytedance","company":"字节跳动","title":"拉美达人运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7681617025368459525/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、达人全链路配置管理：负责整体达人入驻、发文及直播任务配置，以及其他额外触点配置，搭建并维护达人资源池，保障达人供给稳定性；\n2、内容质量与流量监测：负责日常、活动以及RS达人的视频流量监测和内容质量抽查，建立内容效果评估体系，保障平台内容生态健康；\n3、内容加热与达人分层运营：针对不同等级达人进行内容筛选，点对点加热提升好内容流量，通过达人分层管理策略，挖掘各层级达人的增长潜力；\n4、数据复盘与预算管控：开展每日/每周达人任务、活动表现数据复盘，进行产品实验数据监控、产品链路追踪，根据预算情况合理分配任务，为业务决策提供数据支撑；\n5、达人合规治理：负责达人封禁监测，落实平台治理规则，保障达人行为合规，维护平台生态秩序。","requirements":"1、本科及以上学历在读；\n2、每周可实习5天，需确保至少3-6个月线下实习时间，对电商、内容与达人生态有强烈兴趣，具备较好的跨团队协作能力与自驱力；\n3、具备较强的数据分析及提炼总结能力；可熟练使用Excel、SQL完成基础数据分析，具备良好的逻辑思维和结构化表达能力；\n4、有一定西语能力；\n5、有互联网电商平台达人运营、内容运营相关实习经验优先；熟悉TikTok Shop平台规则与达人运营玩法者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669681098100017461","sourceKey":"bytedance","company":"字节跳动","title":"测试开发工程师 - 业务中台","city":"北京","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669681098100017461/detail","duty":"团队介绍：团队负责公司多个跨产品业务方向，提供可复用的平台能力及技术解决方案。我们为公司多业务提供如地理位置、行业数据等多类型的中台能力与技术解决方案，积极利用AI等技术做中台能力提效与升级。\n加入我们，你将有机会从中台的多视角参与业务建设，感受不同类型/阶段的业务特点；通过用户场景的开发&架构工作，学习和解决极富挑战的技术问题；你也可以从数据出发，积极利用策略和模型，为业务提供有价值的助力。\n\n1、负责客户端、服务端及AI产品的质量保障，覆盖功能、性能、稳定性、资产损失、用户体验及模型效果等风险；\n2、深度参与需求全生命周期，从业务建模、风险识别、方案评审到上线监控和问题治理，推动高质量交付；\n3、针对模型、Prompt、Skills及Agent链路，建设评测标准、评测集、评估器、发布门禁和负面案例回流机制；\n4、熟练运用AI，完成测试设计、代码评审、数据构造、自动化验证、问题定位等工作；\n5、将业务知识和质量经验沉淀为结构化知识、Workflow、Skill或Agent，形成可复制、可规模化的质量能力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程及相关专业优先；\n2、具备扎实的计算机基础，熟悉至少一门编程语言，具有良好的工程实践能力；\n3、学习能力强，有好奇心和探索欲；能够快速学习新模型、新工具和新业务，重新建立解决问题的能力；\n4、具备良好的表达能力和判断力；能清晰表达目标、约束和验收标准，能识别AI输出中的事实、幻觉、边界和风险，形成可验证的结论；\n5、具备良好的产品意识、业务理解能力、责任心和跨团队协作能力。\n\n加分项\n1、有大模型应用、Agent、RAG、模型评测或Prompt-Engineering实践；\n2、熟悉自动化测试、性能测试、稳定性治理、数据分析或监控建设；\n3、有AI项目、开源项目、技术竞赛或自主完成复杂项目的经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668149282316585221","sourceKey":"bytedance","company":"字节跳动","title":"AI算法工程师 - 集团信息系统","city":"深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668149282316585221/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、负责AI-Native应用的算法研发和LLM效果优化工作，推动技术的探索和应用；\n2、探索大语言模型等AI技术在字节跳动国际化公司运营的落地，包括领域预训练、指令微调、训练和推理加速、模型评测等技术；\n3、提升自然语言理解的能力，比如实体识别、意图识别、NL2SQL，向量召回，结构化、非结构化，短文本、长文本的表征学习等；应用于对话系统、文本生成、文本分类、知识图谱，检索问答等领域；\n4、提升多模态识别和理解能力，比如图片、音频、视频等多模态分类、内容挖掘、理解和生成等。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、软件工程等相关专业；\n2、学术研究经历优先；扎实的算法和数据结构基础，熟练掌握Python/Go/C++等至少一种编程语言；\n3、动手能力强，熟悉NLP/CV领域的理论基础，掌握统计模型、机器学习相关原理，具有实战经验，参与过相关项目；\n4、学习能力优秀，有良好的团队合作精神，有责任心；\n5、熟悉业界领先大语言模型（GPT系列、LLaMA、ChatGLM等）的原理与训练方法，有NLP、计算机视觉、多模态大模型等科研经历或者对LLM有实践应用经历优先；\n6、在顶级学术会议（如CVPR、ICCV、ECCV等）发表论文者优先；在Kaggle，COCO，ImageNet，ActivityNet，ICPC，NOI/IOI等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665348886480554245","sourceKey":"bytedance","company":"字节跳动","title":"3D视觉算法工程师 - 音视频技术","city":"北京/杭州/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665348886480554245/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责相关产品的AI算法研发，如3D视频、6DoF视频、单目重建、3D、4D AIGC生成等相关工作；\n2、负责关键场景的算法优化，构建高质量的模型，提升业务效果；\n3、跟踪AI前沿技术进展，推动前沿技术的产品化落地。","requirements":"1、2027届获得硕士及以上学位，计算机图形学，计算机视觉，机器学习，计算机科学，计算机摄影，数学等相关专业优先；\n2、扎实的深度学习功底，熟练使用PyTorch/TensorFlow，掌握混合精度、分布式训练、TensorRT/ONNX落地流程；\n3、在图像/视频处理的一个或多个领域有研究和实践经验，有图像/视频生成、3D/4D重建、实时性优化等相关项目经验者优先；\n4、在CV/CG领域顶级学术会议上（SIGGRAPH/CVPR/ICCV/ECCV/TOG等）发表论文者优先；\n5、具有优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情，良好的沟通和团队合作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670100524188502277","sourceKey":"bytedance","company":"字节跳动","title":"AI应用研发工程师（采购方向） - 集团信息系统","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670100524188502277/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、参与公司企业信息系统采购领域相关产品的服务端研发工作，负责功能设计，代码落地，自测联调工作，保障系统稳定性，性能和数据安全；\n2、参与业务需求研讨与产品设计评审，协同前端、测试团队完成需求交付，运用AI Coding工具提升研发效率；\n3、协助探索AI能力在采购业务场景的落地应用，参与AI驱动的功能开发与验证。","requirements":"1、2027届获得本科及以上学历；\n2、熟练掌握Java编程语言，理解面向对象思想，深刻理解计算机原理，具备良好的数据结构，算法基础；\n3、积极主动、责任心强，具备良好的团队沟通协作能力；\n4、了解MySQL、Redis、MQ、ES等基础技术组件的使用，有实践经验者优先；\n5、熟练使用AI Coding相关工具者优先；\n6、对AI/大语言模型（LLM）相关技术有初步实践经验者优，包括但不限于：\n1）了解AI Agent的基本概念与架构模式（如工具调用、规划推理、记忆管理等）；\n2）接触或使用过主流Agent框架（如LangChain/LangGraph、Claude Agent SDK等）；\n3）了解RAG（检索增强生成）的基本原理，有兴趣探索其在企业级场景中的应用；\n4）对Prompt Engineering、LLM API集成有基础了解或学习意愿。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669688563202246917","sourceKey":"bytedance","company":"字节跳动","title":"大数据开发工程师（国际化方向） - 数据BP","city":"北京/上海/深圳","category":"大数据","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669688563202246917/detail","duty":"团队介绍：负责字节跳动旗下泛抖音、国际化、创新与中台等业务的数据 BP 工作，业务版图覆盖抖音、国际化、大模型、番茄小说等板块。我们以数据高效赋能业务增长为核心使命，深度扎根各业务线，以数据体系建设为根基、以业务目标达成为导向，为业务方提供专业、稳定、高效的数据服务与架构解决方案。工作内容聚焦海量数据的治理与应用，需对产品全链路数据进行复杂且深度的分析挖掘；深度参与大数据产品的迭代优化，探索前沿数据技术在业务场景中的落地实践，在字节跳动的技术土壤中实现个人能力与业务价值的双重增长。\n\n1、负责字节跳动旗下国际化相关业务的海量数据全链路建设，包括但不限于国际化场景下的电商、直播、短视频等相关业务，基于分布式计算与存储底座搭建高稳定、高吞吐数据流水线，沉淀标准化数据平台工具与商业化数据产品，支撑集团规模化数据生产；\n2、深度联动各相关业务线，综合运用数据开发、多维分析、数据挖掘能力输出一站式数据解决方案，挖掘数据资产价值，持续优化整体数据流转与使用效率；\n3、落地复杂SQL、ETL流程开发交付，负责超大规模数据任务性能调优、故障治理与高复杂度业务需求落地，跟进并落地前沿大数据技术方案迭代；\n4、落地AI辅助编码提效体系，覆盖需求拆解、数据建模、开发实现、自动化测试、标准化文档全流程，协同前后端工程师共同完成对外数据服务接口交付与上线。","requirements":"1、2027届获得本科及以上学历，计算机、数学等相关专业优先；\n2、计算机基础（操作系统、数据库、算法与数据结构、网络、概率统计等）扎实，有优秀的编码能力，熟练掌握至少一种主流编程语言（包括但不限于C/C++/Java/Python/Golang）；\n3、对数据开发、分析、挖掘领域有兴趣和热情，有志于在大数据领域长期发展；\n4、有分布式系统/数据挖掘等相关领域论文发表，或参与过大数据社区开源项目者加分；\n5、能使用AI Coding加速建模、ETL开发、测试与文档生成，对大模型和AI技术有好奇心和自驱力者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668159142175181109","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（供应链金融方向） - 集团信息系统","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668159142175181109/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、参与平台产品的服务端研发工作，推动业务的快速发展和高效迭代；\n2、参与系统架构设计、优化，提升系统性能和开发效率，保证设计和编码的质量；\n3、协助团队攻克各种高并发、系统解耦等方面的技术难关；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、通信等相关专业优先；\n2、热爱AI技术，积极钻研与实践，熟练使用AI coding编程工具；\n3、有扎实的编程能力，有优秀的设计和代码质量；\n4、深刻理解计算机原理，有良好的数据结构和算法基础；\n5、熟悉MySQL、Redis、消息队列等常用研发组件；\n6、积极乐观，责任心强，工作认真细致，有良好的团队沟通和协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667479014405720325","sourceKey":"bytedance","company":"字节跳动","title":"C++客户端开发工程师 - 抖音研发","city":"北京/上海/广州/深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667479014405720325/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、负责公司移动产品抖音、抖音火山版的客户端技术研发，编写高质量的代码；\n2、主动发现业务问题和技术痛点，深度参与客户端基建需求讨论、技术调研、方案评审、功能开发等；\n3、设计良好的代码结构，不断迭代优化。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、智能手机爱好者和使用者，追求良好的用户体验；\n3、具有良好的编程习惯，代码结构清晰，命名规范；\n4、熟练掌握数据结构与算法、计算机网络、操作系统、编译原理等课程；\n5、熟练掌握C/C++/OC/Swift一种或多种语言，理解基本的设计模式；\n6、有深度参与开源项目或者自己独立开发过App上架App Store优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665584080572418309","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师（搜索） - 抖音研发","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665584080572418309/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、参与AI搜索中台的基建能力建设，参与RAG知识库构建、Agent编排、Agent评测、Agent/Tool/Skill/Data市场、内容安全、Agent可观测等平台能力建设，支持公司内部业务快速搭建AI搜产品能力；\n2、参与搜索平台能力建设，以搜索效果质量保障和研发效率提升为目标，构建抓取评估、安全干预、诊断大师、负面案例管理、数据飞轮等产品矩阵，为抖音搜索、豆包搜索、AI抖音、今日头条搜索等业务线提供一站式接入服务；\n3、深度参与AI在搜索场景的工程化落地或者模型调优，包括但不限于机评Agent、智能归因Agent、平台AI Coding等建设；\n4、建设AI时代的搜索平台架构，利用AI技术构建开发者生态，保障性能与稳定性，提供通用、低成本的平台接入能力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、有扎实的编程能力和良好的代码习惯、数据结构和算法基础；\n3、能熟练使用一种编程语言，包括不限于Golang、Python、Java、PHP、C++、C；熟悉MySQL、Redis、MQ等常用Web组件，并了解基本原理；\n4、关注LLM和Agent相关技术，对新技术有热情；关注用户体验，能够积极把技术转化到用户体验改进上；\n5、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分，具备强烈的求知欲及优秀的学习、沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628872123775895861","sourceKey":"bytedance","company":"字节跳动","title":"【实习】大模型与智能体安全——面向Agentic AI的攻防评估与可信安全防御（隐私计算）-安全与风控（北京/深圳）","city":"深圳","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628872123775895861/detail","duty":"团队介绍：我们团队牵头探索人工智能数据安全与隐私保护、联邦学习、安全多方计算（SMPC）、可信执行环境、差分隐私及同态加密等前沿网络安全技术。\n我们开展尖端研究，致力于将新兴理论转化为数据与系统安全领域的实际应用方案。\n通过开创安全计算与隐私保护的全新方法，为塑造可信数字创新的未来发挥重要作用。\n\n课题介绍：\n智能体应用在爆发式增长同时，也引入了新的安全挑战。包括数据、决策、执行、供应链在内的更大攻击面，及其错综的交互特点和复杂的基础设施，使得传统安全技术纷纷失效，智能体、数据、模型等资产面临着失控、失窃和受损的风险。\n本课题旨在系统研究Agentic AI时代下大模型与智能体的攻防测试评估技术，以及基于大模型可信隐私计算的全链路防御体系，保障公司大模型业务的安全平稳发展，包括：\n1、多模态大模型与智能体的攻防检测与评估方法、测试基准以及工具链；\n2、面向智能体应用的风险防御技术以及可信安全运行保障技术；\n3、大模型以及海量样本下的训练与推理技术，保障数据与模型资产安全；\n4、面向大模型的机密训推基础设施安全构建、性能优化以及国产卡适配。\n\n课题挑战：\n智能体应用在爆发式增长同时，也引入了新的安全挑战。包括数据、决策、执行、供应链在内的更大攻击面，及其错综的交互特点和复杂的基础设施，使得传统安全技术纷纷失效，智能体、数据、模型等资产面临着失控、失窃和受损的风险。\n本课题旨在系统研究Agentic AI时代下大模型与智能体的攻防测试评估技术，以及基于大模型可信隐私计算的全链路防御体系，保障公司大模型业务的安全平稳发展，包括：\n1、多模态大模型与智能体的攻防检测与评估方法、测试基准以及工具链；\n2、面向智能体应用的风险防御技术以及可信安全运行保障技术；\n3、大模型以及海量样本下的训练与推理技术，保障数据与模型资产安全；\n4、面向大模型的机密训推基础设施安全构建、性能优化以及国产卡适配。\n\n课题价值：\n1、技术价值：\n1.1构建Agentic AI多模态安全评估基准与红队测试工具链；\n1.2构建领先的大模型安全训练与推理算法、系统以及智能体安全可信防护能力。\n2、业务价值：\n2.1为智能体产品提供运行时安全防护能力以及可信可证的用户隐私保护措施，保障Flow等大模型和智能体产品安全运行；\n2.2面向第三方算力环境提供安全可信的大模型数据与资产保护能力；","requirements":"1、2027届及以后毕业，博士在读，人工智能、数学、计算机、信息安全等相关专业优先；\n2、具备扎实的计算机科学与数学基础，对数据结构、算法、操作系统和分布式系统有良好理解，熟悉概率统计、信息论、数值线性代数，或程序分析等基础知识；\n3、理解智能体应用范式、Transformer、注意力机制等核心原理，熟悉大模型的高效微调（如LoRA/QLoRA）与对齐范式；理解KV-Cache、量化等大模型推理机制；\n4、在密码学、数据安全、隐私计算、人工智能安全等领域具备扎实的基础知识，在智能体/工具生态安全、大模型用户隐私保护、模型资产保护等方向有经验者优先；\n5、熟练掌握至少一种编程语言（如Python/C++/Go），有良好的代码工程习惯；熟练使用PyTorch等框架；\n6、具备出色的问题分析和解决能力，自主探索新技术与解决方案的能力，以及良好的沟通与团队协作能力；在CCS、NDSS、IEEE S&P、USENIX Security等安全顶级会议或期刊上发表论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622229551623948549","sourceKey":"bytedance","company":"字节跳动","title":"视频生成算法研究员-Seed大模型人才校招","city":"深圳","category":"计算机视觉","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622229551623948549/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n视频生成团队负责与视频生成相关的 foundation model 基础研究，包括了多模态生成、多模态实时交互、视觉智能基础模型/表示等相关方向。团队于26年2月推出 Seedance 2.0，SoTA 音视频&多模态能力世界领先，支持豆包、即梦、火山引擎、抖音、剪映等核心业务场景。\n\n1、参与视频生成基础模型相关结构的研究和开发，包括：VAE，MOE，Attention，动态稀疏结构，超长序列建模，原生多模态表征与架构，AR+Diffusion架构与应用探索；\n2、参与视频生成基础模型全流程的研究和开发，围绕视频生成的新应用/产品研发。","requirements":"1、2027届获得本科及以上学历，计算机、电子、数学等相关专业；\n2、要求至少具备以下某一方向的研究和实践经验，同时具备多方向经验者优先：\n1）图片/视频生成扩散模型，核心环节大规模训练实战经验；\n2）视觉自监督学习/表示学习/VAE的前沿研究经验；\n3）模型结构设计，如MOE，Attention，动态稀疏结构，超长序列建模的大规模实验经验，工程能力强者优先；\n4）原生多模态/生成理解统一的大规模实验经验；\n5）扩散模型/Optimizer的前沿研究经验；\n3、要求工作积极主动，思路有条理性，能够独立完成具有挑战性的前沿研发工作；同时能很好与团队成员协作产出。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7602170390559410437","sourceKey":"bytedance","company":"字节跳动","title":"机器学习训练框架开发实习生-Data AML","city":"北京","category":"机器学习","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7602170390559410437/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、负责研发支持字节跳动内部多个日活十亿级应用的推荐广告模型的分布式训练框架；\n2、探索世界领先的分布式训练框架新范式，解决如何同时支持超大规模的稀疏模型和稠密模型的难题；\n3、深度优化和利用国产新硬件和国际化新型硬件，做到硬件性能的机制优化；\n4、深度优化分布式框架能力，打造支持万卡规模训练能力的分布式训练框架；\n5、与全公司算法部门紧密合作，为探索下一代推荐广告模型训练新范式做前沿探索和深度优化。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟练掌握Linux环境下的C/C++与Python语言，有良好的编程习惯及编码能力；\n3、接触过至少一种机器学习框架（TensorFlow/PyTorch/Jax或其他自研框架）优先；\n4、有以下至少一项的背景知识与经验的优先：GPU编程，编译器，高性能网络，分布式存储，集群调度；\n5、具有独立解决问题的能力，良好的团队合作精神；\n6、有强烈的工作责任心，较好的学习能力、沟通能力和自驱力。","description":"","jdComplete":true,"sourceStatus":null}];
